import {
  applyArtisticStrategy,
  multiLevelNotan,
  temperatureMapColor,
  blendWithIntensity,
  customPaletteStrategy,
  canonicalizeStyledPalette,
} from "../../../utils/colorStrategies";
import { simulateCmyk } from "../../../utils/colorMath";
import type { ArtisticPresetId, RGB } from "../../../config";
import type { ProcessingResult } from "./types";

interface PathCache {
  contours: WeakMap<any, Path2D>;
  chains: Path2D;
}
const pathCache = new WeakMap<ProcessingResult, PathCache>();

function drawSmoothChain(ctx: CanvasRenderingContext2D, pts: [number, number][]): void {
  if (pts.length < 2) return;

  // На прямых линиях canvas нет "орбиты" (это артефакт безье), поэтому длинные
  // прямые границы (горизонт, край стены) рисуем как есть — раньше они ошибочно
  // выкидывались порогом 200px и пропадали в превью.
  ctx.beginPath();
  ctx.moveTo(pts[0][0], pts[0][1]);

  for (let i = 1; i < pts.length; i++) {
    ctx.lineTo(pts[i][0], pts[i][1]);
  }

  ctx.stroke();
}

export function renderSchemeCanvas(
  canvas: HTMLCanvasElement,
  res: ProcessingResult,
  contourWeight: number,
  numberWeight: number,
  activeColors: Set<number>,
  showNumbers: boolean,
  scale: number = 2,
  isArtisticMode: boolean = false,
  artisticStep: number = 0,
  artisticPresetId?: ArtisticPresetId,
  notanLevels: number = 2,
  notanThreshold: number = 128,
  artIntensity: number = 100,
  customArtPalette?: RGB[],
  showTemperatureMap: boolean = false,
  zoneGuideActive: boolean = false,
  currentZoneContourId: number = -1,
  detailsPhotoOpacity: number = 60,
  showContours: boolean = true,
  showBorder: boolean = true,
  recipeApproximations?: Record<number, [number, number, number]>,
  // CMYK-софтпруф: сжимает палитру в достижимый охват офсетной печати.
  // Включается чекбоксом «Симуляция печати» в окне экспорта и применяется
  // ТОЛЬКО к заливкам зон — контуры и номера остаются чёрными.
  cmykProof: boolean = false
): void {
  const { imgW, imgH, colorPalette, contoursData } = res;

  canvas.width = imgW * scale;
  canvas.height = imgH * scale;

  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  // Очистка фона
  if (isArtisticMode && artisticStep === 4) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  } else if (isArtisticMode && artisticStep === 0) {
    const bgAlpha = 1 - detailsPhotoOpacity / 100;
    ctx.fillStyle = `rgba(255, 255, 255, ${bgAlpha})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  } else {
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }

  const shouldFill = isArtisticMode
    ? (artisticStep > 0 && artisticStep < 4) || showTemperatureMap
    : activeColors.size > 0 || (zoneGuideActive && currentZoneContourId >= 0);

  if (shouldFill) {
    // Если передан recipeApproximations (режим предпросмотра реальных красок), используем его
    let activePalette = recipeApproximations || res.colorPalette;

    if (isArtisticMode) {
      const mappedPalette: Record<number, RGB> = {};
      for (const key in res.colorPalette) {
        const rgb = res.colorPalette[key];
        let styled = rgb;
        
        if (showTemperatureMap) {
          styled = temperatureMapColor(rgb);
        } else if (artisticStep === 1) {
          styled = multiLevelNotan(rgb, notanLevels, notanThreshold);
        } else if (artisticStep === 2) {
          if (artisticPresetId === 'original') {
            styled = rgb;
          } else if (customArtPalette && customArtPalette.length >= 2) {
            styled = customPaletteStrategy(rgb, customArtPalette);
            if (artIntensity < 100) {
              styled = blendWithIntensity(rgb, styled, artIntensity);
            }
          } else {
            styled = applyArtisticStrategy(rgb, artisticPresetId as ArtisticPresetId, artIntensity);
          }
        }
        mappedPalette[key] = styled;
      }
      // #6: схлопываем визуально совпавшие стилизованные цвета (warm_cool/pop_art и т.п.)
      activePalette = canonicalizeStyledPalette(mappedPalette);
    }

    // CMYK-софтпруф применяем последним — уже после художественной стилизации и
    // схлопывания палитры, чтобы результат совпадал с тем, что уйдёт в печать.
    if (cmykProof) {
      const proofed: Record<number, RGB> = {};
      for (const key in activePalette) proofed[key] = simulateCmyk(activePalette[key]);
      activePalette = proofed;
    }

    // Прекэширование строк RGB для обхода GC и тяжелых конкатенаций в цикле
    const activePaletteStrings: Record<number, string> = {};
    for (const key in activePalette) {
      const c = activePalette[key];
      activePaletteStrings[key] = `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
    }

    let cache = pathCache.get(res);
    if (!cache) {
      const contoursMap = new WeakMap<any, Path2D>();
      for (const cd of contoursData) {
        if (cd.points && cd.points.length > 0) {
          const p = new Path2D();
          p.moveTo(cd.points[0][0], cd.points[0][1]);
          for (let i = 1; i < cd.points.length; i++) {
            p.lineTo(cd.points[i][0], cd.points[i][1]);
          }
          p.closePath();
          contoursMap.set(cd, p);
        }
      }

      const chainsPath = new Path2D();
      for (const chain of res.chains) {
        if (chain.length < 2) continue;
        // Прямые сегменты рисуются как есть (без порога длины) — длинные ровные
        // границы больше не пропадают.
        chainsPath.moveTo(chain[0][0], chain[0][1]);
        for (let i = 1; i < chain.length; i++) {
          chainsPath.lineTo(chain[i][0], chain[i][1]);
        }
      }

      cache = { contours: contoursMap, chains: chainsPath };
      pathCache.set(res, cache);
    }

    ctx.save();
    ctx.scale(scale, scale);
    ctx.lineJoin = "round";

    for (const cd of contoursData) {
      const isActive = isArtisticMode || activeColors.has(cd.labelId) || (zoneGuideActive && currentZoneContourId === cd.labelId);

      // ВАЖНО: неактивные зоны НЕ пропускаем, а заливаем белым (фон). Иначе
      // активная внешняя зона визуально перекрывает вложенные в неё неактивные
      // зоны (у полигона внешнего контура нет «дырки»). Контуры идут от больших
      // к меньшим, поэтому вложенная белая заливка «пробивает» внешний цвет.
      // В художественном режиме isActive всегда true — там всё как прежде.

      let colorStr = "rgb(255, 255, 255)";

      if (isActive) {
        colorStr = activePaletteStrings[cd.labelId] || colorStr;
        
        // Логика подсветки зоны в гайде
        if (zoneGuideActive && currentZoneContourId >= 0 && cd.labelId !== currentZoneContourId) {
           const c = activePalette[cd.labelId] || [255, 255, 255];
           colorStr = `rgb(${Math.round(c[0] * 0.15 + 240 * 0.85)}, ${Math.round(c[1] * 0.15 + 240 * 0.85)}, ${Math.round(c[2] * 0.15 + 240 * 0.85)})`;
        }
      } else if (zoneGuideActive && currentZoneContourId >= 0 && cd.labelId !== currentZoneContourId) {
         colorStr = "rgb(240, 240, 240)";
      }

      ctx.fillStyle = colorStr;
      
      const shouldStrokePolygon = contourWeight === 0 || !showContours;
      if (shouldStrokePolygon) {
        ctx.strokeStyle = colorStr;
        ctx.lineWidth = 0.6;
      }
      
      const p2d = cache.contours.get(cd);
      if (p2d) {
        ctx.fill(p2d);
        if (shouldStrokePolygon) {
          ctx.stroke(p2d);
        }
      } else {
        // Fallback for older data or missing cache
        ctx.beginPath();
        const pts = cd.points;
        if (pts.length > 0) {
          ctx.moveTo(pts[0][0], pts[0][1]);
          for (let i = 1; i < pts.length; i++) {
            ctx.lineTo(pts[i][0], pts[i][1]);
          }
          ctx.closePath();
          ctx.fill();
          if (shouldStrokePolygon) {
            ctx.stroke();
          }
        }
      }
    }
    ctx.restore();
  }

  ctx.save();
  ctx.scale(scale, scale);

  const shouldDrawLines = (isArtisticMode ? (artisticStep === 0 || artisticStep === 4) : true) && showContours;

  if (shouldDrawLines) {
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    let cache = pathCache.get(res); // Retrieve cache for lines if not already loaded

    if (isArtisticMode && artisticStep === 4 && contourWeight > 0) {
      const weightFactor = contourWeight / 50; 
      
      if (cache && cache.chains) {
         ctx.lineWidth = 2.5 * weightFactor;
         ctx.strokeStyle = "rgba(0,0,0,0.4)";
         ctx.stroke(cache.chains);

         ctx.lineWidth = 1.0 * weightFactor;
         ctx.strokeStyle = "rgba(255,255,255,0.8)";
         ctx.stroke(cache.chains);
      } else {
        const { chains } = res;
        for (const chain of chains) {
          ctx.lineWidth = 2.5 * weightFactor;
          ctx.strokeStyle = "rgba(0,0,0,0.4)";
          drawSmoothChain(ctx, chain);

          ctx.lineWidth = 1.0 * weightFactor;
          ctx.strokeStyle = "rgba(255,255,255,0.8)";
          drawSmoothChain(ctx, chain);
        }
      }
    } else {
      const lineAlpha = contourWeight === 0 ? 0 : (isArtisticMode ? 0.6 : 0.2 + (contourWeight / 100) * 0.8);
      const lineWidth = contourWeight === 0 ? 0 : (isArtisticMode ? 1.0 : 0.5 + (contourWeight / 100) * 1.5);

      ctx.strokeStyle = `rgba(40,40,40,${lineAlpha})`;
      ctx.lineWidth = lineWidth;

      if (cache && cache.chains) {
         ctx.stroke(cache.chains);
      } else {
         const { chains } = res;
         for (const chain of chains) {
           drawSmoothChain(ctx, chain);
         }
      }
    }
  }

  // Отрисовка номеров (только в режиме Студии)
  if (showNumbers && !isArtisticMode) {
    const numAlpha = numberWeight === 0 ? 0 : 0.15 + (numberWeight / 100) * 0.85;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    for (const cd of contoursData) {
      for (const lbl of cd.labelPositions) {
        if (lbl.maxDist < 2) continue;
        // Учёт числа цифр: многозначные номера не вылезают за пределы зоны.
        const digits = String(cd.labelId + 1).length;
        const fitFs = (3.27 * lbl.maxDist) / digits;
        const fs = Math.max(7, Math.min(16, lbl.maxDist * 1.3, fitFs));
        ctx.font = `bold ${fs}px sans-serif`;

        const isActive = activeColors.has(cd.labelId);
        const col = colorPalette[cd.labelId];

        if (isActive && col) {
          const lum = 0.299 * col[0] + 0.587 * col[1] + 0.114 * col[2];
          ctx.fillStyle = lum > 140 ? `rgba(0,0,0,${numAlpha})` : `rgba(255,255,255,${numAlpha})`;
        } else {
          ctx.fillStyle = `rgba(51,51,51,${numAlpha})`;
        }
        ctx.fillText(String(cd.labelId + 1), lbl.x, lbl.y);
      }
    }
  }

  // Рамка картины
  if (showContours && contourWeight > 0 && showBorder) {
    ctx.save();
    const lineAlpha = contourWeight === 0 ? 0 : (isArtisticMode ? 0.6 : 0.2 + (contourWeight / 100) * 0.8);
    const lineWidth = contourWeight === 0 ? 0 : (isArtisticMode ? 1.0 : 0.5 + (contourWeight / 100) * 1.5);

    if (isArtisticMode && artisticStep === 4) {
      const weightFactor = contourWeight / 50;
      ctx.strokeStyle = "rgba(0,0,0,0.4)";
      ctx.lineWidth = 2.5 * weightFactor;
      ctx.strokeRect(0, 0, imgW, imgH);
      ctx.strokeStyle = "rgba(255,255,255,0.8)";
      ctx.lineWidth = 1.0 * weightFactor;
      ctx.strokeRect(0, 0, imgW, imgH);
    } else {
      ctx.strokeStyle = `rgba(40,40,40,${lineAlpha})`;
      ctx.lineWidth = lineWidth;
      ctx.strokeRect(0, 0, imgW, imgH);
    }
    ctx.restore();
  }

  ctx.restore();
}