// src/generator/components/AutoPresetSettings.tsx
//
// Настройки «умного» автопоиска: пользователь отмечает галочками, какими именно
// рычагами разрешено крутить алгоритму. По умолчанию включены ВСЕ. Меньше рычагов
// — быстрее перебор. Состояние живёт в сторе (presetLevers) и читается search.ts.

import { useState } from "react";
import { useAppStore } from "../store";
import type { PresetLevers } from "../store/types";

const LEVERS: Array<{ key: keyof PresetLevers; label: string }> = [
  { key: "colors", label: "Число цветов" },
  { key: "detail", label: "Детализация" },
  { key: "brightness", label: "Яркость" },
  { key: "contrast", label: "Контраст" },
  { key: "saturation", label: "Насыщенность" },
  { key: "sharpness", label: "Резкость" },
  { key: "shadows", label: "Тени" },
  { key: "highlights", label: "Света" },
  { key: "structure", label: "Структура" },
  { key: "emphasis", label: "Акцент на объекте" },
  { key: "backgroundSimplify", label: "Упрощение фона" },
];

export function AutoPresetSettings({ isDark }: { isDark?: boolean }) {
  void isDark;
  const levers = useAppStore((s) => s.presetLevers);
  const update = useAppStore((s) => s.update);
  const [open, setOpen] = useState(false);

  const toggle = (k: keyof PresetLevers) => update({ presetLevers: { ...levers, [k]: !levers[k] } });
  const setAll = (v: boolean) =>
    update({ presetLevers: LEVERS.reduce((acc, l) => ({ ...acc, [l.key]: v }), {} as PresetLevers) });
  const onCount = LEVERS.filter((l) => levers[l.key]).length;

  return (
    <div className="rounded-2xl border-2 border-indigo-500/25 bg-indigo-500/[0.06] p-3 flex flex-col gap-2.5">
      <div className="flex items-center justify-between">
        <span className="text-[11px] font-black uppercase tracking-wider text-indigo-300 flex items-center gap-1.5">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 21v-7M4 10V3M12 21v-9M12 8V3M20 21v-5M20 12V3M1 14h6M9 8h6M17 16h6" /></svg>
          Чем управляет автопоиск
        </span>
        <button
          onClick={() => setOpen((v) => !v)}
          className="text-[10px] font-bold uppercase tracking-wider text-slate-400 hover:text-slate-200"
        >
          {open ? "Скрыть" : `${onCount}/${LEVERS.length} ▾`}
        </button>
      </div>

      {open && (
        <div className="flex flex-col gap-2.5">
          <p className="text-[10px] text-slate-500 leading-snug">
            Отметь рычаги, которыми умному поиску разрешено крутить. По умолчанию — все.
            Меньше рычагов — быстрее перебор.
          </p>
          <div className="grid grid-cols-2 gap-1">
            {LEVERS.map((l) => (
              <label
                key={l.key}
                className="flex items-center gap-2 cursor-pointer select-none py-1 px-1.5 rounded-lg hover:bg-white/5 transition-colors"
              >
                <input
                  type="checkbox"
                  checked={levers[l.key]}
                  onChange={() => toggle(l.key)}
                  className="w-4 h-4 rounded accent-indigo-500 shrink-0"
                />
                <span className="text-[11px] font-semibold text-slate-200">{l.label}</span>
              </label>
            ))}
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => setAll(true)}
              className="flex-1 px-2 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider bg-indigo-600/80 text-white hover:bg-indigo-500 active:scale-[0.98] transition-all"
            >
              Все
            </button>
            <button
              onClick={() => setAll(false)}
              className="flex-1 px-2 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider bg-white/10 text-slate-300 hover:bg-white/15 active:scale-[0.98] transition-all"
            >
              Ничего
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
