// --- Помощники «цвета под краски» (модульный уровень, чистые функции) ---
const GAMUT_THRESHOLD = 6;          // ΔE00, выше которого краски заметно не дотягивают
const MARKER_RGB: RGB = [236, 72, 153]; // маркер «предел красок» (розовый, хорошо виден)

// ΔE00 «идеал → достижимый цвет» по каждой метке.
function computeGamutDelta(
  approx: Record<number, RGB>, ideal: Record<number, RGB>, labels: number[]
): Record<number, number> {
  const d: Record<number, number> = {};
  for (const lab of labels) {
    const a = approx[lab], id = ideal[lab];
    if (a && id) d[lab] = deltaE00(rgbToLab(id), rgbToLab(a));
  }
  return d;
}

// Мягкое сохранение объёма: растягиваем светлоту (L*) достижимых цветов к диапазону
// идеала, сохраняя реальные оттенки (a*, b*). Это возвращает тоновую «глубину»,
// которая схлопывается при обычной подгонке под охват. STRENGTH<1 — компромисс,
// чтобы цвета оставались близки к реально достижимым.
function volumeAdjustPalette(
  approx: Record<number, RGB>, ideal: Record<number, RGB>, labels: number[]
): Record<number, RGB> {
  const out: Record<number, RGB> = { ...approx };
  const apL: number[] = [], idL: number[] = [];
  for (const lab of labels) {
    const a = approx[lab], id = ideal[lab];
    if (a && id) { apL.push(rgbToLab(a)[0]); idL.push(rgbToLab(id)[0]); }
  }
  if (apL.length < 2) return out;
  const aMin = Math.min(...apL), aMax = Math.max(...apL);
  const iMin = Math.min(...idL), iMax = Math.max(...idL);
  const aRange = aMax - aMin, iRange = iMax - iMin;
  if (aRange < 1e-3) return out;
  const STRENGTH = 0.7;
  for (const lab of labels) {
    const a = approx[lab];
    if (!a) continue;
    const [L, aa, bb] = rgbToLab(a);
    const norm = (L - aMin) / aRange;
    const targetL = iMin + norm * iRange;
    const newL = L + (targetL - L) * STRENGTH;
    out[lab] = labToRgb(Math.max(0, Math.min(100, newL)), aa, bb);
  }
  return out;
}

function tintToward(c: RGB, m: RGB, t: number): RGB {
  return [
    Math.round(c[0] * (1 - t) + m[0] * t),
    Math.round(c[1] * (1 - t) + m[1] * t),
    Math.round(c[2] * (1 - t) + m[2] * t),
  ];
}

