// src/calib/scan.ts
//
// Полный проход: фото бланка → цвета красок + картинка с разметкой найденного.
//
// Порядок принципиален:
//   1. найти метки и выпрямить лист (иначе сетка не совпадёт с мазками);
//   2. понять, не перевёрнут ли кадр (по серой шкале — она всегда сверху);
//   3. построить карту освещённости по бумаге (снимает неровный свет и виньетку,
//      заодно даёт баланс белого);
//   4. только теперь мерить цвет — уже на выровненном и сбалансированном листе.

import {
  RECTIFY_W, RECTIFY_H, mmToPx, cellSampleRectMm, cellBoxMm,
  CELLS_PER_PAGE, WEDGE,
} from './sheetSpec';
import { detectMarkers, MARKER_CENTERS_MM, MARKER_CENTERS_MM_FLIPPED } from './markers';
import { homographyFrom4, warpPerspective, applyH, type Mat3 } from './homography';
import { buildFlatField, type FlatField } from './flatField';
import { readSwatch, type SwatchReading } from './swatch';

export interface ScannedCell {
  index: number;
  /** Имя краски из шаблона, если оно известно. */
  name?: string;
  reading: SwatchReading;
  /** Углы окна замера в координатах ИСХОДНОГО фото — для отрисовки поверх снимка. */
  quad: { x: number; y: number }[];
  /** Углы напечатанной рамки в координатах фото — рисуем тонкой линией. */
  boxQuad: { x: number; y: number }[];
}

export interface ExposureReport {
  /** Контраст серой шкалы, 0..1. Меньше 0.35 — кадр вялый/в дымке. */
  wedgeContrast: number;
  /** Светлая ступень упёрлась в белое. */
  highlightsClipped: boolean;
  /** Тёмные ступени слились. */
  shadowsCrushed: boolean;
  /** Разброс яркости бумаги по листу, %. */
  unevennessPct: number;
  messages: string[];
}

/**
 * Физика поверхности, снятая с реальных мазков.
 *
 * ЗАЧЕМ. Чтобы показать работу такой, какой она будет на столе, нужны не
 * только цвета, но и поведение слоя: блестит он или матовый, ровный или
 * зернистый. Табличные значения вида «у масла блеск такой-то» описывают
 * идеальный корпусный слой на холсте, а не то, что человек реально положил
 * своей кистью на свою бумагу.
 *
 * ПОЧЕМУ ТОЛЬКО С ФОТОГРАФИИ. У планшетного сканера собственная геометрия
 * подсветки: источник и приёмник движутся вместе, зеркальная составляющая
 * ведёт себя иначе, чем при взгляде на лист под лампой. Проверка на реальных
 * бланках это подтвердила: одна и та же гуашь дала блеск 0,00 на фотографии
 * и 0,04 на скане, зернистость 0,10 против 0,19. Мерить физику по скану
 * значит выдавать артефакт устройства за свойство краски, поэтому для скана
 * результат помечается недостоверным и в набор не попадает.
 */
export interface SurfacePhysics {
  /** Глянец слоя, 0..1. */
  gloss: number;
  /** Зернистость слоя, 0..1. */
  grain: number;
  /** Измерено по фотографии. На скане величины недостоверны. */
  reliable: boolean;
  /** Сколько ячеек участвовало в оценке. */
  samples: number;
}

export interface ScanResult {
  ok: boolean;
  failure?: 'no-markers' | 'bad-geometry';
  /**
   * Чем снят лист. Определяется по подписи планшетного сканера: свет у него
   * идеально ровный (перепад почти нулевой), но автоэкспозиция выбивает бумагу
   * в чистый белый. У фотографии всё наоборот. Различать нужно потому, что
   * советы по съёмке для этих двух случаев противоположны.
   */
  sourceKind: 'photo' | 'scanner';
  cells: ScannedCell[];
  exposure: ExposureReport;
  /** Гомография «выпрямленный лист → фото». Нужна UI для ручной правки точек. */
  H?: Mat3;
  flipped: boolean;
  markers?: { x: number; y: number }[];
  /** Физика поверхности по этому листу. null — измерить не удалось. */
  physics: SurfacePhysics | null;
}

function meanLuma(img: ImageData, cx: number, cy: number, w: number, h: number): number {
  const { data, width, height } = img;
  const x0 = Math.max(0, Math.round(cx - w / 2)), x1 = Math.min(width - 1, Math.round(cx + w / 2));
  const y0 = Math.max(0, Math.round(cy - h / 2)), y1 = Math.min(height - 1, Math.round(cy + h / 2));
  let s = 0, n = 0;
  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      const i = (y * width + x) * 4;
      if (data[i + 3] < 128) continue;
      s += (data[i] * 299 + data[i + 1] * 587 + data[i + 2] * 114) / 1000;
      n++;
    }
  }
  return n ? s / n : 0;
}

/** Яркости шести ступеней серой шкалы на выпрямленном листе. */
function readWedge(rect: ImageData): number[] {
  const out: number[] = [];
  for (let i = 0; i < WEDGE.steps.length; i++) {
    const cx = mmToPx(WEDGE.xMm + WEDGE.patchWMm * (i + 0.5));
    const cy = mmToPx(WEDGE.yMm + WEDGE.patchHMm / 2);
    out.push(meanLuma(rect, cx, cy, mmToPx(WEDGE.patchWMm * 0.5), mmToPx(WEDGE.patchHMm * 0.5)));
  }
  return out;
}

/**
 * Насколько шкала похожа на «светлое → тёмное».
 * Если лист сфотографирован вверх ногами, в этой области окажется низ бланка,
 * и убывания не будет — так мы и ловим переворот, не тратя отдельную метку.
 */
function wedgeDescendingScore(w: number[]): number {
  let s = 0;
  for (let i = 1; i < w.length; i++) s += w[i - 1] - w[i];
  return s;
}

function quadFor(H: Mat3, r: { x: number; y: number; w: number; h: number }) {
  const c = [
    { x: r.x, y: r.y }, { x: r.x + r.w, y: r.y },
    { x: r.x + r.w, y: r.y + r.h }, { x: r.x, y: r.y + r.h },
  ];
  return c.map(p => applyH(H, p.x, p.y));
}

/**
 * @param photo   исходное фото (полное разрешение или уменьшенное — не важно,
 *                координаты возвращаются в его системе)
 * @param names   имена красок по ячейкам; длина задаёт, сколько ячеек читать
 * @param corners если переданы — используются вместо автопоиска (ручной режим)
 */
export function scanSheet(
  photo: ImageData,
  names: string[],
  corners?: { x: number; y: number }[],
  /**
   * Номер листа, начиная с нуля. Геометрия ячеек на каждом листе одна и та же,
   * а вот сквозная нумерация продолжается: цвета второго листа получают
   * индексы 20..39. Без этого второй лист был бы прочитан как первый и молча
   * переписал бы его результаты.
   */
  pageIndex = 0,
): ScanResult {
  const emptyExposure: ExposureReport = {
    wedgeContrast: 0, highlightsClipped: false, shadowsCrushed: false,
    unevennessPct: 0, messages: [],
  };
  const fail = (failure: ScanResult['failure']): ScanResult => ({
    ok: false, failure, cells: [], exposure: emptyExposure, flipped: false, sourceKind: 'photo',
    physics: null,
  });

  const found = corners && corners.length === 4 ? corners : detectMarkers(photo);
  if (!found) return fail('no-markers');
  const pts = found.map(p => ({ x: p.x, y: p.y }));

  // Две гипотезы ориентации: как есть и повёрнутый на 180°.
  const build = (centersMm: { x: number; y: number }[]) =>
    homographyFrom4(centersMm.map(c => ({ x: mmToPx(c.x), y: mmToPx(c.y) })), pts);

  const hNormal = build(MARKER_CENTERS_MM);
  const hFlipped = build(MARKER_CENTERS_MM_FLIPPED);
  if (!hNormal || !hFlipped) return fail('bad-geometry');

  const rectNormal = warpPerspective(photo, hNormal, RECTIFY_W, RECTIFY_H);
  const wedgeNormal = readWedge(rectNormal);
  const scoreNormal = wedgeDescendingScore(wedgeNormal);

  let H = hNormal, rect = rectNormal, wedge = wedgeNormal, flipped = false;

  // Пересчитываем перевёрнутый вариант только если прямой выглядит сомнительно —
  // варп это самая тяжёлая операция во всём проходе.
  if (scoreNormal < 40) {
    const rectF = warpPerspective(photo, hFlipped, RECTIFY_W, RECTIFY_H);
    const wedgeF = readWedge(rectF);
    if (wedgeDescendingScore(wedgeF) > scoreNormal) {
      H = hFlipped; rect = rectF; wedge = wedgeF; flipped = true;
    }
  }

  const ff: FlatField = buildFlatField(rect);

  // ── Диагностика съёмки по серой шкале ────────────────────────────────────
  const wedgeContrast = Math.max(0, (wedge[0] - wedge[wedge.length - 1]) / 255);
  // Одна-две выбитые точки бумаги — не повод пугать пользователя: мы их всё
  // равно выбрасываем при подгонке. Тревога только если выбита заметная часть
  // листа — тогда локальный белый оценён неверно и цвета поплывут.
  const highlightsClipped = wedge[0] >= 253 && ff.clippedFraction > 0.30;
  // Порог проверен на реальных сканах: у планшетного сканера тёмные ступени
  // сближаются сильнее, чем на фото, и прежнее значение давало ложную тревогу
  // на заведомо хорошем исходнике.
  const shadowsCrushed = Math.abs(wedge[4] - wedge[5]) < 2 && wedge[5] < 28;

  // Планшетный сканер даёт идеально ровный свет и при этом почти всегда
  // выбивает бумагу в чистый белый. Сочетание этих двух признаков однозначно
  // отличает скан от фотографии.
  const sourceKind: 'photo' | 'scanner' =
    ff.unevennessPct <= 8 && ff.clippedFraction > 0.25 ? 'scanner' : 'photo';

  const messages: string[] = [];
  if (wedgeContrast < 0.35) messages.push('Низкий контраст изображения. Вероятная причина: рассеянный или недостаточный свет.');

  if (sourceKind === 'scanner') {
    // Скан геометрически безупречен, и советы про свет и ракурс к нему
    // неприменимы. Осмысленное указание здесь ровно одно: убрать
    // автоматическое повышение яркости, из-за которого сканер теряет
    // различие между бумагой и светлыми красками.
    if (highlightsClipped) {
      // Сознательно не обещаем компенсацию: когда бумага выбита в 255, опорный
      // белый восстановить нечем, и подмена его контрольной шкалой дала бы
      // ложную точность (плотность печати у каждого принтера своя). Насыщенные
      // цвета при этом читаются верно, страдают только светлые.
      messages.push('Сканер осветлил бумагу до чистого белого. Насыщенные цвета прочитаны верно, светлые могут быть неточны. Отключите автояркость и автоконтраст в драйвере сканера и повторите сканирование.');
    }
  } else {
    if (highlightsClipped) messages.push('Светлые участки пересвечены. Уменьшите экспозицию или исключите направленный свет.');
    if (shadowsCrushed) messages.push('Тёмные участки неразличимы. Требуется более освещённое место съёмки.');
    if (ff.unevennessPct > 25) messages.push(`Неравномерное освещение листа, перепад ${ff.unevennessPct}%. Компенсация выполнена; для повышения точности рекомендуется рассеянный свет.`);
  }
  if (ff.probesUsed < ff.probesTotal * 0.6) messages.push('Значительная часть полей листа перекрыта. Краска не должна выходить за пределы рамок.');

  const exposure: ExposureReport = {
    wedgeContrast, highlightsClipped, shadowsCrushed,
    unevennessPct: ff.unevennessPct, messages,
  };

  // ── Замер ячеек ──────────────────────────────────────────────────────────
  const cells: ScannedCell[] = [];
  const base = pageIndex * CELLS_PER_PAGE;
  const remaining = Math.max(0, (names.length || CELLS_PER_PAGE) - base);
  const count = Math.min(remaining, CELLS_PER_PAGE);

  for (let i = 0; i < count; i++) {
    const sMm = cellSampleRectMm(i);
    const sPx = { x: mmToPx(sMm.x), y: mmToPx(sMm.y), w: mmToPx(sMm.w), h: mmToPx(sMm.h) };
    const bMm = cellBoxMm(i);
    const bPx = { x: mmToPx(bMm.x), y: mmToPx(bMm.y), w: mmToPx(bMm.w), h: mmToPx(bMm.h) };

    cells.push({
      // Индекс сквозной по всей палитре, геометрия — локальная для листа.
      index: base + i,
      name: names[base + i],
      reading: readSwatch(rect, sPx, ff.whiteAt),
      quad: quadFor(H, sPx),
      boxQuad: quadFor(H, bPx),
    });
  }

  // ── Физика поверхности ───────────────────────────────────────────────────
  // Медиана, а не среднее: одна ячейка с бликом от окна не должна объявлять
  // всю палитру глянцевой. В расчёт идут только уверенные замеры.
  const good = cells.filter(c => !c.reading.empty && c.reading.confidence >= 70);
  const median = (v: number[]) => {
    if (!v.length) return 0;
    const a = [...v].sort((x, y) => x - y);
    return a[Math.floor(a.length / 2)];
  };
  const physics: SurfacePhysics | null = good.length >= 3
    ? {
        gloss: median(good.map(c => c.reading.gloss)),
        grain: median(good.map(c => c.reading.grain)),
        reliable: sourceKind === 'photo',
        samples: good.length,
      }
    : null;

  return { ok: true, cells, exposure, H, flipped, markers: pts, sourceKind, physics };
}
