// src/calib/sheetPdf.ts
//
// Печатный калибровочный бланк.
//
// Геометрия (метки, шкала, рамки) рисуется ВЕКТОРОМ в оттенках серого:
// jsPDF с одним аргументом в setFillColor пишет DeviceGray, то есть в PDF
// уходит честный чёрный без примеси цвета. Кириллица кладётся отдельным
// растровым слоем, потому что встроенные шрифты jsPDF её не знают, а тащить
// кириллический шрифт в бандл ради одного бланка — дорого.
//
// Про масштаб при печати: «вписать в страницу» бланк не ломает. Метки
// масштабируются вместе с сеткой, а гомография строится ровно по четырём
// меткам — любое равномерное сжатие она снимает автоматически.

import { PAINT_PROFILES, SURFACE_PROFILES, type PaintType, type SurfaceType } from '../config';
import {
  MARKER, WEDGE, GRID, CELLS_PER_PAGE,
  cellBoxMm, cellOriginMm, SHEET_W_MM, SHEET_H_MM,
} from './sheetSpec';

export interface SheetParams {
  /**
   * Названия красок по ячейкам. Пустая строка = ячейка без подписи: под ней
   * печатается линейка для записи от руки, а имя приложение подберёт само
   * после скана. Длина массива задаёт число ячеек; больше 20 — бланк станет
   * многостраничным.
   */
  colorNames: string[];
  paintType: PaintType;
  surfaceType: SurfaceType;
  /** Подпись набора, если калибруется конкретный набор. */
  setName?: string;
}

const TEXT_DPI = 200;
const MM_PER_IN = 25.4;

interface PageText {
  page: number;
  pages: number;
  pageNames: string[];
  paintName: string;
  surfaceName: string;
  dateStr: string;
  setName?: string;
  /** Есть ли на странице ячейки без подписи. */
  anyBlank: boolean;
}

/** Весь текст страницы одним PNG: меньше объектов в PDF и никакой возни с выравниванием. */
function makeTextLayer(p: PageText): string {
  const c = document.createElement('canvas');
  c.width = Math.round((SHEET_W_MM / MM_PER_IN) * TEXT_DPI);
  c.height = Math.round((SHEET_H_MM / MM_PER_IN) * TEXT_DPI);
  const ctx = c.getContext('2d')!;
  // После этого масштабирования рисуем прямо в миллиметрах листа.
  ctx.scale(TEXT_DPI / MM_PER_IN, TEXT_DPI / MM_PER_IN);
  ctx.textBaseline = 'alphabetic';

  ctx.font = 'bold 7px sans-serif';
  ctx.fillStyle = '#000';
  ctx.fillText('MELURA', 15, 47);
  ctx.font = 'bold 3.2px sans-serif';
  ctx.fillStyle = '#555';
  ctx.fillText('КАЛИБРОВОЧНЫЙ БЛАНК', 15, 52);

  ctx.font = '3.2px sans-serif';
  ctx.fillStyle = '#111';
  const info = [`Краска: ${p.paintName}`, `Поверхность: ${p.surfaceName}`, `Дата: ${p.dateStr}`];
  if (p.setName) info.unshift(`Набор: ${p.setName}`);
  info.forEach((t, i) => ctx.fillText(t, 105, 43 + i * 4.2));

  if (p.pages > 1) {
    ctx.font = 'bold 3px sans-serif';
    ctx.fillStyle = '#666';
    ctx.fillText(`Лист ${p.page + 1} из ${p.pages}`, 15, 57);
  }

  ctx.font = 'bold 2.6px sans-serif';
  ctx.fillStyle = '#444';
  ctx.fillText('КОНТРОЛЬНАЯ ШКАЛА. ЗАКРАШИВАНИЕ НЕ ДОПУСКАЕТСЯ', WEDGE.xMm, WEDGE.yMm - 1.8);

  // Подписи ступеней — под шкалой, чтобы не залезать в замеряемое поле.
  ctx.font = '2.4px sans-serif';
  ctx.fillStyle = '#666';
  ctx.textAlign = 'center';
  for (let i = 0; i < WEDGE.steps.length; i++) {
    ctx.fillText(
      `${Math.round(WEDGE.steps[i] * 100)}%`,
      WEDGE.xMm + WEDGE.patchWMm * (i + 0.5),
      WEDGE.yMm + WEDGE.patchHMm + 3.4,
    );
  }
  ctx.textAlign = 'left';

  // Номер и название краски под каждой рамкой.
  for (let i = 0; i < p.pageNames.length; i++) {
    const o = cellOriginMm(i);
    const num = p.page * CELLS_PER_PAGE + i + 1;

    ctx.font = 'bold 3.4px sans-serif';
    ctx.fillStyle = '#000';
    ctx.fillText(String(num), o.x + GRID.boxOffXMm, o.y + GRID.labelYMm);

    const full = p.pageNames[i] || '';
    const labelX = o.x + GRID.boxOffXMm + 5.5;
    const maxW = GRID.boxWMm - 7;

    if (!full) {
      // Ячейка без имени. Приложение назовёт краску само по измеренному цвету,
      // но линейку всё равно печатаем: кто-то захочет подписать от руки, и это
      // ничего не стоит. Линия тонкая и светлая — в окно замера она не попадает.
      ctx.strokeStyle = '#bbb';
      ctx.lineWidth = 0.15;
      ctx.beginPath();
      ctx.moveTo(labelX, o.y + GRID.labelYMm + 0.6);
      ctx.lineTo(labelX + maxW, o.y + GRID.labelYMm + 0.6);
      ctx.stroke();
      continue;
    }

    ctx.font = '2.9px sans-serif';
    ctx.fillStyle = '#333';
    // Длинные названия обрезаем: подпись не должна залезть в соседнюю колонку
    // и накрыть точку замера бумаги.
    let label = full;
    if (ctx.measureText(label).width > maxW) {
      while (label.length > 1 && ctx.measureText(label + '…').width > maxW) label = label.slice(0, -1);
      label += '…';
    }
    ctx.fillText(label, labelX, o.y + GRID.labelYMm);
  }

  // Правила съёмки печатаем на самом бланке: пользователь смотрит на лист,
  // а не в приложение, когда наносит краску и фотографирует.
  ctx.font = 'bold 2.6px sans-serif';
  ctx.fillStyle = '#000';
  ctx.fillText('ПОРЯДОК СЪЁМКИ', 36, 272);
  ctx.font = '2.5px sans-serif';
  ctx.fillStyle = '#333';
  const rules = [
    p.anyBlank
      ? 'Заполните квадраты плотно, до краёв. Порядок нанесения произволен.'
      : 'Заполните квадраты плотно, до краёв, в соответствии с подписями.',
    'Дождитесь полного высыхания краски.',
    'Освещение: дневной свет без прямых солнечных лучей либо лампа 5000–6500 K.',
    'Съёмка без вспышки. Камера располагается параллельно листу, без затенения.',
    'В кадр должен попасть весь лист, включая четыре угловые метки.',
  ];
  rules.filter(Boolean).forEach((t, i) => ctx.fillText(`${i + 1}. ${t}`, 36, 275 + i * 3.2));

  ctx.font = '2.3px sans-serif';
  ctx.fillStyle = '#777';
  ctx.fillText('Печать: формат A4, режим градаций серого. Масштаб не влияет на результат.', 36, 292);

  return c.toDataURL('image/png');
}

function drawMarker(pdf: any, cx: number, cy: number) {
  const o = MARKER.outerMm, m = MARKER.midMm, i = MARKER.innerMm;
  pdf.setFillColor(0);
  pdf.rect(cx - o / 2, cy - o / 2, o, o, 'F');
  pdf.setFillColor(255);
  pdf.rect(cx - m / 2, cy - m / 2, m, m, 'F');
  pdf.setFillColor(0);
  pdf.rect(cx - i / 2, cy - i / 2, i, i, 'F');
}

export async function generateCalibrationSheet(params: SheetParams): Promise<Blob> {
  const { jsPDF } = await import('jspdf');
  const pdf = new jsPDF({ orientation: 'p', unit: 'mm', format: 'a4', compress: true });

  const names = params.colorNames.length ? params.colorNames : [''];
  const pages = Math.max(1, Math.ceil(names.length / CELLS_PER_PAGE));

  const paintName = PAINT_PROFILES[params.paintType]?.name ?? '—';
  const surfaceName = SURFACE_PROFILES[params.surfaceType]?.name ?? '—';
  const dateStr = new Date().toLocaleDateString('ru-RU');

  for (let page = 0; page < pages; page++) {
    if (page > 0) pdf.addPage();
    const pageNames = names.slice(page * CELLS_PER_PAGE, (page + 1) * CELLS_PER_PAGE);

    // Текстовый слой идёт ПЕРВЫМ. Он прозрачный, но порядок выбран на случай,
    // если просмотрщик или драйвер принтера не поймёт альфа-канал PNG: тогда
    // лист просто станет белым, а вектор поверх всё равно напечатается.
    // В обратном порядке белый прямоугольник закрыл бы метки, и бланк стал бы
    // нечитаемым для сканера.
    pdf.addImage(
      makeTextLayer({
        page, pages, pageNames, paintName, surfaceName, dateStr,
        setName: params.setName,
        anyBlank: pageNames.some(n => !n),
      }),
      'PNG', 0, 0, SHEET_W_MM, SHEET_H_MM,
    );

    for (const c of MARKER.centers) drawMarker(pdf, c.x, c.y);

    for (let i = 0; i < WEDGE.steps.length; i++) {
      // Один числовой аргумент = DeviceGray: в PDF уходит чистый K без примеси цвета.
      (pdf as any).setFillColor(Math.round(255 * (1 - WEDGE.steps[i])));
      pdf.rect(WEDGE.xMm + i * WEDGE.patchWMm, WEDGE.yMm, WEDGE.patchWMm, WEDGE.patchHMm, 'F');
    }
    pdf.setDrawColor(0);
    pdf.setLineWidth(0.2);
    pdf.rect(WEDGE.xMm, WEDGE.yMm, WEDGE.patchWMm * WEDGE.steps.length, WEDGE.patchHMm);

    // Рамки под мазки: только контур. Любая заливка внутри попала бы в замер.
    pdf.setLineWidth(0.25);
    pdf.setDrawColor(120);
    for (let i = 0; i < pageNames.length; i++) {
      const b = cellBoxMm(i);
      pdf.rect(b.x, b.y, b.w, b.h);
    }
  }

  return pdf.output('blob');
}
