// src/generator/components/SchemeEditor.tsx
// Ручной редактор готовой раскраски. Работает поверх result.labelMask + палитры:
// выделение зон, перекраска, удаление/слияние, перемещение, правка геометрии
// кистью и рисование своих зон. Любая правка, меняющая геометрию, отдаётся в
// ядро на ре-векторизацию (vectorize_mask) — контуры/номера строятся заново.
// Экспортирует хук useSchemeEditor(canvasRef) и панель EditorToolbar — в едином
// визуальном стиле приложения (как «Защита»).
import { useEffect, useRef, useState, useCallback } from "react";
import { useAppStore } from "../store";
import { cn } from "../../utils/cn";
import { revectorize } from "../utils/imageProcessing/workerManager";
import { zoneClosedPath } from "../utils/schemeViewport";
import { smartCleanup } from "../utils/smartCleanup";
import type { ProcessingResult } from "../utils/imageProcessing/types";
import type { EditTool } from "../store/types";
import {
  imageKeyOf, buildEditSet, editSetMask, saveEditSetDB, loadEditSetDB,
  exportEditSetFile, importEditSetFile, type EditSet,
} from "../utils/editPersistence";

type RGB = [number, number, number];

function buildPaletteArray(colorPalette: Record<number, RGB>): RGB[] {
  let maxL = -1;
  for (const k of Object.keys(colorPalette)) maxL = Math.max(maxL, Number(k));
  const arr: RGB[] = [];
  for (let i = 0; i <= maxL; i++) arr[i] = colorPalette[i] || [255, 255, 255];
  return arr;
}

// Связная область (4-связность) одного label вокруг стартового пикселя.
function floodRegion(mask: Uint8Array, w: number, h: number, start: number): number[] {
  const target = mask[start];
  const out: number[] = [];
  const seen = new Uint8Array(mask.length);
  const stack = [start];
  seen[start] = 1;
  while (stack.length) {
    const p = stack.pop()!;
    out.push(p);
    const x = p % w, y = (p / w) | 0;
    if (x > 0 && !seen[p - 1] && mask[p - 1] === target) { seen[p - 1] = 1; stack.push(p - 1); }
    if (x < w - 1 && !seen[p + 1] && mask[p + 1] === target) { seen[p + 1] = 1; stack.push(p + 1); }
    if (y > 0 && !seen[p - w] && mask[p - w] === target) { seen[p - w] = 1; stack.push(p - w); }
    if (y < h - 1 && !seen[p + w] && mask[p + w] === target) { seen[p + w] = 1; stack.push(p + w); }
  }
  return out;
}

// Подсветка выделения по РЕАЛЬНЫМ контурам зон (cd.points — те же, что использует
// заливка схемы), а не по границе пиксельной маски. Тогда выделение в точности
// повторяет форму зоны. Вложенные НЕвыбранные зоны вырезаются из заливки (even-odd).
// Надёжная внутренняя точка полигона: середина самого широкого горизонтального
// пролёта на вертикали-центре. В отличие от центроида/позиции номера, ГАРАНТИРОВАННО
// лежит внутри зоны (в т.ч. для вогнутых/тонких) — иначе зона «фактически выбрана,
// но не подсвечивается».
function representativePoint(poly: [number, number][]): [number, number] {
  let minY = Infinity, maxY = -Infinity;
  for (const p of poly) { if (p[1] < minY) minY = p[1]; if (p[1] > maxY) maxY = p[1]; }
  const yc = (minY + maxY) / 2;
  const xs: number[] = [];
  const n = poly.length;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const yi = poly[i][1], yj = poly[j][1];
    if ((yi > yc) !== (yj > yc)) {
      const t = (yc - yi) / (yj - yi);
      xs.push(poly[i][0] + t * (poly[j][0] - poly[i][0]));
    }
  }
  xs.sort((a, b) => a - b);
  let bx = poly[0][0], bw = -1;
  for (let k = 0; k + 1 < xs.length; k += 2) {
    const w = xs[k + 1] - xs[k];
    if (w > bw) { bw = w; bx = (xs[k] + xs[k + 1]) / 2; }
  }
  return [bx, yc];
}

// Пиксель, ГАРАНТИРОВАННО принадлежащий зоне контура (labelMask == labelId и
// точка внутри полигона). Раньше выбранность зоны проверяли по одной
// representativePoint, и для тонких/мелких зон она округлялась ЗА пределы зоны —
// зона выделялась «по факту» (пиксели в маске), но не подсвечивалась. Теперь
// берём достоверный внутренний пиксель: центр → подписи → representative → скан
// bbox. Это чинит неподсвечиваемые микрозоны раз и навсегда.
function zoneTestPixel(
  contour: ProcessingResult["contoursData"][number],
  labelMask: Uint8Array, W: number, H: number,
): number {
  const L = contour.labelId;
  const tryPt = (cx: number, cy: number): number => {
    const px = Math.round(cx), py = Math.round(cy);
    if (px < 0 || px >= W || py < 0 || py >= H) return -1;
    const idx = py * W + px;
    if (labelMask[idx] === L && pointInPoly(contour.points, px + 0.5, py + 0.5)) return idx;
    return -1;
  };
  if (contour.center) { const t = tryPt(contour.center[0], contour.center[1]); if (t >= 0) return t; }
  if (contour.labelPositions) for (const lp of contour.labelPositions) { const t = tryPt(lp.x, lp.y); if (t >= 0) return t; }
  { const [rx, ry] = representativePoint(contour.points); const t = tryPt(rx, ry); if (t >= 0) return t; }
  // Крайний случай (совсем тонкая зона): скан ограничивающего прямоугольника.
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const p of contour.points) { if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0]; if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1]; }
  x0 = Math.max(0, Math.floor(x0)); y0 = Math.max(0, Math.floor(y0));
  x1 = Math.min(W - 1, Math.ceil(x1)); y1 = Math.min(H - 1, Math.ceil(y1));
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
    if (labelMask[y * W + x] === L && pointInPoly(contour.points, x + 0.5, y + 0.5)) return y * W + x;
  }
  return -1;
}

function buildSelContourPaths(
  contours: ProcessingResult["contoursData"],
  sel: Uint8Array, labelMask: Uint8Array, W: number, H: number,
): { fill: Path2D; stroke: Path2D } {
  const N = contours.length;
  const testPx: number[] = new Array(N);
  for (let i = 0; i < N; i++) testPx[i] = zoneTestPixel(contours[i], labelMask, W, H);
  const isSel = (i: number) => testPx[i] >= 0 && sel[testPx[i]] === 1;
  const selIdx: number[] = [];
  for (let i = 0; i < N; i++) if (isSel(i)) selIdx.push(i);

  const fill = new Path2D(), stroke = new Path2D();
  // Та же сглаженная геометрия, что у заливки/контура схемы — выделение точно совпадает.
  for (const i of selIdx) {
    const sp = zoneClosedPath(contours[i].points);
    fill.addPath(sp);
    stroke.addPath(sp);
  }
  // Вложенные НЕвыбранные зоны — вырезаем из заливки (even-odd). bbox-фильтр ускоряет.
  const bboxes = selIdx.map((i) => {
    const pts = contours[i].points;
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const p of pts) { if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0]; if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1]; }
    return [x0, y0, x1, y1];
  });
  for (let i = 0; i < N; i++) {
    if (isSel(i) || testPx[i] < 0) continue;
    const px = testPx[i] % W, py = Math.floor(testPx[i] / W);
    for (let b = 0; b < selIdx.length; b++) {
      const bb = bboxes[b];
      if (px < bb[0] || px > bb[2] || py < bb[1] || py > bb[3]) continue;
      if (pointInPoly(contours[selIdx[b]].points, px + 0.5, py + 0.5)) { fill.addPath(zoneClosedPath(contours[i].points)); break; }
    }
  }
  return { fill, stroke };
}

// Точка внутри полигона (ray-casting).
function pointInPoly(poly: [number, number][], x: number, y: number): boolean {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1], xj = poly[j][0], yj = poly[j][1];
    if (((yi > y) !== (yj > y)) && (x < ((xj - xi) * (y - yi)) / (yj - yi) + xi)) inside = !inside;
  }
  return inside;
}

// Растеризация правки узлов: переносим в labelMask ТОЛЬКО «полосу» между старым и
// новым полигоном (симметрическая разность). Пиксели, попавшие внутрь по-новому —
// отдаём зоне (рост в сторону соседа); ушедшие наружу — ближайшему соседу (сжатие).
// Всё, что внутри обоих полигонов (в т.ч. вложенные зоны-дырки) — не трогаем.
function rasterizeNodeEdit(
  orig: [number, number][], edited: [number, number][], label: number,
  mask: Uint8Array, W: number, H: number,
): Uint8Array {
  let minX = W, minY = H, maxX = 0, maxY = 0;
  for (const poly of [orig, edited]) for (const [px, py] of poly) {
    if (px < minX) minX = px; if (px > maxX) maxX = px;
    if (py < minY) minY = py; if (py > maxY) maxY = py;
  }
  minX = Math.max(0, Math.floor(minX) - 2); minY = Math.max(0, Math.floor(minY) - 2);
  maxX = Math.min(W - 1, Math.ceil(maxX) + 2); maxY = Math.min(H - 1, Math.ceil(maxY) + 2);
  const tw = Math.max(1, maxX - minX + 1), th = Math.max(1, maxY - minY + 1);

  // Маска «внутри полигона» тем же способом, что и ПРЕВЬЮ узлов (заливка canvas,
  // nonzero winding). Раньше коммит использовал even-odd ray-casting, и при
  // самопересечении полигона (когда узел тянут далеко) результат расходился с превью.
  const c = document.createElement("canvas");
  c.width = tw; c.height = th;
  const ctx = c.getContext("2d", { willReadFrequently: true });
  const polyMask = (poly: [number, number][]): Uint8Array => {
    const m = new Uint8Array(tw * th);
    if (!ctx || poly.length < 3) return m;
    ctx.clearRect(0, 0, tw, th);
    ctx.beginPath();
    ctx.moveTo(poly[0][0] - minX, poly[0][1] - minY);
    for (let i = 1; i < poly.length; i++) ctx.lineTo(poly[i][0] - minX, poly[i][1] - minY);
    ctx.closePath();
    ctx.fillStyle = "#fff";
    ctx.fill(); // nonzero — как и превью
    const d = ctx.getImageData(0, 0, tw, th).data;
    for (let k = 0; k < m.length; k++) m[k] = d[k * 4 + 3] > 127 ? 1 : 0;
    return m;
  };
  const oM = polyMask(orig), nM = polyMask(edited);

  const nm = mask.slice();
  for (let y = minY; y <= maxY; y++) {
    for (let x = minX; x <= maxX; x++) {
      const li = (y - minY) * tw + (x - minX);
      const oIn = oM[li], nIn = nM[li];
      if (oIn === nIn) continue;
      const i = y * W + x;
      if (nIn && !oIn) {
        nm[i] = label; // рост зоны в сторону соседа
      } else if (oIn && !nIn && mask[i] === label) {
        // сжатие: отдать ближайшему 4-соседу с другим label
        const nb = [x > 0 ? i - 1 : -1, x < W - 1 ? i + 1 : -1, y > 0 ? i - W : -1, y < H - 1 ? i + W : -1];
        for (const j of nb) if (j >= 0 && mask[j] !== label) { nm[i] = mask[j]; break; }
      }
    }
  }
  return nm;
}

export interface EditorCtrl {
  active: boolean;
  tool: EditTool;
  onPointerDown: (e: React.PointerEvent) => void;
  onPointerMove: (e: React.PointerEvent) => void;
  onPointerUp: (e: React.PointerEvent) => void;
  hasSelection: boolean;
  busy: boolean;
  recolor: () => void;
  del: () => void;
  merge: () => void;
  smartClean: () => void;
  cleanLevel: number;
  setCleanLevel: (n: number) => void;
  cleanNote: string | null;
  clearSelection: () => void;
  undo: () => void;
  redo: () => void;
  exit: () => void;
  save: () => void;
  loadFromFile: (file: File) => void;
  applyDbSet: () => void;
  hasDbSet: boolean;
  neighborColors: [number, number, number][];
}

export function useSchemeEditor(
  canvasRef: React.RefObject<HTMLCanvasElement | null>,
  viewRef: React.MutableRefObject<{ x: number; y: number; z: number }>,
  containerRef: React.RefObject<HTMLElement | null>,
  editRedrawRef?: React.MutableRefObject<(() => void) | null>,
): EditorCtrl {
  const active = useAppStore((s) => s.editModeActive);
  const tool = useAppStore((s) => s.editTool);
  const brushSize = useAppStore((s) => s.editBrushSize);
  const editColor = useAppStore((s) => s.editColor);
  const busy = useAppStore((s) => s.editBusy);
  const result = useAppStore((s) => s.result);
  const dims = useAppStore((s) => s.imageDimensions);
  const imageFile = useAppStore((s) => s.imageFile);
  const update = useAppStore((s) => s.update);

  const [dbSet, setDbSet] = useState<EditSet | null>(null);
  const [neighborColors, setNeighborColors] = useState<RGB[]>([]);

  // Рабочая маска-выделение (1 = выделено), список выделенных label и «ведущий» пиксель.
  const selRef = useRef<Uint8Array | null>(null);
  const selLabelsRef = useRef<Set<number>>(new Set());
  const selPathRef = useRef<{ fill: Path2D; stroke: Path2D } | null>(null); // кэш путей выделения
  const paintOffscreenRef = useRef<HTMLCanvasElement | null>(null); // предпросмотр мазка
  const [selCount, setSelCount] = useState(0);

  // Сила умной очистки: 1 — только явно непригодное, 2 — обычная (по умолчанию),
  // 3 — требовать заметно крупных зон. Уровень задаёт МИНИМАЛЬНЫЙ РАЗМЕР зоны на
  // бумаге, а не то, насколько сильно позволено менять картину: допустимое
  // изменение цвета остаётся жёстким на всех уровнях.
  const [cleanLevel, setCleanLevelState] = useState<1 | 2 | 3>(2);
  const [cleanNote, setCleanNote] = useState<string | null>(null);

  // Undo/redo — снимки готового result (быстро и точно, без ре-векторизации).
  const undoRef = useRef<ProcessingResult[]>([]);
  const redoRef = useRef<ProcessingResult[]>([]);
  const CAP = 10; // глубина undo (каждый снимок — полный результат; бережём память)

  // Жест (кисть/рисование/перемещение/прямоугольное выделение).
  type Pt = { x: number; y: number };
  const g = useRef<{ active: boolean; mode: "none" | "paint" | "move" | "rect" | "node"; last: Pt | null; paint: Uint8Array | null; moveStart: Pt | null; rectStart: Pt | null; movePath: { fill: Path2D; stroke: Path2D } | null }>(
    { active: false, mode: "none", last: null, paint: null, moveStart: null, rectStart: null, movePath: null }
  );

  // Правка формы контура по узлам («Форма»).
  type NodeEdit = {
    label: number;
    nodes: [number, number][];       // редактируемый полигон (полное разрешение)
    orig: [number, number][];        // исходный полигон (для растеризации XOR-полосы)
    handleIdx: number[];             // индексы узлов-ручек (прорежённые)
    grabbed: number;                 // индекс узла, за который тянем; -1 — нет
    base: [number, number][] | null; // снимок nodes на момент захвата
    grabStart: Pt | null;
    moved: boolean;
  };
  const nodeRef = useRef<NodeEdit | null>(null);
  const [nodeVer, setNodeVer] = useState(0);
  const bumpNode = useCallback(() => setNodeVer((v) => v + 1), []);

  const W = dims?.w || result?.imgW || 0;
  const H = dims?.h || result?.imgH || 0;

  const setCounts = useCallback(() => {
    update({ editSelCount: selLabelsRef.current.size, editUndoCount: undoRef.current.length, editRedoCount: redoRef.current.length });
  }, [update]);

  // Очистка выделения при выходе/смене фото/результата.
  useEffect(() => {
    if (!active) {
      selRef.current = null; selLabelsRef.current = new Set(); setSelCount(0);
      undoRef.current = []; redoRef.current = [];
      setCounts();
    }
  }, [active, setCounts]);

  // Готовит контекст оверлея редактора: canvas размером с контейнер в реальном
  // разрешении экрана, а рисование — в координатах ИЗОБРАЖЕНИЯ под текущий пан/зум.
  // Так выделение/узлы чёткие (векторные) на любом увеличении, как и сама схема.
  const setupDisplay = useCallback((): { ctx: CanvasRenderingContext2D; vs: number } | null => {
    const c = canvasRef.current, cont = containerRef.current;
    if (!c || !cont) return null;
    const dpr = Math.min(2, (typeof window !== "undefined" ? window.devicePixelRatio : 1) || 1);
    const bw = Math.max(1, Math.round(cont.clientWidth * dpr));
    const bh = Math.max(1, Math.round(cont.clientHeight * dpr));
    if (c.width !== bw) c.width = bw;
    if (c.height !== bh) c.height = bh;
    const ctx = c.getContext("2d");
    if (!ctx) return null;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, bw, bh);
    const v = viewRef.current;
    const s = v.z * dpr;
    ctx.setTransform(s, 0, 0, s, v.x * dpr, v.y * dpr);
    return { ctx, vs: 1 / v.z }; // vs — множитель «экранно-постоянных» размеров
  }, [canvasRef, containerRef, viewRef]);

  // Рисуем подсветку выделения (заливка + чёткая обводка по точным границам),
  // рамку прямоугольного выделения и курсор кисти.
  const redraw = useCallback((cursor?: { x: number; y: number }, rect?: { x: number; y: number; w: number; h: number }) => {
    if (!active) return;
    const disp = setupDisplay();
    if (!disp) return;
    const ctx = disp.ctx;
    const vs = disp.vs;
    const sel = selRef.current;
    if (sel && result) {
      // Подсветка — строго по границе МАСКИ выделения (реальные выделенные пиксели).
      // even-odd исключает дырки: вложенные зоны другого цвета НЕ тонируются.
      const sp = selPathRef.current || (selPathRef.current = buildSelContourPaths(result.contoursData, sel, result.labelMask, W, H));
      ctx.lineJoin = "round"; ctx.lineCap = "round";
      ctx.fillStyle = "rgba(99,102,241,0.28)";
      ctx.fill(sp.fill, "evenodd");
      ctx.strokeStyle = "rgba(79,70,229,0.95)";
      ctx.lineWidth = 1.4 * vs;
      ctx.stroke(sp.stroke);
    }
    if (rect) {
      ctx.strokeStyle = "rgba(99,102,241,0.95)";
      ctx.lineWidth = 1.5 * vs;
      ctx.setLineDash([4 * vs, 3 * vs]);
      ctx.strokeRect(rect.x + 0.5, rect.y + 0.5, rect.w, rect.h);
      ctx.setLineDash([]);
    }
    // Узлы правки формы контура.
    if (tool === "node" && nodeRef.current) {
      const ne = nodeRef.current;
      const poly = ne.nodes;
      if (poly.length >= 2) {
        ctx.beginPath();
        ctx.moveTo(poly[0][0], poly[0][1]);
        for (let i = 1; i < poly.length; i++) ctx.lineTo(poly[i][0], poly[i][1]);
        ctx.closePath();
        ctx.fillStyle = "rgba(99,102,241,0.10)";
        ctx.fill();
        ctx.strokeStyle = "rgba(79,70,229,0.95)";
        ctx.lineWidth = 1.2 * vs;
        ctx.stroke();
      }
      for (const hi of ne.handleIdx) {
        const nx = ne.nodes[hi][0], ny = ne.nodes[hi][1];
        const gr = hi === ne.grabbed;
        ctx.beginPath();
        ctx.arc(nx, ny, (gr ? 4.5 : 3) * vs, 0, Math.PI * 2);
        ctx.fillStyle = gr ? "#4f46e5" : "#ffffff";
        ctx.fill();
        ctx.lineWidth = 1.4 * vs;
        ctx.strokeStyle = "#4f46e5";
        ctx.stroke();
      }
    }

    if (cursor && (tool === "brush" || tool === "draw")) {
      ctx.beginPath();
      ctx.arc(cursor.x, cursor.y, brushSize, 0, Math.PI * 2);
      ctx.strokeStyle = "rgba(99,102,241,0.9)";
      ctx.lineWidth = 1.5 * vs;
      ctx.stroke();
    }
  }, [active, tool, brushSize, result, setupDisplay]);

  useEffect(() => { redraw(); }, [redraw, selCount, nodeVer]);

  // Даём usePanZoom перерисовывать оверлей при пане/зуме (чтобы выделение следовало
  // за видом в разрешении экрана).
  useEffect(() => {
    if (editRedrawRef) editRedrawRef.current = redraw;
    return () => { if (editRedrawRef) editRedrawRef.current = null; };
  }, [editRedrawRef, redraw]);

  // Сброс узлов правки формы при смене инструмента / выходе из редактора.
  useEffect(() => {
    nodeRef.current = null;
    bumpNode();
  }, [tool, active, bumpNode]);

  // Цвета зон, СОСЕДНИХ с выделением — для быстрой перекраски без пипетки.
  useEffect(() => {
    if (!active || !result || !selRef.current) { setNeighborColors([]); return; }
    const sel = selRef.current, m = result.labelMask;
    const freq = new Map<number, number>();
    for (let i = 0; i < sel.length; i++) {
      if (!sel[i]) continue;
      const x = i % W, y = (i / W) | 0;
      const nb = [x > 0 ? i - 1 : -1, x < W - 1 ? i + 1 : -1, y > 0 ? i - W : -1, y < H - 1 ? i + W : -1];
      for (const j of nb) if (j >= 0 && !sel[j]) freq.set(m[j], (freq.get(m[j]) || 0) + 1);
    }
    const labs = [...freq.entries()].sort((a, b) => b[1] - a[1]).map((e) => e[0]);
    const seen = new Set<string>(); const out: RGB[] = [];
    for (const l of labs) {
      const c = result.colorPalette[l];
      if (!c) continue;
      const key = c.join(",");
      if (!seen.has(key)) { seen.add(key); out.push([...c] as RGB); }
    }
    setNeighborColors(out);
  }, [active, result, selCount, W, H]);

  const toImg = useCallback((e: React.PointerEvent) => {
    // Оверлей теперь фикс по контейнеру; координаты изображения получаем через вид.
    const cont = containerRef.current;
    const r = cont ? cont.getBoundingClientRect() : canvasRef.current!.getBoundingClientRect();
    const v = viewRef.current;
    return {
      x: Math.max(0, Math.min(W - 1, Math.floor((e.clientX - r.left - v.x) / v.z))),
      y: Math.max(0, Math.min(H - 1, Math.floor((e.clientY - r.top - v.y) / v.z))),
    };
  }, [canvasRef, containerRef, viewRef, W, H]);

  const refreshSel = useCallback(() => {
    // Пересчитываем список label в выделении + счётчики + перерисовка.
    selPathRef.current = null; // граница выделения изменилась — пересобрать
    const sel = selRef.current;
    const labels = new Set<number>();
    if (sel && result) {
      for (let i = 0; i < sel.length; i++) if (sel[i]) labels.add(result.labelMask[i]);
    }
    selLabelsRef.current = labels;
    setSelCount((v) => v + 1);
    setCounts();
  }, [result, setCounts]);

  const clearSelection = useCallback(() => {
    selRef.current = null; selLabelsRef.current = new Set(); refreshSel();
  }, [refreshSel]);

  // Применить новую маску: снимок в undo, ре-векторизация, запись результата.
  const commit = useCallback(async (newMask: Uint8Array, paletteArr: RGB[]) => {
    if (!result) return;
    undoRef.current.push(result);
    if (undoRef.current.length > CAP) undoRef.current.shift();
    redoRef.current = [];
    update({ editBusy: true });
    try {
      const res = await revectorize(newMask, paletteArr, W, H, result.autoDetail || 5);
      selRef.current = null; selLabelsRef.current = new Set(); selPathRef.current = null;
      update({ result: res, editBusy: false, activeColors: new Set(res.validLabels) });
      setSelCount((v) => v + 1);
      setCounts();
    } catch (err) {
      update({ editBusy: false });
      console.warn("revectorize failed", err);
    }
  }, [result, W, H, update, setCounts]);

  // --- ВЫДЕЛЕНИЕ ---
  // Клик по зоне: если она уже выделена — снять выделение с неё (toggle);
  // иначе выделить (additive/shift/merge — добавить к текущему, иначе заменить).
  const selectAt = useCallback((x: number, y: number, additive: boolean) => {
    if (!result) return;
    const idx = y * W + x;
    const already = selRef.current && selRef.current[idx];
    const region = floodRegion(result.labelMask, W, H, idx);
    if (!selRef.current) selRef.current = new Uint8Array(W * H);
    if (already) {
      for (const p of region) selRef.current[p] = 0;
    } else {
      if (!additive) selRef.current.fill(0);
      for (const p of region) selRef.current[p] = 1;
    }
    refreshSel();
  }, [result, W, H, refreshSel]);

  // Прямоугольное выделение: выбирает только те зоны, что ЦЕЛИКОМ внутри рамки.
  // Зона, задетая рамкой лишь частично, в выделение не попадает.
  const selectRect = useCallback((a: { x: number; y: number }, b: { x: number; y: number }, additive: boolean) => {
    if (!result) return;
    const x0 = Math.min(a.x, b.x), x1 = Math.max(a.x, b.x);
    const y0 = Math.min(a.y, b.y), y1 = Math.max(a.y, b.y);
    if (!selRef.current || !additive) selRef.current = new Uint8Array(W * H);
    const sel = selRef.current;
    const evaluated = new Uint8Array(W * H); // зоны, по которым уже принято решение
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        const idx = y * W + x;
        if (evaluated[idx]) continue;
        const region = floodRegion(result.labelMask, W, H, idx);
        let inside = true;
        for (const q of region) {
          evaluated[q] = 1;
          const qx = q % W, qy = (q / W) | 0;
          if (qx < x0 || qx > x1 || qy < y0 || qy > y1) inside = false;
        }
        if (inside) for (const q of region) sel[q] = 1;
      }
    }
    refreshSel();
  }, [result, W, H, refreshSel]);

  // --- ОПЕРАЦИИ ---
  const recolor = useCallback(() => {
    if (!result || !selRef.current || !editColor) return;
    const pal = buildPaletteArray(result.colorPalette);
    let target = pal.findIndex((c) => c[0] === editColor[0] && c[1] === editColor[1] && c[2] === editColor[2]);
    if (target < 0) { target = pal.length; pal.push([...editColor] as RGB); }
    const nm = result.labelMask.slice();
    for (let i = 0; i < nm.length; i++) if (selRef.current[i]) nm[i] = target;
    commit(nm, pal);
  }, [result, editColor, commit]);

  const del = useCallback(() => {
    if (!result || !selRef.current) return;
    const pal = buildPaletteArray(result.colorPalette);
    const sel = selRef.current, m = result.labelMask;
    // самый частый соседний (невыделенный) label
    const freq = new Map<number, number>();
    for (let i = 0; i < sel.length; i++) {
      if (!sel[i]) continue;
      const x = i % W, y = (i / W) | 0;
      const nb = [x > 0 ? i - 1 : -1, x < W - 1 ? i + 1 : -1, y > 0 ? i - W : -1, y < H - 1 ? i + W : -1];
      for (const j of nb) if (j >= 0 && !sel[j]) freq.set(m[j], (freq.get(m[j]) || 0) + 1);
    }
    let target = -1, best = -1;
    for (const [lab, c] of freq) if (c > best) { best = c; target = lab; }
    if (target < 0) return;
    const nm = m.slice();
    for (let i = 0; i < sel.length; i++) if (sel[i]) nm[i] = target;
    commit(nm, pal);
  }, [result, W, H, commit]);

  const merge = useCallback(() => {
    if (!result || !selRef.current) return;
    const pal = buildPaletteArray(result.colorPalette);
    const sel = selRef.current, m = result.labelMask;
    // цель — label с наибольшей площадью среди выделенных
    const area = new Map<number, number>();
    for (let i = 0; i < sel.length; i++) if (sel[i]) area.set(m[i], (area.get(m[i]) || 0) + 1);
    if (area.size < 2) return;
    let target = -1, best = -1;
    for (const [lab, a] of area) if (a > best) { best = a; target = lab; }
    const nm = m.slice();
    for (let i = 0; i < sel.length; i++) if (sel[i]) nm[i] = target;
    commit(nm, pal);
  }, [result, commit]);

  // Умная очистка схемы от нераскрашиваемых зон.
  //
  // Прежде это была пара действий: «Микрозоны» выделяла всё мелкое по площади,
  // «Убрать» растворяла выделенное в ближайшем по цвету соседе. Подход оказался
  // неверным по существу: зрительная значимость зоны не равна её площади.
  // Зрачок занимает десяток пикселей, но без него лицо мёртвое, а такая же по
  // площади крапина в листве не значит ничего — прежний алгоритм уничтожал обе.
  //
  // Теперь решение принимается по цене изменения (см. smartCleanup): почти
  // неотличимое от соседа растворяется, осмысленный акцент не удаляется, а
  // подрастает до размера, в который попадает кисть.
  const smartClean = useCallback(() => {
    if (!result) return;
    update({ editBusy: true });
    // Разбор синхронный и занимает доли секунды; отдаём браузеру кадр, чтобы
    // успел прорисоваться индикатор занятости.
    setTimeout(() => {
      try {
        const pal = buildPaletteArray(result.colorPalette);
        const res = smartCleanup(result.labelMask, W, H, result.colorPalette, {
          level: cleanLevel,
          validLabels: result.validLabels,
        });
        if (!res.changed) {
          update({ editBusy: false });
          setCleanNote("Нераскрашиваемых зон не найдено");
          return;
        }
        const parts = [`слито ${res.merged}`];
        if (res.grown) parts.push(`увеличено ${res.grown}`);
        if (res.kept) parts.push(`оставлено ${res.kept}`);
        parts.push(`максимальное изменение цвета ΔE ${res.maxDeltaE.toFixed(1)}`);
        setCleanNote(parts.join(", "));
        commit(res.mask, pal);
      } catch (err) {
        update({ editBusy: false });
        setCleanNote("Очистка не выполнена");
        console.warn("smartCleanup failed", err);
      }
    }, 30);
  }, [result, W, H, cleanLevel, commit, update]);

  const setCleanLevel = useCallback((n: number) => {
    setCleanLevelState((n === 1 || n === 3 ? n : 2) as 1 | 2 | 3);
    setCleanNote(null);
  }, []);

  // Итог очистки держим на виду недолго: это отчёт о выполненном действии,
  // а не постоянный элемент панели.
  useEffect(() => {
    if (!cleanNote) return;
    const t = setTimeout(() => setCleanNote(null), 6000);
    return () => clearTimeout(t);
  }, [cleanNote]);

  // --- КИСТЬ / РИСОВАНИЕ / ПЕРЕМЕЩЕНИЕ (жесты) ---
  const stampInto = useCallback((buf: Uint8Array, a: { x: number; y: number }, b: { x: number; y: number } | null) => {
    const r = brushSize;
    const steps = b ? Math.max(1, Math.ceil(Math.hypot(a.x - b.x, a.y - b.y))) : 1;
    for (let s = 0; s <= steps; s++) {
      const cx = b ? Math.round(b.x + (a.x - b.x) * (s / steps)) : a.x;
      const cy = b ? Math.round(b.y + (a.y - b.y) * (s / steps)) : a.y;
      for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
        if (dx * dx + dy * dy > r * r) continue;
        const x = cx + dx, y = cy + dy;
        if (x < 0 || y < 0 || x >= W || y >= H) continue;
        buf[y * W + x] = 1;
      }
    }
  }, [brushSize, W, H]);

  // --- ПРАВКА ФОРМЫ ПО УЗЛАМ ---
  // Загрузить узлы контура зоны под точкой (x,y) в редактор формы.
  const loadNodesAt = useCallback((x: number, y: number) => {
    if (!result) return;
    const lab = result.labelMask[y * W + x];
    let poly: [number, number][] | null = null;
    let bestD = Infinity, fallback: [number, number][] | null = null;
    for (const cd of result.contoursData) {
      if (cd.labelId !== lab) continue;
      const p = (cd.smoothPoints && cd.smoothPoints.length >= 3 ? cd.smoothPoints : cd.points) as [number, number][];
      if (!p || p.length < 3) continue;
      if (pointInPoly(p, x + 0.5, y + 0.5)) { poly = p; break; }
      const d = (cd.center[0] - x) ** 2 + (cd.center[1] - y) ** 2;
      if (d < bestD) { bestD = d; fallback = p; }
    }
    if (!poly) poly = fallback;
    if (!poly) { nodeRef.current = null; bumpNode(); return; }
    const src = poly.map((p) => [p[0], p[1]] as [number, number]);
    const stepN = Math.max(1, Math.round(src.length / 48)); // ~48 ручек максимум
    const handleIdx: number[] = [];
    for (let i = 0; i < src.length; i += stepN) handleIdx.push(i);
    nodeRef.current = {
      label: lab, nodes: src, orig: src.map((p) => [p[0], p[1]] as [number, number]),
      handleIdx, grabbed: -1, base: null, grabStart: null, moved: false,
    };
    bumpNode();
  }, [result, W, bumpNode]);

  const grabHandle = useCallback((x: number, y: number): number => {
    const ne = nodeRef.current; if (!ne) return -1;
    let bi = -1, bd = 11 * 11; // радиус захвата ручки (px изображения)
    for (const hi of ne.handleIdx) {
      const d = (ne.nodes[hi][0] - x) ** 2 + (ne.nodes[hi][1] - y) ** 2;
      if (d <= bd) { bd = d; bi = hi; }
    }
    return bi;
  }, []);

  // Тянем узел: смещаем захваченный узел и соседние по индексу с косинусным
  // затуханием — получается плавная «лепка» участка контура.
  const dragNode = useCallback((x: number, y: number) => {
    const ne = nodeRef.current;
    if (!ne || ne.grabbed < 0 || !ne.base || !ne.grabStart) return;
    const dx = x - ne.grabStart.x, dy = y - ne.grabStart.y;
    const n = ne.nodes.length;
    const RR = Math.max(2, Math.round(n / 14));
    for (let o = -RR; o <= RR; o++) {
      const idx = ((ne.grabbed + o) % n + n) % n;
      const w = 0.5 * (1 + Math.cos((Math.PI * o) / (RR + 1)));
      ne.nodes[idx][0] = ne.base[idx][0] + dx * w;
      ne.nodes[idx][1] = ne.base[idx][1] + dy * w;
    }
    ne.moved = true;
    bumpNode();
  }, [bumpNode]);

  const touchIds = useRef<Set<number>>(new Set()); // активные касания — для жеста двумя пальцами

  const onPointerDown = useCallback((e: React.PointerEvent) => {
    if (!active || !result || busy) return;
    // Средняя/правая кнопка — НЕ перехватываем: пусть работает панорама колёсиком.
    if (e.button === 1 || e.button === 2) return;
    if (e.pointerType === "touch") {
      touchIds.current.add(e.pointerId);
      // Второй палец = жест панорамы/зума: прекращаем операцию редактора и ничего
      // не коммитим (коммит только на pointerUp при active), чтобы не было случайных правок.
      if (touchIds.current.size >= 2) { g.current.active = false; redraw(); return; }
    }
    e.preventDefault(); e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    const p = toImg(e);
    if (tool === "pipette") {
      const lab = result.labelMask[p.y * W + p.x];
      const col = result.colorPalette[lab];
      if (col) update({ editColor: [...col] as [number, number, number], editTool: "recolor" });
      return;
    }
    if (tool === "node") {
      // Клик рядом с ручкой — захватываем узел; иначе загружаем контур зоны.
      const hi = nodeRef.current ? grabHandle(p.x, p.y) : -1;
      if (hi >= 0 && nodeRef.current) {
        nodeRef.current.grabbed = hi;
        nodeRef.current.base = nodeRef.current.nodes.map((q) => [q[0], q[1]] as [number, number]);
        nodeRef.current.grabStart = p;
        nodeRef.current.moved = false;
      } else {
        loadNodesAt(p.x, p.y);
      }
      g.current = { active: true, mode: "node", last: p, paint: null, moveStart: null, rectStart: null, movePath: null };
      return;
    }
    if (tool === "select" || tool === "merge" || tool === "recolor" || tool === "delete") {
      // жест: клик = одна зона (toggle), протяжка = рамка (пачка зон)
      g.current = { active: true, mode: "rect", last: p, paint: null, moveStart: null, rectStart: p, movePath: null };
      return;
    }
    if (tool === "brush" || tool === "draw") {
      // Кисть «Лепить границу» действует на ВЫДЕЛЕННУЮ зону. Если ничего не выделено —
      // сами выделяем зону под кликом, чтобы кисть работала без предварительного шага.
      if (tool === "brush" && (!selRef.current || selLabelsRef.current.size === 0)) {
        selectAt(p.x, p.y, false);
      }
      g.current = { active: true, mode: "paint", last: p, paint: new Uint8Array(W * H), moveStart: null, rectStart: null, movePath: null };
      stampInto(g.current.paint!, p, null);
      redraw(p);
      return;
    }
    if (tool === "move") {
      if (!selRef.current || !selRef.current[p.y * W + p.x]) { selectAt(p.x, p.y, false); }
      // Строим векторную границу выделения один раз — для чёткого предпросмотра сдвига.
      const mp = selRef.current ? buildSelContourPaths(result.contoursData, selRef.current, result.labelMask, W, H) : null;
      g.current = { active: true, mode: "move", last: p, paint: null, moveStart: p, rectStart: null, movePath: mp };
      return;
    }
  }, [active, result, busy, tool, toImg, selectAt, W, H, stampInto, redraw, update, grabHandle, loadNodesAt]);

  const onPointerMove = useCallback((e: React.PointerEvent) => {
    if (!active) return;
    if (touchIds.current.size >= 2) return; // идёт жест двумя пальцами — не рисуем
    const p = toImg(e);
    if (!g.current.active) { if (tool === "brush" || tool === "draw") redraw(p); return; }
    e.preventDefault(); e.stopPropagation();
    if (g.current.mode === "rect") {
      const s = g.current.rectStart!;
      redraw(undefined, { x: Math.min(s.x, p.x), y: Math.min(s.y, p.y), w: Math.abs(p.x - s.x), h: Math.abs(p.y - s.y) });
      return;
    }
    if (g.current.mode === "node") {
      if (nodeRef.current && nodeRef.current.grabbed >= 0) dragNode(p.x, p.y);
      return;
    }
    if (tool === "brush" || tool === "draw") {
      stampInto(g.current.paint!, p, g.current.last);
      g.current.last = p;
      // База (выделение + курсор).
      redraw(p);
      // Зелёный предпросмотр мазка строим на offscreen в разрешении изображения,
      // затем масштабируем (drawImage учитывает трансформацию контекста).
      const c = canvasRef.current!; const ctx = c.getContext("2d")!;
      const buf = g.current.paint!;
      const off = paintOffscreenRef.current || (paintOffscreenRef.current = document.createElement("canvas"));
      if (off.width !== W || off.height !== H) { off.width = W; off.height = H; }
      const octx = off.getContext("2d")!;
      const im = octx.createImageData(W, H);
      for (let i = 0; i < buf.length; i++) if (buf[i]) { im.data[i * 4] = 34; im.data[i * 4 + 1] = 197; im.data[i * 4 + 2] = 94; im.data[i * 4 + 3] = 150; }
      octx.putImageData(im, 0, 0);
      ctx.drawImage(off, 0, 0);
    } else if (tool === "move" && g.current.moveStart) {
      // Векторный ghost-предпросмотр смещения (чётко, в разрешении экрана).
      const dx = p.x - g.current.moveStart.x, dy = p.y - g.current.moveStart.y;
      const mp = g.current.movePath; if (!mp) return;
      const disp = setupDisplay(); if (!disp) return;
      const ctx = disp.ctx, vs = disp.vs;
      ctx.save();
      ctx.translate(dx, dy);
      ctx.lineJoin = "round"; ctx.lineCap = "round";
      ctx.fillStyle = "rgba(99,102,241,0.30)";
      ctx.fill(mp.fill, "evenodd");
      ctx.strokeStyle = "rgba(79,70,229,0.95)";
      ctx.lineWidth = 1.4 * vs;
      ctx.stroke(mp.stroke);
      ctx.restore();
    }
  }, [active, tool, toImg, stampInto, redraw, W, H, dragNode, setupDisplay]);

  const onPointerUp = useCallback((e: React.PointerEvent) => {
    if (e.pointerType === "touch") touchIds.current.delete(e.pointerId);
    if (!g.current.active || !result) { g.current.active = false; return; }
    e.preventDefault(); e.stopPropagation();
    const p = toImg(e);
    const pal = buildPaletteArray(result.colorPalette);

    // Прямоугольное выделение (протяжка) или одиночный клик (toggle зоны).
    if (g.current.mode === "rect") {
      const s = g.current.rectStart!;
      const dist = Math.hypot(p.x - s.x, p.y - s.y);
      g.current.active = false;
      // Ctrl/Cmd или Shift — добавить/снять зону поштучно; в «Слить» — всегда накопительно.
      const additive = e.ctrlKey || e.metaKey || e.shiftKey || tool === "merge";
      if (dist < 4) selectAt(p.x, p.y, additive);
      else selectRect(s, p, additive);
      redraw();
      return;
    }

    if (g.current.mode === "node") {
      g.current.active = false;
      const ne = nodeRef.current;
      if (ne && ne.moved && ne.grabbed >= 0) {
        // Растеризуем правку формы и ре-векторизуем (контуры/номера построятся заново).
        const nm = rasterizeNodeEdit(ne.orig, ne.nodes, ne.label, result.labelMask, W, H);
        nodeRef.current = null;
        commit(nm, pal);
      } else if (ne) {
        ne.grabbed = -1; ne.base = null; ne.grabStart = null; ne.moved = false;
        bumpNode();
      }
      return;
    }

    if (tool === "brush") {
      // Лепим границу ВЫДЕЛЕННОЙ зоны: растим (по умолчанию) или убираем (erase).
      const buf = g.current.paint!;
      const target = selLabelsRef.current.values().next().value;
      g.current.active = false;
      if (target === undefined) return;
      const src = result.labelMask;
      const nm = src.slice();
      const erase = useAppStore.getState().editBrushErase;
      if (!erase) {
        for (let i = 0; i < buf.length; i++) if (buf[i]) nm[i] = target;
      } else {
        for (let i = 0; i < buf.length; i++) {
          if (!buf[i] || src[i] !== target) continue;
          const x = i % W, y = (i / W) | 0;
          const nb = [x > 0 ? i - 1 : -1, x < W - 1 ? i + 1 : -1, y > 0 ? i - W : -1, y < H - 1 ? i + W : -1];
          for (const j of nb) if (j >= 0 && src[j] !== target) { nm[i] = src[j]; break; }
        }
      }
      commit(nm, pal);
      return;
    }
    if (tool === "draw") {
      // новая зона выбранным цветом
      const buf = g.current.paint!;
      const col = editColor || [128, 128, 128];
      let target = pal.findIndex((c) => c[0] === col[0] && c[1] === col[1] && c[2] === col[2]);
      if (target < 0) { target = pal.length; pal.push([...col] as RGB); }
      const nm = result.labelMask.slice();
      for (let i = 0; i < buf.length; i++) if (buf[i]) nm[i] = target;
      g.current.active = false;
      commit(nm, pal);
      return;
    }
    if (tool === "move" && g.current.moveStart) {
      const dx = p.x - g.current.moveStart.x, dy = p.y - g.current.moveStart.y;
      g.current.active = false;
      if (dx === 0 && dy === 0) return;
      const sel = selRef.current; if (!sel) return;
      const m = result.labelMask;
      const nm = m.slice();
      // 1) собрать пиксели+label региона, «прожечь» дыру
      const region: { i: number; lab: number }[] = [];
      const HOLE = 255;
      for (let i = 0; i < sel.length; i++) if (sel[i]) { region.push({ i, lab: m[i] }); nm[i] = HOLE; }
      // 2) залить дыру ближайшими соседями (итеративная дилатация)
      for (let pass = 0; pass < Math.max(W, H); pass++) {
        let changed = false;
        for (const { i } of region) {
          if (nm[i] !== HOLE) continue;
          const x = i % W, y = (i / W) | 0;
          const nb = [x > 0 ? i - 1 : -1, x < W - 1 ? i + 1 : -1, y > 0 ? i - W : -1, y < H - 1 ? i + W : -1];
          for (const j of nb) if (j >= 0 && nm[j] !== HOLE) { nm[i] = nm[j]; changed = true; break; }
        }
        if (!changed) break;
      }
      for (const { i } of region) if (nm[i] === HOLE) nm[i] = 0;
      // 3) перенести регион на смещение
      for (const { i, lab } of region) {
        const x = (i % W) + dx, y = ((i / W) | 0) + dy;
        if (x < 0 || y < 0 || x >= W || y >= H) continue;
        nm[y * W + x] = lab;
      }
      commit(nm, pal);
      return;
    }
    g.current.active = false;
  }, [result, tool, toImg, editColor, commit, W, H, selectAt, selectRect, redraw, bumpNode]);

  const undo = useCallback(() => {
    if (!undoRef.current.length || !result) return;
    redoRef.current.push(result);
    const prev = undoRef.current.pop()!;
    selRef.current = null; selLabelsRef.current = new Set(); selPathRef.current = null;
    update({ result: prev, activeColors: new Set(prev.validLabels) });
    setSelCount((v) => v + 1); setCounts();
  }, [result, update, setCounts]);

  const redo = useCallback(() => {
    if (!redoRef.current.length || !result) return;
    undoRef.current.push(result);
    const next = redoRef.current.pop()!;
    selRef.current = null; selLabelsRef.current = new Set(); selPathRef.current = null;
    update({ result: next, activeColors: new Set(next.validLabels) });
    setSelCount((v) => v + 1); setCounts();
  }, [result, update, setCounts]);

  const exit = useCallback(() => {
    update({ editModeActive: false });
  }, [update]);

  // --- СОХРАНЕНИЕ / ЗАГРУЗКА НАБОРА ПРАВОК ---
  const applySet = useCallback(async (set: EditSet) => {
    if (set.w !== W || set.h !== H) { console.warn("edit-set size mismatch"); return; }
    if (result) { undoRef.current.push(result); if (undoRef.current.length > CAP) undoRef.current.shift(); redoRef.current = []; }
    update({ editBusy: true });
    try {
      const res = await revectorize(editSetMask(set), set.palette, set.w, set.h, set.detail);
      selRef.current = null; selLabelsRef.current = new Set();
      update({ result: res, editBusy: false, activeColors: new Set(res.validLabels) });
      setSelCount((v) => v + 1); setCounts();
    } catch (e) { update({ editBusy: false }); console.warn(e); }
  }, [W, H, result, update, setCounts]);

  const save = useCallback(async () => {
    if (!result) return;
    const key = imageKeyOf(imageFile?.name, imageFile?.size, result.imgW, result.imgH);
    const set = buildEditSet(result, key);
    await saveEditSetDB(set);
    exportEditSetFile(set, `melura-правки-${imageFile?.name || "фото"}`);
    setDbSet(set);
  }, [result, imageFile]);

  const loadFromFile = useCallback(async (file: File) => {
    try { await applySet(await importEditSetFile(file)); } catch (e) { console.warn(e); }
  }, [applySet]);

  const applyDbSet = useCallback(() => { if (dbSet) applySet(dbSet); }, [dbSet, applySet]);

  // Горячие клавиши редактора.
  useEffect(() => {
    if (!active) return;
    const onKey = (e: KeyboardEvent) => {
      const mod = e.ctrlKey || e.metaKey;
      if (mod && e.key.toLowerCase() === "z") { e.preventDefault(); e.shiftKey ? redo() : undo(); }
      else if (mod && e.key.toLowerCase() === "y") { e.preventDefault(); redo(); }
      else if (e.key === "Escape") { e.preventDefault(); clearSelection(); }
      else if (e.key === "Delete" || e.key === "Backspace") { e.preventDefault(); del(); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [active, undo, redo, clearSelection, del]);

  // При входе в редактор ищем сохранённые в браузере правки для этого фото.
  useEffect(() => {
    if (!active || !result) { setDbSet(null); return; }
    const key = imageKeyOf(imageFile?.name, imageFile?.size, result.imgW, result.imgH);
    let cancelled = false;
    loadEditSetDB(key).then((s) => { if (!cancelled) setDbSet(s); });
    return () => { cancelled = true; };
  }, [active, imageFile, result?.imgW, result?.imgH]);

  return {
    active, tool,
    onPointerDown, onPointerMove, onPointerUp,
    hasSelection: selCount >= 0 && !!selRef.current && selLabelsRef.current.size > 0,
    busy,
    recolor, del, merge, smartClean, cleanLevel, setCleanLevel, cleanNote, clearSelection, undo, redo, exit,
    save, loadFromFile, applyDbSet, hasDbSet: !!dbSet,
    neighborColors,
  };
}

