import { memo } from 'react';
import { cn } from '../../utils/cn';

export const MetricCard = memo(function MetricCard({ title, value, accent }: { title: string; value: string; accent?: string }) {
  return (
    <div className="bg-white dark:bg-slate-900 rounded-3xl p-4 sm:p-5 flex flex-col items-center justify-center flex-1 min-w-0 border-2 border-slate-50 dark:border-slate-800 shadow-sm relative overflow-hidden group">
      <div className="absolute top-0 right-0 w-16 h-16 bg-slate-50 dark:bg-slate-800/50 rounded-bl-3xl pointer-events-none -mr-4 -mt-4 transition-transform" />

      <div className="text-[10px] sm:text-xs font-black uppercase tracking-wider text-slate-600 dark:text-slate-400 leading-tight mb-1 relative z-10 w-full text-center">
        {title}
      </div>

      <div className={cn("text-xl sm:text-2xl font-black tracking-tighter relative z-10 leading-none break-all text-center", accent || "text-slate-900 dark:text-white")}>
        {value}
      </div>
    </div>
  );
});
