// src/generator/utils/smartParams.ts
// Замена autoParams.ts. Вычисляет оптимальные numColors и detail
// на основе предвычисленной статистики Importance Map + Image Profile + уровня сложности (complexity).

import type { ImageProfileStats } from "../store/types";

export interface SmartParamsBreakdown {
  highImportanceColors: number;
  lowImportanceColors: number;
  highImportanceDetail: number;
  lowImportanceDetail: number;
}

export interface SmartParamsResult {
  numColors: number;
  detail: number;
  confidence: number;
  breakdown: SmartParamsBreakdown;
  label: string;
}

/** Предвычисленная статистика importance map + пиксельных данных.
 *  Считается ОДИН РАЗ при загрузке фото. */
export interface ImportanceAnalysis {
  highImportanceFraction: number;
  highImportanceColorEntropy: number;
  highImportanceEdgeDensity: number;
  avgImportance: number;
}

/**
 * Анализирует importance map + реальные пиксели изображения.
 * Вызывается ОДИН РАЗ при загрузке фото, результат кэшируется в store.
 */
export function analyzeImportanceDistribution(
  importanceMap: Float32Array,
  imageData: ImageData,
): ImportanceAnalysis {
  const { data, width } = imageData;
  const n = importanceMap.length;
  const importanceThreshold = 0.5;

  let highCount = 0;
  let totalImportance = 0;

  const highColorSet = new Set<number>();
  let highEdgeSum = 0;
  let highEdgeCount = 0;

  for (let i = 0; i < n; i++) {
    totalImportance += importanceMap[i];
    if (importanceMap[i] > importanceThreshold) {
      highCount++;
      const p = i * 4;
      // 5-bit quantization per channel -> 32768 possible "clusters"
      const key = ((data[p] >> 3) << 10) | ((data[p + 1] >> 3) << 5) | (data[p + 2] >> 3);
      highColorSet.add(key);

      // Edge detection in important areas
      const x = i % width;
      const y = Math.floor(i / width);
      if (x > 0 && x < width - 1 && y > 0 && y < imageData.height - 1) {
        const gx = data[(i + 1) * 4] - data[(i - 1) * 4];
        const gy = data[(i + width) * 4] - data[(i - width) * 4];
        highEdgeSum += Math.sqrt(gx * gx + gy * gy);
        highEdgeCount++;
      }
    }
  }

  const highFrac = n > 0 ? highCount / n : 0.5;
  const colorEntropy = Math.min(1, highColorSet.size / 200);
  const edgeDensity = highEdgeCount > 0 ? Math.min(1, (highEdgeSum / highEdgeCount) / 30) : 0;

  return {
    highImportanceFraction: highFrac,
    highImportanceColorEntropy: colorEntropy,
    highImportanceEdgeDensity: edgeDensity,
    avgImportance: n > 0 ? totalImportance / n : 0.5,
  };
}

/**
 * Вычисляет оптимальные numColors и detail для заданного уровня complexity.
 * Использует предвычисленную статистику — НЕ требует пиксельных данных.
 *
 * @param analysis - Предвычисленная статистика (из analyzeImportanceDistribution)
 * @param imageProfile - Статистический профиль изображения
 * @param complexity - Уровень сложности 1-10 (единственный пользовательский параметр)
 */
export function calculateSmartParams(
  analysis: ImportanceAnalysis,
  imageProfile: ImageProfileStats,
  complexity: number,
): SmartParamsResult {
  const clamp = (v: number, min: number, max: number) => Math.max(min, Math.min(max, Math.round(v)));
  const c = Math.max(1, Math.min(10, complexity));

  // Фактор сложности: нелинейная шкала
  const t = (c - 1) / 9; // 0..1

  // ----- Расчёт numColors -----
  // ПЕРЕОСМЫСЛЕНО: раньше число цветов считалось мультипликативно и при
  // "Стандартной" (c=5) легко достигало 40-50 — это непродаваемо для раскраски
  // по номерам (человек не станет держать 40 красок). Теперь базис задаёт УРОВЕНЬ
  // сложности (предсказуемая "тарифная сетка", как в индустрии PBN), а конкретное
  // фото лишь слегка двигает его (+/-15%) по своей "красочности".
  // Ориентир: Комфортная(4)=16, Стандартная(5)=20, Продвинутая(6)=24, Максимальная(10)=42.
  const COLOR_TIERS = [0, 8, 10, 12, 16, 20, 24, 28, 32, 36, 42]; // index = complexity 1..10
  const tierColors = COLOR_TIERS[c] || 20;

  // "Красочность" кадра 0..1: энтропия цвета важных зон + глобальная colorfulness
  const richness = Math.min(1, analysis.highImportanceColorEntropy * 0.6 + imageProfile.colorfulness * 0.7);
  const richnessNudge = 0.85 + richness * 0.30; // 0.85 (приглушённое) .. 1.15 (очень красочное)

  const monoFactor = imageProfile.isMonochrome ? 0.6 : 1.0;

  // Вектор/flat illustration — берём ТОЧНОЕ число плоских цветов (клипарт, логотипы)
  let totalColors: number;
  if (imageProfile.flatColorCount > 0 && imageProfile.flatColorCount <= 32 && imageProfile.complexity < 0.1) {
    totalColors = clamp(imageProfile.flatColorCount + Math.min(2, Math.round(imageProfile.flatColorCount * 0.1)), 4, 48);
  } else {
    totalColors = clamp(tierColors * richnessNudge * monoFactor, 6, 48);
  }

  // Разбивка
  const highImpColorShare = 0.55 + analysis.highImportanceFraction * 0.25;
  const highImpColors = clamp(totalColors * highImpColorShare, 3, totalColors - 1);
  const lowImpColors = totalColors - highImpColors;

  // ----- Расчёт detail -----

  // Базовый detail из edge density в важных зонах
  // Минимум 3 (вместо 1), чтобы "Стандартная" давала хотя бы среднюю детализацию
  const baseDetail = 3 + analysis.highImportanceEdgeDensity * 5; // 3..8

  // Масштабируем по complexity: от 0.4x при c=1 до 1.4x при c=10
  const detailScale = 0.4 + t * 1.0;
  const finalDetail = clamp(baseDetail * detailScale, 1, 10);

  const highDetail = clamp(finalDetail + 1, 1, 10);
  const lowDetail = clamp(finalDetail - 2, 1, 10);

  // ----- Confidence -----
  const varianceCheck = analysis.highImportanceFraction > 0.05 && analysis.highImportanceFraction < 0.95;
  const confidence = varianceCheck ? 0.85 : 0.5;

  // ----- Label -----
  const labels = ["", "Эскиз", "Минимальная", "Простая", "Комфортная",
    "Стандартная", "Продвинутая", "Детальная", "Сложная", "Экспертная", "Максимальная"];

  return {
    numColors: totalColors,
    detail: finalDetail,
    confidence,
    breakdown: {
      highImportanceColors: highImpColors,
      lowImportanceColors: lowImpColors,
      highImportanceDetail: highDetail,
      lowImportanceDetail: lowDetail,
    },
    label: labels[c] || `Уровень ${c}`,
  };
}
