// src/generator/utils/pdfExport.ts
import { renderSchemeCanvas, type ProcessingResult } from "./imageProcessing";
import { calculateDrops, getErrorRating, type RecipeVariant, type RGB } from "../../engine";
import {
  PAINT_PROFILES,
  BASE_COLORS,
  formatParts,
  type PaintType,
  type SurfaceType,
  type ColorComponent,
  type EngineSettings,
} from "../../config";
import type { ArtisticPresetId } from "../../config";
import { simulateCmyk } from "../../utils/colorMath";


export interface PdfExportParams {
  res: ProcessingResult;
  originalImageUrl: string | null;
  paperSize: "a4" | "a3" | "a2";
  dpi: number;
  tileMode: boolean;
  includeRecipes: boolean;
  activeComps: ColorComponent[];
  exportPaintType: PaintType;
  exportSurfaceType: SurfaceType;
  isArtistic: boolean;
  contourWeight: number;
  numberWeight: number;
  artisticPresetId?: ArtisticPresetId;
  notanLevels: number;
  notanThreshold: number;
  artIntensity: number;
  customArtPalette?: RGB[];
  detailsPhotoOpacity: number;
  totalPartsLimit: number | null;
  engineSettings: EngineSettings;
  updateProgress: (msg: string, pct: number) => void;
  watermark: boolean;
  projectTitle: string;
  showBorder: boolean;
  recipeOverrides?: Record<number, RecipeVariant>;
  /**
   * CMYK-софтпруф («Симуляция печати»). Приближённо сжимает все цветовые образцы
   * в достижимый охват офсетной печати: сюда попадают обложка, палитра, сводка,
   * образцы рецептов и живописные слои. Нужен, когда PDF готовится для типографии
   * и заказчик должен утвердить именно печатный, а не экранный цвет.
   * ВАЖНО: это не ICC-профиль. Числа рецептов не меняются — только их превью.
   */
  cmykSimulation?: boolean;
}

export async function generatePdf(params: PdfExportParams): Promise<void> {
  const {
    res, originalImageUrl, paperSize, dpi, tileMode, includeRecipes, activeComps,
    exportPaintType, exportSurfaceType, isArtistic, contourWeight, numberWeight,
    artisticPresetId, notanLevels, notanThreshold, artIntensity, customArtPalette,
    detailsPhotoOpacity, totalPartsLimit, engineSettings, updateProgress, watermark, projectTitle,
    showBorder, recipeOverrides = {}, cmykSimulation = false
  } = params;

  // Единая точка применения печатного софтпруфа. Все образцы цвета в PDF идут
  // через proof() — выключенный чекбокс не меняет ни одного пикселя.
  const proof = (rgb: RGB | [number, number, number]): [number, number, number] =>
    cmykSimulation ? (simulateCmyk(rgb as RGB) as [number, number, number]) : (rgb as [number, number, number]);

  const { jsPDF } = await import("jspdf");

  const orient = res.imgW > res.imgH ? "l" : "p";
  // compress: true — КРИТИЧНО для размера. Без него jsPDF пишет ВСЕ потоки без
  // сжатия: векторная схема «по номерам» (pdf.lines/pdf.text на каждый контур и
  // номер) превращается в десятки/сотни МБ сырого текста в PDF. Zlib-сжатие
  // потоков ужимает это в разы (и не трогает уже сжатые JPEG/PNG-изображения).
  const pdf = new jsPDF({ orientation: orient, unit: "mm", format: paperSize, compress: true });
  
  const pw = pdf.internal.pageSize.getWidth();
  const ph = pdf.internal.pageSize.getHeight();

  // Закладки (outline) — навигация по многостраничному PDF. Регистрируем текущую
  // страницу как раздел. Обёрнуто в try/catch на случай старого jsPDF без outline.
  const addBookmark = (title: string) => {
    try { (pdf as any).outline.add(null, title, { pageNumber: pdf.getNumberOfPages() }); } catch { /* outline недоступен */ }
  };

  // Логическая система координат страницы ≈ 300 DPI для A4 (вся вёрстка растровых
  // страниц задана в этих единицах). Реальное разрешение холста масштабируем по
  // выбранному DPI, поэтому селектор «Качество (DPI)» теперь реально влияет на
  // чёткость растровых страниц (обложка, палитра, сводка, рецепты) — раньше он
  // не менял ничего для режима «по номерам».
  const renderW = orient === "p" ? 2480 : 3508;
  const renderH = orient === "p" ? 3508 : 2480;
  const renderScale = Math.max(0.5, Math.min(2, dpi / 300)); // 150→0.5, 300→1, 600→2

  const drawWatermark = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    if (!watermark) return;
    ctx.save();
    ctx.rotate(-Math.PI / 4);
    
    // Calculate thickness relative to contour weight with a high coefficient
    const baseThickness = isArtistic ? contourWeight : (contourWeight * 1.2);
    const textStrokeWeight = Math.max(3, baseThickness / 4); 
    
    ctx.font = "bold 140px sans-serif";
    ctx.fillStyle = "rgba(0, 0, 0, 0.12)";
    ctx.strokeStyle = "rgba(0, 0, 0, 0.15)";
    ctx.lineWidth = textStrokeWeight;
    ctx.textAlign = "center";
    
    const stepX = 700;
    const stepY = 350;
    
    for (let x = -w; x < w * 2; x += stepX) {
      for (let y = -h; y < h * 2; y += stepY) {
        ctx.strokeText("MELURA", x, y);
        ctx.fillText("MELURA", x, y);
      }
    }
    ctx.restore();
  };

  const addCanvasPage = (drawFn: (ctx: CanvasRenderingContext2D, w: number, h: number) => void, isCover = false, photographic = false) => {
    const c = document.createElement("canvas");
    // Реальные пиксели холста = логический размер × renderScale (по выбранному DPI).
    c.width = Math.round(renderW * renderScale);
    c.height = Math.round(renderH * renderScale);
    const ctx = c.getContext("2d")!;
    // Вся вёрстка ниже работает в логических координатах renderW×renderH — масштаб
    // применяем один раз здесь, чтобы не трогать сотни абсолютных координат.
    ctx.scale(renderScale, renderScale);
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, renderW, renderH);

    // Smooth rendering
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = "high";

    drawFn(ctx, renderW, renderH);

    if (watermark) drawWatermark(ctx, renderW, renderH);
    
    // Premium Footer
    if (!isCover && (pdf as any).internal.pages.length > 0) {
      const footerY = renderH - 100;
      ctx.strokeStyle = "#f1f5f9";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(150, footerY - 40); ctx.lineTo(renderW - 150, footerY - 40); ctx.stroke();
      
      ctx.fillStyle = "#94a3b8";
      ctx.font = "bold 28px sans-serif";
      ctx.textAlign = "left";
      ctx.letterSpacing = "2px";
      ctx.fillText("MELURA", 150, footerY);
      
      ctx.textAlign = "right";
      ctx.font = "32px monospace";
      // Fixed numbering: Current total pages - 1 (excluding cover)
      const pageNum = (pdf as any).internal.getNumberOfPages();
      ctx.fillText(String(pageNum).padStart(2, '0'), renderW - 150, footerY);
      ctx.letterSpacing = "0px";
    }

    // Выбор формата растровой страницы — критично для размера PDF:
    //  • Обложка и «фотографические»/живописные страницы (сплошная многоцветная
    //    заливка, оригинал-фото, слои живописи) → JPEG. PNG без потерь на таком
    //    контенте раздувает файл до десятков МБ на страницу (причина «PDF на 102 МБ»).
    //  • Штриховые страницы (схема с тонкими контурами и цифрами, палитра, карточки
    //    рецептов — в основном белый фон + линии/текст) → PNG: остаётся ЧЁТКИМ
    //    (JPEG давал ореолы на линиях) и при этом отлично сжимается (сотни КБ).
    if (isCover || photographic) {
      pdf.addImage(c.toDataURL("image/jpeg", 0.9), "JPEG", 0, 0, pw, ph);
    } else {
      pdf.addImage(c.toDataURL("image/png"), "PNG", 0, 0, pw, ph);
    }
    c.width = 0;
    c.height = 0;
  };

  const drawHeader = (ctx: CanvasRenderingContext2D, title: string, subtitle: string, w: number) => {
    const headerY = 160;
    ctx.fillStyle = "#0f172a";
    ctx.font = "bold 100px sans-serif";
    ctx.textAlign = "left";
    ctx.letterSpacing = "-2px";
    ctx.fillText(title, 150, headerY);
    
    ctx.fillStyle = "#6366f1";
    ctx.font = "bold 36px sans-serif";
    ctx.letterSpacing = "4px";
    ctx.fillText(subtitle.toUpperCase(), 155, headerY + 60);
    ctx.letterSpacing = "0px";
    
    ctx.strokeStyle = "#e2e8f0";
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(150, headerY + 110); ctx.lineTo(w - 150, headerY + 110); ctx.stroke();
  };

  const drawDecorativeBorder = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    ctx.strokeStyle = "#e2e8f0";
    ctx.lineWidth = 2;
    // Main frame
    ctx.strokeRect(80, 80, w - 160, h - 160);
    
    // Decorative corners
    ctx.strokeStyle = "#cbd5e1";
    ctx.lineWidth = 12;
    const len = 150;
    const gap = 60;
    
    // Top-Left
    ctx.beginPath(); ctx.moveTo(gap, gap + len); ctx.lineTo(gap, gap); ctx.lineTo(gap + len, gap); ctx.stroke();
    // Top-Right
    ctx.beginPath(); ctx.moveTo(w - gap - len, gap); ctx.lineTo(w - gap, gap); ctx.lineTo(w - gap, gap + len); ctx.stroke();
    // Bottom-Left
    ctx.beginPath(); ctx.moveTo(gap, h - gap - len); ctx.lineTo(gap, h - gap); ctx.lineTo(gap + len, h - gap); ctx.stroke();
    // Bottom-Right
    ctx.beginPath(); ctx.moveTo(w - gap - len, h - gap); ctx.lineTo(w - gap, h - gap); ctx.lineTo(w - gap, h - gap - len); ctx.stroke();
  };

  if (isArtistic) {
    const stepNames = ["Эскиз и композиция", "Светотеневой разбор", "Цветовая база", "Экспрессия и колорит", "Финальные акценты"];
    updateProgress("Формирование обложки", 10);
    
    addCanvasPage((ctx, w, h) => {
      drawDecorativeBorder(ctx, w, h);

      // Logo Treatment
      ctx.fillStyle = "#0f172a";
      ctx.font = "bold 180px sans-serif";
      ctx.textAlign = "center";
      ctx.letterSpacing = "12px";
      ctx.fillText("MELURA", w / 2, h * 0.15);
      
      ctx.fillStyle = "#6366f1";
      ctx.font = "bold 44px sans-serif";
      ctx.letterSpacing = "8px";
      ctx.fillText("ART-PRACTICUM", w / 2, h * 0.185);
      ctx.letterSpacing = "0px";

      if (projectTitle) {
        ctx.fillStyle = "#334155";
        ctx.font = "bold 60px serif";
        ctx.fillText(projectTitle.toUpperCase(), w / 2, h * 0.22);
      }

      const availH = h * 0.55;
      const availW = w * 0.75;
      let pW = availW;
      let pH = pW * (res.imgH / res.imgW);
      if (pH > availH) { pH = availH; pW = pH * (res.imgW / res.imgH); }

      const pX = (w - pW) / 2;
      const pY = h * 0.23 + (availH - pH) / 2;

      // Multi-layered Shadow Effect - isolated with save/restore
      ctx.save();
      ctx.shadowColor = "rgba(15, 23, 42, 0.1)";
      ctx.shadowBlur = 120;
      ctx.shadowOffsetY = 60;
      
      const tmp = document.createElement("canvas");
      tmp.width = res.imgW;
      tmp.height = res.imgH;
      tmp.getContext("2d")!.putImageData(res.previewImageData, 0, 0);
      
      ctx.drawImage(tmp, pX, pY, pW, pH);
      ctx.restore();

      // Bottom Info
      ctx.fillStyle = "#334155";
      ctx.font = "italic 60px serif";
      ctx.fillText("Индивидуальная стратегия живописи", w / 2, pY + pH + 140);
      
      ctx.fillStyle = "#94a3b8";
      ctx.font = "bold 32px sans-serif";
      ctx.letterSpacing = "2px";
      ctx.fillText("VERSION 2.0 • PROFESSIONAL EDITION", w / 2, h - 160);
    }, true);
    addBookmark("Обложка");

    const margin = 12;
    const availW = pw - margin * 2;
    const availH = ph - margin * 3;
    let fitW = availW;
    let fitH = availW / (res.imgW / res.imgH);
    if (fitH > availH) { fitH = availH; fitW = availH * (res.imgW / res.imgH); }
    const pxPerMm = dpi / 25.4;
    const scale = (Math.round(fitW * pxPerMm)) / res.imgW;

    let origImg: HTMLImageElement | null = null;
    if (originalImageUrl) {
      origImg = new Image();
      origImg.crossOrigin = "anonymous";
      origImg.src = originalImageUrl;
      await new Promise((resolve, reject) => {
        origImg!.onload = resolve; origImg!.onerror = reject;
      });
    }

    for (let step = 0; step < 5; step++) {
      updateProgress(`Генерация шага ${step + 1} из 5...`, 20 + step * 15);
      pdf.addPage();
      addBookmark(`Шаг ${step + 1}: ${stepNames[step]}`);
      const rc = document.createElement("canvas");
      rc.width = res.imgW * scale;
      rc.height = res.imgH * scale;

      renderSchemeCanvas(
        rc, res, contourWeight, numberWeight, new Set(), false, scale, true, step,
        artisticPresetId, notanLevels, notanThreshold, artIntensity,
        customArtPalette && customArtPalette.length >= 2 ? customArtPalette : undefined,
        false, false, -1, detailsPhotoOpacity, true, showBorder,
        undefined, cmykSimulation
      );

      addCanvasPage((ctx, w, h) => {
        drawHeader(ctx, `ШАГ 0${step + 1}`, stepNames[step], w);

        const imgAreaY = 320;
        const imgAreaH = h - imgAreaY - 200;
        const imgAreaW = w - 300;
        
        let dW = imgAreaW;
        let dH = dW * (rc.height / rc.width);
        if (dH > imgAreaH) { dH = imgAreaH; dW = dH * (rc.width / rc.height); }

        const dX = 150 + (imgAreaW - dW) / 2;
        const dY = imgAreaY + (imgAreaH - dH) / 2;

        if (step === 4 && origImg) {
          ctx.globalAlpha = 0.3;
          ctx.drawImage(origImg, dX, dY, dW, dH);
          ctx.globalAlpha = 1.0;
        }

        ctx.shadowColor = "rgba(0,0,0,0.1)";
        ctx.shadowBlur = 40;
        ctx.drawImage(rc, dX, dY, dW, dH);
        ctx.shadowBlur = 0;
        
        ctx.strokeStyle = "#e2e8f0";
        ctx.lineWidth = 2;
        ctx.strokeRect(dX, dY, dW, dH);
      }, false, true); // photographic: живописные слои → JPEG (компактно)
    }
  } else {
    // Режим "По номерам"
    const sl = [...res.validLabels].sort((a, b) => a - b);
    const recipes: { id: number; variant: RecipeVariant }[] = [];

    if (includeRecipes) {
      const displayComps = activeComps.length > 0 ? activeComps : BASE_COLORS.slice(0, 12);
      
      let completedRecipes = 0;
      updateProgress("Расчёт рецептов", 10);

      const recipePromises = sl.map(async (id) => {
        const target = res.colorPalette[id];
        let best: RecipeVariant;
        
        if (recipeOverrides[id]) {
          best = recipeOverrides[id]!;
        } else {
          const calc = await calculateDrops(
            target, displayComps,
            { ...engineSettings, paintType: exportPaintType, surfaceType: exportSurfaceType, targetTotalParts: totalPartsLimit },
            () => {}
          );
          best = calc.variants[0];
        }
        
        completedRecipes++;
        updateProgress(`Расчёт рецептов: ${completedRecipes} из ${sl.length}`, Math.round((completedRecipes / sl.length) * 30));
        
        return { id, variant: best };
      });
      
      const results = await Promise.all(recipePromises);
      recipes.push(...results);
    }

    updateProgress("Формирование обложки", 35);
    addCanvasPage((ctx, w, h) => {
      drawDecorativeBorder(ctx, w, h);
      ctx.fillStyle = "#0f172a";
      ctx.font = "bold 200px sans-serif";
      ctx.textAlign = "center";
      ctx.letterSpacing = "16px";
      ctx.fillText("MELURA", w / 2, h * 0.16);
      ctx.fillStyle = "#6366f1";
      ctx.font = "bold 44px sans-serif";
      ctx.letterSpacing = "6px";
      ctx.fillText("PREMIUM PAINT-BY-NUMBERS", w / 2, h * 0.195);
      ctx.letterSpacing = "0px";

      if (projectTitle) {
        ctx.fillStyle = "#334155";
        ctx.font = "bold 60px serif";
        ctx.fillText(projectTitle.toUpperCase(), w / 2, h * 0.23);
      }

      const availH = h * 0.5;
      const availW = w * 0.8;
      let pW = availW;
      let pH = pW * (res.imgH / res.imgW);
      if (pH > availH) { pH = availH; pW = pH * (res.imgW / res.imgH); }
      const pX = (w - pW) / 2;
      const pY = h * 0.26 + (availH - pH) / 2;

      const tmp = document.createElement("canvas");
      tmp.width = res.imgW; tmp.height = res.imgH;
      const ctxTmp = tmp.getContext("2d")!;
      
      // Обложка обязана показывать ТЕ ЖЕ цвета, что палитра/сводка/рецепты — т.е.
      // текущий colorPalette (с учётом «Цвета под краски»/аппроксимации рецептов), а не
      // «замороженный» на момент генерации previewImageData. Иначе картинка на обложке
      // и образцы в палитре/рецептах различаются. Собираем заливку по маске меток;
      // для меток без цвета в палитре — откат к исходному превью.
      const imgData = new ImageData(res.imgW, res.imgH);
      {
        const d = imgData.data;
        const src = res.previewImageData.data;
        const mask = res.labelMask;
        const n = res.imgW * res.imgH;
        // Софтпруф считаем один раз на метку, а не на пиксель — иначе для
        // многомегапиксельной картинки это сотни тысяч лишних вызовов.
        const proofCache = new Map<number, [number, number, number]>();
        for (let i = 0; i < n; i++) {
          const k = i * 4;
          const id = mask[i];
          const raw = res.colorPalette[id];
          if (raw) {
            let col = proofCache.get(id);
            if (!col) { col = proof(raw); proofCache.set(id, col); }
            d[k] = col[0]; d[k + 1] = col[1]; d[k + 2] = col[2]; d[k + 3] = 255;
          }
          else { d[k] = src[k]; d[k + 1] = src[k + 1]; d[k + 2] = src[k + 2]; d[k + 3] = src[k + 3]; }
        }
      }

      // Цвета красок; при включённой «Симуляции печати» — уже сжатые в CMYK-охват,
      // так что обложка совпадает с палитрой, сводкой и образцами рецептов.
      ctxTmp.putImageData(imgData, 0, 0);

      ctx.save();
      ctx.shadowColor = "rgba(15, 23, 42, 0.15)";
      ctx.shadowBlur = 120;
      ctx.shadowOffsetY = 60;
      ctx.drawImage(tmp, pX, pY, pW, pH);
      ctx.restore();

      // Russian pluralization logic for "оттенок"
      const n = sl.length;
      const n10 = n % 10;
      const n100 = n % 100;
      let label = "";
      if (n10 === 1 && n100 !== 11) {
        label = `${n} ИСКЛЮЧИТЕЛЬНЫЙ ОТТЕНОК`;
      } else if (n10 >= 2 && n10 <= 4 && (n100 < 10 || n100 >= 20)) {
        label = `${n} ИСКЛЮЧИТЕЛЬНЫХ ОТТЕНКА`;
      } else {
        label = `${n} ИСКЛЮЧИТЕЛЬНЫХ ОТТЕНКОВ`;
      }

      ctx.fillStyle = "#0f172a";
      ctx.font = "bold 70px sans-serif";
      ctx.fillText(label, w / 2, pY + pH + 180);
      
      const SURFACE_NAMES: Record<string, string> = {
        white_paper: 'Белая бумага',
        cream_paper: 'Кремовая бумага',
        craft_paper: 'Крафт-бумага',
        canvas: 'Холст',
        wood: 'Дерево',
        custom: 'Своя поверхность'
      };
      const surfaceName = SURFACE_NAMES[exportSurfaceType] || exportSurfaceType.toUpperCase();
      
      ctx.fillStyle = "#64748b";
      ctx.font = "36px sans-serif";
      ctx.fillText(`ПРОФИЛЬ: ${PAINT_PROFILES[exportPaintType].name.toUpperCase()} / ${surfaceName.toUpperCase()}`, w / 2, h - 140);

      if (cmykSimulation) {
        ctx.fillStyle = "#94a3b8";
        ctx.font = "bold 28px sans-serif";
        ctx.letterSpacing = "3px";
        ctx.fillText("CMYK-ПРУФ. ЦВЕТА ПРИВЕДЕНЫ К ПЕЧАТНОМУ ОХВАТУ", w / 2, h - 92);
        ctx.letterSpacing = "0px";
      }
    }, true);
    addBookmark("Обложка");

    // Сводка цветов: номер, образец, доля площади, число зон — «карта покрытия»,
    // помогает планировать замешивание и оценивать объём работы по каждому цвету.
    const areaByLabel = new Map<number, number>();
    let zonesByLabel = new Map<number, number>();
    let totalArea = 0;
    for (const cd of res.contoursData) {
      if (!res.validLabels.has(cd.labelId)) continue;
      areaByLabel.set(cd.labelId, (areaByLabel.get(cd.labelId) || 0) + cd.area);
      zonesByLabel.set(cd.labelId, (zonesByLabel.get(cd.labelId) || 0) + 1);
      totalArea += cd.area;
    }

    // Palette Overview Page
    updateProgress("Формирование обзора палитры", 45);
    pdf.addPage();
    addCanvasPage((ctx, w, h) => {
      drawHeader(ctx, "ПАЛИТРА", cmykSimulation ? "Обзор оттенков. CMYK-пруф" : "Обзор выбранных оттенков", w);

      const startY = 320;
      const itemsPerRow = orient === "p" ? 6 : 8;
      const gap = 40;
      const size = (w - 300 - (itemsPerRow - 1) * gap) / itemsPerRow;
      
      sl.forEach((id, i) => {
        const r = Math.floor(i / itemsPerRow);
        const c = i % itemsPerRow;
        const cx = 150 + c * (size + gap);
        const cy = startY + r * (size + gap + 80);
        
        const col = proof(res.colorPalette[id]);
        ctx.fillStyle = `rgb(${col[0]},${col[1]},${col[2]})`;
        ctx.beginPath();
        ctx.roundRect(cx, cy, size, size, 24);
        ctx.fill();
        ctx.strokeStyle = "rgba(0,0,0,0.05)";
        ctx.lineWidth = 2;
        ctx.stroke();
        
        ctx.fillStyle = "#475569";
        ctx.font = "bold 36px monospace";
        ctx.textAlign = "center";
        ctx.fillText(String(id + 1).padStart(2, '0'), cx + size / 2, cy + size + 45);
      });
    });
    addBookmark("Палитра");

    // Страница «Сводка цветов» — таблица: образец • № • доля площади • число зон.
    updateProgress("Формирование сводки цветов", 52);
    pdf.addPage();
    addCanvasPage((ctx, w, h) => {
      drawHeader(ctx, "СВОДКА ЦВЕТОВ", "Покрытие и объём работы по каждому оттенку", w);
      const rows = [...sl].sort((a, b) => (areaByLabel.get(b) || 0) - (areaByLabel.get(a) || 0));
      const colX = orient === "p" ? [180, 320, 520, 900, 1300] : [180, 320, 560, 1100, 1700];
      let ty = 360;
      const rowH = 84;
      ctx.textAlign = "left";
      ctx.fillStyle = "#94a3b8";
      ctx.font = "bold 30px sans-serif";
      ctx.fillText("ЦВЕТ", colX[1], ty);
      ctx.fillText("№", colX[2], ty);
      ctx.fillText("ДОЛЯ ПЛОЩАДИ", colX[3], ty);
      ctx.fillText("ЗОН", colX[4], ty);
      ty += 30;
      ctx.strokeStyle = "#e2e8f0"; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(colX[0], ty); ctx.lineTo(w - 150, ty); ctx.stroke();
      ty += 40;
      for (const id of rows) {
        if (ty > h - 220) break; // не залезаем в футер; при большой палитре покажем топ по площади
        const pct = totalArea > 0 ? ((areaByLabel.get(id) || 0) / totalArea) * 100 : 0;
        const col = proof(res.colorPalette[id]);
        ctx.fillStyle = `rgb(${col[0]},${col[1]},${col[2]})`;
        ctx.beginPath(); ctx.roundRect(colX[0], ty - 40, 56, 56, 12); ctx.fill();
        ctx.strokeStyle = "rgba(0,0,0,0.08)"; ctx.lineWidth = 2; ctx.stroke();
        ctx.fillStyle = "#334155"; ctx.font = "bold 34px monospace"; ctx.textAlign = "left";
        ctx.fillText(String(id + 1).padStart(2, '0'), colX[2], ty);
        // Полоска доли площади + число
        const barX = colX[3], barW = (orient === "p" ? 500 : 700), barH = 26;
        ctx.fillStyle = "#f1f5f9"; ctx.beginPath(); ctx.roundRect(barX, ty - 26, barW, barH, 8); ctx.fill();
        ctx.fillStyle = `rgb(${col[0]},${col[1]},${col[2]})`;
        ctx.beginPath(); ctx.roundRect(barX, ty - 26, Math.max(6, barW * Math.min(1, pct / 100)), barH, 8); ctx.fill();
        ctx.fillStyle = "#334155"; ctx.font = "28px sans-serif";
        ctx.fillText(`${pct.toFixed(1)}%`, barX + barW + 24, ty);
        ctx.fillStyle = "#64748b"; ctx.font = "30px sans-serif";
        ctx.fillText(String(zonesByLabel.get(id) || 0), colX[4], ty);
        ty += rowH;
      }
    });
    addBookmark("Сводка цветов");

    updateProgress("Отрисовка схемы", 60);
    await new Promise((r) => setTimeout(r, 50));

    const margin = 10;
    const availW = pw - margin * 2;
    const availH = ph - margin * 2;
    let fitW = availW;
    let fitH = availW / (res.imgW / res.imgH);

    if (fitH > availH) {
      fitH = availH;
      fitW = availH * (res.imgW / res.imgH);
    }

    const tilesX = tileMode ? 2 : 1;
    const tilesY = tileMode ? 2 : 1;
    const totalPhysicalW = fitW * tilesX;
    const totalPhysicalH = fitH * tilesY;
    
    const scale = totalPhysicalW / res.imgW;

    const pdfContourWeight = contourWeight * 1.2; 
    const pdfNumberWeight = numberWeight * 1.1;

    for (let ty = 0; ty < tilesY; ty++) {
      for (let tx = 0; tx < tilesX; tx++) {
        pdf.addPage();
        if (ty === 0 && tx === 0) addBookmark(tileMode ? "Схема (по фрагментам)" : "Схема");

        // Векторная отрисовка через jsPDF
        const offsetX = (pw - fitW) / 2 - (tx * fitW);
        const offsetY = (ph - fitH) / 2 - (ty * fitH);

        // Настраиваем отсечение (Clipping) для tileMode.
        // discardPath() ОБЯЗАТЕЛЕН: без него путь прямоугольника-обрезки остаётся
        // «висящим» и обводится первой же линией контура (оператор S) — из-за этого
        // вокруг всей картинки ВСЕГДА печаталась рамка, независимо от чекбокса.
        pdf.rect((pw - fitW) / 2, (ph - fitH) / 2, fitW, fitH, null);
        pdf.clip();
        pdf.discardPath();

        if (watermark) {
          pdf.saveGraphicsState();
          // Примитивный водяной знак для векторов (можно использовать текст)
          pdf.setTextColor(230, 230, 230);
          pdf.setFontSize(80);
          for (let wx = -totalPhysicalW; wx < totalPhysicalW * 2; wx += 200) {
            for (let wy = -totalPhysicalH; wy < totalPhysicalH * 2; wy += 200) {
              pdf.text("MELURA", offsetX + wx, offsetY + wy, { angle: 45 });
            }
          }
          pdf.restoreGraphicsState();
        }

        const lineW = pdfContourWeight === 0 ? 0 : 0.1 + (pdfContourWeight / 100) * 0.5;
        
        if (pdfContourWeight > 0) {
          pdf.setDrawColor(40, 40, 40);
          pdf.setLineWidth(lineW);

          // Сегменты, идущие ВДОЛЬ самого края изображения, — это внешняя рамка
          // (контур крайних зон совпадает с границей картинки). Ею управляет
          // отдельный чекбокс «Рамка картины», поэтому из контуров зон мы её
          // убираем — иначе рамка печаталась всегда, даже при выключенном чекбоксе.
          // Внутренние границы зон (перпендикулярные краю) сохраняются полностью.
          // Допуск пропорционален размеру: сглаживание контуров может немного
          // «вдавить» линию края внутрь, поэтому фиксированные 0.6px её не ловили.
          const eps = Math.max(1.5, Math.min(res.imgW, res.imgH) * 0.004);
          const onEdge = (p: [number, number]) =>
            p[0] <= eps || p[1] <= eps || p[0] >= res.imgW - eps || p[1] >= res.imgH - eps;
          const drawRun = (run: [number, number][]) => {
            if (run.length < 2) return;
            const rel: number[][] = [];
            for (let i = 1; i < run.length; i++) rel.push([(run[i][0] - run[i - 1][0]) * scale, (run[i][1] - run[i - 1][1]) * scale]);
            pdf.lines(rel, offsetX + run[0][0] * scale, offsetY + run[0][1] * scale, [1, 1], 'S', false);
          };
          for (const chain of res.chains) {
            if (chain.length < 2) continue;
            let run: [number, number][] = [];
            for (let i = 0; i < chain.length; i++) {
              const cur = chain[i] as [number, number];
              if (i > 0 && onEdge(chain[i - 1] as [number, number]) && onEdge(cur)) {
                drawRun(run); run = [cur]; continue; // выкидываем сегмент вдоль края
              }
              run.push(cur);
            }
            drawRun(run);
          }
        }

        if (pdfNumberWeight > 0) {
          const numAlpha = 0.15 + (pdfNumberWeight / 100) * 0.85;
          pdf.setTextColor(10, 10, 10);
          // Насыщенность номеров из редактора (ползунок «номера») теперь реально
          // применяется через прозрачность — раньше numAlpha считался, но не
          // использовался, и цифры всегда были сплошно-чёрными.
          try { pdf.setGState(new (pdf as any).GState({ opacity: numAlpha })); } catch { /* старый jsPDF */ }

          for (const cd of res.contoursData) {
            for (const lbl of cd.labelPositions) {
              // ВАЖНО: набор и размер номеров ОБЯЗАН совпадать с редактором
              // (schemeViewport.ts). Тот же порог зоны и та же формула кегля —
              // иначе в PDF пропадают номера, которые видны на экране.
              if (lbl.maxDist < 2.5) continue;          // порог как в редакторе — набор номеров совпадает
              const digits = String(cd.labelId + 1).length;
              // АДАПТИВНЫЙ кегль прямо в мм (а не перевод экранных пикселей —
              // тот давал ~1 мм, нечитаемо на листе). Размер растёт с реальным
              // размером зоны: R — печатный инрадиус зоны в мм.
              const R = lbl.maxDist * scale;             // мм
              const byHeight = R * 1.35;                 // чтобы номер помещался по высоте зоны
              const byWidth = (1.8 * R) / (digits * 0.6); // многозначные не вылезают по ширине
              // Пол 2.0 мм — гарантированная читаемость даже в мелких зонах;
              // потолок 9 мм — крупные зоны не получают гигантских цифр.
              const fs = Math.max(2.0, Math.min(9, byHeight, byWidth));
              pdf.setFontSize(fs);
              // Пропускаем текст, который точно за пределами текущего тайла
              const txAbs = offsetX + lbl.x * scale;
              const tyAbs = offsetY + lbl.y * scale;
              const margin = 10;
              if (txAbs < (pw - fitW) / 2 - margin || txAbs > pw - (pw - fitW) / 2 + margin ||
                  tyAbs < (ph - fitH) / 2 - margin || tyAbs > ph - (ph - fitH) / 2 + margin) {
                continue;
              }
              pdf.text(String(cd.labelId + 1), txAbs, tyAbs, { align: 'center', baseline: 'middle' });
            }
          }
          try { pdf.setGState(new (pdf as any).GState({ opacity: 1 })); } catch { /* старый jsPDF */ }
        }

        // Единственный источник внешней рамки: контур края мы убрали выше, поэтому
        // рамка появляется ТОЛЬКО когда включён чекбокс (при любой толщине контуров).
        if (showBorder) {
          pdf.setDrawColor(40, 40, 40);
          pdf.setLineWidth(Math.max(lineW, 0.3));
          pdf.rect(offsetX, offsetY, res.imgW * scale, res.imgH * scale);
        }
      }
    }

    if (includeRecipes && recipes.length > 0) {
      updateProgress("Вёрстка книги рецептов", 85);
      let recIdx = 0;
      let pageNum = 1;
      const paintProfile = PAINT_PROFILES[exportPaintType];

      // Pre-calculate items per page to know total pages
      let testCy = 340;
      const testCols = orient === "p" ? 2 : 3;
      const testCardH = 500;
      let testRows = 0;
      while (testCy < renderH - testCardH - 120) {
        testRows++;
        testCy += testCardH + 80;
      }
      const recipesPerPage = testCols * testRows;
      const totalRecipePages = Math.ceil(recipes.length / recipesPerPage);

      while (recIdx < recipes.length) {
        pdf.addPage();
        if (recIdx === 0) addBookmark("Рецепты");
        addCanvasPage((ctx, w, h) => {
          const subtitle = totalRecipePages === 1
            ? "Инструкции по смешиванию" 
            : `Инструкции по смешиванию (Часть ${pageNum})`;
          drawHeader(ctx, "РЕЦЕПТЫ", subtitle, w);

          let cy = 340;
          const cols = orient === "p" ? 2 : 3;
          const cardW = Math.floor((w - 300 - (cols - 1) * 80) / cols);
          const cardH = 500;
          let cx = 150;
          let colCount = 0;

          while (recIdx < recipes.length && cy < h - cardH - 120) {
            const { id, variant } = recipes[recIdx];
            const col = res.colorPalette[id];

            ctx.save();
            ctx.translate(cx, cy);
            
            // Card Base with soft elevation
            ctx.fillStyle = "#ffffff";
            ctx.shadowColor = "rgba(0,0,0,0.03)";
            ctx.shadowBlur = 20;
            ctx.beginPath(); ctx.roundRect(0, 0, cardW, cardH, 24); ctx.fill();
            ctx.strokeStyle = "#f1f5f9";
            ctx.lineWidth = 2;
            ctx.stroke();
            ctx.restore();

            // Color Swatch Strip (Masked in Demo)
            if (watermark) {
              ctx.fillStyle = "#f1f5f9";
              ctx.beginPath(); ctx.roundRect(cx + 20, cy + 20, 120, cardH - 40, 16); ctx.fill();
              ctx.fillStyle = "#cbd5e1";
              ctx.font = "bold 60px sans-serif";
              ctx.textAlign = "center";
              ctx.fillText("?", cx + 80, cy + cardH / 2 + 20);
            } else {
              // Образец — «как напечатается», HEX ниже — реальный целевой цвет краски
              // (его и надо замешивать), поэтому софтпруф на HEX сознательно не идёт.
              const pc = proof(col);
              ctx.fillStyle = `rgb(${pc[0]},${pc[1]},${pc[2]})`;
              ctx.beginPath(); ctx.roundRect(cx + 20, cy + 20, 120, cardH - 40, 16); ctx.fill();
            }
            
            // ID Label and Hex Code
            ctx.fillStyle = "#0f172a";
            ctx.font = "bold 64px monospace";
            ctx.textAlign = "left";
            ctx.fillText(String(id + 1).padStart(2, '0'), cx + 170, cy + 85);
            
            if (!watermark) {
              const hexStr = "#" + col.map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('').toUpperCase();
              ctx.fillStyle = "#64748b";
              ctx.font = "bold 32px monospace";
              ctx.textAlign = "right";
              ctx.fillText(hexStr, cx + cardW - 40, cy + 85);
            }

            ctx.strokeStyle = "#f1f5f9";
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(cx + 170, cy + 115); ctx.lineTo(cx + cardW - 40, cy + 115); ctx.stroke();

            let ry = cy + 185;
            for (const item of variant.recipe) {
              // Ingredient Swatch (Masked in Demo)
              if (watermark) {
                ctx.strokeStyle = "#e2e8f0";
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.arc(cx + 195, ry - 16, 24, 0, Math.PI * 2); ctx.stroke();
              } else {
                const simRgb = proof(item.rgb);
                ctx.fillStyle = `rgb(${simRgb[0]},${simRgb[1]},${simRgb[2]})`;
                ctx.beginPath(); ctx.arc(cx + 195, ry - 16, 24, 0, Math.PI * 2); ctx.fill();
              }
              
              ctx.fillStyle = "#334155";
              ctx.font = "bold 40px sans-serif";
              ctx.textAlign = "left";
              let name = watermark ? "ОТТЕНОК СКРЫТ" : item.name; 
              if(name.length > 16) name = name.substring(0, 14) + "...";
              ctx.fillText(name, cx + 235, ry);

              ctx.fillStyle = watermark ? "#f43f5e" : "#6366f1";
              ctx.font = "bold 44px monospace";
              ctx.textAlign = "right";
              ctx.fillText(watermark ? "???" : formatParts(item.parts, paintProfile), cx + cardW - 40, ry);
              ry += 70;
            }
            
            // Accuracy Indicator (Localized)
            if (!watermark) {
              const rating = getErrorRating(variant.deltaE);
              ctx.fillStyle = "#94a3b8";
              ctx.font = "bold 24px sans-serif";
              ctx.textAlign = "right";
              ctx.fillText(`Точность: ${rating.toLowerCase()}`, cx + cardW - 40, cy + cardH - 35);
            } else if (watermark) {
              ctx.fillStyle = "#f43f5e";
              ctx.font = "bold 20px sans-serif";
              ctx.textAlign = "right";
              ctx.fillText("DEMO VERSION", cx + cardW - 40, cy + cardH - 35);
            }

            cx += cardW + 80;
            colCount++;
            if (colCount % cols === 0) { cx = 150; cy += cardH + 80; }
            recIdx++;
          }
        });
        pageNum++;
      }
    }
  }

  updateProgress("Сохранение PDF", 98);
  pdf.save(`melura_${isArtistic ? "art" : "pbn"}_${Date.now()}.pdf`);
}
