// src/generator/utils/paintingCoach.ts
// «Мозг» наставника режима «Живопись»: анализ конкретного изображения для
// персональных советов и метрики для фото-самопроверки холста.
// Все функции чистые (без DOM), пригодны для node-тестов.
import type { RGB } from '../../config';
import { rgbToLab } from '../../utils/colorMath';

export interface PaintingInsights {
  subjectLabel: string;                 // «по центру», «левее центра сверху», …
  contrast: 'low' | 'normal' | 'high';
  contrastSpread: number;               // размах L палитры (0..100)
  darkest: RGB; lightest: RGB;
  warmest: RGB; coolest: RGB;
  tempBias: 'warm' | 'cool' | 'neutral';
  numColors: number;
  toneGroups: number;                   // рекомендуемое число тональных групп
}

function lum(rgb: RGB): number { return rgbToLab(rgb)[0]; }
function bStar(rgb: RGB): number { return rgbToLab(rgb)[2]; }

/** Позиция смыслового центра по карте значимости → человекочитаемая подпись. */
export function describeSubject(importanceMap: Float32Array | null, w: number, h: number): string {
  if (!importanceMap || importanceMap.length < w * h || w <= 0 || h <= 0) return 'на главном объекте';
  let sum = 0, cx = 0, cy = 0;
  // Берём только «значимые» пиксели (важность выше средней), чтобы центр не
  // размывался фоном.
  let mean = 0;
  for (let i = 0; i < w * h; i++) mean += importanceMap[i];
  mean /= (w * h);
  const thr = Math.max(mean, 0.35);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const v = importanceMap[y * w + x];
      if (v <= thr) continue;
      sum += v; cx += x * v; cy += y * v;
    }
  }
  if (sum <= 0) return 'на главном объекте';
  const nx = cx / sum / w, ny = cy / sum / h;
  const hor = nx < 0.4 ? 'слева' : nx > 0.6 ? 'справа' : 'по центру';
  const ver = ny < 0.4 ? 'вверху' : ny > 0.6 ? 'внизу' : '';
  if (hor === 'по центру' && !ver) return 'по центру';
  return [hor, ver].filter(Boolean).join(' ');
}

/** Анализ картины: экстремумы тона/температуры, контраст, смысловой центр. */
export function analyzePaintingImage(
  colorPalette: Record<number, RGB>,
  areaByLabel: Map<number, number>,
  importanceMap: Float32Array | null,
  dimW: number,
  dimH: number,
): PaintingInsights | null {
  const ids = Object.keys(colorPalette).map(Number).filter((id) => colorPalette[id]);
  if (ids.length === 0) return null;

  let darkest = colorPalette[ids[0]], lightest = colorPalette[ids[0]];
  let warmest = colorPalette[ids[0]], coolest = colorPalette[ids[0]];
  let minL = 999, maxL = -999, maxB = -999, minB = 999;
  let wbSum = 0, areaSum = 0;

  for (const id of ids) {
    const rgb = colorPalette[id];
    const L = lum(rgb), b = bStar(rgb);
    if (L < minL) { minL = L; darkest = rgb; }
    if (L > maxL) { maxL = L; lightest = rgb; }
    if (b > maxB) { maxB = b; warmest = rgb; }
    if (b < minB) { minB = b; coolest = rgb; }
    const a = areaByLabel.get(id) || 1;
    wbSum += b * a; areaSum += a;
  }

  const spread = Math.max(0, maxL - minL);
  const contrast: 'low' | 'normal' | 'high' = spread < 45 ? 'low' : spread > 78 ? 'high' : 'normal';
  const meanB = areaSum > 0 ? wbSum / areaSum : 0;
  const tempBias: 'warm' | 'cool' | 'neutral' = meanB > 8 ? 'warm' : meanB < -6 ? 'cool' : 'neutral';
  // Рекомендуемое число тональных групп: от размаха контраста.
  const toneGroups = spread > 70 ? 4 : spread > 50 ? 3 : 2;

  return {
    subjectLabel: describeSubject(importanceMap, dimW, dimH),
    contrast, contrastSpread: Math.round(spread),
    darkest, lightest, warmest, coolest,
    tempBias, numColors: ids.length, toneGroups,
  };
}

export interface ImageStats {
  meanL: number;                        // средняя светлота (0..100)
  meanA: number; meanB: number;         // средние a*/b* (температура/оттенок)
  shadowPct: number; midPct: number; lightPct: number; // распределение тона
  spread: number;                       // размах тона (p95−p5), 0..100
}

/** Робастные агрегатные метрики картинки (для сравнения фото холста с эталоном).
 *  Считаем по выборке пикселей — устойчиво к неточной рамке и освещению. */
export function computeImageStats(data: Uint8ClampedArray, width: number, height: number): ImageStats {
  const n = width * height;
  const step = Math.max(1, Math.floor(n / 40000)); // ~40k выборок максимум
  let sumL = 0, sumA = 0, sumB = 0, cnt = 0;
  let sh = 0, mid = 0, lt = 0;
  const Ls: number[] = [];
  for (let i = 0; i < n; i += step) {
    const p = i * 4;
    const al = data[p + 3];
    if (al < 128) continue; // прозрачные пиксели пропускаем
    const lab = rgbToLab([data[p], data[p + 1], data[p + 2]]);
    const L = lab[0];
    sumL += L; sumA += lab[1]; sumB += lab[2]; cnt++;
    if (L < 40) sh++; else if (L > 72) lt++; else mid++;
    Ls.push(L);
  }
  if (cnt === 0) return { meanL: 0, meanA: 0, meanB: 0, shadowPct: 0, midPct: 0, lightPct: 0, spread: 0 };
  Ls.sort((x, y) => x - y);
  const p5 = Ls[Math.floor(Ls.length * 0.05)] ?? Ls[0];
  const p95 = Ls[Math.floor(Ls.length * 0.95)] ?? Ls[Ls.length - 1];
  return {
    meanL: sumL / cnt, meanA: sumA / cnt, meanB: sumB / cnt,
    shadowPct: (sh / cnt) * 100, midPct: (mid / cnt) * 100, lightPct: (lt / cnt) * 100,
    spread: Math.max(0, p95 - p5),
  };
}

export interface CoachVerdict { kind: 'ok' | 'value' | 'contrast' | 'temp' | 'zones'; text: string; }
export interface CoachReport { verdicts: CoachVerdict[]; grade: 'close' | 'work'; }

/** Сравнение метрик холста (user) с эталоном (ref) → конкретные советы. */
export function comparePaintingToReference(user: ImageStats, ref: ImageStats): CoachReport {
  const v: CoachVerdict[] = [];

  // 1. Общая светлота
  const dL = user.meanL - ref.meanL;
  if (dL > 8) v.push({ kind: 'value', text: `Работа в целом светлее эталона (на ~${Math.round(dL)} ед.) — углубите тени.` });
  else if (dL < -8) v.push({ kind: 'value', text: `Работа в целом темнее эталона (на ~${Math.round(-dL)} ед.) — добавьте света в освещённые места.` });

  // 2. Контраст (размах тона)
  const dS = user.spread - ref.spread;
  if (dS < -12) v.push({ kind: 'contrast', text: 'Не хватает контраста: тени недостаточно тёмные или света недостаточно светлые. Разведите крайние тона сильнее.' });
  else if (dS > 15) v.push({ kind: 'contrast', text: 'Контраст выше эталона — работа может «рваться». Смягчите переходы в полутонах.' });

  // 3. Температура
  const dB = user.meanB - ref.meanB; // b*: тепло(+)/холод(−)
  const dA = user.meanA - ref.meanA; // a*: красный(+)/зелёный(−)
  if (dB > 7) v.push({ kind: 'temp', text: 'Работа теплее эталона — добавьте прохлады (синего/холодного) в тени и фон.' });
  else if (dB < -7) v.push({ kind: 'temp', text: 'Работа холоднее эталона — добавьте тепла (жёлтого/охры) в освещённые места.' });
  if (dA > 9) v.push({ kind: 'temp', text: 'Есть перекос в красноту — приглушите комплементом (немного зелёного).' });
  else if (dA < -9) v.push({ kind: 'temp', text: 'Есть перекос в зелень — приглушите каплей красного.' });

  // 4. Распределение тона
  if (user.shadowPct < ref.shadowPct - 12) v.push({ kind: 'zones', text: 'Теней в работе меньше, чем в эталоне — не бойтесь закладывать крупные тёмные массы.' });
  else if (user.shadowPct > ref.shadowPct + 15) v.push({ kind: 'zones', text: 'Теней больше, чем нужно — работа «затемнена». Раскройте полутона и света.' });

  if (v.length === 0) {
    v.push({ kind: 'ok', text: 'Отлично! По тону, контрасту и температуре работа близка к эталону. Двигайтесь к следующему этапу.' });
    return { verdicts: v, grade: 'close' };
  }
  return { verdicts: v, grade: 'work' };
}
