// src/generator/hooks/useSchemeRenderer.ts
import { useEffect, useRef } from "react";
import { renderSchemeCanvas } from "../utils/imageProcessing";
import { applyMaterial, type MaterialParams } from "../utils/canvasMaterial";
import { applyMaterialGL, materialGLFast } from "../utils/canvasMaterialGL";
import type { ProcessingResult } from "../utils/imageProcessing";
import type { RGB } from "../../config";

interface UseSchemeRendererProps {
  result: ProcessingResult | null;
  schemeCanvasRef: React.RefObject<HTMLCanvasElement | null>;
  idealCanvasRef?: React.RefObject<HTMLCanvasElement | null>;
  contourWeight: number;
  numberWeight: number;
  activeColors: Set<number>;
  showNumbers: boolean;
  showContours: boolean;
  studioMode: "painting" | "pbn";
  paintingLayer: number;
  paintingStyleId: string | undefined;
  notanLevels: number;
  notanThreshold: number;
  artIntensity: number;
  customArtPalette: RGB[];
  showTemperatureMap: boolean;
  zoneGuideActive: boolean;
  currentZoneContourId: number;
  detailsPhotoOpacity: number;
  applySplit: () => void;
  recipeSplitMode?: boolean;
  recipeApproximations?: Record<number, [number, number, number]> | null;
  renderScale?: number; // супер-сэмпл (кратность разрешения canvas), следует за зумом
  /**
   * Физика материала. Накладывается ПОСЛЕ отрисовки схемы, поверх готового
   * изображения: цвета, контуры и номера считаются как прежде, а этот проход
   * добавляет им рельеф основы и свет. null — показывать плоскую схему.
   */
  material?: MaterialParams | null;
}

export function useSchemeRenderer({
  result,
  schemeCanvasRef,
  idealCanvasRef,
  contourWeight,
  numberWeight,
  activeColors,
  showNumbers,
  studioMode,
  paintingLayer,
  paintingStyleId,
  notanLevels,
  notanThreshold,
  artIntensity,
  customArtPalette,
  showTemperatureMap,
  zoneGuideActive,
  currentZoneContourId,
  detailsPhotoOpacity,
  showContours,
  applySplit,
  recipeSplitMode,
  recipeApproximations,
  renderScale = 2,
  material,
}: UseSchemeRendererProps) {
  const renderTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!result) {
      if (schemeCanvasRef.current) {
        schemeCanvasRef.current.width = 0;
        schemeCanvasRef.current.height = 0;
      }
      if (idealCanvasRef?.current) {
        idealCanvasRef.current.width = 0;
        idealCanvasRef.current.height = 0;
      }
      applySplit();
      return;
    }

    const isPainting = studioMode === "painting";

    if (renderTimerRef.current) clearTimeout(renderTimerRef.current);
    // Физика материала на процессоре — проход по каждому пикселю холста, на
    // полном превью это доли секунды. При таскании ползунка света события идут
    // потоком, поэтому пауза перед перерисовкой удлиняется: иначе очередь
    // тяжёлых проходов не даёт интерфейсу дышать. На видеокарте кадр стоит
    // единицы миллисекунд, и удлинять паузу незачем.
    const debounceMs = material && !materialGLFast() ? 140 : 30;
    renderTimerRef.current = setTimeout(() => {
      const c = schemeCanvasRef.current;
      if (c) {
        try {
          renderSchemeCanvas(
            c,
            result,
            contourWeight,
            numberWeight,
            activeColors,
            showNumbers,
            renderScale,
            isPainting,
            paintingLayer,
            paintingStyleId as any,
            notanLevels,
            notanThreshold,
            artIntensity,
            (customArtPalette && customArtPalette.length >= 2) ? customArtPalette : undefined,
            showTemperatureMap,
            zoneGuideActive,
            currentZoneContourId,
            detailsPhotoOpacity,
            showContours,
            true, // showBorder defaults to true for preview
            recipeSplitMode ? (recipeApproximations || undefined) : undefined
          );
          // Физика материала идёт последним проходом: ей нужна уже готовая
          // картинка, включая контуры и номера — они напечатаны на той же
          // основе и обязаны получить ту же фактуру.
          // Сначала пробуем видеокарту. Если её нет или что-то пошло не так,
          // тот же расчёт выполняется на процессоре: пользователь видит
          // одинаковую картину, разница только в скорости.
          if (material && !applyMaterialGL(c, result, renderScale, material)) {
            applyMaterial(c, result, renderScale, material);
          }
        } catch (err) {
          console.error("Scheme render error:", err);
        }
      }

      if (idealCanvasRef && idealCanvasRef.current && recipeSplitMode) {
        try {
          renderSchemeCanvas(
            idealCanvasRef.current,
            result,
            contourWeight,
            numberWeight,
            activeColors,
            showNumbers,
            renderScale,
            isPainting,
            paintingLayer,
            paintingStyleId as any,
            notanLevels,
            notanThreshold,
            artIntensity,
            (customArtPalette && customArtPalette.length >= 2) ? customArtPalette : undefined,
            showTemperatureMap,
            zoneGuideActive,
            currentZoneContourId,
            detailsPhotoOpacity,
            showContours,
            true,
            undefined // always ideal
          );
        } catch (err) {
          console.error("Ideal scheme render error:", err);
        }
      }

      applySplit();
    }, debounceMs);

    return () => {
      if (renderTimerRef.current) clearTimeout(renderTimerRef.current);
    };
  }, [
    result,
    contourWeight,
    numberWeight,
    activeColors,
    showNumbers,
    showContours,
    applySplit,
    studioMode,
    paintingLayer,
    paintingStyleId,
    notanLevels,
    notanThreshold,
    artIntensity,
    customArtPalette,
    showTemperatureMap,
    zoneGuideActive,
    currentZoneContourId,
    detailsPhotoOpacity,
    schemeCanvasRef,
    recipeSplitMode,
    recipeApproximations,
    renderScale,
    material,
  ]);
}
