import { create, type StateCreator } from "zustand";
import { persist } from "zustand/middleware";
import { saveHistoryEntry, getHistoryEntries, deleteHistoryEntry, clearAllHistoryEntries } from "../../utils/idb";
import { 
  DEFAULT_CORRECTION, DEFAULT_VIEW_TRANSFORM, MAX_HISTORY, 
  DEFAULT_PAINTING_STATE, DEFAULT_PBN_STATE, SYNC_KEYS 
} from "./constants";
import { buildFlatState, syncCurrentFlatIntoModes } from "./utils";
import { profileImageQuick } from "../utils/imageProcessing/profiler";
import type { 
  AppState, UISlice, EngineSlice, CorrectionSlice, HistorySlice, HistoryEntry, 
  PaintingModeState, PbnModeState 
} from "./types";

export * from "./types";
export * from "./constants";

const createUISlice: StateCreator<AppState, [], [], UISlice> = (set) => ({
  isDark: (() => {
    try {
      const v = localStorage.getItem("pbn-dark");
      if (v === "1") return true;
      if (v === "0") return false;
    } catch {}
    return window.matchMedia("(prefers-color-scheme: dark)").matches;
  })(),
  isProcessing: false,
  isExporting: false,
  isOptimizing: false,
  optimizationData: [],
  recipeOverrides: {},
  progress: 0,
  statusMsg: "",
  abortController: null,
  mobileSettingsOpen: false,
  mobileCorrectionOpen: false,
  mobilePaletteExpanded: false,
  cropModalOpen: false,
  urlModalOpen: false,
  exportModalOpen: false,
  historyModalOpen: false,
  arCameraOpen: false,
  colorPickerActive: false,
  pickedColor: null,
  colorPickerPanelOpen: false,
  pickingHarmonyBaseHue: false,
  isInteracting: false,
  projectTitle: "",
  update: (partial) =>
    set((state) => {
      // Изолируем UI-обновления. Если меняются только ключи, не влияющие на расчеты и режимы, просто возвращаем partial.
      const keys = Object.keys(partial);
      const isOnlyUI = keys.every((k) => !SYNC_KEYS.has(k) && k !== 'result' && k !== 'activeColors');
      
      if (isOnlyUI) {
        return partial as Partial<AppState>;
      }

      const merged = { ...state, ...partial } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { ...partial, ...synced } as Partial<AppState>;
    }),
});

const createEngineSlice: StateCreator<AppState, [], [], EngineSlice> = (set, get) => {
  const paintingModeState = { ...DEFAULT_PAINTING_STATE, activeColors: new Set<number>(), viewTransform: { ...DEFAULT_VIEW_TRANSFORM } };
  const pbnModeState = { ...DEFAULT_PBN_STATE, activeColors: new Set<number>(), viewTransform: { ...DEFAULT_VIEW_TRANSFORM } };
  const flat = buildFlatState("pbn", paintingModeState, pbnModeState);

  return {
    imageFile: null, originalImageUrl: null, correctedImageUrl: null, imageDimensions: null, imageProfile: null,
    importanceMap: null, importanceBaseMap: null, importanceAnalysis: null,
    protectMask: null, protectMaskW: 0, protectMaskH: 0, protectVersion: 0, protectDetail: 5,
    protectToolActive: false, protectTool: "brush", protectBrushSize: 8,
    editModeActive: false, editTool: "select", editBrushSize: 6, editBrushErase: false, editColor: null,
    editSelCount: 0, editUndoCount: 0, editRedoCount: 0, editBusy: false,
    aiMask: null, aiMaskWidth: 0, aiMaskHeight: 0, faceLandmarks: null, complexity: 5,
    importanceEmphasis: 1,
    backgroundSimplify: 1,
    presetSearch: { running: false, progress: 0, candidates: null, error: null, open: false, sourceUrl: null, appliedId: null },
    presetLevers: { colors: true, detail: true, brightness: true, contrast: true, saturation: true, sharpness: true, shadows: true, highlights: true, structure: true, emphasis: true, backgroundSimplify: true },
    paintAdapt: true,
    idealPalette: null,
    adaptedPalette: null,
    gamutDelta: null,
    // Восстановление тонового объёма встроено в режим «Цвета под краски» и
    // отключению не подлежит: подгонка под краски всегда сжимает диапазон
    // светлоты, и без растяжки картина выходит плоской.
    preserveVolume: true,
    gamutMarker: false,
    materialView: false,
    materialLightK: 5200,
    materialAzimuth: 135,
    materialStrength: 65,
    materialSurfaceId: '',
    cropRect: null, studioMode: "pbn", paintingModeState, pbnModeState,
    autoEnhance: true,
    ...flat,

    switchStudioMode: (mode) => set((state) => {
      const synced = syncCurrentFlatIntoModes(state);
      const flatState = buildFlatState(mode, synced.paintingModeState, synced.pbnModeState);
      return { studioMode: mode, paintingModeState: synced.paintingModeState, pbnModeState: synced.pbnModeState, ...flatState };
    }),

    setPaintingStyle: (styleId) => set((state) => {
      const nextPainting = { ...state.paintingModeState, paintingStyleId: styleId };
      return { paintingModeState: nextPainting, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
    }),

    toggleColor: (id) => set((state) => {
      const next = new Set(state.activeColors);
      if (next.has(id)) next.delete(id); else next.add(id);
      const merged = { ...state, activeColors: next } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { activeColors: next, ...synced };
    }),

    toggleAllColors: () => set((state) => {
      if (!state.result) return {};
      const all = Array.from(state.result.validLabels);
      const allOn = state.activeColors.size === all.length;
      const next = allOn ? new Set<number>() : new Set(all);
      const merged = { ...state, activeColors: next } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { activeColors: next, ...synced };
    }),

    isolateColor: (id) => set((state) => {
      if (!state.result) return {};
      const next = new Set<number>();
      if (state.activeColors.size === 1 && state.activeColors.has(id)) {
        state.result.validLabels.forEach((label) => {
          if (label !== id) next.add(label);
        });
      } else {
        next.add(id);
      }
      const merged = { ...state, activeColors: next } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { activeColors: next, ...synced };
    }),

    setNotanLevels: (levels) => set((state) => {
      const value = Math.max(2, Math.min(5, levels));
      const nextPainting = { ...state.paintingModeState, notanLevels: value };
      return { paintingModeState: nextPainting, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
    }),

    setNotanThreshold: (threshold) => set((state) => {
      const value = Math.max(0, Math.min(255, threshold));
      const nextPainting = { ...state.paintingModeState, notanThreshold: value };
      return { paintingModeState: nextPainting, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
    }),

    selectZone: (id) => set((state) => {
      const merged = { ...state, selectedZoneId: id, zoneInfoVisible: id !== null } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { selectedZoneId: id, zoneInfoVisible: id !== null, ...synced };
    }),

    setCustomArtPalette: (colors) => set((state) => {
      const nextPainting = { ...state.paintingModeState, customArtPalette: colors };
      return { paintingModeState: nextPainting, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
    }),

    toggleZoneGuide: () => set((state) => {
      const next = !state.zoneGuideActive;
      const merged = { ...state, zoneGuideActive: next, currentZoneIndex: next ? state.currentZoneIndex : 0 } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { zoneGuideActive: next, currentZoneIndex: next ? state.currentZoneIndex : 0, ...synced };
    }),

    nextZone: () => set((state) => {
      if (!state.result) return {};
      const totalZones = state.result.contoursData.length;
      if (totalZones === 0) return {};
      const currentZoneIndex = (state.currentZoneIndex + 1) % totalZones;
      const merged = { ...state, currentZoneIndex } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { currentZoneIndex, ...synced };
    }),

    prevZone: () => set((state) => {
      if (!state.result) return {};
      const totalZones = state.result.contoursData.length;
      if (totalZones === 0) return {};
      const currentZoneIndex = (state.currentZoneIndex - 1 + totalZones) % totalZones;
      const merged = { ...state, currentZoneIndex } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { currentZoneIndex, ...synced };
    }),

    setGridType: (type) => set((state) => {
      const merged = { ...state, gridType: type } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { gridType: type, ...synced };
    }),

    setGridSize: (size) => set((state) => {
      const value = Math.max(2, Math.min(20, size));
      const merged = { ...state, gridSize: value } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { gridSize: value, ...synced };
    }),

    toggleFlip: () => set((state) => {
      const merged = { ...state, flipHorizontal: !state.flipHorizontal } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { flipHorizontal: !state.flipHorizontal, ...synced };
    }),

    toggleTemperatureMap: () => set((state) => {
      const merged = { ...state, showTemperatureMap: !state.showTemperatureMap } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { showTemperatureMap: !state.showTemperatureMap, ...synced };
    }),

    setArtIntensity: (intensity) => set((state) => {
      const value = Math.max(0, Math.min(100, intensity));
      const nextPainting = { ...state.paintingModeState, artIntensity: value };
      return { paintingModeState: nextPainting, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
    }),

    setDetailsPhotoOpacity: (opacity) => set((state) => {
      const value = Math.max(0, Math.min(100, opacity));
      const nextPainting = { ...state.paintingModeState, detailsPhotoOpacity: value };
      return { paintingModeState: nextPainting, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
    }),

    setPaintingNumColors: (colors) => set((state) => {
      const value = Math.max(4, Math.min(50, colors));
      const nextPainting = { ...state.paintingModeState, numColors: value };
      return { paintingModeState: nextPainting, paintingNumColors: value, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
    }),

    setPaintingDetail: (detail) => set((state) => {
      const value = Math.max(1, Math.min(10, detail));
      const nextPainting = { ...state.paintingModeState, detail: value };
      return { paintingModeState: nextPainting, paintingDetail: value, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
    }),

    calculateRecipeApproximations: async (engineSettings, activeComps, totalPartsLimit, autoEnableSplit) => {
      const state = get();
      if (!state.result || state.studioMode !== "pbn") return;

      set({ isProcessing: true, statusMsg: "Расчет красок...", progress: 0 });

      const sl = [...state.result.validLabels].sort((a, b) => a - b);
      const approximations: Record<number, [number, number, number]> = {};
      const { calculateDrops } = await import('../../engine');

      const tt = totalPartsLimit === 'авто' || totalPartsLimit === '' || totalPartsLimit == null
        ? null 
        : Number(totalPartsLimit) || null;

      for (let i = 0; i < sl.length; i++) {
        const id = sl[i];
        
        const over = state.recipeOverrides[id];
        if (over) {
          approximations[id] = over.approxRgb;
          set({ progress: Math.round((i / sl.length) * 100) });
          continue;
        }

        const target = state.result.colorPalette[id];
        // Защита: если у метки нет цвета в палитре (или он битый), не валим весь
        // расчёт — пропускаем зону, её цвет останется идеальным.
        if (!target || target.length < 3 || target.some((v) => typeof v !== 'number' || Number.isNaN(v))) {
          set({ progress: Math.round((i / sl.length) * 100) });
          continue;
        }

        try {
          const calc = await calculateDrops(
            target,
            activeComps,
            { ...engineSettings, targetTotalParts: tt },
            () => {}
          );
          const a = calc?.variants?.[0]?.approxRgb;
          if (a) approximations[id] = a;
        } catch (err) {
          // Один сбойный цвет не должен ломать всю адаптацию.
          console.warn('recipe approx failed for label', id, target, err);
        }
        set({ progress: Math.round((i / sl.length) * 100) });
      }

      set((state) => {
        const shouldEnableSplit = autoEnableSplit === true || state.pbnModeState.recipeSplitMode;
        const nextPbn = { ...state.pbnModeState, recipeApproximations: approximations, recipeSplitMode: shouldEnableSplit };
        return { pbnModeState: nextPbn, ...(state.studioMode === "pbn" ? buildFlatState("pbn", state.paintingModeState, nextPbn) : {}), isProcessing: false };
      });
    },

    setPaintingLayerAnimated: (layer) => {
      const s = get();
      if (s.paintingLayer === layer) return;
      set((state) => {
        const nextPainting = { ...state.paintingModeState, prevPaintingLayer: state.paintingLayer, layerTransitioning: true, paintingLayer: layer, selectedZoneId: null, zoneInfoVisible: false };
        return { paintingModeState: nextPainting, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
      });
      setTimeout(() => {
        set((state) => {
          const nextPainting = { ...state.paintingModeState, layerTransitioning: false };
          return { paintingModeState: nextPainting, ...(state.studioMode === "painting" ? buildFlatState("painting", nextPainting, state.pbnModeState) : {}) };
        });
      }, 300);
    },

    togglePaintingSplit: () => set((state) => {
      if (state.studioMode === "painting") {
        const next = !state.paintingSplitMode;
        const merged = { ...state, paintingSplitMode: next } as AppState;
        const synced = syncCurrentFlatIntoModes(merged);
        return { paintingSplitMode: next, ...synced };
      } else {
        const next = !state.pbnModeState.recipeSplitMode;
        const merged = { ...state, recipeSplitMode: next } as any;
        const synced = syncCurrentFlatIntoModes(merged);
        return { recipeSplitMode: next, ...synced } as any;
      }
    }),
    
    setViewTransform: (patch) => set((state) => {
      const merged = { ...state, viewTransform: { ...state.viewTransform, ...patch } } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { viewTransform: { ...state.viewTransform, ...patch }, ...synced };
    }),

    resetViewTransform: () => set((state) => {
      const merged = { ...state, viewTransform: { ...DEFAULT_VIEW_TRANSFORM } } as AppState;
      const synced = syncCurrentFlatIntoModes(merged);
      return { viewTransform: { ...DEFAULT_VIEW_TRANSFORM }, ...synced };
    }),
  };
};

const createCorrectionSlice: StateCreator<AppState, [], [], CorrectionSlice> = (set, get) => ({
  correction: { ...DEFAULT_CORRECTION },
  correctionHistory: [{ ...DEFAULT_CORRECTION }],
  correctionHistoryIndex: 0,
  updateCorrection: (partial) => {
    const current = get().correction;
    set({ correction: { ...current, ...partial } });
  },
  pushCorrectionHistory: () => {
    const s = get();
    const history = s.correctionHistory.slice(0, s.correctionHistoryIndex + 1);
    history.push({ ...s.correction });
    if (history.length > 50) history.shift();
    set({ correctionHistory: history, correctionHistoryIndex: history.length - 1 });
  },
  resetCorrection: () => {
    const def = { ...DEFAULT_CORRECTION };
    const s = get();
    const history = s.correctionHistory.slice(0, s.correctionHistoryIndex + 1);
    history.push(def);
    if (s.correctedImageUrl && s.correctedImageUrl.startsWith("blob:")) {
      URL.revokeObjectURL(s.correctedImageUrl);
    }
    set({ correction: def, correctedImageUrl: null, correctionHistory: history, correctionHistoryIndex: history.length - 1 });
  },
  undoCorrection: () => {
    const s = get();
    if (s.correctionHistoryIndex <= 0) return;
    const newIndex = s.correctionHistoryIndex - 1;
    set({ correction: { ...s.correctionHistory[newIndex] }, correctionHistoryIndex: newIndex });
  },
  redoCorrection: () => {
    const s = get();
    if (s.correctionHistoryIndex >= s.correctionHistory.length - 1) return;
    const newIndex = s.correctionHistoryIndex + 1;
    set({ correction: { ...s.correctionHistory[newIndex] }, correctionHistoryIndex: newIndex });
  },
});

const createHistorySlice: StateCreator<AppState, [], [], HistorySlice> = (set, get) => ({
  generationHistory: [],
  historyCounter: 0,
  initHistory: async () => {
    try {
      const entries = await getHistoryEntries();
      entries.sort((a, b) => b.timestamp - a.timestamp);
      set({ generationHistory: entries, historyCounter: entries.length > 0 ? Math.max(...entries.map((e) => e.id)) : 0 });
    } catch (e) {
      console.error(e);
    }
  },
  addToHistory: async (entry) => {
    const s = get();
    const id = s.historyCounter + 1;
    const newEntry = { ...entry, id };
    const list = [newEntry, ...s.generationHistory].slice(0, MAX_HISTORY);
    set({ generationHistory: list, historyCounter: id });
    try {
      await saveHistoryEntry(newEntry as HistoryEntry);
      if (s.generationHistory.length >= MAX_HISTORY) {
        const toDelete = s.generationHistory.slice(MAX_HISTORY - 1);
        for (const old of toDelete) await deleteHistoryEntry(old.id);
      }
    } catch (e) {
      console.error(e);
    }
  },
  loadFromHistory: async (id) => {
    const s = get();
    const entry = s.generationHistory.find((e) => e.id === id);
    if (!entry) return;
    const allColors = new Set(Array.from(entry.result.validLabels));
    let originalImageUrl = s.originalImageUrl;
    let imageDimensions = s.imageDimensions;
    let imageProfile = s.imageProfile;
    if (entry.originalImageStr) {
      try {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.src = entry.originalImageStr;
        await new Promise((resolve, reject) => { img.onload = resolve; img.onerror = reject; });
        originalImageUrl = entry.originalImageStr;
        imageDimensions = { w: img.width, h: img.height };
        
        const c = document.createElement("canvas");
        c.width = img.width;
        c.height = img.height;
        const ctx = c.getContext("2d");
        if (ctx) {
          ctx.drawImage(img, 0, 0);
          const imageData = ctx.getImageData(0, 0, img.width, img.height);
          imageProfile = profileImageQuick(imageData.data, img.width, img.height);
        }
      } catch (e) {
        console.error(e);
      }
    }
    if (s.correctedImageUrl && s.correctedImageUrl.startsWith("blob:")) {
      URL.revokeObjectURL(s.correctedImageUrl);
    }
    const mode = entry.studioMode;
    const paintingModeState = mode === "painting" ? { ...s.paintingModeState, numColors: entry.numColors, detail: entry.detail, activeColors: allColors, selectedZoneId: null, zoneInfoVisible: false, zoneGuideActive: false, showTemperatureMap: false, paintingSplitMode: false, flipHorizontal: false, viewTransform: { ...DEFAULT_VIEW_TRANSFORM } } : s.paintingModeState;
    const pbnModeState = mode === "pbn" ? { ...s.pbnModeState, numColors: entry.numColors, detail: entry.detail, activeColors: allColors, selectedZoneId: null, zoneInfoVisible: false, zoneGuideActive: false, showTemperatureMap: false, paintingSplitMode: false, flipHorizontal: false, viewTransform: { ...DEFAULT_VIEW_TRANSFORM } } : s.pbnModeState;
    const flatState = buildFlatState(mode, paintingModeState, pbnModeState);
    set({
      originalImageUrl, imageDimensions, imageProfile, correctedImageUrl: null,
      correction: { ...DEFAULT_CORRECTION }, correctionHistory: [{ ...DEFAULT_CORRECTION }], correctionHistoryIndex: 0,
      studioMode: mode, paintingModeState, pbnModeState, ...flatState, result: entry.result,
      historyModalOpen: false, statusMsg: "Загружено из истории",
    });
  },
  removeFromHistory: async (id) => {
    set((s) => ({ generationHistory: s.generationHistory.filter((e) => e.id !== id) }));
    try { await deleteHistoryEntry(id); } catch (e) { console.error(e); }
  },
  clearHistory: async () => {
    set({ generationHistory: [], historyCounter: 0 });
    try {
      await clearAllHistoryEntries();
    } catch (e) {
      console.error(e);
    }
  },
});

export const useAppStore = create<AppState>()(
  persist(
    (...a) => ({
      ...createUISlice(...a),
      ...createEngineSlice(...a),
      ...createCorrectionSlice(...a),
      ...createHistorySlice(...a),
    }),
    {
      name: "melura_generator_state",
      partialize: (state) => ({
        isDark: state.isDark,
        correction: state.correction,
        correctionHistory: state.correctionHistory,
        correctionHistoryIndex: state.correctionHistoryIndex,
        paintingModeState: {
          ...state.paintingModeState,
          activeColors: Array.from(state.paintingModeState.activeColors),
          result: null,
        },
        pbnModeState: {
          ...state.pbnModeState,
          activeColors: Array.from(state.pbnModeState.activeColors),
          result: null,
          recipeApproximations: null,
        },
      }),
      merge: (persistedState: any, currentState: AppState) => {
        const paintingModeState: PaintingModeState = persistedState?.paintingModeState
          ? {
              ...DEFAULT_PAINTING_STATE,
              ...persistedState.paintingModeState,
              activeColors: new Set<number>(persistedState.paintingModeState.activeColors || []),
              viewTransform: { ...DEFAULT_VIEW_TRANSFORM, ...(persistedState.paintingModeState.viewTransform || {}) },
              contourWeight: persistedState.paintingModeState.contourWeight === 50 ? 25 : (persistedState.paintingModeState.contourWeight ?? 25),
              numberWeight: persistedState.paintingModeState.numberWeight === 50 ? 25 : (persistedState.paintingModeState.numberWeight ?? 25),
            }
          : { ...DEFAULT_PAINTING_STATE, activeColors: new Set<number>(), viewTransform: { ...DEFAULT_VIEW_TRANSFORM } };

        const pbnModeState: PbnModeState = persistedState?.pbnModeState
          ? {
              ...DEFAULT_PBN_STATE,
              ...persistedState.pbnModeState,
              activeColors: new Set<number>(persistedState.pbnModeState.activeColors || []),
              viewTransform: { ...DEFAULT_VIEW_TRANSFORM, ...(persistedState.pbnModeState.viewTransform || {}) },
              contourWeight: persistedState.pbnModeState.contourWeight === 50 ? 25 : (persistedState.pbnModeState.contourWeight ?? 25),
              numberWeight: persistedState.pbnModeState.numberWeight === 50 ? 25 : (persistedState.pbnModeState.numberWeight ?? 25),
              recipeApproximations: null,
            }
          : { ...DEFAULT_PBN_STATE, activeColors: new Set<number>(), viewTransform: { ...DEFAULT_VIEW_TRANSFORM } };

        const studioMode: "painting" | "pbn" = "pbn";
        const flatState = buildFlatState(studioMode, paintingModeState, pbnModeState);

        return {
          ...currentState,
          ...persistedState,
          studioMode,
          paintingModeState,
          pbnModeState,
          ...flatState,
          // Нормализуем светокоррекцию: у старых сохранённых сессий может не быть
          // новых полей (shadows/highlights/structure) — дополняем дефолтами.
          correction: { ...DEFAULT_CORRECTION, ...(persistedState?.correction || {}) },
        };
      },
      }
      )
      );
