// src/generator/components/PalettePanel.tsx
import { memo, useMemo, useRef, useCallback, useState } from "react";
import { useAppStore } from "../store";

export const PalettePanel = memo(function PalettePanel() {
  const isDark = useAppStore((s) => s.isDark);
  const result = useAppStore((s) => s.result);
  const activeColors = useAppStore((s) => s.activeColors);
  const toggleColor = useAppStore((s) => s.toggleColor);
  const isolateColor = useAppStore((s) => s.isolateColor);
  const toggleAllColors = useAppStore((s) => s.toggleAllColors);
  const expanded = useAppStore((s) => s.mobilePaletteExpanded);
  const update = useAppStore((s) => s.update);
  const studioMode = useAppStore((s) => s.studioMode);

  const [showRanking, setShowRanking] = useState(false);

  const clickState = useRef({ timer: null as ReturnType<typeof setTimeout> | null, lastTime: 0, lastId: -1 });

  const handleColorClick = useCallback((id: number) => {
    const now = Date.now();
    const state = clickState.current;

    if (state.lastId === id && (now - state.lastTime) < 250) {
      // Fast double click: Isolate / Invert
      clearTimeout(state.timer);
      isolateColor(id);
      state.lastTime = 0;
      state.lastId = -1;
    } else {
      // Single click wait
      state.lastTime = now;
      state.lastId = id;
      clearTimeout(state.timer);
      state.timer = setTimeout(() => {
        toggleColor(id);
        state.lastId = -1;
      }, 250);
    }
  }, [isolateColor, toggleColor]);

  const isArtistic = studioMode === "painting";

  const { sorted, ranking } = useMemo(() => {
    if (!result) return { sorted: [], ranking: [] };
    const valid = [...result.validLabels].sort((a, b) => a - b);
    
    // Подсчет площади для рейтинга
    const areaMap = new Map<number, number>();
    let totalArea = 0;
    
    for (const contour of result.contoursData) {
      if (result.validLabels.has(contour.labelId)) {
        const area = contour.area || 0;
        areaMap.set(contour.labelId, (areaMap.get(contour.labelId) || 0) + area);
        totalArea += area;
      }
    }
    
    const rankList = valid.map(id => ({
      id,
      area: areaMap.get(id) || 0,
      percent: totalArea > 0 ? ((areaMap.get(id) || 0) / totalArea) * 100 : 0
    })).sort((a, b) => b.area - a.area);
    
    return { sorted: valid, ranking: rankList };
  }, [result]);

  if (!result) return null;

  const allOn = activeColors.size === sorted.length;
  const maxCollapsed = 12;
  const needsExpand = sorted.length > maxCollapsed;
  const visibleColors = expanded || !needsExpand ? sorted : sorted.slice(0, maxCollapsed);

  return (
    <div
      className={`flex-shrink-0 border-t px-3 py-2 flex flex-col ${
        isDark ? "bg-gray-900 border-gray-800" : "bg-white border-gray-200"
      }`}
      style={{ maxHeight: showRanking ? '50vh' : 'auto' }}
      role="region"
      aria-label="Палитра цветов"
    >
      {/* Header */}
      <div className="flex items-center gap-2 mb-2 shrink-0">
        <span
          className={`text-xs font-bold uppercase tracking-wider ${
            isDark ? "text-gray-500" : "text-gray-400"
          }`}
        >
          {sorted.length} {plural(sorted.length)}
        </span>

        <button
          type="button"
          onClick={(e) => { e.preventDefault(); e.stopPropagation(); setShowRanking(!showRanking); }}
          className={`ml-2 inline-flex items-center justify-center gap-1.5 px-2.5 py-1 rounded-md text-[10px] font-bold uppercase tracking-widest transition-all ${
            showRanking 
              ? (isDark ? "bg-indigo-500/20 text-indigo-400" : "bg-indigo-50 text-indigo-600")
              : (isDark ? "bg-slate-800 text-slate-400 hover:text-slate-300" : "bg-slate-100 text-slate-500 hover:text-slate-700")
          }`}
        >
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg>
          Объем краски
        </button>

        <div className="flex-1" />

        {activeColors.size > 0 && activeColors.size < sorted.length && (
          <span
            className={`text-xs px-1.5 py-0.5 rounded-full hidden sm:inline-block ${
              isDark ? "bg-indigo-900 text-indigo-300" : "bg-indigo-50 text-indigo-600"
            }`}
            aria-live="polite"
          >
            {activeColors.size} выбрано
          </span>
        )}

        <button
          data-palette-action
          onClick={toggleAllColors}
          aria-label={allOn ? "Скрыть все цвета" : "Показать все цвета"}
          className={`inline-flex items-center justify-center gap-1 px-2 py-1 rounded-md text-xs font-semibold transition-all leading-none ${
            allOn
              ? isDark
                ? "text-indigo-400 hover:text-indigo-300"
                : "text-indigo-600 hover:text-indigo-700"
              : isDark
                ? "text-gray-500 hover:text-gray-400"
                : "text-gray-400 hover:text-gray-500"
          }`}
        >
          {allOn ? "Снять все" : "Выбрать все"}
        </button>
      </div>

      {showRanking ? (
        <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 space-y-2 mt-2 pb-2">
          {ranking.map((item, idx) => {
            const c = result.colorPalette[item.id];
            const [r, g, b] = c;
            const lum = 0.299 * r + 0.587 * g + 0.114 * b;
            const on = activeColors.has(item.id);
            const hex = "#" + c.map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('').toUpperCase();

            return (
              <div 
                key={item.id} 
                onClick={() => handleColorClick(item.id)}
                className={`flex items-center gap-3 p-2 rounded-xl cursor-pointer transition-all ${
                  on ? (isDark ? "bg-indigo-500/10 ring-1 ring-indigo-500/30" : "bg-indigo-50 ring-1 ring-indigo-200") 
                     : (isDark ? "hover:bg-slate-800" : "hover:bg-slate-50 opacity-70")
                }`}
              >
                <div className="w-8 h-8 rounded-lg shrink-0 flex items-center justify-center text-xs font-black shadow-sm"
                     style={{
                       backgroundColor: hex,
                       color: lum > 140 ? "#000" : "#fff",
                       border: lum > 230 ? "1px solid #d1d5db" : "none",
                     }}>
                  {item.id + 1}
                </div>
                
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-baseline mb-1.5">
                    <span className={`text-[10px] font-black uppercase tracking-widest ${isDark ? "text-slate-400" : "text-slate-500"}`}>
                      {idx + 1} место
                    </span>
                    <span className={`text-xs font-bold ${isDark ? "text-slate-300" : "text-slate-700"}`}>
                      {item.percent.toFixed(1)}%
                    </span>
                  </div>
                  <div className={`h-2 rounded-full overflow-hidden ${isDark ? "bg-slate-800" : "bg-slate-100"}`}>
                    <div className="h-full bg-indigo-500 rounded-full" style={{ width: `${item.percent}%` }} />
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="flex overflow-x-auto sm:flex-wrap gap-1.5 shrink-0 scrollbar-none snap-x px-1 py-1" role="group" aria-label="Цвета палитры">
          {visibleColors.map((id) => {
            const c = result.colorPalette[id];
            if (!c) return null;

            const [r, g, b] = c;
            const lum = 0.299 * r + 0.587 * g + 0.114 * b;
            const on = activeColors.has(id);

            return (
              <button
                key={id}
                data-swatch
                onClick={() => handleColorClick(id)}
                title={`Цвет ${id + 1}: rgb(${r},${g},${b})`}
                aria-pressed={on}
                aria-label={`Цвет ${id + 1}`}
                className={`inline-flex items-center justify-center rounded-lg text-xs font-bold transition-all duration-100 leading-none shrink-0 snap-start ${
                  on
                    ? `ring-2 ring-indigo-500 scale-110 shadow-lg z-10 ${
                        isDark ? "ring-offset-gray-900" : "ring-offset-white"
                      } ring-offset-1`
                    : "hover:bg-slate-200/50 dark:hover:bg-slate-700/50 opacity-40 hover:opacity-70"
                }`}
                style={{
                  width: 40,
                  height: 40,
                  backgroundColor: `rgb(${r},${g},${b})`,
                  color: lum > 140 ? "#000" : "#fff",
                  border: lum > 230 ? "1px solid #d1d5db" : "none",
                }}
              >
                {id + 1}
              </button>
            );
          })}

          {needsExpand && (
            <button
              data-swatch
              onClick={() => update({ mobilePaletteExpanded: !expanded })}
              aria-label={
                expanded
                  ? "Свернуть палитру"
                  : `Показать ещё ${sorted.length - maxCollapsed} ${plural(sorted.length - maxCollapsed)}`
              }
              className={`inline-flex items-center justify-center rounded-lg text-xs font-bold transition-all leading-none shrink-0 ${
                isDark
                  ? "bg-gray-800 text-gray-400 hover:bg-gray-700"
                  : "bg-gray-100 text-gray-500 hover:bg-gray-200"
              }`}
              style={{ width: 40, height: 40 }}
            >
              {expanded
                ? <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="m18 15-6-6-6 6" /></svg>
                : `+${sorted.length - maxCollapsed}`}
            </button>
          )}
        </div>
      )}

      {/* Информационная подсказка для понимания режима */}
      {!showRanking && (
        <div className="mt-2 shrink-0">
          <p
            className={`text-xs leading-relaxed ${
              isDark ? "text-gray-500" : "text-gray-400"
            }`}
          >
            {isArtistic
              ? "Выбор цветов сохраняется отдельно для режима живописи."
              : "Выбор цветов сохраняется отдельно для режима по номерам."}
          </p>
        </div>
      )}
    </div>
  );
});

function plural(n: number): string {
  const m10 = n % 10;
  const m100 = n % 100;
  if (m100 >= 11 && m100 <= 19) return "цветов";
  if (m10 === 1) return "цвет";
  if (m10 >= 2 && m10 <= 4) return "цвета";
  return "цветов";
}