// src/paints/match.ts
//
// Подбор достоверного названия для измеренного цвета.
//
// После скана бланка у нас на руках честно измеренный RGB, но без имени —
// а рецепт, палитра и книга рецептов читаются людьми, и «Цвет №7» там никуда
// не годится. Поэтому измеренный цвет сопоставляется с реально существующими
// красками: сначала внутри выбранного набора (там мы знаем, что именно человек
// клал в ячейку), затем по всей базе.
//
// Сравнение идёт по ΔE2000 в Lab, а не по расстоянию в RGB: RGB неравномерен,
// и в нём два синих, различимых глазом, оказываются «ближе», чем два зелёных,
// которые глаз не различает вовсе.

import { rgbToLab, deltaE00 } from '../utils/colorMath';
import { EXTENDED_COLORS, type RGB } from '../config';
import { BUILT_IN_SETS } from './sets';
import type { PaintSet, PaintSetColor } from './types';
import { canonicalScore } from './naming';

export interface PaintMatch {
  name: string;
  code?: string;
  /** Откуда взято имя — показываем, чтобы предложение не выглядело гаданием. */
  origin: string;
  deltaE: number;
  rgb: RGB;
  /**
   * Другие краски, неотличимые от этой по цвету.
   * Нужны, потому что задача «назвать краску по её цвету» в общем случае
   * НЕРАЗРЕШИМА: «Белила титановые» и «Белила цинковые» отличаются на ΔE≈1,
   * то есть меньше порога различимости. Честный ответ здесь не «одно имя»,
   * а «вот эти два, выберите своё» — что UI и показывает одним тапом.
   */
  alternatives?: { name: string; origin: string; deltaE: number }[];
}

interface Candidate extends PaintSetColor { origin: string }

function buildCandidates(customSets: PaintSet[]): Candidate[] {
  const out: Candidate[] = [];
  const seen = new Set<string>();

  for (const s of [...BUILT_IN_SETS, ...customSets]) {
    for (const c of s.colors) {
      const key = `${s.brand}|${c.name}`;
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({ ...c, origin: `${s.brand}, ${s.line}` });
    }
  }

  // Общепигментные названия из базовой палитры приложения — на случай, когда
  // измеренный цвет не похож ни на что из конкретных наборов.
  for (const c of EXTENDED_COLORS) {
    if (seen.has(`общее|${c.name}`)) continue;
    seen.add(`общее|${c.name}`);
    out.push({ name: c.name, rgb: c.rgb, origin: 'Общепринятое название пигмента' });
  }

  return out;
}

/**
 * Возвращает несколько ближайших реальных красок, лучшая первой.
 * @param preferSet если задан, краски этого набора идут вне конкурса первыми —
 *                  пользователь заявил, что красил именно ими, и это сильная
 *                  подсказка, которую глупо игнорировать ради формального ΔE.
 */
export function matchPaint(
  rgb: RGB,
  opts: { customSets?: PaintSet[]; preferSet?: PaintSet; limit?: number } = {},
): PaintMatch[] {
  const { customSets = [], preferSet, limit = 3 } = opts;
  const lab = rgbToLab(rgb);

  const rank = (list: Candidate[]): PaintMatch[] =>
    list
      .map(c => ({ name: c.name, code: c.code, origin: c.origin, rgb: c.rgb, deltaE: deltaE00(lab, rgbToLab(c.rgb)) }))
      .sort((a, b) => a.deltaE - b.deltaE);

  const result: PaintMatch[] = [];

  if (preferSet) {
    const own = rank(preferSet.colors.map(c => ({ ...c, origin: `${preferSet.brand}, ${preferSet.line}` })));
    result.push(...own.slice(0, limit));
  }

  const rest = rank(buildCandidates(customSets)).filter(
    m => !result.some(r => r.name === m.name && r.origin === m.origin),
  );
  result.push(...rest);

  return result.slice(0, limit);
}

/**
 * Насколько предложенному имени можно верить.
 * Пороги — из практики восприятия цвета: до 2 ΔE разницу почти не видно,
 * до 5 её замечает тренированный глаз, дальше это уже разные краски.
 */
export function matchConfidence(deltaE: number): 'совпадение' | 'близкое соответствие' | 'приближённое соответствие' {
  if (deltaE < 2.5) return 'совпадение';
  if (deltaE < 6) return 'близкое соответствие';
  return 'приближённое соответствие';
}

/**
 * Венгерский алгоритм (метод кратчайших дополняющих путей) для прямоугольной
 * матрицы стоимостей: строк не больше, чем столбцов.
 *
 * Здесь он заменяет прежнюю жадную раздачу имён, и это не оптимизация, а
 * исправление ошибки. Жадность разбирала пары по возрастанию ΔE, поэтому
 * последним ячейкам доставалось то, что осталось: чёрный мазок мог получить
 * имя «Коричневая», а фиолетовый — «Чёрная», хотя нужные имена в списке были
 * и остались нерозданными. Венгерский алгоритм минимизирует сумму по всему
 * назначению сразу, и такой размен становится невозможен.
 *
 * @returns для каждой строки номер назначенного столбца
 */
function solveAssignment(cost: number[][]): number[] {
  const n = cost.length;
  if (!n) return [];
  const m = cost[0].length;
  const INF = Infinity;
  const u = new Float64Array(n + 1);
  const v = new Float64Array(m + 1);
  const p = new Int32Array(m + 1);
  const way = new Int32Array(m + 1);

  for (let i = 1; i <= n; i++) {
    p[0] = i;
    let j0 = 0;
    const minv = new Float64Array(m + 1).fill(INF);
    const used = new Uint8Array(m + 1);
    do {
      used[j0] = 1;
      const i0 = p[j0];
      let delta = INF, j1 = 0;
      for (let j = 1; j <= m; j++) {
        if (used[j]) continue;
        const cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
        if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
        if (minv[j] < delta) { delta = minv[j]; j1 = j; }
      }
      for (let j = 0; j <= m; j++) {
        if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
        else minv[j] -= delta;
      }
      j0 = j1;
    } while (p[j0] !== 0);
    do { const j1 = way[j0]; p[j0] = p[j1]; j0 = j1; } while (j0);
  }

  const res = new Array<number>(n).fill(-1);
  for (let j = 1; j <= m; j++) if (p[j] > 0) res[p[j] - 1] = j - 1;
  return res;
}

/**
 * Надбавка к ΔE для красок вне заявленного набора.
 *
 * Заявленный набор — сильное утверждение пользователя, и по умолчанию имена
 * берутся из него. Но утверждение может быть и ошибочным: человек оставил
 * активным акварельный набор, а снял лист с акрилом. Раньше набор был жёстким
 * ограничением, и в такой ситуации приложение обязано было выдать 12 акварельных
 * имён — заведомо неверных, но с виду уверенных. Теперь набор лишь имеет
 * преимущество: имя со стороны выигрывает, только если оно ближе к измеренному
 * цвету более чем на эту величину. Значение заметно больше порога различимости,
 * поэтому при верно указанном наборе посторонние имена не появляются.
 */
const OUTSIDE_SET_PENALTY = 12;

/**
 * Раздаёт имена сразу всей пачке измеренных цветов — так, чтобы имена НЕ
 * повторялись.
 *
 * Зачем отдельная функция вместо вызова matchPaint в цикле: независимый подбор
 * легко назовёт два разных зелёных мазка одной «Зелёной средней», просто потому
 * что она ближайшая к обоим. Для палитры это брак — два разных пигмента с одним
 * именем ломают и рецепты, и книгу рецептов.
 *
 * Решается как задача о назначении, оптимально: минимизируется суммарное
 * расхождение по всей пачке.
 */
export function assignUniqueNames(
  cells: { index: number; rgb: RGB }[],
  opts: { customSets?: PaintSet[]; preferSet?: PaintSet; preferBrand?: string } = {},
): Map<number, PaintMatch> {
  const { customSets = [], preferSet, preferBrand } = opts;
  const out = new Map<number, PaintMatch>();
  if (!cells.length) return out;

  const setNames = new Set(preferSet ? preferSet.colors.map(c => c.name) : []);
  const pool: Candidate[] = preferSet
    ? [
        ...preferSet.colors.map(c => ({ ...c, origin: `${preferSet.brand}, ${preferSet.line}` })),
        ...buildCandidates(customSets),
      ]
    : buildCandidates(customSets);

  // Одно имя — один кандидат. Первым в списке идёт набор, поэтому при совпадении
  // названий побеждает вариант из набора вместе с его артикулом.
  const cands: Candidate[] = [];
  const seenName = new Set<string>();
  for (const c of pool) {
    if (seenName.has(c.name)) continue;
    seenName.add(c.name);
    cands.push(c);
  }
  if (cands.length < cells.length) {
    // Красок в базе меньше, чем ячеек: назначение невозможно. Такого не бывает
    // при штатной базе, но проверка дешевле, чем разбор падения.
    for (const c of cells) out.set(c.index, { name: `Цвет ${c.index + 1}`, origin: 'Соответствие в базе не найдено', rgb: c.rgb, deltaE: 100 });
    return out;
  }

  // Притяжение к узнаваемым именам. Наш замер сам по себе имеет погрешность
  // порядка 1–2 ΔE, поэтому спорить о разнице в этих пределах бессмысленно:
  // если два имени одинаково близки, выбираем то, которое человек скорее узнает.
  // Размер поблажки сознательно НЕ больше погрешности замера — иначе
  // узнаваемость начала бы перебивать реальный цвет. Внутри заявленного набора
  // поблажка не действует: там каждое имя равно достоверно, и переставлять их
  // местами по «узнаваемости» значит искажать факт.
  const CANON_PULL = 1.4;
  const bonus = cands.map(c => {
    if (setNames.has(c.name)) return 0;
    const pull = CANON_PULL * Math.max(0, Math.min(1, canonicalScore(c.name, preferBrand) / 250));
    return (preferSet ? OUTSIDE_SET_PENALTY : 0) - pull;
  });

  const candLab = cands.map(c => rgbToLab(c.rgb));
  const cellLab = cells.map(c => rgbToLab(c.rgb));

  const dist: number[][] = cellLab.map(lab => candLab.map(cl => deltaE00(lab, cl)));
  const cost: number[][] = dist.map(row => row.map((d, j) => d + bonus[j]));

  const assign = solveAssignment(cost);

  for (let i = 0; i < cells.length; i++) {
    const j = assign[i];
    const cell = cells[i];
    if (j < 0) {
      out.set(cell.index, { name: `Цвет ${cell.index + 1}`, origin: 'Соответствие в базе не найдено', rgb: cell.rgb, deltaE: 100 });
      continue;
    }
    const c = cands[j];

    // Альтернативы: другие краски, неотличимые от измеренного цвета. Задача
    // «назвать краску по её цвету» в общем случае неразрешима: «Белила
    // титановые» и «Белила цинковые» отличаются меньше порога различимости.
    // Честный ответ здесь не одно имя, а короткий список на выбор.
    const alternatives = dist[i]
      .map((d, k) => ({ d, k }))
      .filter(x => x.k !== j && x.d < 4)
      .sort((a, b) => a.d - b.d)
      .slice(0, 5)
      .map(x => ({ name: cands[x.k].name, origin: cands[x.k].origin, deltaE: x.d }));

    out.set(cell.index, {
      name: c.name, code: c.code, origin: c.origin,
      rgb: c.rgb, deltaE: dist[i][j], alternatives,
    });
  }

  return out;
}
