import { useState } from 'react';
import { ModalWide } from '../ui/Modal';
import { generateDiagnosticReport } from '../../utils/diagnostics';
import { APP_VERSION, BUILD_DATE } from '../../version';

export function ServiceMenuDialog({ onClose }: { onClose: () => void }) {
  const [isGenerating, setIsGenerating] = useState(false);
  const [progressMsg, setProgressMsg] = useState('');
  const [progressPct, setProgressPct] = useState(0);
  const [reportText, setReportText] = useState('');

  const handleGenerate = async () => {
    setIsGenerating(true);
    setProgressMsg('Запуск...');
    setProgressPct(0);
    setReportText('');

    try {
      const text = await generateDiagnosticReport((msg, pct) => {
        setProgressMsg(msg);
        setProgressPct(pct);
      });
      setReportText(text);
    } catch (e: any) {
      setReportText(`Ошибка при генерации отчета: ${e.message}`);
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(reportText);
    alert('Отчет скопирован в буфер обмена');
  };

  const downloadReport = () => {
    if (!reportText) return;
    const blob = new Blob([reportText], { type: 'text/markdown;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    a.download = `melura_diagnostic_${timestamp}.md`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <ModalWide onClose={onClose}>
      <div className="px-5 pt-4 sm:pt-5 pb-4 border-b border-slate-200/50 dark:border-slate-800/50 flex flex-col shrink-0">
        <div className="flex items-center justify-between mb-1">
          <div className="flex items-center gap-2.5">
            <span className="text-indigo-500 bg-indigo-50 dark:bg-indigo-500/10 p-1.5 rounded-lg shrink-0">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>
              </svg>
            </span>
            <h2 className="text-base sm:text-lg font-bold text-slate-900 dark:text-white truncate">Сервисное меню</h2>
          </div>
          <div className="flex items-center gap-1">
            <button onClick={onClose} className="w-10 h-10 -mr-2 rounded-full flex items-center justify-center bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors" aria-label="Закрыть">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M18 6L6 18M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>
        <div className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500 ml-9 pr-10">
          Инструменты отладки ядра
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-5 sm:p-6 space-y-6 custom-scrollbar bg-slate-50/30 dark:bg-slate-900/30">
        
        <div className="bg-white dark:bg-slate-900 p-4 sm:p-5 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm flex flex-col gap-4">
          <div>
            <h3 className="font-extrabold text-sm mb-1.5 text-slate-900 dark:text-white">Диагностика физического движка</h3>
            <p className="text-xs text-slate-500 dark:text-slate-400 leading-relaxed">
              Формирует подробный Markdown-отчет по расчету смешивания красок. Прогоняет целевые цвета через все возможные комбинации настроек и профилей.
            </p>
          </div>

          {!isGenerating && !reportText && (
            <button 
              onClick={handleGenerate}
              className="w-full py-3.5 px-4 bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-black uppercase tracking-[0.2em] rounded-xl transition-all shadow-lg shadow-indigo-600/20 active:scale-[0.98]"
            >
              Запустить анализ
            </button>
          )}

          {isGenerating && (
            <div className="space-y-2.5 bg-slate-50 dark:bg-slate-800/50 p-4 rounded-xl border border-slate-100 dark:border-slate-700/50">
              <div className="flex justify-between items-center text-xs font-bold text-slate-700 dark:text-slate-300">
                <span className="truncate pr-4">{progressMsg}</span>
                <span className="shrink-0">{progressPct}%</span>
              </div>
              <div className="w-full bg-slate-200 dark:bg-slate-700 rounded-full h-2 overflow-hidden">
                <div className="bg-indigo-500 h-full rounded-full transition-all duration-300 ease-out" style={{ width: `${progressPct}%` }}></div>
              </div>
            </div>
          )}

          {reportText && !isGenerating && (
            <div className="flex flex-col gap-3">
              <textarea 
                readOnly
                value={reportText}
                className="w-full h-[280px] p-3 text-[11px] sm:text-xs font-mono bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-slate-800 dark:text-slate-300 focus:outline-none custom-scrollbar overflow-y-auto overscroll-contain resize-none shadow-inner"
              />
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                <button 
                  onClick={downloadReport}
                  className="col-span-2 sm:col-span-1 flex items-center justify-center gap-2 py-2.5 bg-emerald-500 hover:bg-emerald-600 text-white text-xs font-black uppercase tracking-wider rounded-xl transition-colors shadow-md shadow-emerald-500/20 active:scale-[0.98]"
                >
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg>
                  Скачать
                </button>
                <button 
                  onClick={copyToClipboard}
                  className="flex items-center justify-center gap-2 py-2.5 bg-slate-200 hover:bg-slate-300 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-800 dark:text-white text-xs font-black uppercase tracking-wider rounded-xl transition-colors active:scale-[0.98]"
                >
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="14" height="14" x="8" y="8" rx="2" ry="2"/><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/></svg>
                  Копия
                </button>
                <button 
                  onClick={handleGenerate}
                  className="flex items-center justify-center gap-2 py-2.5 bg-indigo-50 hover:bg-indigo-100 dark:bg-indigo-500/10 dark:hover:bg-indigo-500/20 text-indigo-700 dark:text-indigo-400 text-xs font-black uppercase tracking-wider rounded-xl transition-colors border border-indigo-200 dark:border-indigo-500/20 active:scale-[0.98]"
                >
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>
                  Заново
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="text-center text-[11px] font-medium text-slate-400 dark:text-slate-500 pt-1 pb-2">
          Melura · версия {APP_VERSION}{BUILD_DATE ? ` · сборка ${BUILD_DATE}` : ''}
        </div>
      </div>
    </ModalWide>
  );
}
