export function findSet(id: string, custom: PaintSet[] = []): PaintSet | undefined {
  return BUILT_IN_SETS.find(s => s.id === id) ?? custom.find(s => s.id === id);
}

/** Наборы, пригодные для указанного материала. */
export function setsForType(paintType: PaintType, custom: PaintSet[] = []): PaintSet[] {
  return [...BUILT_IN_SETS, ...custom].filter(s => s.paintType === paintType);
}

/**
 * Набор, включаемый по умолчанию при выборе материала.
 *
 * Отдельной «базовой палитры» больше нет: она была источником путаницы, потому
 * что не соответствовала ни одному материалу. Роль базы теперь исполняет
 * конкретный народный набор того же материала, что выбран в настройках.
 * Пользовательские наборы имеют приоритет: если человек откалибровал свои
 * краски, подставлять ему чужие незачем.
 */
export function defaultSetFor(paintType: PaintType, custom: PaintSet[] = []): PaintSet | undefined {
  const own = custom.filter(s => s.paintType === paintType);
  if (own.length) {
    // Самый свежий измеренный набор пользователя.
    return [...own].sort((a, b) => (b.createdAt ?? 0) - (a.createdAt ?? 0))[0];
  }
  return BUILT_IN_SETS.find(s => s.paintType === paintType);
}
