// src/generator/utils/recipeOptimizer.ts
import { calculateDrops, getErrorRating } from "../../engine";
import type { RecipeVariant } from "../../engine/types";
import { PAINT_PROFILES, SURFACE_PROFILES, type RGB, type ColorComponent, type EngineSettings } from "../../config";
import { deltaE00, rgbToLab } from "../../utils/colorMath";
import { mixColors } from "../../utils/mixing";
import { calculateDryColor } from "../../lab/core";

export interface OptimizationOption {
  type: "increase_parts" | "all_colors" | "new_shade";
  variant: RecipeVariant;
  description: string;
  totalParts?: number;
}

export interface ProblematicColor {
  id: number;
  targetRgb: RGB;
  currentVariant: RecipeVariant;
  options: OptimizationOption[];
}

export async function scanAndOptimize(
  targetPalette: Record<number, RGB>,
  validLabels: number[],
  selectedComps: ColorComponent[],
  allAvailableComps: ColorComponent[],
  engineSettings: EngineSettings,
  totalPartsLimit: number | null,
  onProgress: (pct: number) => void
): Promise<ProblematicColor[]> {
  const problems: ProblematicColor[] = [];
  const sl = [...validLabels].sort((a, b) => a - b);

  let completedCount = 0;
  
  const processColor = async (id: number): Promise<ProblematicColor | null> => {
    const target = targetPalette[id];
    const localOptions: OptimizationOption[] = [];
    
    // 1. Рассчитываем текущий лучший рецепт
    const currentRes = await calculateDrops(target, selectedComps, {
      ...engineSettings,
      targetTotalParts: totalPartsLimit
    }, () => {});

    const currentBest = currentRes.variants[0];
    
    // Если качество рецепта "Низкая" (DeltaE >= 3)
    if (currentBest.deltaE >= 3) {
      let problemSolved = false; // Флаг, что мы нашли рецепт с DeltaE < 3
      let bestExistingDelta = currentBest.deltaE;

      // ШАГ 1: Попытка увеличить количество частей (если лимит не "авто")
      if (totalPartsLimit !== null && totalPartsLimit > 0) {
        const increasedLimits = [totalPartsLimit + 2, totalPartsLimit * 2].filter(v => v <= 50);
        
        // Для ШАГА 1 можно также запустить параллельно, но они зависят друг от друга по bestExistingDelta,
        // поэтому оставим последовательно внутри одного цвета.
        for (const newLimit of increasedLimits) {
          const optRes = await calculateDrops(target, selectedComps, {
            ...engineSettings,
            targetTotalParts: newLimit
          }, () => {});
          
          let added = false;
          for (let vIdx = 0; vIdx < Math.min(3, optRes.variants.length); vIdx++) {
            const optBest = optRes.variants[vIdx];
            if (optBest.deltaE < bestExistingDelta - 0.5) {
              localOptions.push({
                type: "increase_parts",
                variant: optBest,
                description: `Увеличить лимит до ${newLimit} частей${vIdx > 0 ? ` (Вариант ${vIdx + 1})` : ''}`,
                totalParts: newLimit
              });
              added = true;
              if (optBest.deltaE < 3) problemSolved = true;
            }
          }
          
          if (added) {
            bestExistingDelta = Math.min(...localOptions.map(o => o.variant.deltaE));
          }
          if (problemSolved) break; // Проблема решена, больше лимиты не проверяем
        }
      }

      // ШАГ 2: В случае провала (DeltaE всё ещё >= 3), анализируем всю базу красок
      let allBest: RecipeVariant | null = null;
      
      if (!problemSolved) {
        const allRes = await calculateDrops(target, allAvailableComps, {
          ...engineSettings,
          targetTotalParts: totalPartsLimit
        }, () => {});
        
        let added = false;
        for (let vIdx = 0; vIdx < Math.min(3, allRes.variants.length); vIdx++) {
          const optAll = allRes.variants[vIdx];
          if (optAll.deltaE < bestExistingDelta - 0.5) {
            localOptions.push({
              type: "all_colors",
              variant: optAll,
              description: vIdx === 0 ? "Использовать другие краски из базы приложения" : `Альтернативный рецепт из базы #${vIdx + 1}`
            });
            added = true;
            if (vIdx === 0) allBest = optAll;
            if (optAll.deltaE < 3) problemSolved = true;
          }
        }
        
        if (added) {
          bestExistingDelta = Math.min(...localOptions.map(o => o.variant.deltaE));
        }
      }

      // ШАГ 3: Если даже вся база красок не помогла (DeltaE >= 3), предлагаем идеальную краску
      if (!problemSolved) {
        let bestSingle: ColorComponent | null = null;
        let minDelta = Infinity;
        let bestApproxRgb: RGB | null = null;
        const targetLab = rgbToLab(target);
        
        const profile = PAINT_PROFILES[engineSettings.paintType];
        const surface = engineSettings.surfaceType === 'custom'
          ? { ...SURFACE_PROFILES.custom, color: engineSettings.customSurfaceColor }
          : SURFACE_PROFILES[engineSettings.surfaceType];
        const substrateColor = profile.usesSubstrate ? surface.color : ([255, 255, 255] as RGB);
        
        for (const c of allAvailableComps) {
           // Физический вид краски на холсте (10 капель) + ВЫСЫХАНИЕ — чтобы
           // метрика совпадала с рецептами (они тоже сравниваются по сухому цвету).
           const wet = mixColors([10], [c.rgb], profile, substrateColor as RGB, false);
           const approxRgb = profile.drying ? calculateDryColor(wet, profile.drying) : wet;
           const d = deltaE00(rgbToLab(approxRgb), targetLab);
           if (d < minDelta) {
             minDelta = d;
             bestSingle = c;
             bestApproxRgb = approxRgb;
           }
        }

        if (bestSingle && bestApproxRgb && minDelta < bestExistingDelta - 0.5) {
          const isDuplicateOfAllBest = allBest && allBest.recipe.length === 1 && allBest.recipe[0].name === bestSingle.name;

          if (!isDuplicateOfAllBest) {
            const singleVariant: RecipeVariant = {
               recipe: [{
                 name: bestSingle.name,
                 rgb: bestSingle.rgb,
                 parts: totalPartsLimit || 10,
                 percent: 100
               }],
               deltaE: minDelta,
               tsDeltaE: minDelta,
               rating: getErrorRating(minDelta),
               totalDrops: totalPartsLimit || 10,
               approxRgb: bestApproxRgb,
               wetRgb: bestApproxRgb,
               dryRgb: bestApproxRgb,
               opticalRgb: bestApproxRgb,
               physicalRgb: bestApproxRgb,
               drops: [totalPartsLimit || 10],
               components: [bestSingle],
               usedColors: 1,
               label: ""
            };

            localOptions.push({
              type: "new_shade",
              variant: singleVariant,
              description: `Приобрести готовую краску: ${bestSingle.name}`
            });
          }
        }
      }
    }
    
    completedCount++;
    onProgress(Math.round((completedCount / sl.length) * 100));

    if (localOptions.length > 0) {
      return {
        id,
        targetRgb: target,
        currentVariant: currentBest,
        options: localOptions.sort((a, b) => a.variant.deltaE - b.variant.deltaE)
      };
    }
    return null;
  };

  // Ограничиваем одновременность числом воркеров: иначе на большой палитре
  // очередь к пулу распухает и задачи отваливаются по таймауту (+ CPU-трэш).
  // Кэш солвера при этом делает повторные цвета почти бесплатными.
  const LIMIT = Math.max(2, (typeof navigator !== 'undefined' ? (navigator.hardwareConcurrency || 4) : 4) - 1);
  const results: (ProblematicColor | null)[] = new Array(sl.length).fill(null);
  let cursor = 0;
  const runNext = async (): Promise<void> => {
    const idx = cursor++;
    if (idx >= sl.length) return;
    results[idx] = await processColor(sl[idx]);
    return runNext();
  };
  await Promise.all(Array.from({ length: Math.min(LIMIT, sl.length) }, () => runNext()));

  for (const r of results) {
    if (r) problems.push(r);
  }

  return problems;
}
