// Ловит системное событие beforeinstallprompt (Android/Chrome/Edge) как можно раньше
// — на уровне модуля, до монтирования React, — и отдаёт компонентам простой API:
//   canInstall   — установка реально доступна (событие пришло и не установлено);
//   promptInstall — вызвать нативный диалог установки.
// Если браузер не считает сайт устанавливаемым, событие не приходит и canInstall=false.
import { useEffect, useState } from 'react';

let deferred: any = null;
const listeners = new Set<() => void>();
const notify = () => listeners.forEach((l) => l());

function isStandalone(): boolean {
  if (typeof window === 'undefined') return false;
  return window.matchMedia?.('(display-mode: standalone)').matches || (navigator as any).standalone === true;
}

if (typeof window !== 'undefined') {
  window.addEventListener('beforeinstallprompt', (e: any) => {
    e.preventDefault();
    deferred = e;
    notify();
  });
  window.addEventListener('appinstalled', () => {
    deferred = null;
    notify();
  });
}

export function useInstallPrompt() {
  const [, force] = useState(0);
  useEffect(() => {
    const l = () => force((n) => n + 1);
    listeners.add(l);
    return () => { listeners.delete(l); };
  }, []);

  const promptInstall = async () => {
    if (!deferred) return;
    deferred.prompt();
    try { await deferred.userChoice; } catch { /* ignore */ }
    deferred = null;
    notify();
  };

  return { canInstall: !!deferred && !isStandalone(), promptInstall };
}
