// src/store/appStore.ts
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { DEFAULT_ENGINE_SETTINGS, BASE_COLORS, EXTENDED_COLORS, PAINT_PROFILES, type EngineSettings, type ColorComponent, type RGB } from '../config';
import type { HistoryEntry } from '../types';
import type { CalibrationEntry } from '../calibration';
import type { PaintSet } from '../paints/types';
import { findSet, defaultSetFor } from '../paints/sets';

/** Имена, которые уже есть во встроенной базе пигментов. */
const BUILT_IN_NAMES = new Set(EXTENDED_COLORS.map(c => c.name));

/**
 * Состояние палитры при включении набора.
 *
 * Вынесено в отдельную функцию, потому что вызывается из двух мест: явного
 * выбора набора и смены материала красок. Дублировать эту логику нельзя:
 * расхождение двух путей и порождало ситуацию, когда в настройках указан один
 * материал, а в палитре лежат краски другого.
 */
function paletteStateForSet(
  state: { customColors: ColorComponent[]; overrides: Record<string, RGB>; deletedBuiltIns: string[]; customPaintSets: PaintSet[] },
  ps: PaintSet,
) {
  const byName = new Map(state.customColors.map(c => [c.name, c]));
  const overrides = { ...state.overrides };

  for (const c of ps.colors) {
    if (BUILT_IN_NAMES.has(c.name)) {
      // Имя уже есть в базе пигментов. Прикидочные значения набора туда не
      // пишем: встроенное значение выверено и, возможно, уже уточнено
      // калибровкой. Измеренный набор — другое дело, он и есть источник
      // истины о цвете конкретной краски. Независимый набор исключение:
      // его названия не сверялись с номенклатурой, и совпадение имени
      // ничего не доказывает.
      if (ps.measured && !ps.standalone) overrides[c.name] = c.rgb;
    } else {
      byName.set(c.name, { name: c.name, rgb: c.rgb });
    }
  }

  const names = new Set(ps.colors.map(c => c.name));
  return {
    activePaintSetId: ps.id,
    customColors: Array.from(byName.values()),
    overrides,
    // Краска из набора не может оставаться в списке удалённых: иначе она
    // просто исчезнет из палитры, хотя человек заявил, что работает ею.
    deletedBuiltIns: state.deletedBuiltIns.filter(n => !names.has(n)),
    selectedNames: ps.colors.map(c => c.name),
  };
}

const INITIAL_SET = defaultSetFor(DEFAULT_ENGINE_SETTINGS.paintType);

interface AppState {
  isDark: boolean;
  customColors: ColorComponent[];
  overrides: Record<string, RGB>;
  deletedBuiltIns: string[];
  selectedNames: string[];
  engineSettings: EngineSettings;
  totalPartsLimit: string | number;
  history: HistoryEntry[];
  favorites: string[];

  // Навигационный интент между вкладками (Студия ↔ Академия). Транзитный —
  // не сохраняется. Позволяет глубоким компонентам попросить смену экрана.
  screenRequest: 'generator' | 'lab' | null;

  /** Наборы красок, собранные пользователем (в том числе калибровкой). */
  customPaintSets: PaintSet[];
  /** Какой набор сейчас в работе. null = свободная палитра, как было раньше. */
  activePaintSetId: string | null;

  /**
   * Фактура настоящей поверхности, снятая с фотографии пустого её куска.
   *
   * Хранится здесь, а не в наборе красок: поверхность и краски — разные вещи,
   * одним холстом человек пишет разными наборами. Плитка держится строкой
   * base64: пересчитывать её при каждом запуске значило бы требовать снимок
   * заново, а это неуважение к уже сделанной работе.
   */
  surfaceTexture: {
    tile: string;
    size: number;
    tileMm: number;
    amplitude: number;
    periodMm: number;
    summary: string;
  } | null;

  // Actions
  setScreenRequest: (s: 'generator' | 'lab' | null) => void;
  toggleTheme: () => void;
  setTheme: (isDark: boolean) => void;
  saveColor: (color: ColorComponent, isBuiltIn: boolean, originalName?: string) => void;
  deleteColor: (name: string, isCustom: boolean) => void;
  restoreBuiltIn: (name: string) => void;
  toggleColorSelection: (name: string) => void;
  setAllColorsSelection: (names: string[]) => void;
  resetPalette: () => void;
  updateEngineSettings: (patch: Partial<EngineSettings>) => void;
  setTotalPartsLimit: (limit: string | number) => void;
  addHistory: (entries: HistoryEntry[]) => void;
  clearHistory: () => void;
  toggleFavorite: (key: string) => void;
  clearFavorites: () => void;
  importCalibration: (entries: CalibrationEntry[]) => void;
  /** Делает набор активным и подставляет его цвета в палитру. */
  applyPaintSet: (id: string | null) => void;
  saveCustomPaintSet: (set: PaintSet) => void;
  deleteCustomPaintSet: (id: string) => void;
  setSurfaceTexture: (t: AppState['surfaceTexture']) => void;
}

export const useAppStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDark: window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)').matches : false,
      // На первом запуске палитра не «общий список всех красок», а конкретный
      // набор того материала, который выбран по умолчанию. Абстрактной базовой
      // палитры больше нет: она не соответствовала ни одному реальному
      // материалу и служила источником путаницы.
      customColors: INITIAL_SET ? INITIAL_SET.colors.filter(c => !BUILT_IN_NAMES.has(c.name)).map(c => ({ name: c.name, rgb: c.rgb })) : [],
      overrides: {},
      deletedBuiltIns: [],
      selectedNames: INITIAL_SET ? INITIAL_SET.colors.map(c => c.name) : BASE_COLORS.map(c => c.name),
      engineSettings: DEFAULT_ENGINE_SETTINGS,
      totalPartsLimit: 'авто',
      history: [],
      favorites: [],
      screenRequest: null,
      customPaintSets: [],
      activePaintSetId: INITIAL_SET?.id ?? null,
      surfaceTexture: null,

      setScreenRequest: (s) => set({ screenRequest: s }),

      toggleTheme: () => set((state) => ({ isDark: !state.isDark })),
      
      setTheme: (isDark) => set({ isDark }),

      saveColor: (c, isBuiltIn, originalName) => set((state) => {
        if (originalName) {
          // Если имя изменилось, обновляем его в selectedNames, чтобы цвет не пропал из палитры
          const updatedSelectedNames = state.selectedNames.map(n => n === originalName ? c.name : n);
          
          if (isBuiltIn) {
            const newOverrides = { ...state.overrides };
            if (c.name !== originalName) delete newOverrides[originalName];
            newOverrides[c.name] = c.rgb;
            return { overrides: newOverrides, selectedNames: updatedSelectedNames };
          } else {
            return { 
              customColors: state.customColors.map(x => x.name === originalName ? c : x),
              selectedNames: updatedSelectedNames
            };
          }
        } else {
          return {
            customColors: [...state.customColors, c],
            selectedNames: Array.from(new Set([...state.selectedNames, c.name]))
          };
        }
      }),

      deleteColor: (name, isCustom) => set((state) => {
        if (isCustom) {
          return {
            customColors: state.customColors.filter(c => c.name !== name),
            selectedNames: state.selectedNames.filter(n => n !== name)
          };
        } else {
          const { [name]: _, ...restOverrides } = state.overrides;
          return {
            deletedBuiltIns: Array.from(new Set([...state.deletedBuiltIns, name])),
            selectedNames: state.selectedNames.filter(n => n !== name),
            overrides: restOverrides
          };
        }
      }),

      restoreBuiltIn: (name) => set((state) => {
        const { [name]: _, ...restOverrides } = state.overrides;
        return {
          deletedBuiltIns: state.deletedBuiltIns.filter(n => n !== name),
          selectedNames: Array.from(new Set([...state.selectedNames, name])),
          overrides: restOverrides
        };
      }),

      toggleColorSelection: (name) => set((state) => ({
        selectedNames: state.selectedNames.includes(name)
          ? state.selectedNames.filter(n => n !== name)
          : [...state.selectedNames, name]
      })),

      setAllColorsSelection: (names) => set({ selectedNames: names }),

      // Сброс возвращает не абстрактную базу, а полный состав активного набора:
      // именно он и есть «всё, что у пользователя есть» при выбранном материале.
      resetPalette: () => set((state) => {
        const ps = state.activePaintSetId ? findSet(state.activePaintSetId, state.customPaintSets) : undefined;
        return { selectedNames: (ps ? ps.colors : BASE_COLORS).map(c => c.name) };
      }),

      updateEngineSettings: (patch) => set((state) => {
        const newSettings = { ...state.engineSettings, ...patch };
        if (patch.paintType && patch.paintType !== state.engineSettings.paintType) {
          // Рекомендуемое число цветов в замесе у каждого материала своё.
          newSettings.maxColorsInMix = PAINT_PROFILES[patch.paintType].maxColorsInMix;

          // Материал определяет набор. Без этого возникала бессмыслица:
          // выбрано масло, а в палитре остались акварельные краски прежнего
          // набора, и рецепты считались по чужому материалу.
          const ps = defaultSetFor(patch.paintType, state.customPaintSets);
          if (ps) return { engineSettings: newSettings, ...paletteStateForSet(state, ps) };
          return { engineSettings: newSettings, activePaintSetId: null };
        }
        return { engineSettings: newSettings };
      }),

      setTotalPartsLimit: (limit) => set({ totalPartsLimit: limit }),

      addHistory: (entries) => set((state) => {
        // Защита от дубликатов (спама) при многократном нажатии "Рассчитать"
        if (state.history.length > 0 && entries.length === 1) {
          const last = state.history[0];
          const curr = entries[0];
          if (last.hex === curr.hex && last.paintType === curr.paintType) {
            return state; 
          }
        }
        return { history: [...entries, ...state.history].slice(0, 50) };
      }),

      clearHistory: () => set({ history: [] }),

      toggleFavorite: (key) => set((state) => ({
        favorites: state.favorites.includes(key)
          ? state.favorites.filter(k => k !== key)
          : [...state.favorites, key]
      })),

      clearFavorites: () => set({ favorites: [] }),

      applyPaintSet: (id) => set((state) => {
        if (!id) return { activePaintSetId: null };
        const ps = findSet(id, state.customPaintSets);
        if (!ps) return { activePaintSetId: null };

        // Материал следует за набором, а не наоборот: акварельный набор не
        // может быть активен при выбранном масле.
        const engineSettings = state.engineSettings.paintType === ps.paintType
          ? state.engineSettings
          : {
              ...state.engineSettings,
              paintType: ps.paintType,
              maxColorsInMix: PAINT_PROFILES[ps.paintType].maxColorsInMix,
            };

        return { ...paletteStateForSet(state, ps), engineSettings };
      }),

      saveCustomPaintSet: (ps) => set((state) => ({
        customPaintSets: [
          ...state.customPaintSets.filter(x => x.id !== ps.id),
          { ...ps, custom: true, createdAt: ps.createdAt ?? Date.now() },
        ],
      })),

      setSurfaceTexture: (t) => set({ surfaceTexture: t }),

      deleteCustomPaintSet: (id) => set((state) => ({
        customPaintSets: state.customPaintSets.filter(x => x.id !== id),
        activePaintSetId: state.activePaintSetId === id ? null : state.activePaintSetId,
      })),

      importCalibration: (entries) => set((state) => {
        const overridesCopy = { ...state.overrides };
        const customColorsCopy = [...state.customColors];

        for (const e of entries) {
          const customIdx = customColorsCopy.findIndex(c => c.name === e.name);
          if (customIdx !== -1) {
            // Кастомный цвет обновляем напрямую, чтобы его можно было удалить потом
            customColorsCopy[customIdx] = { ...customColorsCopy[customIdx], rgb: e.calibratedRgb };
          } else {
            // Встроенный пишем в overrides
            overridesCopy[e.name] = e.calibratedRgb;
          }
        }
        return { overrides: overridesCopy, customColors: customColorsCopy };
      }),
    }),
    {
      name: 'melura_global_state',
      partialize: (state) => ({
        isDark: state.isDark,
        customColors: state.customColors,
        overrides: state.overrides,
        deletedBuiltIns: state.deletedBuiltIns,
        selectedNames: state.selectedNames,
        engineSettings: state.engineSettings,
        totalPartsLimit: state.totalPartsLimit,
        history: state.history,
        favorites: state.favorites,
        customPaintSets: state.customPaintSets,
        activePaintSetId: state.activePaintSetId,
        surfaceTexture: state.surfaceTexture,
      }),
      merge: (persistedState: any, currentState) => ({
        ...currentState,
        ...persistedState,
        engineSettings: {
          ...currentState.engineSettings,
          ...(persistedState?.engineSettings || {})
        }
      })
    }
  )
);