// src/generator/components/PaintingCoach.tsx
// Наставник режима «Живопись»: персональные советы по конкретному фото,
// мини-задания на этап, фото-самопроверка холста и режим «по памяти».
import { useMemo, useRef, useState } from "react";
import { useAppStore } from "../store";
import { cn } from "../../utils/cn";
import { rgbToHex } from "../../utils/colorMath";
import { wordColors } from "../../utils/plural";
import {
  analyzePaintingImage,
  computeImageStats,
  comparePaintingToReference,
  type PaintingInsights,
  type CoachReport,
} from "../utils/paintingCoach";
import type { RGB } from "../../config";

type StageId = "contours" | "underpaint" | "temperature" | "color" | "details";

function resolveStage(showTemp: boolean, layer: number): StageId {
  if (showTemp) return "temperature";
  if (layer === 0) return "contours";
  if (layer === 1) return "underpaint";
  if (layer === 3) return "color";
  if (layer === 4) return "details";
  return "underpaint";
}

function Swatch({ rgb, label }: { rgb: RGB; label: string }) {
  return (
    <div className="flex items-center gap-1.5">
      <span className="w-5 h-5 rounded-md border border-black/10 shadow-sm shrink-0" style={{ backgroundColor: rgbToHex(rgb) }} />
      <span className="text-[10px] font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400">{label}</span>
    </div>
  );
}

export function PaintingStageCoach({ showTemp, layer, isDark }: { showTemp: boolean; layer: number; isDark: boolean }) {
  const result = useAppStore((s) => s.result);
  const importanceMap = useAppStore((s) => s.importanceMap);
  const imageDimensions = useAppStore((s) => s.imageDimensions);

  const [checkOpen, setCheckOpen] = useState(false);
  const [memory, setMemory] = useState(false);

  const insights: PaintingInsights | null = useMemo(() => {
    if (!result) return null;
    const areaByLabel = new Map<number, number>();
    for (const cd of result.contoursData) {
      if (!result.validLabels.has(cd.labelId)) continue;
      areaByLabel.set(cd.labelId, (areaByLabel.get(cd.labelId) || 0) + cd.area);
    }
    const w = imageDimensions?.w || result.imgW;
    const h = imageDimensions?.h || result.imgH;
    return analyzePaintingImage(result.colorPalette as Record<number, RGB>, areaByLabel, importanceMap, w, h);
  }, [result, importanceMap, imageDimensions]);

  if (!result || !insights) return null;

  const stage = resolveStage(showTemp, layer);

  // Персональная строка «на вашем фото» под текущий этап.
  const personal: string[] = [];
  if (stage === "contours") {
    personal.push(`Смысловой центр — ${insights.subjectLabel}. Разместите его продуманно и проверьте пропорции.`);
  } else if (stage === "underpaint") {
    personal.push(insights.contrast === "high"
      ? "Сюжет контрастный — смело закладывайте глубокие тени и яркие света."
      : insights.contrast === "low"
        ? "Контраст сюжета мягкий — не пересильте тени, работайте сближенными тонами."
        : "Контраст средний — держите ясные свет, полутон и тень.");
  } else if (stage === "temperature") {
    personal.push(insights.tempBias === "warm"
      ? "Общий колорит тёплый — стройте гармонию на тёплых, а холодным подчёркивайте акценты."
      : insights.tempBias === "cool"
        ? "Общий колорит холодный — тёплые пятна станут смысловыми акцентами."
        : "Колорит нейтральный — балансируйте тёплое и холодное осознанно.");
  } else if (stage === "color") {
    personal.push(`В картине ~${insights.numColors} основных ${wordColors(insights.numColors)}. Кладите их в тон, найденный на подмалёвке, и держите приглушёнными.`);
  } else if (stage === "details") {
    personal.push(`Детали и максимальный контраст — только ${insights.subjectLabel} (главный объект). Края второстепенного смягчайте.`);
  }

  // Мини-задания (дриллы) с образцами цвета, где это уместно.
  return (
    <div className={cn("rounded-2xl border-2 p-4 space-y-3", isDark ? "border-slate-800 bg-slate-800/30" : "border-slate-100 bg-white shadow-sm")}>
      <div className="flex items-center gap-2">
        <span className="text-indigo-500 dark:text-indigo-300 shrink-0">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2a7 7 0 0 0-4 12.7V17a2 2 0 0 0 2 2h4a2 2 0 0 0 2-2v-2.3A7 7 0 0 0 12 2z"/><path d="M9 21h6"/></svg>
        </span>
        <div className="text-[11px] font-black uppercase tracking-[0.15em] text-slate-500 dark:text-slate-400">Наставник · на вашем фото</div>
      </div>

      {personal.map((p, i) => (
        <p key={i} className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed">{p}</p>
      ))}

      {/* Образцы-ориентиры под этап */}
      {stage === "underpaint" && (
        <div className="flex flex-wrap items-center gap-3 pt-1">
          <Swatch rgb={insights.darkest} label="самое тёмное" />
          <Swatch rgb={insights.lightest} label="самое светлое" />
          <span className="text-[10px] font-bold uppercase tracking-wide text-slate-400 dark:text-slate-500">свести к {insights.toneGroups} тонам</span>
        </div>
      )}
      {stage === "temperature" && (
        <div className="flex flex-wrap items-center gap-3 pt-1">
          <Swatch rgb={insights.warmest} label="самое тёплое" />
          <Swatch rgb={insights.coolest} label="самое холодное" />
        </div>
      )}

      {/* Действия наставника */}
      <div className="flex flex-col gap-2 pt-2 border-t border-slate-100 dark:border-slate-800">
        <button
          onClick={() => setCheckOpen(true)}
          className="w-full flex items-center justify-center gap-2 py-2.5 rounded-xl text-[11px] font-black uppercase tracking-widest bg-indigo-600 text-white shadow-lg shadow-indigo-600/20 hover:bg-indigo-700 transition-all active:scale-[0.98]"
        >
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg>
          Самопроверка этапа по фото
        </button>

        <button
          onClick={() => setMemory((m) => !m)}
          className={cn(
            "w-full flex items-center justify-center gap-2 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest border-2 transition-all active:scale-[0.98]",
            memory
              ? "bg-amber-500/10 border-amber-500/40 text-amber-600 dark:text-amber-400"
              : isDark ? "border-slate-700 text-slate-300 hover:border-slate-600" : "border-slate-100 text-slate-500 hover:border-slate-200"
          )}
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">{memory ? <><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><path d="M1 1l22 22"/></> : <><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></>}</svg>
          {memory ? "Эталон скрыт — пишите по памяти" : "Режим «по памяти»"}
        </button>
      </div>

      {memory && (
        <p className="text-[11px] text-amber-700/80 dark:text-amber-400/80 leading-relaxed">
          Отвернитесь от экрана и пишите этап по памяти 5–10 минут. Затем вернитесь и запустите «Самопроверку по фото» — так вырабатывается насмотренность и независимость от образца.
        </p>
      )}

      {checkOpen && (
        <PaintingSelfCheckModal
          stage={stage}
          refData={result.previewImageData}
          isDark={isDark}
          onClose={() => setCheckOpen(false)}
        />
      )}
    </div>
  );
}

const STAGE_CHECK_HINT: Record<StageId, string> = {
  contours: "Сверяем общий тон и композицию наброска с эталоном.",
  underpaint: "Сверяем тональный разбор: светлоту, контраст и долю теней.",
  temperature: "Сверяем температурный баланс: тёплое/холодное.",
  color: "Сверяем цвет: светлоту, контраст и температуру в массе.",
  details: "Финальная сверка тона, контраста и температуры всей работы.",
};

function PaintingSelfCheckModal({
  stage, refData, isDark, onClose,
}: { stage: StageId; refData: ImageData; isDark: boolean; onClose: () => void }) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [report, setReport] = useState<CoachReport | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  const refStats = useMemo(() => computeImageStats(refData.data, refData.width, refData.height), [refData]);

  const onFile = (file: File) => {
    setErr(null); setBusy(true); setReport(null);
    const img = new Image();
    img.onload = () => {
      try {
        const MAX = 900;
        const k = Math.min(1, MAX / Math.max(img.width, img.height));
        const w = Math.max(1, Math.round(img.width * k));
        const h = Math.max(1, Math.round(img.height * k));
        const cv = document.createElement("canvas");
        cv.width = w; cv.height = h;
        const cx = cv.getContext("2d");
        if (!cx) { setErr("Не удалось обработать фото."); setBusy(false); return; }
        cx.drawImage(img, 0, 0, w, h);
        setPreview(cv.toDataURL("image/jpeg", 0.7));
        const data = cx.getImageData(0, 0, w, h).data;
        const userStats = computeImageStats(data, w, h);
        setReport(comparePaintingToReference(userStats, refStats));
      } catch {
        setErr("Не удалось обработать фото.");
      } finally {
        setBusy(false);
      }
    };
    img.onerror = () => { setErr("Не удалось загрузить фото."); setBusy(false); };
    img.src = URL.createObjectURL(file);
  };

  return (
    <div className="fixed inset-0 z-[130] flex items-end sm:items-center justify-center p-0 sm:p-4" role="dialog" aria-modal="true" aria-label="Самопроверка этапа">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className={cn("relative z-10 w-full sm:max-w-md max-h-[85dvh] flex flex-col rounded-t-3xl sm:rounded-2xl shadow-premium overflow-hidden", isDark ? "bg-slate-900 border border-slate-800" : "bg-white")}>
        <div className={cn("flex items-center justify-between px-5 pt-4 pb-3 border-b", isDark ? "border-slate-800" : "border-slate-100")}>
          <div>
            <h2 className={cn("text-base font-bold", isDark ? "text-slate-100" : "text-slate-900")}>Самопроверка этапа</h2>
            <div className="text-[11px] font-bold uppercase tracking-widest text-slate-400 dark:text-slate-500 mt-0.5">Сравнение с эталоном</div>
          </div>
          <button onClick={onClose} aria-label="Закрыть" className={cn("w-9 h-9 rounded-full flex items-center justify-center", isDark ? "bg-slate-800 text-slate-400 hover:bg-slate-700" : "bg-slate-100 text-slate-500 hover:bg-slate-200")}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><path d="M18 6L6 18M6 6l12 12"/></svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 space-y-4 custom-scrollbar">
          <p className="text-xs text-slate-500 dark:text-slate-400 leading-relaxed">
            Сфотографируйте свой холст (по возможности при ровном свете, фронтально). {STAGE_CHECK_HINT[stage]} Сравнение — по общему тону, контрасту и температуре и устойчиво к неточной съёмке.
          </p>

          <input ref={fileRef} type="file" accept="image/*" capture="environment" className="hidden"
            onChange={(e) => { const f = e.target.files?.[0]; if (f) onFile(f); e.target.value = ""; }} />

          <button onClick={() => fileRef.current?.click()} disabled={busy}
            className="w-full py-3 rounded-2xl text-xs font-black uppercase tracking-widest bg-indigo-600 text-white hover:bg-indigo-700 transition-all active:scale-[0.98] disabled:opacity-50">
            {busy ? "Анализ…" : preview ? "Заменить фото" : "Сделать / выбрать фото холста"}
          </button>

          {err && <div className="text-xs font-bold text-rose-500">{err}</div>}

          {preview && (
            <img src={preview} alt="Ваш холст" className="w-full rounded-xl border border-slate-200 dark:border-slate-700" />
          )}

          {report && (
            <div className="space-y-2">
              <div className={cn("text-xs font-black uppercase tracking-widest",
                report.grade === "close" ? "text-emerald-500" : "text-amber-500")}>
                {report.grade === "close" ? "Хорошо — близко к эталону" : "Есть над чем поработать"}
              </div>
              {report.verdicts.map((vd, i) => (
                <div key={i} className={cn("flex gap-2 p-3 rounded-xl text-xs leading-relaxed",
                  vd.kind === "ok"
                    ? (isDark ? "bg-emerald-500/10 text-emerald-300" : "bg-emerald-50 text-emerald-700")
                    : (isDark ? "bg-slate-800 text-slate-200" : "bg-slate-50 text-slate-700"))}>
                  <span className="shrink-0 mt-0.5 text-indigo-500">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6L9 17l-5-5"/></svg>
                  </span>
                  <span>{vd.text}</span>
                </div>
              ))}
              <p className="text-[10px] text-slate-400 dark:text-slate-500 leading-relaxed pt-1">
                Оценка приблизительная: сравниваются общий тон, контраст и температура, а не точное совпадение пикселей.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
