// src/calib/swatch.ts
//
// ИЗВЛЕЧЕНИЕ РЕАЛЬНОГО ЦВЕТА МАЗКА.
//
// Старый алгоритм брал медиану «пучка» пикселей. Это плохо ровно потому, что
// медиана считает блик, тень от бугорка и краску одной сущностью и усредняет их.
// Блик поверх синего даёт светло-голубой; медиана честно вернёт что-то
// посередине — и рецепт будет замешан не на тот цвет.
//
// Здесь используется дихроматическая модель отражения: свет, ушедший в камеру,
// = диффузная часть (собственно цвет краски) + зеркальная часть (блик, у него
// цвет ЛАМПЫ, а не краски). Из неё следуют два факта, на которых всё держится:
//
//   1. У матовой краски цветность (доля каналов в сумме) постоянна по всему
//      мазку и НЕ зависит от того, как повёрнут бугорок и сколько на него
//      упало света. Меняется только яркость.
//   2. Блик подмешивает нейтральный свет и утаскивает цветность к серому.
//
// Отсюда алгоритм: найти самую населённую цветность (это и есть краска),
// выбросить всё, что от неё ушло (блики, бумага, соседний мазок), а среди
// оставшегося взять моду яркости — самую частую ориентацию поверхности,
// то есть ровно лежащую краску. Тени в ямках и искры на гранях остаются
// в хвостах гистограммы и на ответ не влияют.

import { linearToSrgb, srgbToLinear } from '../utils/colorMath';
import type { RGB } from '../config';

export interface SwatchReading {
  /** Итоговый цвет краски в sRGB, бумага принята за белый. */
  rgb: RGB;
  /** 0..100. Ниже 55 — стоит переснять. */
  confidence: number;
  /** Доля пикселей, отбракованных как блик. */
  specularPct: number;
  /** Доля пикселей, попавших в основное облако цветности. */
  coveragePct: number;
  /** Доля пикселей, выбитых в 255 или в 0 — там информации о цвете уже нет. */
  clippedPct: number;
  /**
   * Глянец слоя, 0..1. Измеряется по яркому «хвосту» тех пикселей, чья
   * цветность утянута к цвету источника: это и есть зеркальная составляющая.
   * У матовой гуаши такого хвоста практически нет, у масла он выражен.
   *
   * Оговорка, о которой нельзя молчать: величина зависит и от того, под каким
   * углом снят лист. Она годится как оценка порядка, а не как паспортное
   * значение блеска.
   */
  gloss: number;
  /**
   * Зернистость слоя, 0..1. Робастный разброс яркости внутри диффузного
   * облака: гранулирующая акварель и грубый мазок дают высокий разброс,
   * ровно укрытая гуашь — низкий.
   */
  grain: number;
  /** Человеческие предупреждения для UI. */
  warnings: string[];
  /** Пусто, если в окне вообще нечего мерить. */
  empty: boolean;
}

interface Px { r: number; g: number; b: number; cr: number; cg: number; i: number }


/** Читает окно, переводит в линейный свет, делит на локальный белый. */
function collect(
  rect: ImageData,
  r: { x: number; y: number; w: number; h: number },
  whiteAt: (x: number, y: number) => [number, number, number],
): { px: Px[]; clipped: number; totalRead: number } {
  const { data, width, height } = rect;
  const x0 = Math.max(0, Math.round(r.x)), x1 = Math.min(width - 1, Math.round(r.x + r.w));
  const y0 = Math.max(0, Math.round(r.y)), y1 = Math.min(height - 1, Math.round(r.y + r.h));

  const px: Px[] = [];
  let clipped = 0, totalRead = 0;

  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      const idx = (y * width + x) * 4;
      if (data[idx + 3] < 128) continue;
      totalRead++;

      const sr = data[idx], sg = data[idx + 1], sb = data[idx + 2];
      // Выбитые пиксели несут ноль информации о цвете: в 255 сгорели все
      // различия в светах, в 0 — в тенях. Считаем их отдельно и не мерим.
      if (sr >= 253 || sg >= 253 || sb >= 253 || (sr <= 2 && sg <= 2 && sb <= 2)) { clipped++; continue; }

      const w = whiteAt(x, y);
      // Деление на локальный белый — это одновременно и выравнивание света,
      // и баланс белого по бумаге (фон Криза по диагонали в линейном свете).
      const lr = srgbToLinear(sr) / w[0];
      const lg = srgbToLinear(sg) / w[1];
      const lb = srgbToLinear(sb) / w[2];

      const i = lr + lg + lb;
      if (i < 1e-4) continue;
      px.push({ r: lr, g: lg, b: lb, cr: lr / i, cg: lg / i, i });
    }
  }
  return { px, clipped, totalRead };
}

/**
 * @param rect      выпрямленный лист
 * @param rectPx    окно замера в пикселях выпрямленного листа
 * @param whiteAt   локальный белый из карты освещённости
 */
export function readSwatch(
  rect: ImageData,
  rectPx: { x: number; y: number; w: number; h: number },
  whiteAt: (x: number, y: number) => [number, number, number],
): SwatchReading {
  const { px, clipped, totalRead } = collect(rect, rectPx, whiteAt);

  if (px.length < 25) {
    return {
      rgb: [128, 128, 128], confidence: 0, specularPct: 0, coveragePct: 0, gloss: 0, grain: 0,
      clippedPct: totalRead ? Math.round((clipped / totalRead) * 100) : 100,
      warnings: ['Мазок не обнаружен. Ячейка не заполнена.'], empty: true,
    };
  }

  // Замер идёт строго по центральному окну. Пробовал расширять его до всей
  // напечатанной рамки, чтобы поймать менее засвеченную краску по краям, —
  // на стенде стало заметно хуже: у края мазок тоньше, просвечивает бумага,
  // и переходные пиксели ломают оценку цветности.
  const cpx = px;

  // ── 1. Мода цветности: самое населённое место в плоскости (cr, cg) ──────────
  // Сетка 0.005 ≈ порог различимости и заведомо мельче разброса от текстуры.
  const BIN = 0.005;
  const hist = new Map<number, number>();
  const key = (p: Px) => Math.round(p.cr / BIN) * 4096 + Math.round(p.cg / BIN);
  for (const p of cpx) hist.set(key(p), (hist.get(key(p)) || 0) + 1);

  let bestKey = 0, bestCount = -1;
  for (const [k, c] of hist) if (c > bestCount) { bestCount = c; bestKey = k; }
  let modeCr = Math.round(bestKey / 4096) * BIN;
  let modeCg = (bestKey - Math.round(bestKey / 4096) * 4096) * BIN;

  // Уточняем моду средним сдвигом: два прохода по окрестности радиуса 0.02
  // подтягивают центр к настоящему пику, а не к границе ячейки гистограммы.
  for (let iter = 0; iter < 2; iter++) {
    let sr = 0, sg = 0, n = 0;
    const R = 0.02;
    for (const p of cpx) {
      const d = Math.hypot(p.cr - modeCr, p.cg - modeCg);
      if (d < R) { sr += p.cr; sg += p.cg; n++; }
    }
    if (n > 0) { modeCr = sr / n; modeCg = sg / n; }
  }

  // ── 1б. Поправка на «блик занял больше половины ячейки» ────────────────────
  //
  // Мода — это голосование большинством, и на глянцевом акриле блик это
  // большинство может выиграть: тогда за цвет краски принимается цвет лампы.
  // Спасает асимметрия физики: подмешивание блика двигает цветность ТОЛЬКО
  // к нейтрали и никогда от неё. Значит все пиксели ячейки лежат на отрезке
  // между нейтралью и настоящим цветом краски, а краска — это дальний конец
  // отрезка, а не самая населённая его точка.
  //
  // Берём высокий процентиль удаления от нейтрали вдоль этого направления:
  // сам максимум был бы неустойчив к шуму, а 96-й процентиль — нет.
  // Значение подобрано замерами на стенде: ниже — хуже худшие случаи,
  // выше — начинает пересыщать чистые мазки.
  const NEUTRAL = 1 / 3;
  let stabilitySpread = 0;
  const dirX0 = modeCr - NEUTRAL, dirY0 = modeCg - NEUTRAL;
  const dirLen = Math.hypot(dirX0, dirY0);

  // У нейтральных красок (серая, чёрная, белила) направление вырождено —
  // там отрезок стягивается в точку, и остаётся честная мода.
  if (dirLen > 0.015) {
    const dx = dirX0 / dirLen, dy = dirY0 / dirLen;
    const onLine: number[] = [];
    for (const p of cpx) {
      const vx = p.cr - NEUTRAL, vy = p.cg - NEUTRAL;
      const t = vx * dx + vy * dy;
      if (t <= 0) continue;                                   // «за» нейтралью — чужой цвет
      const perp = Math.abs(vx * dy - vy * dx);
      if (perp > 0.02) continue;                              // сбоку от линии — другая краска
      onLine.push(t);
    }
    if (onLine.length >= cpx.length * 0.25) {
      onLine.sort((a, b) => a - b);
      const at = (q: number) => onLine[Math.min(onLine.length - 1, Math.floor(onLine.length * q))];
      const tMid = at(0.5);
      const tHi = at(0.96);

      // Насколько распределение растянуто к нейтрали. У чистого матового мазка
      // цветность постоянна и разброс близок к нулю; блик добавляет длинный
      // хвост в сторону серого, и разброс растёт.
      const spreadRel = tHi > 1e-6 ? (tHi - tMid) / tHi : 0;

      // Экстраполяция нужна ТОЛЬКО когда блик действительно есть. На бледной
      // акварели, где сигнал слаб и хвоста нет, 96-й процентиль подхватывал
      // шум и систематически пересыщал цвет. Проверено на реальных сканах:
      // там разброс мал, и правильный ответ даёт медиана.
      const w = Math.max(0, Math.min(1, (spreadRel - 0.08) / 0.22));
      const tUse = tMid + (tHi - tMid) * w;

      modeCr = NEUTRAL + dx * tUse;
      modeCg = NEUTRAL + dy * tUse;

      // Расхождение двух крайних оценок — прямая мера устойчивости замера.
      // Если медиана и высокий процентиль дают почти один цвет, ответ не
      // зависит от выбора статистики и ему можно верить.
      stabilitySpread = spreadRel;

      // Насколько сильно «выцветание к нейтрали» разбросано по ячейке.
      // У чистого матового мазка цветность постоянна, и разброс близок к нулю.
      // Если же по мазку размазан блик, часть пикселей систематически ближе
      // к серому — и разброс растёт. Это единственный признак, по которому
      // можно отличить «краска действительно бледная» от «краску залило бликом».
    }
  }

  // ── 2. Инлайеры: пиксели той же цветности = диффузная краска ───────────────
  const dists = px.map(p => Math.hypot(p.cr - modeCr, p.cg - modeCg));
  const sortedD = [...dists].sort((a, b) => a - b);
  const madD = Math.max(0.004, sortedD[Math.floor(sortedD.length * 0.5)]);
  const radius = Math.min(0.05, Math.max(0.012, madD * 2.2));

  const inliers: Px[] = [];
  let specular = 0;
  for (let k = 0; k < px.length; k++) {
    if (dists[k] <= radius) { inliers.push(px[k]); continue; }
    // Ушёл от моды И при этом ближе к нейтрали и ярче — это блик, а не
    // соседний мазок. Различать важно: блик мы «прощаем», а чужую краску
    // в кадре надо показать пользователю как низкое покрытие.
    const dNeutralPx = Math.hypot(px[k].cr - 1 / 3, px[k].cg - 1 / 3);
    const dNeutralMode = Math.hypot(modeCr - 1 / 3, modeCg - 1 / 3);
    if (dNeutralPx < dNeutralMode) specular++;
  }

  const pool = inliers.length >= 20 ? inliers : px;

  // ── 3. Мода яркости среди инлайеров ───────────────────────────────────────
  // Именно мода, а не среднее и не медиана: у краски с фактурой гистограмма
  // яркости несимметрична — слева хвост из теней между бугорками, справа из
  // подсвеченных граней. Пик отвечает ровно лежащей поверхности.
  const intens = pool.map(p => p.i);
  const iMin = Math.min(...intens), iMax = Math.max(...intens);
  const span = Math.max(1e-6, iMax - iMin);
  const NB = 48;
  const ihist = new Float64Array(NB);
  for (const v of intens) ihist[Math.min(NB - 1, Math.floor(((v - iMin) / span) * NB))]++;

  // Лёгкое сглаживание, иначе на малых выборках пик прыгает по соседним корзинам.
  const sm = new Float64Array(NB);
  for (let k = 0; k < NB; k++) {
    sm[k] = (ihist[Math.max(0, k - 1)] + 2 * ihist[k] + ihist[Math.min(NB - 1, k + 1)]) / 4;
  }
  let peak = 0;
  for (let k = 1; k < NB; k++) if (sm[k] > sm[peak]) peak = k;

  // Центр тяжести пика по трём корзинам — даёт субкорзинную точность.
  let wsum = 0, vsum = 0;
  for (let k = Math.max(0, peak - 1); k <= Math.min(NB - 1, peak + 1); k++) {
    const lo = iMin + (k / NB) * span, hi = iMin + ((k + 1) / NB) * span;
    for (const v of intens) if (v >= lo && v < hi) { vsum += v; wsum++; }
  }
  const iPeak = wsum > 0 ? vsum / wsum : (iMin + iMax) / 2;

  // ── 4. Сборка цвета: цветность моды × яркость пика ────────────────────────
  const cb = 1 - modeCr - modeCg;
  const lin: [number, number, number] = [modeCr * iPeak, modeCg * iPeak, cb * iPeak];

  const rgb: RGB = [
    Math.max(0, Math.min(255, Math.round(linearToSrgb(lin[0]) * 255))),
    Math.max(0, Math.min(255, Math.round(linearToSrgb(lin[1]) * 255))),
    Math.max(0, Math.min(255, Math.round(linearToSrgb(lin[2]) * 255))),
  ];

  // ── 5. Оценка доверия и предупреждения ────────────────────────────────────
  const coveragePct = Math.round((inliers.length / px.length) * 100);
  const specularPct = Math.round((specular / px.length) * 100);
  const clippedPct = totalRead ? Math.round((clipped / totalRead) * 100) : 0;

  const warnings: string[] = [];
  let confidence = 100;

  // Разброс цветности у акварельной заливки велик по природе: слой тонкий,
  // пигмент ложится неровно, сквозь него просвечивает бумага. Проверка на
  // реальных бланках показала, что при покрытии 30–55 % цвет читается верно,
  // а прежний порог помечал такие ячейки как сомнительные. Тревожно только
  // тогда, когда в окне замера действительно два разных цвета.
  if (coveragePct < 32) {
    confidence -= (32 - coveragePct) * 1.5;
    warnings.push('В области замера присутствует более одного цвета. Заполните рамку полностью.');
  }
  if (specularPct > 40) {
    confidence -= (specularPct - 40) * 0.8;
    warnings.push('Значительная доля бликов. Измените угол съёмки или уберите направленный свет.');
  }
  // Выбитые пиксели мы просто не берём в расчёт, поэтому небольшая доля
  // безвредна: мода считается по оставшимся. Опасно, когда выбита половина
  // ячейки — тогда от неё остались одни затенённые края, и яркость занижается.
  if (clippedPct > 25) {
    confidence -= (clippedPct - 25) * 1.6;
    warnings.push(clippedPct > 55
      ? 'Ячейка пересвечена. Цвет не восстанавливается, требуется повторная съёмка с меньшей экспозицией.'
      : 'Часть светлых участков пересвечена. Рекомендуется уменьшить экспозицию.');
  }
  const lum = 0.2126 * lin[0] + 0.7152 * lin[1] + 0.0722 * lin[2];
  if (lum > 1.06) warnings.push('Яркость ячейки превышает яркость бумаги. Вероятен блик.');
  if (lum < 0.008) warnings.push('Крайне низкая яркость. Убедитесь, что в области замера краска, а не тень.');

  // Разброс цветности внутри инлайеров: рыхлая, полупрозрачная или плохо
  // просохшая краска даёт «размазанное» облако.
  // Устойчивость: расходятся ли медианная и максимальная оценки цветности.
  // Это честный признак сомнительного замера, в отличие от простой
  // неоднородности, которая у акварели является нормой.
  if (stabilitySpread > 0.35) {
    confidence -= (stabilitySpread - 0.35) * 90;
    warnings.push('Замер неустойчив: поверх краски лежит сильный блик. Измените угол съёмки.');
  }

  // ── 6. Физика слоя ────────────────────────────────────────────────────────
  //
  // Здесь измеряется не цвет, а поведение поверхности: насколько она блестит
  // и насколько зерниста. Эти две величины и определяют, как работа будет
  // выглядеть при боковом свете, поэтому их стоит взять с реального мазка,
  // а не из таблицы «у масла блеск такой-то».

  // Глянец. Берём пиксели, чья цветность утянута к нейтрали сильнее, чем у
  // моды: это зеркальное отражение источника. Важна не их доля, а насколько
  // они ЯРЧЕ диффузного пика — матовая поверхность рассеивает свет ровно и
  // яркого хвоста не даёт вовсе.
  const specI: number[] = [];
  const dNeutralMode2 = Math.hypot(modeCr - 1 / 3, modeCg - 1 / 3);
  for (let k = 0; k < px.length; k++) {
    if (dists[k] <= radius) continue;
    if (Math.hypot(px[k].cr - 1 / 3, px[k].cg - 1 / 3) < dNeutralMode2) specI.push(px[k].i);
  }
  let gloss = 0;
  if (specI.length >= 4 && iPeak > 1e-6) {
    specI.sort((a, b) => a - b);
    const hi = specI[Math.floor(specI.length * 0.9)];
    const excess = Math.max(0, (hi - iPeak) / iPeak);
    // Доля зеркальных пикселей входит в оценку с корнем: даже небольшая, но
    // яркая зона блика говорит о глянце, а линейный вес её бы утопил.
    const frac = Math.sqrt(Math.min(1, specI.length / px.length));
    gloss = Math.max(0, Math.min(1, excess * frac * 1.6));
  }

  // Зернистость. Робастный разброс яркости внутри диффузного облака,
  // отнесённый к самой яркости. Межквантильный размах, а не дисперсия:
  // одиночная пылинка или волосок кисти не должны определять результат.
  let grain = 0;
  if (pool.length >= 12 && iPeak > 1e-6) {
    const gi = pool.map(p => p.i).sort((a, b) => a - b);
    const lo = gi[Math.floor(gi.length * 0.16)];
    const hi = gi[Math.floor(gi.length * 0.84)];
    grain = Math.max(0, Math.min(1, ((hi - lo) / (2 * iPeak)) * 2.2));
  }

  return {
    rgb,
    confidence: Math.max(0, Math.min(100, Math.round(confidence))),
    specularPct, coveragePct, clippedPct, gloss, grain, warnings, empty: false,
  };
}
