// src/generator/utils/imageProcessing/importanceMap.ts
// Строит карту визуальной значимости (Importance Map) для каждого пикселя.
// Importance Map управляет квантизацией палитры, фильтрацией и post-processing.

// ─────────────────────────────────────────────────────────────
// Signal 1: Spectral Residual Saliency (Hou & Zhang, 2007)
// Полностью вычислительный, 0 ML-зависимостей.
// ─────────────────────────────────────────────────────────────

/** Radix-2 Cooley-Tukey FFT (in-place, iterative). Работает на массивах длины 2^N. */
function fft(re: Float64Array, im: Float64Array, inverse: boolean): void {
  const n = re.length;
  // Bit-reversal permutation
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      let tmp = re[i]; re[i] = re[j]; re[j] = tmp;
      tmp = im[i]; im[i] = im[j]; im[j] = tmp;
    }
  }
  const sign = inverse ? -1 : 1;
  for (let len = 2; len <= n; len <<= 1) {
    const half = len >> 1;
    const angle = (sign * 2 * Math.PI) / len;
    const wRe = Math.cos(angle);
    const wIm = Math.sin(angle);
    for (let i = 0; i < n; i += len) {
      let curRe = 1, curIm = 0;
      for (let j = 0; j < half; j++) {
        const uRe = re[i + j], uIm = im[i + j];
        const vRe = re[i + j + half] * curRe - im[i + j + half] * curIm;
        const vIm = re[i + j + half] * curIm + im[i + j + half] * curRe;
        re[i + j] = uRe + vRe;
        im[i + j] = uIm + vIm;
        re[i + j + half] = uRe - vRe;
        im[i + j + half] = uIm - vIm;
        const tmpR = curRe * wRe - curIm * wIm;
        curIm = curRe * wIm + curIm * wRe;
        curRe = tmpR;
      }
    }
  }
  if (inverse) {
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
  }
}

/** Ближайшая степень двойки >= n */
function nextPow2(n: number): number {
  let p = 1;
  while (p < n) p <<= 1;
  return p;
}

/**
 * 2D FFT через построчную/постолбцовую 1D FFT.
 * Работает in-place, ожидает padded массивы размера fftW × fftH (степени двойки).
 */
function fft2d(re: Float64Array, im: Float64Array, w: number, h: number, inverse: boolean): void {
  // Rows
  const rowRe = new Float64Array(w);
  const rowIm = new Float64Array(w);
  for (let y = 0; y < h; y++) {
    const off = y * w;
    rowRe.set(re.subarray(off, off + w));
    rowIm.set(im.subarray(off, off + w));
    fft(rowRe, rowIm, inverse);
    re.set(rowRe, off);
    im.set(rowIm, off);
  }
  // Columns
  const colRe = new Float64Array(h);
  const colIm = new Float64Array(h);
  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) { colRe[y] = re[y * w + x]; colIm[y] = im[y * w + x]; }
    fft(colRe, colIm, inverse);
    for (let y = 0; y < h; y++) { re[y * w + x] = colRe[y]; im[y * w + x] = colIm[y]; }
  }
}

/**
 * Spectral Residual Saliency.
 * Возвращает Float32Array[w*h] с нормализованными значениями 0..1.
 */
function computeSpectralSaliency(gray: Float32Array, w: number, h: number): Float32Array {
  const fftW = nextPow2(w);
  const fftH = nextPow2(h);
  const n = fftW * fftH;

  const re = new Float64Array(n);
  const im = new Float64Array(n);

  // Заполняем с zero-padding
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      re[y * fftW + x] = gray[y * w + x];
    }
  }

  // Forward FFT
  fft2d(re, im, fftW, fftH, false);

  // Log amplitude spectrum
  const logAmp = new Float64Array(n);
  const phase = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    const amp = Math.sqrt(re[i] * re[i] + im[i] * im[i]);
    logAmp[i] = Math.log(amp + 1e-10);
    phase[i] = Math.atan2(im[i], re[i]);
  }

  // Average filter on log amplitude (3×3 mean filter in frequency domain)
  const smoothed = new Float64Array(n);
  for (let y = 0; y < fftH; y++) {
    for (let x = 0; x < fftW; x++) {
      let sum = 0, count = 0;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          const ny = (y + dy + fftH) % fftH;
          const nx = (x + dx + fftW) % fftW;
          sum += logAmp[ny * fftW + nx];
          count++;
        }
      }
      smoothed[y * fftW + x] = sum / count;
    }
  }

  // Spectral Residual = log_amp - smoothed_log_amp
  // Reconstruct with original phase
  for (let i = 0; i < n; i++) {
    const residual = logAmp[i] - smoothed[i];
    const amp = Math.exp(residual);
    re[i] = amp * Math.cos(phase[i]);
    im[i] = amp * Math.sin(phase[i]);
  }

  // Inverse FFT
  fft2d(re, im, fftW, fftH, true);

  // Squared magnitude → saliency
  const raw = new Float32Array(w * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const val = re[y * fftW + x];
      raw[y * w + x] = val * val;
    }
  }

  // Gaussian blur (σ=8) для сглаживания шумных пиков
  const blurred = gaussianBlur(raw, w, h, 8);

  // Normalize to 0..1
  let maxVal = 0;
  for (let i = 0; i < blurred.length; i++) {
    if (blurred[i] > maxVal) maxVal = blurred[i];
  }
  if (maxVal > 0) {
    for (let i = 0; i < blurred.length; i++) {
      blurred[i] /= maxVal;
    }
  }
  return blurred;
}

// ─────────────────────────────────────────────────────────────
// Signal 2: Semantic Segmentation Weight
// ─────────────────────────────────────────────────────────────

const SEMANTIC_WEIGHTS: Record<number, number> = {
  0: 0.10, // background
  1: 0.60, // hair
  2: 0.70, // body
  3: 1.00, // face
  4: 0.30, // clothes
  5: 0.50, // accessories
  6: 0.98, // eyes/lips (injected zone from face landmarks)
};

function computeSemanticMap(
  semanticMask: Uint8Array | null,
  maskW: number, maskH: number,
  targetW: number, targetH: number,
): Float32Array {
  const n = targetW * targetH;
  const map = new Float32Array(n);

  if (!semanticMask) {
    // Без сегментации — равномерный средний вес
    map.fill(0.5);
    return map;
  }

  // Nearest-neighbor scaling от размера маски к размеру изображения
  const scaleX = maskW / targetW;
  const scaleY = maskH / targetH;
  for (let y = 0; y < targetH; y++) {
    const srcY = Math.min(maskH - 1, Math.floor(y * scaleY));
    for (let x = 0; x < targetW; x++) {
      const srcX = Math.min(maskW - 1, Math.floor(x * scaleX));
      const cls = semanticMask[srcY * maskW + srcX];
      map[y * targetW + x] = SEMANTIC_WEIGHTS[cls] ?? 0.5;
    }
  }
  return map;
}

// ─────────────────────────────────────────────────────────────
// Signal 3: Face Features from Landmarks
// ─────────────────────────────────────────────────────────────

/**
 * Помечает зоны глаз, носа, рта как максимально важные.
 * Возвращает Float32Array с бинарными зонами: 0 или 1.
 */
function computeFaceFeatureMap(
  faceLandmarks: any | null,
  w: number, h: number,
): Float32Array {
  const map = new Float32Array(w * h);

  if (!faceLandmarks) return map;

  const faces = Array.isArray(faceLandmarks) ? faceLandmarks : [faceLandmarks];

  // Landmark indices for key facial features (MediaPipe 468 mesh)
  const FEATURE_GROUPS = [
    // Left eye
    [33, 7, 163, 144, 145, 153, 154, 155, 133, 173, 157, 158, 159, 160, 161, 246],
    // Right eye
    [362, 382, 381, 380, 374, 373, 390, 249, 263, 466, 388, 387, 386, 385, 384, 398],
    // Lips
    [61, 146, 91, 181, 84, 17, 314, 405, 321, 375, 291, 308, 324, 318, 402, 317, 14, 87, 178, 88, 95, 78],
    // Nose
    [1, 2, 98, 327, 168, 6, 197, 195, 5, 4],
    // Eyebrows
    [70, 63, 105, 66, 107, 55, 65, 52, 53, 46],
    [300, 293, 334, 296, 336, 285, 295, 282, 283, 276],
  ];

  const padding = 3; // px around each feature point

  for (const face of faces) {
    const landmarks = face?.keypoints || face;
    if (!Array.isArray(landmarks)) continue;

    for (const group of FEATURE_GROUPS) {
      for (const idx of group) {
        if (idx >= landmarks.length) continue;
        const lm = landmarks[idx];
        const px = Math.round((lm.x ?? lm[0]) * w);
        const py = Math.round((lm.y ?? lm[1]) * h);

        for (let dy = -padding; dy <= padding; dy++) {
          for (let dx = -padding; dx <= padding; dx++) {
            const nx = px + dx;
            const ny = py + dy;
            if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
              map[ny * w + nx] = 1.0;
            }
          }
        }
      }
    }
  }

  // Расширяем зоны Gaussian blur (σ=4) чтобы плавно затухали от лицевых фич
  return gaussianBlur(map, w, h, 4);
}

// ─────────────────────────────────────────────────────────────
// Signal 4: Edge Density (Sobel-based, computed per block)
// ─────────────────────────────────────────────────────────────

function computeEdgeDensityMap(gray: Float32Array, w: number, h: number): Float32Array {
  const map = new Float32Array(w * h);
  const blockSize = 16;
  const blocksX = Math.ceil(w / blockSize);
  const blocksY = Math.ceil(h / blockSize);

  // Compute per-block edge density
  const blockDensity = new Float32Array(blocksX * blocksY);
  let maxDensity = 0;

  for (let by = 0; by < blocksY; by++) {
    for (let bx = 0; bx < blocksX; bx++) {
      let edgeSum = 0;
      let count = 0;
      const y0 = by * blockSize;
      const x0 = bx * blockSize;
      const y1 = Math.min(y0 + blockSize, h - 1);
      const x1 = Math.min(x0 + blockSize, w - 1);

      for (let y = y0 + 1; y < y1; y++) {
        for (let x = x0 + 1; x < x1; x++) {
          const gx = gray[y * w + x + 1] - gray[y * w + x - 1];
          const gy = gray[(y + 1) * w + x] - gray[(y - 1) * w + x];
          edgeSum += Math.sqrt(gx * gx + gy * gy);
          count++;
        }
      }
      const density = count > 0 ? edgeSum / count : 0;
      blockDensity[by * blocksX + bx] = density;
      if (density > maxDensity) maxDensity = density;
    }
  }

  // Normalize and expand to pixel level with bilinear interpolation
  if (maxDensity > 0) {
    for (let i = 0; i < blockDensity.length; i++) {
      blockDensity[i] /= maxDensity;
    }
  }

  for (let y = 0; y < h; y++) {
    const by = Math.min(blocksY - 1, y / blockSize);
    const byFloor = Math.floor(by);
    const byCeil = Math.min(blocksY - 1, byFloor + 1);
    const fy = by - byFloor;

    for (let x = 0; x < w; x++) {
      const bx = Math.min(blocksX - 1, x / blockSize);
      const bxFloor = Math.floor(bx);
      const bxCeil = Math.min(blocksX - 1, bxFloor + 1);
      const fx = bx - bxFloor;

      // Bilinear interpolation
      const v00 = blockDensity[byFloor * blocksX + bxFloor];
      const v10 = blockDensity[byFloor * blocksX + bxCeil];
      const v01 = blockDensity[byCeil * blocksX + bxFloor];
      const v11 = blockDensity[byCeil * blocksX + bxCeil];
      map[y * w + x] = v00 * (1 - fx) * (1 - fy) + v10 * fx * (1 - fy) + v01 * (1 - fx) * fy + v11 * fx * fy;
    }
  }
  return map;
}

// ─────────────────────────────────────────────────────────────
// Signal 5: Focus Detection (Laplacian variance per block)
// ─────────────────────────────────────────────────────────────

function computeFocusMap(gray: Float32Array, w: number, h: number): Float32Array {
  const map = new Float32Array(w * h);
  const blockSize = 32;
  const blocksX = Math.ceil(w / blockSize);
  const blocksY = Math.ceil(h / blockSize);

  const blockFocus = new Float32Array(blocksX * blocksY);
  let maxFocus = 0;

  for (let by = 0; by < blocksY; by++) {
    for (let bx = 0; bx < blocksX; bx++) {
      let sum = 0, sumSq = 0, count = 0;
      const y0 = by * blockSize;
      const x0 = bx * blockSize;
      const y1 = Math.min(y0 + blockSize, h - 1);
      const x1 = Math.min(x0 + blockSize, w - 1);

      for (let y = y0 + 1; y < y1; y++) {
        for (let x = x0 + 1; x < x1; x++) {
          // Laplacian = 4*center - left - right - up - down
          const lap = 4 * gray[y * w + x]
            - gray[y * w + x - 1] - gray[y * w + x + 1]
            - gray[(y - 1) * w + x] - gray[(y + 1) * w + x];
          sum += lap;
          sumSq += lap * lap;
          count++;
        }
      }
      // Variance of Laplacian — high = sharp/in-focus, low = blurry
      const mean = count > 0 ? sum / count : 0;
      const variance = count > 0 ? (sumSq / count - mean * mean) : 0;
      blockFocus[by * blocksX + bx] = variance;
      if (variance > maxFocus) maxFocus = variance;
    }
  }

  // Normalize and expand to pixel level
  if (maxFocus > 0) {
    for (let i = 0; i < blockFocus.length; i++) {
      blockFocus[i] = Math.min(1, blockFocus[i] / maxFocus);
    }
  }

  for (let y = 0; y < h; y++) {
    const by = Math.min(blocksY - 1, y / blockSize);
    const byFloor = Math.floor(by);
    const byCeil = Math.min(blocksY - 1, byFloor + 1);
    const fy = by - byFloor;
    for (let x = 0; x < w; x++) {
      const bx = Math.min(blocksX - 1, x / blockSize);
      const bxFloor = Math.floor(bx);
      const bxCeil = Math.min(blocksX - 1, bxFloor + 1);
      const fx = bx - bxFloor;
      const v00 = blockFocus[byFloor * blocksX + bxFloor];
      const v10 = blockFocus[byFloor * blocksX + bxCeil];
      const v01 = blockFocus[byCeil * blocksX + bxFloor];
      const v11 = blockFocus[byCeil * blocksX + bxCeil];
      map[y * w + x] = v00 * (1 - fx) * (1 - fy) + v10 * fx * (1 - fy) + v01 * (1 - fx) * fy + v11 * fx * fy;
    }
  }
  return map;
}

// ─────────────────────────────────────────────────────────────
// Utility: Gaussian Blur (separable, approximated by 3 box passes)
// ─────────────────────────────────────────────────────────────

function gaussianBlur(data: Float32Array, w: number, h: number, sigma: number): Float32Array {
  // Approximate Gaussian with 3 box blur passes (Box-Müller approximation)
  const radius = Math.ceil(sigma * 2.57);
  let result = new Float32Array(data);

  for (let pass = 0; pass < 3; pass++) {
    // Horizontal pass
    const temp = new Float32Array(w * h);
    for (let y = 0; y < h; y++) {
      let sum = 0;
      const width = 2 * radius + 1;
      // Init window
      for (let x = -radius; x <= radius; x++) {
        sum += result[y * w + Math.max(0, Math.min(w - 1, x))];
      }
      temp[y * w] = sum / width;
      for (let x = 1; x < w; x++) {
        sum += result[y * w + Math.min(w - 1, x + radius)]
             - result[y * w + Math.max(0, x - radius - 1)];
        temp[y * w + x] = sum / width;
      }
    }
    // Vertical pass
    const temp2 = new Float32Array(w * h);
    for (let x = 0; x < w; x++) {
      let sum = 0;
      const width = 2 * radius + 1;
      for (let y = -radius; y <= radius; y++) {
        sum += temp[Math.max(0, Math.min(h - 1, y)) * w + x];
      }
      temp2[x] = sum / width;
      for (let y = 1; y < h; y++) {
        sum += temp[Math.min(h - 1, y + radius) * w + x]
             - temp[Math.max(0, y - radius - 1) * w + x];
        temp2[y * w + x] = sum / width;
      }
    }
    result = temp2;
  }
  return result;
}

// ─────────────────────────────────────────────────────────────
// Signal 6: Feature Saliency (локальный контраст мелких структур)
// ─────────────────────────────────────────────────────────────
//
// |gray - локальное_среднее|. Ловит МЕЛКИЕ важные структуры: глаза, зрачок,
// ноздри, блик, край век, губы — независимо от лэндмарков (работает и для
// животных/предметов). Крупные плавные градиенты (щека) сюда почти не попадают.
function computeFeatureSaliency(gray: Float32Array, w: number, h: number): Float32Array {
  const mean = gaussianBlur(gray, w, h, 6);
  const out = new Float32Array(w * h);
  for (let i = 0; i < w * h; i++) {
    const d = Math.abs(gray[i] - mean[i]);
    out[i] = Math.min(1, d / 0.22);
  }
  return out;
}

// ─────────────────────────────────────────────────────────────
// Utility: Convert ImageData to Grayscale
// ─────────────────────────────────────────────────────────────

function toGrayscale(imageData: ImageData): Float32Array {
  const { data, width, height } = imageData;
  const gray = new Float32Array(width * height);
  for (let i = 0; i < width * height; i++) {
    const p = i * 4;
    // ITU-R BT.601 luminance
    gray[i] = (data[p] * 0.299 + data[p + 1] * 0.587 + data[p + 2] * 0.114) / 255;
  }
  return gray;
}

// ─────────────────────────────────────────────────────────────
// Utility: Bilinear resample (srcW×srcH) -> (dstW×dstH)
// ─────────────────────────────────────────────────────────────

function resampleBilinear(
  src: Float32Array, srcW: number, srcH: number,
  dstW: number, dstH: number,
): Float32Array {
  const out = new Float32Array(dstW * dstH);
  for (let y = 0; y < dstH; y++) {
    const fy = ((y + 0.5) * srcH) / dstH - 0.5;
    const y0 = Math.max(0, Math.min(srcH - 1, Math.floor(fy)));
    const y1 = Math.min(srcH - 1, y0 + 1);
    const wy = fy - Math.floor(fy);
    for (let x = 0; x < dstW; x++) {
      const fx = ((x + 0.5) * srcW) / dstW - 0.5;
      const x0 = Math.max(0, Math.min(srcW - 1, Math.floor(fx)));
      const x1 = Math.min(srcW - 1, x0 + 1);
      const wx = fx - Math.floor(fx);
      const v00 = src[y0 * srcW + x0], v10 = src[y0 * srcW + x1];
      const v01 = src[y1 * srcW + x0], v11 = src[y1 * srcW + x1];
      out[y * dstW + x] =
        v00 * (1 - wx) * (1 - wy) + v10 * wx * (1 - wy) +
        v01 * (1 - wx) * wy + v11 * wx * wy;
    }
  }
  return out;
}

// ─────────────────────────────────────────────────────────────
// MAIN: Build Importance Map
// ─────────────────────────────────────────────────────────────

export interface ImportanceMapInput {
  imageData: ImageData;
  segmentationMask: Uint8Array | null;
  segmentationWidth: number;
  segmentationHeight: number;
  faceLandmarks: any | null;
  // Универсальная карта главного объекта (U²-Net), 0..1. null — недоступна.
  foregroundMask?: Float32Array | null;
  foregroundWidth?: number;
  foregroundHeight?: number;
  // Пользовательская маска защиты (1 = защищено). Пиксели зоны помечаются
  // сентинелом 2.0 — Rust-ядро трактует их как «заблокированные».
  protectMask?: Uint8Array | null;
  protectWidth?: number;
  protectHeight?: number;
}

/**
 * Строит Importance Map — Float32Array[W × H] с весами 0.0–1.0.
 * Высокие значения = визуально важные области (лицо, глаза, резкие детали, главный объект).
 * Низкие значения = фон, размытые области, однотонные зоны.
 *
 * Вызывается один раз при загрузке фото. Результат переиспользуется
 * при каждой перегенерации с разными параметрами.
 */
export function buildImportanceMap(input: ImportanceMapInput): Float32Array {
  const {
    imageData, segmentationMask, segmentationWidth, segmentationHeight, faceLandmarks,
    foregroundMask = null, foregroundWidth = 0, foregroundHeight = 0,
    protectMask = null, protectWidth = 0, protectHeight = 0,
  } = input;
  const w = imageData.width;
  const h = imageData.height;
  const n = w * h;

  const gray = toGrayscale(imageData);

  // 1. Spectral Residual Saliency
  const saliency = computeSpectralSaliency(gray, w, h);

  // 2. Semantic Segmentation (люди)
  const semantic = computeSemanticMap(segmentationMask, segmentationWidth, segmentationHeight, w, h);

  // 3. Face Features
  const faceFeatures = computeFaceFeatureMap(faceLandmarks, w, h);

  // 4. Edge Density
  const edgeDensity = computeEdgeDensityMap(gray, w, h);

  // 5. Focus Detection
  const focusMap = computeFocusMap(gray, w, h);

  // 5b. Feature saliency — мелкие важные структуры (глаза, ноздри, блики).
  const feature = computeFeatureSaliency(gray, w, h);

  // 6. Foreground / Salient Object (универсальная модель U²-Net) — главный
  //    сигнал «объект vs фон» для ЛЮБОГО сюжета (животные, предметы, цветы...).
  let foreground: Float32Array | null = null;
  let fgCoverage = 0;
  if (foregroundMask && foregroundWidth > 0 && foregroundHeight > 0) {
    foreground = resampleBilinear(foregroundMask, foregroundWidth, foregroundHeight, w, h);
    let fg = 0;
    for (let i = 0; i < n; i++) if (foreground[i] > 0.5) fg++;
    fgCoverage = fg / n;
  }

  // Насколько foreground дискриминативен: объект во весь кадр (~1) или почти
  // отсутствует (~0) — сигнал бесполезен, опираемся на структуру.
  const fgDiscriminative = foreground
    ? Math.max(0, Math.min(1, Math.min(fgCoverage, 1 - fgCoverage) / 0.15))
    : 0;

  // Combine signals
  const importance = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    let val: number;

    if (foreground) {
      const fgv = foreground[i];
      // Feature saliency работает ТОЛЬКО внутри объекта (иначе поднимет шум фона).
      const feat = feature[i] * Math.max(fgv, 0.12);
      const fgShare = 0.30 + 0.25 * fgDiscriminative; // 0.30..0.55
      val = fgv * fgShare
          + feat * 0.30
          + faceFeatures[i] * 0.14
          + edgeDensity[i] * 0.10
          + saliency[i] * 0.08
          + semantic[i] * 0.08
          + focusMap[i] * 0.04;
      // Барьерность: явный фон приглушаем (создаёт fg/bg-барьер на GPU),
      // явный объект приподнимаем — чтобы граница «объект/фон» не замыливалась.
      if (fgv < 0.25) val *= 0.72 + 0.6 * fgv;
      else if (fgv > 0.75) val = Math.max(val, 0.35 + 0.4 * fgv);
      // Мелкая важная структура внутри объекта (глаз/ноздря/блик) — почти максимум.
      if (feat > 0.45 && fgv > 0.30) val = Math.max(val, 0.9);
    } else {
      // Фолбэк без модели (как раньше, но с feature saliency).
      val = saliency[i] * 0.22
          + semantic[i] * 0.20
          + faceFeatures[i] * 0.16
          + edgeDensity[i] * 0.14
          + feature[i] * 0.22
          + focusMap[i] * 0.06;
      if (feature[i] > 0.5) val = Math.max(val, 0.85);
    }

    // Мелкие важные фичи (глаза/губы по лэндмаркам) — всегда максимум.
    if (faceFeatures[i] > 0.5) {
      val = Math.max(val, 0.95);
    }

    importance[i] = Math.max(0, Math.min(1, val));
  }

  // Финальная нормализация: растягиваем диапазон до [0, 1] для максимального контраста
  let minImp = 1, maxImp = 0;
  for (let i = 0; i < n; i++) {
    if (importance[i] < minImp) minImp = importance[i];
    if (importance[i] > maxImp) maxImp = importance[i];
  }
  const range = maxImp - minImp;
  if (range > 0.01) {
    for (let i = 0; i < n; i++) {
      importance[i] = (importance[i] - minImp) / range;
    }
  }

  // Пользовательская защита зон: ПОСЛЕ нормализации помечаем защищённые пиксели
  // сентинелом 2.0 (вне диапазона [0,1]). Rust-ядро распознаёт imp >= 1.5 как
  // «заблокировано»: гарантирует цвет палитры и переназначает пиксели после
  // всех чисток, чтобы алгоритм не мог их стереть (одинокая звезда, блик и т.п.).
  if (protectMask && protectWidth > 0 && protectHeight > 0) {
    const sx = protectWidth / w;
    const sy = protectHeight / h;
    for (let y = 0; y < h; y++) {
      const py = Math.min(protectHeight - 1, Math.floor(y * sy));
      for (let x = 0; x < w; x++) {
        const px = Math.min(protectWidth - 1, Math.floor(x * sx));
        if (protectMask[py * protectWidth + px]) {
          importance[y * w + x] = 2.0;
        }
      }
    }
  }

  return importance;
}

/**
 * «Акцент на объекте»: перераспределяет карту значимости S-КРИВОЙ (smoothstep).
 *
 * ВАЖНО: НЕ степенная кривая. imp^gamma давит средние значения — а лицо в карте
 * неоднородно (глаза≈1, но кожа щёк/лба ~0.5–0.7). Возведение в степень размывало
 * бы саму кожу. S-кривая наоборот: весь объект (всё, что выше порога) ПОДНИМАЕТ к 1
 * — движок даёт ему максимум детализации (чёткое лицо), а фон (ниже порога) опускает
 * к 0 — движок его упрощает. Так лечится и «мыльное» лицо, и «рассыпанный» фон.
 * level 1 = без изменений, 2 = умеренно, 3 = агрессивно. Сентинелы (>=1.5) не трогаем.
 */
export function emphasizeImportance(imp: Float32Array | null, level: number): Float32Array | null {
  if (!imp || !(level > 1)) return imp;
  // Порог «объект/фон»: ниже lo → фон (→0), выше hi → объект (→1), между — плавно.
  const lo = level >= 3 ? 0.14 : 0.22;
  const hi = level >= 3 ? 0.42 : 0.52;
  const inv = 1 / Math.max(1e-6, hi - lo);
  const out = new Float32Array(imp.length);
  for (let i = 0; i < imp.length; i++) {
    const v = imp[i];
    if (v >= 1.5) { out[i] = v; continue; } // защита
    let t = (v - lo) * inv;
    t = t < 0 ? 0 : t > 1 ? 1 : t;
    out[i] = t * t * (3 - 2 * t); // smoothstep
  }
  return out;
}
