// src/paints/naming.ts
//
// Какое из нескольких неотличимых по цвету имён считать основным.
//
// Задача возникает потому, что база — это объединение реальных наборов, а в них
// одна и та же по цвету краска называется по-разному: «Сажа газовая» у Ладоги,
// «Чёрная» у Луча, «Марс чёрный» в справочнике пигментов. Измерением выбрать
// между ними нельзя — они совпадают по цвету. Значит нужно правило.
//
// Правило такое, по убыванию веса:
//   1. Имя, которое встречается в БОЛЬШЕМ числе реальных наборов, вероятнее
//      окажется знакомым: оно напечатано на большем числе тюбиков.
//   2. Более ИНФОРМАТИВНОЕ имя лучше пустого. «Сажа газовая» говорит о пигменте,
//      «Чёрная» не говорит ни о чём. Рецепт и книга рецептов читаются людьми,
//      и там разница ощутима.
//   3. Пара честных исключений там, где первые два правила дают ничью.
//
// Проигравшие имена не выбрасываются — они уходят в альтернативы и доступны
// в один тап. Это принципиально: для владельца гуаши «Луч» правильный ответ —
// именно «Чёрная», и отнять у него это право приложение не вправе.

import { BUILT_IN_SETS } from './sets';
import { EXTENDED_COLORS } from '../config';

/**
 * Слова, которые сами по себе не несут информации о краске.
 * Имя, целиком собранное из них, считается «пустым».
 */
const COLOR_WORDS = new Set([
  'белая', 'белый', 'белила', 'жёлтая', 'желтая', 'красная', 'зелёная', 'зеленая',
  'синяя', 'голубая', 'фиолетовая', 'оранжевая', 'коричневая', 'чёрная', 'черная',
  'розовая', 'бирюзовая', 'серая', 'алая', 'сиреневая', 'лиловая', 'салатовая',
  'красный', 'зелёный', 'синий', 'чёрный', 'жёлтый', 'оранжевый', 'фиолетовый',
  'коричневый', 'розовый', 'голубой', 'серый', 'бежевый', 'телесный',
]);

const MODIFIERS = new Set([
  'светлая', 'тёмная', 'темная', 'средняя', 'светлый', 'тёмный', 'темный', 'средний', 'new',
]);

/** Имя состоит только из названия цвета и модификатора — информации ноль. */
export function isGenericName(name: string): boolean {
  const tokens = name.toLowerCase().replace(/ё/g, 'ё').split(/[\s,«»"()·]+/).filter(Boolean);
  if (!tokens.length) return true;
  return tokens.every(t => COLOR_WORDS.has(t) || MODIFIERS.has(t));
}

/**
 * Ручные предпочтения там, где счёт наборов и информативность дают ничью.
 * Список сознательно короткий: каждая строка — редакторское решение, а не
 * измерение, и разрастаться ему незачем.
 */
const EDITORIAL_BONUS: Record<string, number> = {
  // Титановые — белила по умолчанию почти во всех линейках; цинковые
  // покупают отдельно и осознанно, под лессировки.
  'Белила титановые': 30,
  // «Сажа газовая» — общепринятое название чёрного в русской школе.
  'Сажа газовая': 20,
  // Ультрамарин узнают все; «Синяя» не говорит ничего.
  'Ультрамарин': 15,
};

const setCount = (() => {
  const m = new Map<string, number>();
  for (const s of BUILT_IN_SETS) {
    for (const c of s.colors) m.set(c.name, (m.get(c.name) ?? 0) + 1);
  }
  return m;
})();

const inExtended = new Set(EXTENDED_COLORS.map(c => c.name));

/** Какие марки используют это имя. */
const brandsByName = (() => {
  const m = new Map<string, Set<string>>();
  for (const s of BUILT_IN_SETS) {
    for (const c of s.colors) {
      if (!m.has(c.name)) m.set(c.name, new Set());
      m.get(c.name)!.add(s.brand);
    }
  }
  return m;
})();

/**
 * Чем больше, тем охотнее имя выбирается основным.
 *
 * @param preferBrand если пользователь назвал производителя, его словарь
 *   перевешивает всё остальное. Это не подгонка, а прямая логика: названия
 *   красок — не физика, а соглашение конкретной марки. «Чёрная» у Луча и
 *   «Сажа газовая» у Невской палитры — один и тот же цвет; какое из имён
 *   верное, определяет надпись на тюбике, а не измерение.
 */
export function canonicalScore(name: string, preferBrand?: string): number {
  let score = 100 * (setCount.get(name) ?? 0);
  if (inExtended.has(name)) score += 25;
  if (isGenericName(name)) score -= 60;
  score += EDITORIAL_BONUS[name] ?? 0;
  if (preferBrand && brandsByName.get(name)?.has(preferBrand)) score += 400;
  return score;
}

/** Марки, по которым можно сузить словарь названий. */
export function knownBrands(): string[] {
  const s = new Set<string>();
  for (const b of BUILT_IN_SETS) s.add(b.brand);
  return [...s];
}
