import { useState, useEffect } from "react";
import { useAppStore } from "../store";
import { rgbToHex, hslToRgb } from "../../utils/colorMath";

export function HuePickerDialog() {
  const pickingHarmonyBaseHue = useAppStore((s) => s.pickingHarmonyBaseHue);
  const update = useAppStore((s) => s.update);
  const colorHarmonyCustomHue = useAppStore((s) => s.colorHarmonyCustomHue);
  const imageProfile = useAppStore((s) => s.imageProfile);

  const initialHue = colorHarmonyCustomHue !== null ? colorHarmonyCustomHue : (imageProfile?.dominantHue || 0);
  const [localHue, setLocalHue] = useState(initialHue);

  useEffect(() => {
    if (pickingHarmonyBaseHue) {
      setLocalHue(colorHarmonyCustomHue !== null ? colorHarmonyCustomHue : (imageProfile?.dominantHue || 0));
    }
  }, [pickingHarmonyBaseHue, colorHarmonyCustomHue, imageProfile]);

  if (!pickingHarmonyBaseHue) return null;

  return (
    <div className="fixed inset-0 z-[9999] flex items-end sm:items-center justify-center p-0 sm:p-4 sm:p-6">
      {/* Полностью непрозрачный темный фон для изоляции */}
      <div 
        className="absolute inset-0 bg-slate-950/95 backdrop-blur-xl"
        onClick={() => update({ pickingHarmonyBaseHue: false })}
      />
      
      <div className="relative bg-white dark:bg-slate-900 rounded-t-[2.5rem] sm:rounded-[2.5rem] shadow-2xl border border-white/20 dark:border-white/5 w-full max-w-sm overflow-hidden modal-enter">
        <div className="p-8 flex flex-col items-center">
          <div className="w-16 h-1 bg-slate-200 dark:bg-slate-800 rounded-full mb-8 opacity-50" />
          
          <h3 className="text-xl font-black uppercase tracking-[0.2em] text-slate-800 dark:text-white mb-2 text-center">
            Выбор оттенка
          </h3>
          <p className="text-[10px] font-bold text-slate-500 dark:text-slate-400 text-center mb-10 leading-relaxed uppercase tracking-widest">
            Сдвиньте ползунок для настройки<br/>базового цвета гармонии
          </p>
          
          <div className="w-full space-y-8">
            <div className="relative group">
              <input 
                type="range" 
                min="0" max="360" 
                value={localHue}
                onChange={(e) => setLocalHue(parseInt(e.target.value))}
                className="w-full h-4 bg-gradient-to-r from-red-500 via-yellow-500 via-green-500 via-blue-500 via-purple-500 to-red-500 rounded-full appearance-none cursor-pointer outline-none slider-thumb-pro shadow-inner"
              />
            </div>
            
            <div className="flex flex-col items-center gap-4">
              <div 
                className="w-32 h-32 rounded-[2.5rem] shadow-2xl border-[6px] border-white dark:border-slate-800 transition-all duration-300 transform scale-110"
                style={{ 
                  backgroundColor: rgbToHex(hslToRgb(localHue, 0.8, 0.5)),
                  boxShadow: `0 20px 50px -10px ${rgbToHex(hslToRgb(localHue, 0.8, 0.5))}44`
                }}
              />
              <div className="mt-4 px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 font-mono text-sm font-black text-slate-600 dark:text-slate-300">
                {localHue}° HUE
              </div>
            </div>
          </div>

          <div className="flex gap-3 w-full mt-12">
            <button 
              onClick={() => update({ pickingHarmonyBaseHue: false })}
              className="flex-1 h-14 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-black uppercase tracking-widest rounded-2xl transition-all hover:bg-slate-200 active:scale-95"
            >
              Отмена
            </button>
            <button 
              onClick={() => {
                update({ colorHarmonyCustomHue: localHue, pickingHarmonyBaseHue: false });
              }}
              className="flex-[2] h-14 bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase tracking-widest rounded-2xl transition-all shadow-lg shadow-indigo-500/30 active:scale-95 flex items-center justify-center gap-2"
            >
              <span>Применить</span>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}