// src/calib/homography.ts
//
// Гомография по четырём точкам: перевод «фото под углом» → «вид строго сверху».
// Снимая лист телефоном с рук, пользователь неизбежно даёт трапецию. Без
// выпрямления сетка ячеек не совпадёт с реальными мазками, и любой замер цвета
// будет браться не оттуда.

export type Mat3 = number[]; // 9 чисел, построчно

/** Решает плотную систему методом Гаусса с выбором ведущего элемента. */
function solveLinear(A: number[][], b: number[]): number[] | null {
  const n = b.length;
  const M = A.map((row, i) => [...row, b[i]]);

  for (let col = 0; col < n; col++) {
    let piv = col;
    for (let r = col + 1; r < n; r++) if (Math.abs(M[r][col]) > Math.abs(M[piv][col])) piv = r;
    if (Math.abs(M[piv][col]) < 1e-12) return null; // вырожденная конфигурация точек
    [M[col], M[piv]] = [M[piv], M[col]];

    const d = M[col][col];
    for (let c = col; c <= n; c++) M[col][c] /= d;

    for (let r = 0; r < n; r++) {
      if (r === col) continue;
      const f = M[r][col];
      if (f === 0) continue;
      for (let c = col; c <= n; c++) M[r][c] -= f * M[col][c];
    }
  }
  return M.map(row => row[n]);
}

/**
 * Матрица, переводящая src → dst (по 4 пары точек).
 * Классический DLT: 8 неизвестных, h33 фиксируем в 1.
 */
export function homographyFrom4(
  src: { x: number; y: number }[],
  dst: { x: number; y: number }[],
): Mat3 | null {
  if (src.length < 4 || dst.length < 4) return null;

  const A: number[][] = [];
  const b: number[] = [];
  for (let i = 0; i < 4; i++) {
    const { x, y } = src[i];
    const { x: u, y: v } = dst[i];
    A.push([x, y, 1, 0, 0, 0, -u * x, -u * y]); b.push(u);
    A.push([0, 0, 0, x, y, 1, -v * x, -v * y]); b.push(v);
  }

  const h = solveLinear(A, b);
  if (!h) return null;
  return [h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7], 1];
}

export function applyH(H: Mat3, x: number, y: number): { x: number; y: number } {
  const w = H[6] * x + H[7] * y + H[8];
  const iw = Math.abs(w) < 1e-12 ? 0 : 1 / w;
  return { x: (H[0] * x + H[1] * y + H[2]) * iw, y: (H[3] * x + H[4] * y + H[5]) * iw };
}

export function invertH(H: Mat3): Mat3 | null {
  const [a, b, c, d, e, f, g, h, i] = H;
  const A = e * i - f * h, B = -(d * i - f * g), C = d * h - e * g;
  const det = a * A + b * B + c * C;
  if (Math.abs(det) < 1e-12) return null;
  const id = 1 / det;
  return [
    A * id, (c * h - b * i) * id, (b * f - c * e) * id,
    B * id, (a * i - c * g) * id, (c * d - a * f) * id,
    C * id, (b * g - a * h) * id, (a * e - b * d) * id,
  ];
}

/**
 * Выпрямляет исходное изображение в канонический прямоугольник.
 * Билинейная интерполяция: съёмка почти всегда даёт масштаб не 1:1, и
 * «ближайший сосед» добавил бы к цвету ступенчатый шум ровно там, где мы
 * потом ищем моду гистограммы.
 */
export function warpPerspective(
  src: ImageData,
  H: Mat3, // из координат листа (dst) в координаты фото (src)
  outW: number,
  outH: number,
): ImageData {
  const out = new ImageData(outW, outH);
  const sd = src.data, od = out.data;
  const sw = src.width, sh = src.height;

  for (let y = 0; y < outH; y++) {
    for (let x = 0; x < outW; x++) {
      const p = applyH(H, x + 0.5, y + 0.5);
      const o = (y * outW + x) * 4;

      if (p.x < 0 || p.y < 0 || p.x >= sw - 1 || p.y >= sh - 1) {
        od[o + 3] = 0;
        continue;
      }

      const x0 = Math.floor(p.x), y0 = Math.floor(p.y);
      const fx = p.x - x0, fy = p.y - y0;
      const i00 = (y0 * sw + x0) * 4;
      const i10 = i00 + 4;
      const i01 = i00 + sw * 4;
      const i11 = i01 + 4;
      const w00 = (1 - fx) * (1 - fy), w10 = fx * (1 - fy), w01 = (1 - fx) * fy, w11 = fx * fy;

      for (let c = 0; c < 3; c++) {
        od[o + c] = sd[i00 + c] * w00 + sd[i10 + c] * w10 + sd[i01 + c] * w01 + sd[i11 + c] * w11;
      }
      od[o + 3] = 255;
    }
  }
  return out;
}
