// src/generator/hooks/useGeneratorHotkeys.ts
import { useEffect } from "react";
import { useAppStore } from "../store";

export function useGeneratorHotkeys(
  isOpen: boolean,
  cancelProcessing: () => void,
  loadImage: (file: File) => void
) {
  useEffect(() => {
    const h = (e: KeyboardEvent) => {
      if (!isOpen) return;
      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement ||
        e.target instanceof HTMLSelectElement
      ) return;

      const s = useAppStore.getState();
      const isPaintingMode = s.studioMode === "painting";

      if (e.key === "Escape") {
        if (s.zoneInfoVisible) {
          useAppStore.getState().selectZone(null);
          return;
        }
        if (s.exportModalOpen) {
          useAppStore.getState().update({ exportModalOpen: false });
          return;
        }
        if (s.historyModalOpen) {
          useAppStore.getState().update({ historyModalOpen: false });
          return;
        }
        if (s.cropModalOpen) {
          useAppStore.getState().update({ cropModalOpen: false });
          return;
        }
        if (s.urlModalOpen) {
          useAppStore.getState().update({ urlModalOpen: false });
          return;
        }
        if (s.mobileSettingsOpen) {
          useAppStore.getState().update({ mobileSettingsOpen: false });
          return;
        }
        if (s.isProcessing || s.isExporting) cancelProcessing();
      }

      if (e.key === "z" && (e.ctrlKey || e.metaKey) && !e.shiftKey) {
        e.preventDefault();
        useAppStore.getState().undoCorrection();
      }

      if ((e.key === "y" && (e.ctrlKey || e.metaKey)) || (e.key === "z" && (e.ctrlKey || e.metaKey) && e.shiftKey)) {
        e.preventDefault();
        useAppStore.getState().redoCorrection();
      }

      if (isPaintingMode && !!s.result && !e.ctrlKey && !e.metaKey && !e.altKey) {
        if (e.key >= "1" && e.key <= "5") {
          e.preventDefault();
          useAppStore.getState().setPaintingLayerAnimated(parseInt(e.key) - 1);
        }
        if (e.key === "0") {
          e.preventDefault();
          useAppStore.getState().setPaintingLayerAnimated(0);
        }
        if (e.key === "f" || e.key === "F" || e.key === "а" || e.key === "А") {
          e.preventDefault();
          useAppStore.getState().toggleFlip();
        }
        if (e.key === "t" || e.key === "T" || e.key === "е" || e.key === "Е") {
          e.preventDefault();
          useAppStore.getState().toggleTemperatureMap();
        }
        if (e.key === "z" || e.key === "Z" || e.key === "я" || e.key === "Я") {
          e.preventDefault();
          useAppStore.getState().toggleZoneGuide();
        }
        if (e.key === "s" || e.key === "S" || e.key === "ы" || e.key === "Ы") {
          e.preventDefault();
          useAppStore.getState().togglePaintingSplit();
        }
      }

      if (s.zoneGuideActive) {
        if (e.key === "ArrowRight") {
          e.preventDefault();
          useAppStore.getState().nextZone();
        }
        if (e.key === "ArrowLeft") {
          e.preventDefault();
          useAppStore.getState().prevZone();
        }
      }
    };

    document.addEventListener("keydown", h);
    return () => document.removeEventListener("keydown", h);
  }, [isOpen, cancelProcessing]);

  useEffect(() => {
    if (!isOpen) return;

    const handlePaste = (e: ClipboardEvent) => {
      const items = e.clipboardData?.items;
      if (!items) return;
      for (const item of Array.from(items)) {
        const file = item.getAsFile();
        if (file) {
          const isHeic = file.name.toLowerCase().endsWith('.heic') || file.name.toLowerCase().endsWith('.heif');
          if (item.type.startsWith("image/") || isHeic) {
            e.preventDefault();
            loadImage(file);
            return;
          }
        }
      }
    };

    document.addEventListener("paste", handlePaste);
    return () => document.removeEventListener("paste", handlePaste);
  }, [isOpen, loadImage]);
}
