// src/generator/components/RecommendationsPanel.tsx
//
// Центр рекомендаций в боковой панели.
//
// Прежде разбор недостижимых цветов жил в модальном окне на выходе из
// экспорта: там, где решение уже принято и менять палитру поздно. Здесь он
// стоит рядом с самой палитрой, то есть там, где его выводы можно немедленно
// применить.

import { useState } from 'react';
import { cn } from '../../utils/cn';
import { ColorCircle } from '../../components/ui/ColorCircle';
import type { Advice, PaintSuggestion } from '../utils/advisor';

const SEVERITY_STYLE: Record<Advice['severity'], string> = {
  high: 'border-amber-400/50 bg-amber-50 dark:bg-amber-500/10',
  medium: 'border-slate-200/70 dark:border-slate-700 bg-white dark:bg-slate-800',
  low: 'border-slate-200/70 dark:border-slate-700 bg-white dark:bg-slate-800',
};

function PaintRow({ p, canEnable, onEnable }: {
  p: PaintSuggestion;
  canEnable: boolean;
  onEnable: (name: string) => void;
}) {
  const [open, setOpen] = useState(false);
  return (
    <div className="rounded-xl border border-slate-200/70 dark:border-slate-700 bg-white dark:bg-slate-900 p-2.5">
      <div className="flex items-center gap-2.5">
        <ColorCircle rgb={p.rgb} size={26} />
        <div className="min-w-0 flex-1">
          <div className="text-xs font-black text-slate-800 dark:text-slate-100 truncate">
            {p.name}{p.code ? `, артикул ${p.code}` : ''}
          </div>
          <div className="text-[10px] font-medium text-slate-500 truncate">{p.source}</div>
        </div>
        {canEnable && (
          <button
            onClick={() => onEnable(p.name)}
            className="shrink-0 px-2.5 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider bg-indigo-600 text-white active:scale-95 transition-all">
            Включить
          </button>
        )}
      </div>

      {/* Главное число: сколько цветов картины краска приводит в норму.
          Оно, а не близость к одному оттенку, определяет ценность покупки. */}
      <div className="mt-2 text-[10px] font-bold text-slate-500 dark:text-slate-400 leading-relaxed">
        {p.fixes > 0 && <>Приводит в норму цветов: {p.fixes}. </>}
        {p.improves > 0 && <>Заметно улучшает ещё: {p.improves}. </>}
        Остаточное расхождение ΔE {p.residualDeltaE.toFixed(1)}.
      </div>

      {p.substitutes.length > 0 && (
        <>
          <button onClick={() => setOpen(o => !o)}
            className="mt-1.5 text-[10px] font-black uppercase tracking-wider text-indigo-500 hover:text-indigo-400">
            {open ? 'Скрыть замены' : `Равноценные замены (${p.substitutes.length})`}
          </button>
          {open && (
            <div className="mt-1.5 space-y-1">
              <p className="text-[10px] font-medium text-slate-500 leading-relaxed">
                Эти краски отличаются от рекомендованной меньше, чем на порог различимости
                при выкраске. Подойдёт любая из них.
              </p>
              {p.substitutes.map(s => (
                <div key={s.name} className="flex items-center gap-2">
                  <ColorCircle rgb={s.rgb} size={16} />
                  <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200 truncate">{s.name}</span>
                  <span className="text-[10px] font-medium text-slate-400 truncate">{s.source}</span>
                  <span className="ml-auto text-[10px] font-bold text-slate-400 tabular-nums shrink-0">ΔE {s.deltaE.toFixed(1)}</span>
                </div>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}

export function RecommendationsPanel({ advice, onEnablePaint, onRaiseParts }: {
  advice: Advice[];
  onEnablePaint: (name: string) => void;
  onRaiseParts?: () => void;
}) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  if (!advice.length) return null;

  const actionable = advice.filter(a => a.kind !== 'info').length;

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between px-1">
        <span className="text-xs font-black uppercase tracking-[0.2em] text-slate-500 dark:text-slate-400">
          Рекомендации
        </span>
        {actionable > 0 && (
          <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-amber-500/15 text-amber-600 dark:text-amber-400">
            {actionable}
          </span>
        )}
      </div>

      {advice.map(a => {
        const open = expanded[a.id] ?? a.severity === 'high';
        return (
          <div key={a.id} className={cn('rounded-2xl border-2 p-3', SEVERITY_STYLE[a.severity])}>
            <button
              onClick={() => setExpanded(e => ({ ...e, [a.id]: !open }))}
              className="w-full flex items-start gap-2 text-left">
              <span className="flex-1 text-xs font-black text-slate-800 dark:text-slate-100 leading-snug">{a.title}</span>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"
                className={cn('text-slate-400 mt-1 shrink-0 transition-transform', open && 'rotate-180')}>
                <path d="m6 9 6 6 6-6" />
              </svg>
            </button>

            {open && (
              <div className="mt-2 space-y-2">
                <p className="text-[11px] font-medium text-slate-600 dark:text-slate-300 leading-relaxed">{a.detail}</p>

                {a.paints?.map(p => (
                  <PaintRow key={p.name} p={p} canEnable={a.kind === 'enable-paint'} onEnable={onEnablePaint} />
                ))}

                {a.kind === 'raise-parts' && onRaiseParts && (
                  <button onClick={onRaiseParts}
                    className="px-3 py-2 rounded-xl text-[10px] font-black uppercase tracking-wider bg-indigo-600 text-white active:scale-95 transition-all">
                    Ослабить ограничение
                  </button>
                )}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}
