// src/generator/components/ProtectMaskModal.tsx
// Редактор КАРТЫ ЗНАЧИМОСТИ («Защита»). Показывает тепловую карту приоритетов, по
// которой ИИ/алгоритмы распределяют детализацию и цвета: зелёный — высокий приоритет,
// жёлтый — средний, красный — низкий. Пользователь кистями повышает/понижает приоритет
// нужных зон, принудительно объясняя алгоритмам, что важно. Правки применяются к той же
// importanceMap, что управляет генерацией. «Сохранение» — неявное: бюджет (число цветов
// и детализация) фиксирован, поэтому подняв приоритет здесь, вы автоматически отнимаете
// его у остального (нормировки карты нет — она задаёт абсолютный приоритет).
// Экспортирует хук useProtectMask (логика на переданном canvas) и панель ProtectToolbar.
import { useEffect, useRef, useState, useCallback } from "react";
import { useAppStore } from "../store";
import { cn } from "../../utils/cn";

type Tool = "raise" | "lower";

export interface ProtectCtrl {
  active: boolean;
  tool: Tool; setTool: (t: Tool) => void;
  brush: number; setBrush: (n: number) => void;
  strength: number; setStrength: (n: number) => void;
  opacity: number; setOpacity: (n: number) => void;
  onPointerDown: (e: React.PointerEvent) => void;
  onPointerMove: (e: React.PointerEvent) => void;
  onPointerUp: (e: React.PointerEvent) => void;
  reset: () => void;
  apply: () => void;
  cancel: () => void;
}

export function useProtectMask(canvasRef: React.RefObject<HTMLCanvasElement>): ProtectCtrl {
  const active = useAppStore((s) => s.protectToolActive);
  const dims = useAppStore((s) => s.imageDimensions);
  const update = useAppStore((s) => s.update);
  const brush = useAppStore((s) => s.protectBrushSize);
  const setBrush = useCallback((n: number) => useAppStore.getState().update({ protectBrushSize: n }), []);

  const [tool, setTool] = useState<Tool>("raise");
  const [strength, setStrength] = useState(50);   // 0..100 — сила кисти
  const [opacity, setOpacity] = useState(65);     // 0..100 — прозрачность накладки

  const workRef = useRef<Float32Array | null>(null); // рабочая копия карты значимости
  const g = useRef<{ active: boolean; last: { x: number; y: number } | null }>({ active: false, last: null });
  const touchIds = useRef<Set<number>>(new Set());   // активные касания (для жеста двумя пальцами)
  const strokeSnapshot = useRef<Float32Array | null>(null); // снимок карты до штриха — откат при жесте

  const W = dims?.w || 0, H = dims?.h || 0;

  // Тепловая отрисовка карты: v=0 (красный) → 0.5 (жёлтый) → 1 (зелёный).
  const renderHeat = useCallback(() => {
    const c = canvasRef.current, work = workRef.current;
    if (!c || !work || !dims || W * H === 0) return;
    const ctx = c.getContext("2d");
    if (!ctx) return;
    const im = ctx.createImageData(W, H);
    const a = Math.round((opacity / 100) * 190);
    const d = im.data;
    for (let i = 0; i < W * H; i++) {
      let v = work[i];
      v = v < 0 ? 0 : v > 1 ? 1 : v;
      let r: number, gr: number;
      if (v < 0.5) { r = 255; gr = (v / 0.5) * 255; }
      else { r = (1 - (v - 0.5) / 0.5) * 255; gr = 255; }
      const k = i * 4;
      d[k] = r; d[k + 1] = gr; d[k + 2] = 45; d[k + 3] = a;
    }
    ctx.putImageData(im, 0, 0);
  }, [canvasRef, dims, W, H, opacity]);

  // Инициализация при включении: рабочая копия из текущей карты значимости.
  useEffect(() => {
    if (!active || !dims || W * H === 0) return;
    const store = useAppStore.getState();
    const src = store.importanceMap;
    if (src && src.length >= W * H) {
      workRef.current = src.slice(0, W * H);
      if (!store.importanceBaseMap || store.importanceBaseMap.length !== src.length) {
        update({ importanceBaseMap: src.slice() });
      }
    } else {
      workRef.current = new Float32Array(W * H); // карты ещё нет — нули
    }
    requestAnimationFrame(() => renderHeat());
  }, [active, dims, W, H, renderHeat, update]);

  // Перерисовка при смене прозрачности.
  useEffect(() => { if (active) renderHeat(); }, [opacity, active, renderHeat]);

  const toImg = useCallback((e: React.PointerEvent) => {
    const c = canvasRef.current!, r = c.getBoundingClientRect();
    return { x: (e.clientX - r.left) * (W / r.width), y: (e.clientY - r.top) * (H / r.height) };
  }, [canvasRef, W, H]);

  // Кисть: в круге радиуса brush меняем приоритет с мягким затуханием, clamp [0,1].
  const paint = useCallback((cx: number, cy: number) => {
    const work = workRef.current; if (!work) return;
    const rad = Math.max(1, brush);
    const dir = (tool === "raise" ? 1 : -1) * (strength / 100) * 0.30; // дельта за штамп
    const r2 = rad * rad;
    const x0 = Math.max(0, Math.floor(cx - rad)), x1 = Math.min(W - 1, Math.ceil(cx + rad));
    const y0 = Math.max(0, Math.floor(cy - rad)), y1 = Math.min(H - 1, Math.ceil(cy + rad));
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        const dx = x - cx, dy = y - cy, dd = dx * dx + dy * dy;
        if (dd > r2) continue;
        const fall = 1 - Math.sqrt(dd) / rad; // линейное затухание к краю
        const i = y * W + x;
        const nv = work[i] + dir * fall;
        work[i] = nv < 0 ? 0 : nv > 1 ? 1 : nv;
      }
    }
  }, [brush, tool, strength, W, H]);

  const stroke = useCallback((a: { x: number; y: number }, b: { x: number; y: number } | null) => {
    if (!b) { paint(a.x, a.y); return; }
    const steps = Math.max(1, Math.ceil(Math.hypot(a.x - b.x, a.y - b.y) / Math.max(1, brush * 0.5)));
    for (let s = 0; s <= steps; s++) paint(b.x + (a.x - b.x) * (s / steps), b.y + (a.y - b.y) * (s / steps));
  }, [paint, brush]);

  const onPointerDown = useCallback((e: React.PointerEvent) => {
    if (!active) return;
    // Средняя/правая кнопка — не рисуем: пусть работает панорама полотна колёсиком.
    if (e.button === 1 || e.button === 2) return;
    if (e.pointerType === "touch") {
      touchIds.current.add(e.pointerId);
      // Появился второй палец → это жест панорамы/зума. Откатываем начатый штрих
      // (по снимку) и прекращаем рисование, чтобы не оставлять случайных мазков.
      if (touchIds.current.size >= 2) {
        if (strokeSnapshot.current && workRef.current) { workRef.current.set(strokeSnapshot.current); renderHeat(); }
        g.current = { active: false, last: null };
        return;
      }
    }
    e.preventDefault(); e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    if (workRef.current) strokeSnapshot.current = workRef.current.slice(); // снимок для отката
    const p = toImg(e);
    g.current = { active: true, last: p };
    stroke(p, null); renderHeat();
  }, [active, toImg, stroke, renderHeat]);

  const onPointerMove = useCallback((e: React.PointerEvent) => {
    if (!active || !g.current.active || touchIds.current.size >= 2) return;
    e.preventDefault(); e.stopPropagation();
    const p = toImg(e);
    stroke(p, g.current.last); g.current.last = p; renderHeat();
  }, [active, toImg, stroke, renderHeat]);

  const onPointerUp = useCallback((e: React.PointerEvent) => {
    if (e.pointerType === "touch") touchIds.current.delete(e.pointerId);
    if (!g.current.active) return;
    e.preventDefault(); e.stopPropagation();
    g.current = { active: false, last: null };
  }, []);

  const reset = useCallback(() => {
    const base = useAppStore.getState().importanceBaseMap;
    if (base && base.length >= W * H) { workRef.current = base.slice(0, W * H); renderHeat(); }
  }, [W, H, renderHeat]);

  const cancel = useCallback(() => update({ protectToolActive: false }), [update]);

  // Применить: записать отредактированную карту и перегенерировать (bump protectVersion
  // инвалидирует кэш/сигнатуру, поэтому раскраска пересоберётся с новыми приоритетами).
  const apply = useCallback(() => {
    const work = workRef.current;
    const store = useAppStore.getState();
    if (!work) { update({ protectToolActive: false }); return; }
    // Перегенерируем ТОЛЬКО если карта реально изменилась. Иначе просто закрываем
    // редактор без bump protectVersion — лишней пересборки раскраски не будет.
    const prev = store.importanceMap;
    let changed = !prev || prev.length !== work.length;
    if (!changed && prev) {
      for (let i = 0; i < work.length; i++) {
        if (Math.abs(work[i] - prev[i]) > 1e-4) { changed = true; break; }
      }
    }
    if (changed) {
      update({ importanceMap: work.slice(), protectVersion: store.protectVersion + 1, protectToolActive: false });
    } else {
      update({ protectToolActive: false });
    }
  }, [update]);

  return { active, tool, setTool, brush, setBrush, strength, setStrength, opacity, setOpacity, onPointerDown, onPointerMove, onPointerUp, reset, apply, cancel };
}

// Компактный ползунок в стиле приложения.
function MiniSlider({
  label, value, min, max, onChange, suffix = "",
}: { label: string; value: number; min: number; max: number; onChange: (v: number) => void; suffix?: string }) {
  const trackRef = useRef<HTMLDivElement>(null);
  const pct = ((value - min) / (max - min)) * 100;
  const handle = useCallback((clientX: number) => {
    const el = trackRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const p = Math.max(0, Math.min(1, (clientX - r.left) / r.width));
    onChange(Math.round(p * (max - min) + min));
  }, [min, max, onChange]);
  const onDown = (e: React.PointerEvent) => {
    e.preventDefault(); e.stopPropagation();
    handle(e.clientX);
    const mv = (ev: PointerEvent) => handle(ev.clientX);
    const up = () => { document.removeEventListener("pointermove", mv); document.removeEventListener("pointerup", up); };
    document.addEventListener("pointermove", mv);
    document.addEventListener("pointerup", up);
  };
  return (
    <div className="flex items-center gap-2 px-1 select-none">
      <span className="text-[10px] font-black uppercase tracking-wider text-slate-400">{label}</span>
      <div ref={trackRef} onPointerDown={onDown} className="relative w-20 sm:w-24 h-6 flex items-center cursor-pointer touch-none">
        <div className="w-full h-1.5 rounded-full bg-white/20 overflow-hidden shadow-inner">
          <div className="h-full bg-indigo-500 rounded-full transition-all duration-75" style={{ width: `${pct}%` }} />
        </div>
        <div
          className="absolute top-1/2 w-4 h-4 bg-white rounded-full border-2 border-slate-700 shadow-lg pointer-events-none"
          style={{ left: `${pct}%`, transform: "translate(-50%,-50%)" }}
        />
      </div>
      <span className="text-xs font-black tabular-nums text-white w-7 text-center">{value}{suffix}</span>
    </div>
  );
}

// Плавающая панель редактора карты значимости (поверх фото).
export function ProtectToolbar({ ctrl }: { ctrl: ProtectCtrl }) {
  if (!ctrl.active) return null;
  const { tool, setTool, brush, setBrush, strength, setStrength, opacity, setOpacity, reset, apply, cancel } = ctrl;

  return (
    <>
      {/* Верхняя панель: заголовок + легенда + Сброс/Отмена/Готово. На мобиле —
          на всю ширину с переносом, чтобы кнопки не уезжали за край экрана. */}
      <div className="absolute top-2 inset-x-2 sm:inset-x-auto sm:left-1/2 sm:-translate-x-1/2 z-40 flex flex-wrap items-center justify-center gap-2 px-3 py-2 rounded-2xl bg-slate-900/90 backdrop-blur-xl border border-white/10 shadow-2xl max-w-full sm:max-w-[96vw]">
        <button onClick={cancel} title="Закрыть карту значимости" aria-label="Закрыть" className="w-9 h-9 rounded-lg flex items-center justify-center text-slate-300 hover:bg-white/10 hover:text-white active:scale-90 transition-all">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12" /></svg>
        </button>
        <span className="text-indigo-400"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" /></svg></span>
        <span className="text-[11px] font-black uppercase tracking-widest text-white">Карта значимости</span>
        {/* Легенда: как ИИ расставляет приоритеты */}
        <span className="hidden md:inline-flex items-center gap-1.5 text-[10px] font-bold text-slate-300 ml-1">
          <span className="w-3 h-3 rounded-sm" style={{ background: "rgb(40,220,45)" }} /> важно
          <span className="w-3 h-3 rounded-sm ml-1" style={{ background: "rgb(255,220,0)" }} /> средне
          <span className="w-3 h-3 rounded-sm ml-1" style={{ background: "rgb(255,45,45)" }} /> фон
        </span>
        <span className="w-px h-5 bg-white/10 mx-1" />
        <button onClick={reset} title="Вернуть карту, предложенную ИИ" className="px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider text-slate-300 hover:bg-white/10 active:scale-95 transition-all">Сброс</button>
        <button onClick={cancel} className="px-3 py-1 rounded-lg text-[11px] font-black uppercase tracking-widest text-slate-300 hover:bg-white/10 active:scale-95 transition-all">Отмена</button>
        <button onClick={apply} title="Применить карту и перегенерировать раскраску" className="px-4 py-1 rounded-lg text-[11px] font-black uppercase tracking-widest bg-indigo-600 text-white shadow-lg shadow-indigo-600/30 hover:bg-indigo-500 active:scale-95 transition-all">Готово</button>
      </div>

      {/* Нижняя панель инструментов */}
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-40 flex flex-wrap items-center justify-center gap-2 px-3 py-2 rounded-2xl bg-slate-900/90 backdrop-blur-xl border border-white/10 shadow-2xl max-w-[95%]">
        <div className="flex items-center gap-1">
          <button onClick={() => setTool("raise")} title="Повысить приоритет (больше деталей и цветов)" aria-label="Повысить приоритет"
            className={cn("px-3 h-10 rounded-xl inline-flex items-center gap-1.5 text-[11px] font-black uppercase tracking-wider transition-all active:scale-90",
              tool === "raise" ? "bg-emerald-600 text-white shadow-lg shadow-emerald-600/30" : "text-slate-300 hover:bg-white/10 hover:text-white")}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 19V5M5 12l7-7 7 7" /></svg>
            Повысить
          </button>
          <button onClick={() => setTool("lower")} title="Понизить приоритет (меньше деталей)" aria-label="Понизить приоритет"
            className={cn("px-3 h-10 rounded-xl inline-flex items-center gap-1.5 text-[11px] font-black uppercase tracking-wider transition-all active:scale-90",
              tool === "lower" ? "bg-rose-600 text-white shadow-lg shadow-rose-600/30" : "text-slate-300 hover:bg-white/10 hover:text-white")}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 5v14M19 12l-7 7-7-7" /></svg>
            Понизить
          </button>
        </div>
        <div className="w-px h-7 bg-white/10" />
        <MiniSlider label="Размер" value={brush} min={1} max={100} onChange={setBrush} />
        <MiniSlider label="Сила" value={strength} min={5} max={100} onChange={setStrength} />
        <div className="w-px h-7 bg-white/10" />
        <MiniSlider label="Видимость" value={opacity} min={10} max={100} onChange={setOpacity} suffix="%" />
      </div>
    </>
  );
}
