import type { RGB, PaintProfile } from '../config';
import { rgbToLab } from '../utils/colorMath';

export function generateWarnings(
  targetRgb: RGB,
  bestDelta: number,
  profile: PaintProfile,
  usedColors: number
): string[] {
  const warnings: string[] = [];

  // 1. Ограничения физической палитры
  if (bestDelta > 15) {
    warnings.push('Этот цвет физически невозможно получить из имеющейся палитры. Попробуйте включить дополнительные краски в настройках.');
  } else if (bestDelta > 6) {
    warnings.push('Ограничения палитры: результат может визуально отличаться от оригинала. Для 100% совпадения нужна другая базовая краска.');
  }

  // 2. Экспоненциальная грязь (перенасыщение пигментами)
  if (usedColors > profile.maxColorsInMix) {
    warnings.push(`Слишком сложный замес (${usedColors} шт). Смешивание более ${profile.maxColorsInMix} цветов ${profile.name.toLowerCase()} неминуемо приведет к образованию "грязи" и потере яркости.`);
  }

  const lab = rgbToLab(targetRgb);
  const chroma = Math.sqrt(lab[1] * lab[1] + lab[2] * lab[2]);

  // 3. Цифровые против Аналоговых цветов
  if (chroma > 85) {
    warnings.push('Экстремальная насыщенность: цифровые (экранные) цвета всегда выглядят ярче, чем реальные физические пигменты на холсте.');
  }

  const max = Math.max(targetRgb[0], targetRgb[1], targetRgb[2]);
  const min = Math.min(targetRgb[0], targetRgb[1], targetRgb[2]);
  
  if (max > 240 && min < 30 && max - min > 200) {
    warnings.push('Чистый световой спектр (неон). Обычными красками этот цвет передать невозможно, потребуется специальный флуоресцентный пигмент.');
  }

  // 4. Специфика прозрачности
  if (profile.id === 'watercolor' && lab[0] < 25) {
    warnings.push('Акварель прозрачна: получить глубокий черный цвет без потери оптического "свечения" бумаги будет очень сложно.');
  }

  // 5. Динамическое уведомление о компенсации высыхания (Wet-to-Dry Shift)
  if (profile.drying && profile.drying.brightnessFactor > 1.02) {
    const pct = Math.round((profile.drying.brightnessFactor - 1.0) * 100);
    warnings.push(`${profile.name} светлеет при высыхании на ~${pct}%. Рецепт намеренно рассчитан темнее, чтобы после высыхания на холсте цвет идеально совпал с оригиналом.`);
  } else if (profile.drying && profile.drying.brightnessFactor < 0.98) {
    const pct = Math.round((1.0 - profile.drying.brightnessFactor) * 100);
    warnings.push(`${profile.name} темнеет при полимеризации на ~${pct}%. Рецепт рассчитан чуть светлее, не пугайтесь разницы в сыром виде на палитре.`);
  }

  return warnings;
}