// src/engine/calculator.ts
import type { RGB, ColorComponent, EngineSettings } from '../config';
import { PAINT_PROFILES, SURFACE_PROFILES } from '../config';
import { rgbToLab } from '../utils/colorMath';
import EngineWorker from './worker?worker';
import type { CalculationResult, SolverCandidate } from './types';
import { selectVariants } from './variants';
import { generateWarnings } from './warnings';

// --- Worker Pool ---
// Используем пул воркеров для распараллеливания расчетов рецептов (особенно важно при экспорте PDF и пакетной оптимизации)
const MAX_WORKERS = typeof navigator !== 'undefined' ? Math.max(1, (navigator.hardwareConcurrency || 4) - 1) : 3;
let workerPool: Worker[] = [];
let nextWorkerIdx = 0;

let jobCounter = 0;
const activeJobs = new Map<number, { resolve: Function, reject: Function, onProgress: Function, timeout: ReturnType<typeof setTimeout> }>();

function getEngineWorker() {
  if (workerPool.length === 0) {
    for (let i = 0; i < MAX_WORKERS; i++) {
      const w = new EngineWorker();
      
      w.onmessage = (e: MessageEvent) => {
        const { type, value, candidates, jobId } = e.data;
        const job = activeJobs.get(jobId);
        if (!job) return;

        if (type === 'progress') {
          job.onProgress(value);
        } else if (type === 'result') {
          clearTimeout(job.timeout);
          activeJobs.delete(jobId);
          job.resolve(candidates);
        }
      };

      w.onerror = (err) => {
        activeJobs.forEach(job => {
          clearTimeout(job.timeout);
          job.reject(new Error(`worker error: ${err.message}`));
        });
        activeJobs.clear();
        workerPool.forEach(worker => worker.terminate());
        workerPool = [];
      };

      workerPool.push(w);
    }
  }
  
  const worker = workerPool[nextWorkerIdx];
  nextWorkerIdx = (nextWorkerIdx + 1) % workerPool.length;
  return worker;
}

// --- Кэш результатов (LRU) ---
// Солвер детерминирован (PRNG засеян хешем цвета), поэтому один и тот же запрос
// всегда даёт один результат. Мемоизируем по сигнатуре: калькулятор, «умное
// сканирование» и экспорт PDF перестают пересчитывать одни и те же цвета.
const RESULT_CACHE = new Map<string, CalculationResult>();
const RESULT_CACHE_MAX = 600;

function cacheKey(target: RGB, components: ColorComponent[], s: EngineSettings): string {
  const comps = components
    .map((c) => `${c.name}:${c.rgb[0]},${c.rgb[1]},${c.rgb[2]}`)
    .sort()
    .join('|');
  const surf = s.surfaceType === 'custom'
    ? `custom:${(s.customSurfaceColor || []).join(',')}`
    : s.surfaceType;
  return `${target.join(',')}#${s.paintType}#${surf}#${s.maxPartsPerColor}#${s.maxColorsInMix}#${s.targetTotalParts}#${comps}`;
}

function cacheGet(k: string): CalculationResult | undefined {
  const v = RESULT_CACHE.get(k);
  if (v) { RESULT_CACHE.delete(k); RESULT_CACHE.set(k, v); } // «поднимаем» как свежий
  return v;
}

function cacheSet(k: string, v: CalculationResult): void {
  RESULT_CACHE.set(k, v);
  if (RESULT_CACHE.size > RESULT_CACHE_MAX) {
    const oldest = RESULT_CACHE.keys().next().value;
    if (oldest !== undefined) RESULT_CACHE.delete(oldest);
  }
}

export async function calculateDrops(
  target: RGB,
  components: ColorComponent[],
  settings: EngineSettings,
  onProgress: (p: number) => void,
): Promise<CalculationResult> {
  // Быстрый путь: если ровно такой запрос уже считали — отдаём из кэша.
  const ck = cacheKey(target, components, settings);
  const cached = cacheGet(ck);
  if (cached) { onProgress(100); return cached; }
  // ВАЖНО: НЕ исключаем краски, совпадающие с целью. Раньше здесь отбрасывались
  // тюбики в пределах ΔE ≤ 1 от цели («чтобы не мешать зелёный из зелёного») —
  // но для калькулятора смешивания это как раз ВЕРНЫЙ ответ: если у художника
  // есть точная краска, лучший рецепт — «взять её». Из-за фильтра #000000 не мог
  // использовать чёрный тюбик (и любой точный цвет — свой тюбик) и давал низкую
  // точность (ΔE 7+). Теперь используем все доступные краски как есть.
  const initialTargetLab = rgbToLab(target);

  // Строго сортируем компоненты по имени для гарантии 100% детерминированности алгоритма,
  // независимо от того, в каком порядке массивы были переданы из UI.
  const sortedComponents = [...components].sort((a, b) => a.name.localeCompare(b.name));

  const profile = PAINT_PROFILES[settings.paintType];
  const surface = settings.surfaceType === 'custom'
    ? { ...SURFACE_PROFILES.custom, color: settings.customSurfaceColor }
    : SURFACE_PROFILES[settings.surfaceType];

  const substrateColor = profile.usesSubstrate ? surface.color : ([255, 255, 255] as RGB);

  const componentsRgb = sortedComponents.map((c) => c.rgb);
  const n = sortedComponents.length;
  const maxPC = settings.maxPartsPerColor;
  const maxMix = settings.maxColorsInMix;
  const isFixed = settings.targetTotalParts !== null && settings.targetTotalParts > 0;
  const targetTotal = settings.targetTotalParts;
  const targetLab = initialTargetLab;

  const worker = getEngineWorker();
  const jobId = ++jobCounter;

  try {
    const candidates: SolverCandidate[] = await new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        activeJobs.delete(jobId);
        reject(new Error('timeout'));
      }, 30000);

      activeJobs.set(jobId, { resolve, reject, onProgress, timeout });

      // «Доработать цвет»: исходный замес ОБЯЗАН участвовать в рецепте — всегда,
      // в том числе при заданном лимите «Всего частей». Раньше при isFixed эта
      // обязательность отключалась (baseIdx=-1), и режим перехода мог не включать
      // стартовый цвет. Режим перехода в воркере корректно работает и с лимитом
      // (scales=[лимит]), поэтому находим базу независимо от isFixed.
      const baseColorIndex = sortedComponents.findIndex(c => c.name === 'Исходный цвет');

      worker.postMessage({
        jobId, // Отправляем ID задачи воркеру
        target,
        crgb: componentsRgb,
        n,
        mpc: maxPC,
        isF: isFixed,
        tt: targetTotal,
        tLab: targetLab,
        profile: {
          kmWeight: profile.kmWeight,
          transparency: profile.transparency,
          usesSubstrate: profile.usesSubstrate,
          darkeningFactor: profile.darkeningFactor,
          brightnessFactor: profile.drying.brightnessFactor,
          saturationShift: profile.drying.saturationShift,
        },
        subColor: substrateColor,
        maxMix,
        baseIdx: baseColorIndex >= 0 ? baseColorIndex : undefined,
      });
    });

    const variants = selectVariants(candidates, sortedComponents, profile, substrateColor, targetLab);

    const best = variants[0] || {
      drops: new Array(n).fill(0),
      components: sortedComponents,
      deltaE: 999,
      totalDrops: 0,
      approxRgb: [0, 0, 0] as RGB,
      rating: 'Плохо',
      usedColors: 0,
      label: '',
      recipe: [],
    };

    const targetHex = `#${target.map((v) => v.toString(16).padStart(2, '0')).join('').toUpperCase()}`;
    const warnings = generateWarnings(target, best.deltaE, profile, best.usedColors);

    const out: CalculationResult = {
      targetRgb: target,
      targetHex,
      drops: best.drops,
      components: sortedComponents,
      deltaE: best.deltaE,
      totalDrops: best.totalDrops,
      approxRgb: best.approxRgb,
      rating: best.rating,
      variants,
      paintType: settings.paintType,
      warnings,
    };
    cacheSet(ck, out);
    return out;
  } catch (e) {
    throw e;
  }
}