// src/generator/utils/editPersistence.ts
// Сохранение/загрузка «набора корректировок» ручного редактора.
// Набор = сжатая маска зон (RLE) + палитра + размеры + привязка к фото.
// Два канала: IndexedDB (авто, по ключу фото) и файл .melura (перенос).

import type { ProcessingResult } from "./imageProcessing/types";

export interface EditSet {
  v: 1;
  imageKey: string;
  w: number;
  h: number;
  detail: number;
  palette: [number, number, number][]; // индекс = номер зоны
  maskRLE: number[];                    // пары [value,count]
  ts: number;
}

// Ключ фото: имя+размер файла + разрешение генерации.
export function imageKeyOf(fileName: string | undefined, fileSize: number | undefined, w: number, h: number): string {
  return `${fileName || "img"}_${fileSize || 0}_${w}x${h}`;
}

function rleEncode(mask: Uint8Array): number[] {
  const out: number[] = [];
  let i = 0;
  while (i < mask.length) {
    const v = mask[i];
    let c = 1;
    while (i + c < mask.length && mask[i + c] === v && c < 0xffffff) c++;
    out.push(v, c);
    i += c;
  }
  return out;
}

function rleDecode(rle: number[], length: number): Uint8Array {
  const out = new Uint8Array(length);
  let p = 0;
  for (let i = 0; i < rle.length; i += 2) {
    const v = rle[i], c = rle[i + 1];
    for (let j = 0; j < c && p < length; j++) out[p++] = v;
  }
  return out;
}

export function buildEditSet(result: ProcessingResult, imageKey: string): EditSet {
  let maxL = -1;
  for (const k of Object.keys(result.colorPalette)) maxL = Math.max(maxL, Number(k));
  const palette: [number, number, number][] = [];
  for (let i = 0; i <= maxL; i++) palette[i] = result.colorPalette[i] || [255, 255, 255];
  return {
    v: 1,
    imageKey,
    w: result.imgW,
    h: result.imgH,
    detail: result.autoDetail || 5,
    palette,
    maskRLE: rleEncode(result.labelMask),
    ts: Date.now(),
  };
}

export function editSetMask(set: EditSet): Uint8Array {
  return rleDecode(set.maskRLE, set.w * set.h);
}

// ——— IndexedDB ———
const DB = "melura-edits";
const STORE = "edits";

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE, { keyPath: "imageKey" });
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export async function saveEditSetDB(set: EditSet): Promise<void> {
  try {
    const db = await openDB();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE, "readwrite");
      tx.objectStore(STORE).put(set);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
    db.close();
  } catch (e) {
    console.warn("saveEditSetDB failed", e);
  }
}

export async function loadEditSetDB(imageKey: string): Promise<EditSet | null> {
  try {
    const db = await openDB();
    const res = await new Promise<EditSet | null>((resolve, reject) => {
      const tx = db.transaction(STORE, "readonly");
      const r = tx.objectStore(STORE).get(imageKey);
      r.onsuccess = () => resolve((r.result as EditSet) || null);
      r.onerror = () => reject(r.error);
    });
    db.close();
    return res;
  } catch (e) {
    console.warn("loadEditSetDB failed", e);
    return null;
  }
}

// ——— Файл ———
export function exportEditSetFile(set: EditSet, baseName = "melura-правки") {
  const blob = new Blob([JSON.stringify(set)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${baseName}.melura`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function importEditSetFile(file: File): Promise<EditSet> {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => {
      try {
        const set = JSON.parse(String(r.result)) as EditSet;
        if (set && set.v === 1 && Array.isArray(set.maskRLE) && Array.isArray(set.palette)) resolve(set);
        else reject(new Error("Некорректный файл правок"));
      } catch (e) { reject(e); }
    };
    r.onerror = () => reject(r.error);
    r.readAsText(file);
  });
}
