// Ненавязчивая кнопка установки. Появляется маленькой плашкой снизу ТОЛЬКО когда
// установка реально доступна (браузер прислал beforeinstallprompt) и приложение ещё
// не установлено. Клик — нативный диалог установки (настоящее приложение, не ярлык).
// «Скрыть» убирает плашку до конца сессии. Если браузер не считает сайт устанавливаемым,
// плашка не показывается вовсе.
import { useState } from 'react';
import { useInstallPrompt } from '../hooks/useInstallPrompt';

export function InstallButton() {
  const { canInstall, promptInstall } = useInstallPrompt();
  const [hidden, setHidden] = useState(false);

  if (!canInstall || hidden) return null;

  return (
    <div className="fixed z-[180] bottom-4 left-1/2 -translate-x-1/2 animate-fade-in-up">
      <div className="flex items-center gap-1.5 pl-3 pr-1.5 py-1.5 rounded-full bg-white/95 dark:bg-slate-900/95 backdrop-blur border border-slate-200/70 dark:border-slate-700 shadow-xl shadow-black/10">
        <button
          onClick={promptInstall}
          className="flex items-center gap-2 pl-1 pr-2 py-1 rounded-full text-xs font-bold text-indigo-600 dark:text-indigo-300 hover:text-indigo-500 transition-colors"
        >
          <span className="w-6 h-6 rounded-full bg-indigo-50 dark:bg-indigo-500/10 flex items-center justify-center">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 3v12" /><path d="m8 11 4 4 4-4" /><path d="M20 17v2a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-2" /></svg>
          </span>
          Установить приложение
        </button>
        <button
          onClick={() => setHidden(true)}
          aria-label="Скрыть"
          className="w-6 h-6 rounded-full flex items-center justify-center text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
        >
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12" /></svg>
        </button>
      </div>
    </div>
  );
}
