export function findSurfacePreset(id: string): SurfacePreset | undefined {
  return SURFACE_PRESETS.find(p => p.id === id);
}

/**
 * Какую основу предложить, зная тип поверхности из настроек расчёта.
 *
 * Список там короткий и служит другой цели — он описывает, как краска
 * взаимодействует с основой, а не как основа выглядит. Поэтому связь здесь
 * не жёсткая: это лишь разумная отправная точка, которую пользователь меняет.
 */
export function defaultSurfaceFor(surfaceType: string): string {
  switch (surfaceType) {
    case 'paper_white': return 'wc_cold';
    case 'paper_cream': return 'wc_cold';
    case 'paper_kraft': return 'kraft';
    case 'canvas': return 'canvas_med';
    case 'wood': return 'wood';
    default: return 'canvas_med';
  }
}

/* ── Форма поверхности ──────────────────────────────────────────────────────
 *
 * Координаты в миллиметрах на картине. Возвращается высота в условных
 * единицах, симметричная относительно нуля: средняя светлота картины от
 * фактуры не уезжает.
 */

export interface NoiseFn { (x: number, y: number): number }

export function surfaceHeight(
  xMm: number, yMm: number, p: SurfacePreset, noise: NoiseFn,
): number {
  switch (p.kind) {
    case 'plain': {
      // Полотняное переплетение: две системы нитей, идущие через одну.
      // Шаг слегка «гуляет» — у настоящей ткани нити не идеально ровные,
      // и без этого картина выглядит как миллиметровка.
      const s = p.pitchMm;
      const jx = p.irregular * 0.35 * noise(xMm / (s * 4), yMm / (s * 4));
      const jy = p.irregular * 0.35 * noise(xMm / (s * 4) + 37, yMm / (s * 4) + 11);
      const wx = Math.cos(6.2831853 * (xMm / s + jx));
      const wy = Math.cos(6.2831853 * (yMm / (s * p.aniso) + jy));
      const weave = 0.5 * (wx + wy) + 0.25 * wx * wy;
      // Неравномерная толщина нити: у льна она заметна, у портретного холста нет.
      const thick = p.irregular * 0.5 * noise(xMm / (s * 1.5) + 5, yMm / (s * 1.5) + 91);
      return weave * (1 - p.irregular * 0.3) + thick;
    }
    case 'tooth': {
      // Зерно бумаги правильной структуры не имеет вовсе. Три октавы шума:
      // крупные впадины между волокнами, средние неровности, мелкая ворса.
      const s = p.pitchMm;
      return 1.3 * (
        0.60 * noise(xMm / s, yMm / (s * p.aniso)) +
        0.30 * noise(xMm / (s * 0.45) + 13, yMm / (s * 0.45 * p.aniso) + 7) +
        0.15 * noise(xMm / (s * 0.2) + 29, yMm / (s * 0.2 * p.aniso) + 53)
      );
    }
    case 'laid': {
      // Верже: частые вержеры от проволок отливной сетки и редкие валики
      // понтюзо поперёк них.
      const lines = Math.cos(6.2831853 * yMm / p.pitchMm);
      const ch = Math.cos(6.2831853 * xMm / Math.max(1, p.pitch2Mm));
      const chain = Math.pow(Math.max(0, ch), 12);
      const grain = 0.25 * noise(xMm / 0.15, yMm / 0.15);
      return 0.62 * lines + 0.5 * chain + grain;
    }
    case 'fibre': {
      // Древесина: волокно, вытянутое вдоль доски, и годичные слои поперёк.
      // Слои идут не прямыми линиями — их ведёт, поэтому фаза колебания сама
      // модулируется медленным шумом.
      const s = p.pitchMm;
      const fib =
        0.70 * noise(xMm / (s * p.aniso), yMm / s) +
        0.30 * noise(xMm / (s * p.aniso * 0.4) + 17, yMm / (s * 0.4) + 23);
      const r2 = Math.max(0.5, p.pitch2Mm);
      const wobble = p.irregular * 2.0 * noise(xMm / (r2 * 3), yMm / (r2 * 3));
      const rings = Math.cos(6.2831853 * yMm / r2 + wobble);
      return 0.6 * fib + 0.35 * rings;
    }
  }
}

/**
 * Тот же расчёт на языке шейдеров.
 *
 * Держится строкой рядом с оригиналом сознательно: две реализации одной формы,
 * лежащие в разных файлах, однажды разъедутся, и заметить это будет тяжело.
 */
export const SURFACE_GLSL = `
// kind: 0 plain, 1 tooth, 2 laid, 3 fibre
float surfaceHeight(vec2 mm, int kind, float pitch, float pitch2, float irr, float aniso) {
  if (kind == 0) {
    float s = pitch;
    float jx = irr * 0.35 * noiseAt(vec2(mm.x / (s * 4.0), mm.y / (s * 4.0)));
    float jy = irr * 0.35 * noiseAt(vec2(mm.x / (s * 4.0) + 37.0, mm.y / (s * 4.0) + 11.0));
    float wx = cos(6.2831853 * (mm.x / s + jx));
    float wy = cos(6.2831853 * (mm.y / (s * aniso) + jy));
    float weave = 0.5 * (wx + wy) + 0.25 * wx * wy;
    float thick = irr * 0.5 * noiseAt(vec2(mm.x / (s * 1.5) + 5.0, mm.y / (s * 1.5) + 91.0));
    return weave * (1.0 - irr * 0.3) + thick;
  } else if (kind == 1) {
    float s = pitch;
    return 1.3 * (
      0.60 * noiseAt(vec2(mm.x / s, mm.y / (s * aniso))) +
      0.30 * noiseAt(vec2(mm.x / (s * 0.45) + 13.0, mm.y / (s * 0.45 * aniso) + 7.0)) +
      0.15 * noiseAt(vec2(mm.x / (s * 0.2) + 29.0, mm.y / (s * 0.2 * aniso) + 53.0))
    );
  } else if (kind == 2) {
    float lines = cos(6.2831853 * mm.y / pitch);
    float ch = cos(6.2831853 * mm.x / max(1.0, pitch2));
    float chain = pow(max(0.0, ch), 12.0);
    float grain = 0.25 * noiseAt(vec2(mm.x / 0.15, mm.y / 0.15));
    return 0.62 * lines + 0.5 * chain + grain;
  } else {
    float s = pitch;
    float fib =
      0.70 * noiseAt(vec2(mm.x / (s * aniso), mm.y / s)) +
      0.30 * noiseAt(vec2(mm.x / (s * aniso * 0.4) + 17.0, mm.y / (s * 0.4) + 23.0));
    float r2 = max(0.5, pitch2);
    float wobble = irr * 2.0 * noiseAt(vec2(mm.x / (r2 * 3.0), mm.y / (r2 * 3.0)));
    float rings = cos(6.2831853 * mm.y / r2 + wobble);
    return 0.6 * fib + 0.35 * rings;
  }
}
`;

export const KIND_INDEX: Record<SurfaceKind, number> = {
  plain: 0, tooth: 1, laid: 2, fibre: 3,
};
