// src/generator/utils/advisor.ts
//
// Центр рекомендаций: разбор того, что мешает картине получиться, и
// конкретные шаги к исправлению.
//
// ЗАЧЕМ. Кнопка «Предел» честно показывает, какие цвета краски не вытягивают,
// но на этом разговор обрывался: пользователь видел проблему и не получал
// ответа, что с ней делать. Диагноз без назначения бесполезен.
//
// ПРИНЦИПЫ, которым подчинён этот модуль.
//
// 1. Сначала бесплатное. Нужная краска часто уже есть у человека в базе, просто
//    не отмечена в палитре. Совет «купите краску» в такой ситуации — оскорбление
//    здравым смыслом. Поэтому сперва проверяется, что можно включить даром.
//
// 2. Покупка — с адресом. «Приобретите более насыщенный зелёный» невыполнимо.
//    Выполнимо: «Ладога, Кобальт зелёный светлый, артикул 706». Кандидаты
//    берутся из базы реальных наборов, вместе с маркой и артикулом.
//
// 3. Одна покупка — много починок. Считается не «какая краска ближе всего
//    к цвету № 7», а «какая одна краска закроет наибольшее число проблемных
//    цветов сразу». Человеку нужен минимум покупок, а не минимум ΔE.
//
// 4. Всегда есть замена. У человека может не оказаться именно этой краски,
//    поэтому к каждой рекомендации прилагаются равноценные по цвету варианты
//    других марок.
//
// ОБ ОЦЕНКЕ. Пригодность краски оценивается по её виду на холсте в чистом
// виде — после смешивания с подложкой и высыхания. Это заведомо нижняя оценка:
// в замесе краска работает лучше, чем в одиночку. Точный рецепт считается
// солвером уже после того, как краска добавлена в палитру; здесь нужна быстрая
// прикидка по всей базе, а не точный ответ по одному цвету.

import { PAINT_PROFILES, SURFACE_PROFILES, EXTENDED_COLORS, type RGB, type ColorComponent, type EngineSettings } from '../../config';
import { deltaE00, rgbToLab } from '../../utils/colorMath';
import { mixColors } from '../../utils/mixing';
import { calculateDryColor } from '../../lab/core';
import { BUILT_IN_SETS } from '../../paints/sets';
import type { PaintSet } from '../../paints/types';

/** Насколько ближе должна стать краска, чтобы считаться помощью. */
const HELP_MARGIN = 1.5;

/** Порог, ниже которого две краски считаются взаимозаменяемыми. */
const SUBSTITUTE_DELTA_E = 6;

export type AdviceKind =
  | 'enable-paint'   // включить краску, которая уже есть в базе
  | 'buy-paint'      // приобрести краску
  | 'raise-parts'    // ослабить лимит частей
  | 'cleanup'        // мелкие зоны
  | 'info';          // сообщение без действия

export interface PaintSuggestion {
  name: string;
  rgb: RGB;
  /** Марка и линейка, где эта краска выпускается. */
  source: string;
  /** Артикул производителя, если известен. */
  code?: string;
  /** Сколько проблемных цветов картины краска приводит в норму. */
  fixes: number;
  /** Сколько проблемных цветов заметно улучшает, не доводя до нормы. */
  improves: number;
  /** Среднее остаточное расхождение по тем цветам, которым краска помогает. */
  residualDeltaE: number;
  /** Равноценные по цвету краски других марок. */
  substitutes: { name: string; source: string; rgb: RGB; deltaE: number }[];
}

export interface Advice {
  id: string;
  severity: 'high' | 'medium' | 'low';
  kind: AdviceKind;
  title: string;
  /** Разбор причины. Без этого совет выглядит гаданием. */
  detail: string;
  /** Краски к включению или покупке, лучшие первыми. */
  paints?: PaintSuggestion[];
  /** Номера цветов схемы, к которым относится совет. */
  labels?: number[];
}

export interface AdvisorInput {
  /** Идеальные цвета схемы по номерам. */
  ideal: Record<number, RGB>;
  /** Достижимые цвета — то, что реально дадут краски. */
  adapted: Record<number, RGB> | null;
  /** Расхождение идеала и достижимого, ΔE2000. */
  gamutDelta: Record<number, number> | null;
  validLabels: number[];
  /** Краски, отмеченные пользователем как имеющиеся в работе. */
  selected: ColorComponent[];
  /** Вся палитра приложения, включая неотмеченное и пользовательское. */
  available: ColorComponent[];
  customSets: PaintSet[];
  engineSettings: EngineSettings;
  totalPartsLimit: string | number;
  /** Порог, выше которого расхождение считается заметным. */
  threshold: number;
}

/* ── Вспомогательное ────────────────────────────────────────────────────────*/

/** Как краска выглядит на холсте в чистом виде после высыхания. */
function driedAppearance(rgb: RGB, engineSettings: EngineSettings): RGB {
  const profile = PAINT_PROFILES[engineSettings.paintType];
  const surface = engineSettings.surfaceType === 'custom'
    ? { ...SURFACE_PROFILES.custom, color: engineSettings.customSurfaceColor }
    : SURFACE_PROFILES[engineSettings.surfaceType];
  const substrate = (profile.usesSubstrate ? surface.color : [255, 255, 255]) as RGB;
  const wet = mixColors([10], [rgb], profile, substrate, false);
  return profile.drying ? calculateDryColor(wet, profile.drying) : wet;
}

interface Candidate {
  name: string;
  rgb: RGB;
  source: string;
  code?: string;
  lab: [number, number, number];
  /** Краска уже есть у пользователя в базе, её достаточно отметить. */
  owned: boolean;
}

/**
 * Собирает всех кандидатов: и то, что у человека уже есть, и краски реальных
 * наборов. Отмеченные в палитре исключаются — их предлагать бессмысленно.
 */
function buildCandidates(input: AdvisorInput): Candidate[] {
  const selectedNames = new Set(input.selected.map(c => c.name));
  const out: Candidate[] = [];
  const seen = new Set<string>();

  // Своё, но не отмеченное. Идёт первым: включение бесплатно.
  for (const c of input.available) {
    if (selectedNames.has(c.name) || seen.has(c.name)) continue;
    seen.add(c.name);
    out.push({
      name: c.name, rgb: c.rgb, source: 'В базе приложения',
      lab: rgbToLab(driedAppearance(c.rgb, input.engineSettings)), owned: true,
    });
  }

  // Краски реальных наборов, которых в базе пользователя нет.
  for (const s of [...BUILT_IN_SETS, ...input.customSets]) {
    for (const c of s.colors) {
      if (selectedNames.has(c.name) || seen.has(c.name)) continue;
      seen.add(c.name);
      out.push({
        name: c.name, rgb: c.rgb, source: `${s.brand}, ${s.line}`, code: c.code,
        lab: rgbToLab(driedAppearance(c.rgb, input.engineSettings)), owned: false,
      });
    }
  }

  // Общепигментные названия — на случай, когда ни один набор не закрывает
  // потребность, но пигмент как таковой существует.
  for (const c of EXTENDED_COLORS) {
    if (selectedNames.has(c.name) || seen.has(c.name)) continue;
    seen.add(c.name);
    out.push({
      name: c.name, rgb: c.rgb, source: 'Общепринятое название пигмента',
      lab: rgbToLab(driedAppearance(c.rgb, input.engineSettings)), owned: true,
    });
  }

  return out;
}

/**
 * Разбор причины промаха: чего именно не хватает краскам.
 *
 * Сравнение идёт в Lab, покомпонентно: светлота, насыщенность, тон. Именно
 * это и нужно человеку — «не хватает тёмного» и «не хватает насыщенного»
 * лечатся разными покупками.
 */
function diagnose(ideal: RGB, got: RGB): 'light' | 'dark' | 'chroma' | 'hue' {
  const a = rgbToLab(ideal), b = rgbToLab(got);
  const dL = a[0] - b[0];
  const ca = Math.hypot(a[1], a[2]), cb = Math.hypot(b[1], b[2]);
  const dC = ca - cb;
  const dH = Math.sqrt(Math.max(0, (a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2 - dC * dC));
  if (Math.abs(dL) >= Math.abs(dC) && Math.abs(dL) >= dH) return dL > 0 ? 'light' : 'dark';
  if (dC >= dH) return 'chroma';
  return 'hue';
}

const DIAGNOSIS_TEXT: Record<string, string> = {
  light: 'не хватает светлых красок: смеси получаются темнее нужного',
  dark: 'не хватает тёмных красок: смеси получаются светлее нужного',
  chroma: 'не хватает насыщенных красок: смеси выходят приглушёнными',
  hue: 'в палитре нет красок нужного оттенка: тон уходит в сторону',
};

/* ── Основная функция ───────────────────────────────────────────────────────*/

export function buildAdvice(input: AdvisorInput): Advice[] {
  const out: Advice[] = [];
  const { ideal, adapted, gamutDelta, validLabels, threshold } = input;

  if (!adapted || !gamutDelta) return out;

  const problems = validLabels
    .filter(l => (gamutDelta[l] ?? 0) > threshold && ideal[l] && adapted[l])
    .sort((a, b) => (gamutDelta[b] ?? 0) - (gamutDelta[a] ?? 0));

  if (!problems.length) {
    out.push({
      id: 'gamut-ok',
      severity: 'low',
      kind: 'info',
      title: 'Все цвета достижимы',
      detail: 'Выбранные краски покрывают палитру картины. Заметных отклонений от идеальных цветов нет.',
    });
    return out;
  }

  // Разбор причины по всей группе проблемных цветов.
  const tally: Record<string, number> = { light: 0, dark: 0, chroma: 0, hue: 0 };
  for (const l of problems) tally[diagnose(ideal[l], adapted[l])]++;
  const mainCause = Object.entries(tally).sort((a, b) => b[1] - a[1])[0][0];
  const worst = gamutDelta[problems[0]] ?? 0;

  /* --- Оценка кандидатов ------------------------------------------------- */

  const cands = buildCandidates(input);
  const targetLabs = problems.map(l => rgbToLab(ideal[l]));
  const currentDe = problems.map(l => gamutDelta[l] ?? 0);

  interface Scored extends Candidate { fixes: number; improves: number; residual: number }
  const scored: Scored[] = [];

  for (const c of cands) {
    let fixes = 0, improves = 0, sum = 0, n = 0;
    for (let i = 0; i < problems.length; i++) {
      const de = deltaE00(targetLabs[i], c.lab);
      if (de >= currentDe[i] - HELP_MARGIN) continue; // не помогает
      if (de <= threshold) fixes++; else improves++;
      sum += de; n++;
    }
    if (!n) continue;
    scored.push({ ...c, fixes, improves, residual: sum / n });
  }

  // Одна покупка, закрывающая много цветов, ценнее нескольких точечных.
  // Поэтому первый критерий — число починенных цветов, и лишь затем близость.
  scored.sort((a, b) =>
    (b.fixes - a.fixes) ||
    (b.improves - a.improves) ||
    (a.residual - b.residual));

  const subsFor = (c: Scored): PaintSuggestion['substitutes'] =>
    cands
      .filter(o => o.name !== c.name)
      .map(o => ({ name: o.name, source: o.source, rgb: o.rgb, deltaE: deltaE00(c.lab, o.lab) }))
      .filter(o => o.deltaE < SUBSTITUTE_DELTA_E)
      .sort((a, b) => a.deltaE - b.deltaE)
      .slice(0, 4);

  const toSuggestion = (c: Scored): PaintSuggestion => ({
    name: c.name, rgb: c.rgb, source: c.source, code: c.code,
    fixes: c.fixes, improves: c.improves, residualDeltaE: c.residual,
    substitutes: subsFor(c),
  });

  const owned = scored.filter(c => c.owned).slice(0, 3).map(toSuggestion);
  const foreign = scored.filter(c => !c.owned).slice(0, 3).map(toSuggestion);

  /* --- Советы ------------------------------------------------------------ */

  const head = `Цветов с заметным отклонением: ${problems.length}. Наибольшее расхождение ΔE ${worst.toFixed(1)}. Причина: ${DIAGNOSIS_TEXT[mainCause]}.`;

  if (owned.length) {
    out.push({
      id: 'enable-owned',
      severity: 'high',
      kind: 'enable-paint',
      title: 'Включите краски, которые уже есть в базе',
      detail: `${head} Эти краски присутствуют в базе приложения, но не отмечены в вашей палитре. Включение ничего не стоит и выполняется одним нажатием.`,
      paints: owned,
      labels: problems,
    });
  }

  if (foreign.length) {
    out.push({
      id: 'buy-paint',
      severity: owned.length ? 'medium' : 'high',
      kind: 'buy-paint',
      title: 'Краски, которых не хватает палитре',
      detail: `${owned.length ? '' : head + ' '}Каждая краска показана с указанием набора и артикула, а также с равноценными заменами других марок: если конкретно этой краски нет, подойдёт любая из списка замен.`,
      paints: foreign,
      labels: problems,
    });
  }

  // Лимит частей. Иногда цвет недостижим не из-за нехватки красок, а из-за
  // того, что рецепту не дают развернуться: в трёх частях тонкий оттенок
  // не выразить.
  const limit = typeof input.totalPartsLimit === 'number' ? input.totalPartsLimit : null;
  if (limit !== null && limit > 0 && limit <= 12) {
    out.push({
      id: 'raise-parts',
      severity: 'low',
      kind: 'raise-parts',
      title: 'Ослабьте ограничение на число частей',
      detail: `Сейчас рецепт ограничен ${limit} частями. Часть недостижимых оттенков берётся не новой краской, а более дробной пропорцией: при ${Math.min(20, limit * 2)} частях solver получает вдвое более мелкий шаг. Плата за это — более кропотливое отмеривание.`,
    });
  }

  return out;
}
