// src/generator/utils/autoPreset/search.ts
//
// «Автоподбор пресетов»: умный СУБЪЕКТ-ОРИЕНТИРОВАННЫЙ поиск лучших вариантов.
// Прогоняем движок вхолостую на уменьшенном изображении по сетке
// (число красок × детализация × «акцент на объекте»), уточняем фото-коррекцию
// у лидеров, оцениваем каждый вариант субъект-первой метрикой (scoring.ts) и
// возвращаем несколько ЛУЧШИХ и РАЗНООБРАЗНЫХ вариантов, где главное (лицо/объект)
// сохранено и чисто, а фон не рассыпан.

import { applyCorrection, type FullCorrectionParams } from "../imageProcessing/imageCorrection";
import { emphasizeImportance } from "../imageProcessing/importanceMap";
import type { ProcessingResult } from "../imageProcessing/types";
import { buildOrigRef, scoreCandidate, type ScoreBreakdown } from "./scoring";
import type { PresetLevers } from "../../store/types";

export interface PresetCandidate {
  numColors: number;
  detail: number;
  emphasis: number;                 // акцент на объекте (гамма карты значимости), 1 = без акцента
  backgroundSimplify: number;       // сила упрощения фона, применённая в варианте
  correction: FullCorrectionParams;
  breakdown: ScoreBreakdown;
  score: number;
  preview: ImageData;
  imgW: number;
  imgH: number;
}

export type RunOne = (
  img: ImageData,
  numColors: number,
  detail: number,
  importance: Float32Array | null,
  bgSimplify: number,
) => Promise<ProcessingResult>;

export interface SearchOptions {
  baseImage: ImageData;
  importance: Float32Array | null;
  baseCorrection: FullCorrectionParams;
  runOne: RunOne;
  onProgress?: (done: number, total: number, best: number) => void;
  signal?: AbortSignal;
  refineCorrection?: boolean;
  maxResults?: number;
  levers?: PresetLevers;   // какими рычагами разрешено рулить (по умолч. все)
  baseColors?: number;     // текущее число красок (если рычаг «цвета» выключен)
  baseDetail?: number;     // текущая детализация (если рычаг «детали» выключен)
}

// Широкий перебор: доводим до ~сотни «мысленных» генераций. Детали 2 выброшены
// как заведомо-мыльные; цвета доведены до 40 — эталон «хорошо» у пользователя на
// портрете жил на 39 красках, значит богатая палитра должна быть в досягаемости.
const COLOR_GRID = [12, 14, 16, 18, 20, 22, 24, 26, 28, 32, 36, 40];
const DETAIL_GRID = [3, 4, 5, 6, 7, 8, 9, 10];
const EMPH_LEVELS = [1, 1.4, 1.8];   // уровни «акцента на объекте» (гамма карты значимости)
const BG_BASE = 1;                    // базовое упрощение фона (как в движке по умолчанию)

const ALL_LEVERS: PresetLevers = {
  colors: true, detail: true, brightness: true, contrast: true, saturation: true,
  sharpness: true, shadows: true, highlights: true, structure: true, emphasis: true, backgroundSimplify: true,
};

const yieldToUI = () => new Promise<void>((r) => setTimeout(r, 0));

/** Полный набор параметров одной «мысленной» генерации. */
interface Cfg {
  numColors: number;
  detail: number;
  emphasis: number;
  bgSimplify: number;
  correction: FullCorrectionParams;
}
interface Scored extends PresetCandidate {}

const clampCorr = (v: number) => (v < -100 ? -100 : v > 100 ? 100 : v);

export async function runAutoPresetSearch(opts: SearchOptions): Promise<PresetCandidate[]> {
  const { baseImage, importance, baseCorrection, runOne, onProgress, signal } = opts;
  const refine = opts.refineCorrection !== false;
  const maxResults = opts.maxResults ?? 5;
  const levers = opts.levers ?? ALL_LEVERS;

  // Эталон верности — фото с УЖЕ применённой базовой коррекцией.
  const refImage = applyCorrection(baseImage, baseCorrection, importance);
  const ref = buildOrigRef(refImage, importance);

  // Заострённые карты значимости по уровням акцента (считаем один раз).
  const impByEmph = new Map<number, Float32Array | null>();
  for (const e of EMPH_LEVELS) impByEmph.set(e, importance ? emphasizeImportance(importance, e) : null);

  const all: Scored[] = [];
  let best = 0;

  const cache = new Map<string, ProcessingResult>();
  const corrKey = (c: FullCorrectionParams) =>
    `${c.brightness},${c.contrast},${c.saturation},${c.sharpness},${c.shadows ?? 0},${c.highlights ?? 0},${c.structure ?? 0}`;
  const cfgKey = (g: Cfg) => `${g.numColors}|${g.detail}|e${g.emphasis}|b${g.bgSimplify}|${corrKey(g.correction)}`;

  const evalOne = async (g: Cfg): Promise<Scored> => {
    const key = cfgKey(g);
    let res = cache.get(key);
    if (!res) {
      const corrected = applyCorrection(baseImage, g.correction, importance);
      res = await runOne(corrected, g.numColors, g.detail, impByEmph.get(g.emphasis) ?? importance, g.bgSimplify);
      cache.set(key, res);
    }
    const breakdown = scoreCandidate(ref, res);
    return {
      numColors: g.numColors, detail: g.detail, emphasis: g.emphasis, backgroundSimplify: g.bgSimplify,
      correction: g.correction, breakdown, score: breakdown.score,
      preview: res.previewImageData, imgW: res.imgW, imgH: res.imgH,
    };
  };

  // Фаза A: число красок × детализация. Выключенный рычаг → фиксируем текущее.
  const colorGrid = levers.colors ? COLOR_GRID : [opts.baseColors ?? 20];
  const detailGrid = levers.detail ? DETAIL_GRID : [opts.baseDetail ?? 6];

  // Оси уточнения (Фаза B): каждая — 2 пробы; берём ТОЛЬКО включённые рычаги.
  type Move = (cur: Cfg) => Cfg[];
  const corrMove = (field: keyof FullCorrectionParams, deltas: number[]): Move =>
    (cur) => deltas.map((d) => ({
      ...cur,
      correction: { ...cur.correction, [field]: clampCorr(((cur.correction[field] as number | undefined) ?? 0) + d) },
    }));
  const moves: Move[] = [];
  if (levers.shadows) moves.push(corrMove("shadows", [-16, 12]));
  if (levers.highlights) moves.push(corrMove("highlights", [-14, 12]));
  if (levers.contrast) moves.push(corrMove("contrast", [-12, 12]));
  if (levers.saturation) moves.push(corrMove("saturation", [-12, 12]));
  if (levers.structure) moves.push(corrMove("structure", [12, 24]));
  if (levers.brightness) moves.push(corrMove("brightness", [-8, 8]));
  if (levers.sharpness) moves.push(corrMove("sharpness", [15, 30]));
  if (levers.emphasis && importance)
    moves.push((cur) => EMPH_LEVELS.filter((e) => e !== cur.emphasis).slice(0, 2).map((e) => ({ ...cur, emphasis: e })));
  if (levers.backgroundSimplify)
    moves.push((cur) => [0, 2].filter((b) => b !== cur.bgSimplify).map((b) => ({ ...cur, bgSimplify: b })));

  const totalPhaseA = colorGrid.length * detailGrid.length;
  const totalRefine = refine ? 3 * moves.length * 2 : 0; // 3 лидера × оси × 2 шага
  const total = totalPhaseA + totalRefine;
  let done = 0;

  const baseCfg = (nc: number, dt: number): Cfg =>
    ({ numColors: nc, detail: dt, emphasis: 1, bgSimplify: BG_BASE, correction: baseCorrection });

  // ---- Фаза A ----
  for (const nc of colorGrid) {
    for (const dt of detailGrid) {
      if (signal?.aborted) throw new DOMException("Aborted", "AbortError");
      const c = await evalOne(baseCfg(nc, dt));
      all.push(c);
      if (c.score > best) best = c.score;
      done++;
      onProgress?.(done, total, best);
      await yieldToUI();
    }
  }

  // ---- Фаза B: hill-climb у топ-3 лидеров по ВКЛЮЧЁННЫМ осям ----
  if (refine && moves.length > 0) {
    const leaders = [...all].sort((a, b) => b.score - a.score).slice(0, 3);
    const seen = new Set<string>();
    for (const leader of leaders) {
      let cur: Cfg = {
        numColors: leader.numColors, detail: leader.detail, emphasis: leader.emphasis,
        bgSimplify: leader.backgroundSimplify, correction: leader.correction,
      };
      let curScore = leader.score;
      for (const move of moves) {
        const variants = move(cur);
        for (let i = 0; i < 2; i++) {          // фиксированно 2 шага прогресса на ось
          if (signal?.aborted) throw new DOMException("Aborted", "AbortError");
          done++;
          const v = variants[i];
          if (!v) { onProgress?.(done, total, best); continue; }
          const k = cfgKey(v);
          if (seen.has(k)) { onProgress?.(done, total, best); continue; }
          seen.add(k);
          const cand = await evalOne(v);
          all.push(cand);
          if (cand.score > best) best = cand.score;
          if (cand.score > curScore) { cur = v; curScore = cand.score; }
          onProgress?.(done, total, best);
          await yieldToUI();
        }
      }
    }
  }

  onProgress?.(total, total, best);
  // Есть ли явный субъект (лицо/объект)? Для него включаем «порог реализма».
  let subjectPresent = false;
  if (importance) {
    let hi = 0; for (let i = 0; i < importance.length; i++) if (importance[i] > 0.6) hi++;
    subjectPresent = hi / importance.length > 0.03;
  }

  return selectDiverse(all, maxResults, subjectPresent);
}

/**
 * Отбор вариантов. Три принципа:
 *  1) ДЕДУП по РЕАЛЬНОМУ выходу — пиксель-идентичные картинки (различие лишь в
 *     ползунке детализации, реальной перегенерации нет) схлопываются в одну.
 *  2) «КОЛЕНО КРИВОЙ» на РАЗЛИЧАЮЩЕМ балле — «Лучший» = самый ЭКОНОМНЫЙ среди
 *     «не хуже максимума» (eps). Простой Луне десятки цветов не поднимают балл →
 *     скромная палитра; лицу качество реально растёт с деталями → колено уходит
 *     вверх, результат богат. Расход подстраивается под сложность фото сам.
 *  3) РАЗНООБРАЗИЕ остальных карточек — сильные, но заметно разный расход/выход.
 */
function selectDiverse(all: Scored[], n: number, subjectPresent: boolean): PresetCandidate[] {
  if (all.length === 0) return [];

  // Порог реализма: для лица детали/цвета ниже порога — заведомо мыло, отсекаем.
  const REALISM_DETAIL = 6, REALISM_COLORS = 18;
  let base = all;
  if (subjectPresent) {
    const realistic = all.filter((c) => c.detail >= REALISM_DETAIL && c.breakdown.usedColors >= REALISM_COLORS);
    if (realistic.length >= n) base = realistic;
    else if (realistic.length > 0) base = realistic;
    else base = all.filter((c) => c.detail >= REALISM_DETAIL);
    if (base.length < n) base = all;
  }

  // Расход (меньше = экономнее) и сигнатура фактического результата.
  const cost = (c: Scored) => c.breakdown.usedColors + c.detail * 1.2;
  const sig = (c: Scored) =>
    `${c.breakdown.usedColors}|${c.breakdown.zones}|${c.breakdown.microzones}|${Math.round(c.score * 1000)}`;

  // (1) ДЕДУП по выходу: пиксель-идентичные картинки (различие лишь в ползунке
  // детализации) → оставляем самую дешёвую. Устраняет «дубликаты» в выдаче.
  const bySig = new Map<string, Scored>();
  for (const c of base) {
    const ex = bySig.get(sig(c));
    if (!ex || cost(c) < cost(ex)) bySig.set(sig(c), c);
  }
  const uniq = [...bySig.values()];

  // (2) КОЛЕНО на различающем балле: «Лучший» = самый ЭКОНОМНЫЙ среди «не хуже
  // максимума на eps». Порог АДАПТИВНЫЙ и завязан не на «есть ли субъект», а на
  // том, ПРОЯВЛЯЕТ ли детализация черты. Ведь Луна — тоже «объект», но гладкий:
  // сравниваем сохранность черт (structure=featureKept) на высокой и низкой
  // детализации. Растёт заметно (лицо) → узкий eps, держим богато. Плоско (Луна,
  // простые формы) → широкий eps, режем палитру: незачем 40 цветов на гладкий шар.
  const avgFeature = (arr: Scored[]) =>
    arr.length ? arr.reduce((s, c) => s + c.breakdown.structure, 0) / arr.length : 0;
  const featureBenefit =
    avgFeature(uniq.filter((c) => c.detail >= 8)) - avgFeature(uniq.filter((c) => c.detail <= 4));
  const bestScore = Math.max(...uniq.map((c) => c.score));
  const EPS = featureBenefit > 0.05 ? 0.012 : 0.03;
  const plateau = uniq.filter((c) => c.score >= bestScore - EPS).sort((a, b) => cost(a) - cost(b));
  const best = plateau[0] ?? [...uniq].sort((a, b) => b.score - a.score)[0];

  // (3) РАЗНООБРАЗИЕ остальных карточек: сильные по баллу, но иные по расходу и выходу.
  const pick: PresetCandidate[] = [best];
  const pickedSig = new Set<string>([sig(best)]);
  const others = uniq.filter((c) => c !== best).sort((a, b) => b.score - a.score);
  const distinctEnough = (c: Scored) =>
    !pickedSig.has(sig(c)) &&
    pick.every((p) => Math.abs(p.breakdown.usedColors - c.breakdown.usedColors) >= 2 || Math.abs(p.detail - c.detail) >= 1);

  for (const c of others) { if (pick.length >= n) break; if (distinctEnough(c)) { pick.push(c); pickedSig.add(sig(c)); } }
  for (const c of others) { if (pick.length >= n) break; if (!pickedSig.has(sig(c))) { pick.push(c); pickedSig.add(sig(c)); } }
  return pick;
}
