// src/generator/hooks/useGeneratorLogic.ts
import { useCallback, useEffect, useRef } from "react";
import { useAppStore } from "../store";
import { wordColors, wordZones } from "../../utils/plural";
import { processImage, generateColorPreview, type ProcessingResult } from "../utils/imageProcessing";
import { applyCorrection, applyColorHarmony } from "../utils/imageProcessing/imageCorrection";
import { profileImageQuick } from "../utils/imageProcessing/profiler";
import { calculateSmartParams, analyzeImportanceDistribution } from "../utils/smartParams";
import { analyzeAutoCorrection } from "../utils/imageProcessing/imageCorrection";
import { buildImportanceMap, emphasizeImportance } from "../utils/imageProcessing/importanceMap";
import { enhanceFaces } from "../utils/imageProcessing/faceEnhance";
import heic2any from "heic2any";
import { aiEngine } from "../utils/ai/mediaPipeService";
import { salientObjectEngine } from "../utils/ai/salientObjectService";
import { useGeneratorHotkeys } from "./useGeneratorHotkeys";

const MAX_FILE_SIZE = 50 * 1024 * 1024;
const MAX_SIDE = 900;
const ACCEPTED_TYPES = new Set(["image/jpeg", "image/png", "image/webp", "image/heic", "image/heif"]);

export function useGeneratorLogic(isOpen: boolean, isDark: boolean) {
  const update = useAppStore((s) => s.update);
  
  const originalImageUrl = useAppStore((s) => s.originalImageUrl);
  const hasOriginal = !!originalImageUrl;
  const studioMode = useAppStore((s) => s.studioMode);
  const numColors = useAppStore((s) => s.numColors);
  const detail = useAppStore((s) => s.detail);
  const paintingModeState = useAppStore((s) => s.paintingModeState);
  const pbnModeState = useAppStore((s) => s.pbnModeState);
  const colorHarmony = useAppStore((s) => s.colorHarmony);
  const colorHarmonyIntensity = useAppStore((s) => s.colorHarmonyIntensity);
  const colorHarmonyCustomHue = useAppStore((s) => s.colorHarmonyCustomHue);
  const correction = useAppStore((s) => s.correction);
  const importanceEmphasis = useAppStore((s) => s.importanceEmphasis);
  const backgroundSimplify = useAppStore((s) => s.backgroundSimplify);
  const isInteracting = useAppStore((s) => s.isInteracting);
  const autoEnhanceEnabled = useAppStore((s) => s.autoEnhance);
  const protectVersion = useAppStore((s) => s.protectVersion);
  const autoEnhanceMounted = useRef(false);

  const processingRef = useRef(false);
  const autoGenTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastSignaturesRef = useRef<Record<string, string>>({ painting: "", pbn: "" });
  const resultCache = useRef<Map<string, ProcessingResult>>(new Map());

  useEffect(() => {
    resultCache.current.clear();
    lastSignaturesRef.current = { painting: "", pbn: "" };
  }, [originalImageUrl]);

  useEffect(() => {
    if (isOpen) useAppStore.getState().initHistory();
  }, [isOpen]);

  useEffect(() => {
    if (isOpen) update({ isDark });
  }, [isDark, isOpen, update]);

  const buildProcessingParams = useCallback(() => {
    const s = useAppStore.getState();
    if (s.studioMode === "painting") {
      return {
        mode: "painting",
        numColors: s.paintingModeState.numColors,
        detail: s.paintingModeState.detail,
        correction: s.correction,
        importanceEmphasis: s.importanceEmphasis ?? 1,
        backgroundSimplify: s.backgroundSimplify ?? 1,
        colorHarmony: "none" as const,
        colorHarmonyIntensity: 70,
        colorHarmonyCustomHue: null as number | null,
      };
    }
    return {
      mode: "pbn",
      numColors: s.pbnModeState.numColors,
      detail: s.pbnModeState.detail,
      correction: s.correction,
      importanceEmphasis: s.importanceEmphasis ?? 1,
      backgroundSimplify: s.backgroundSimplify ?? 1,
      colorHarmony: s.pbnModeState.colorHarmony,
      colorHarmonyIntensity: s.pbnModeState.colorHarmonyIntensity,
      colorHarmonyCustomHue: s.pbnModeState.colorHarmonyCustomHue,
    };
  }, []);

  const buildProcessingSignature = useCallback(() => {
    const s = useAppStore.getState();
    const srcUrl = s.originalImageUrl || "";
    const params = buildProcessingParams();
    return JSON.stringify({
      srcUrl,
      mode: params.mode,
      numColors: params.numColors,
      detail: params.detail,
      correction: params.correction,
      importanceEmphasis: params.importanceEmphasis,
      backgroundSimplify: params.backgroundSimplify,
      colorHarmony: params.colorHarmony,
      colorHarmonyIntensity: params.colorHarmonyIntensity,
      colorHarmonyCustomHue: params.colorHarmonyCustomHue,
      protectVersion: useAppStore.getState().protectVersion,
    });
  }, [buildProcessingParams]);

  const buildProcessingCacheKey = useCallback(() => {
    const s = useAppStore.getState();
    const srcUrl = s.originalImageUrl || "no-image";
    const params = buildProcessingParams();
    return JSON.stringify({
      srcUrl,
      mode: params.mode,
      numColors: params.numColors,
      detail: params.detail,
      correction: params.correction,
      importanceEmphasis: params.importanceEmphasis,
      backgroundSimplify: params.backgroundSimplify,
      colorHarmony: params.colorHarmony,
      colorHarmonyIntensity: params.colorHarmonyIntensity,
      colorHarmonyCustomHue: params.colorHarmonyCustomHue,
      protectVersion: useAppStore.getState().protectVersion,
    });
  }, [buildProcessingParams]);

  const startProcessing = useCallback(async () => {
    if (processingRef.current) return;

    const s = useAppStore.getState();
    const srcUrl = s.originalImageUrl;
    if (!srcUrl) return;

    const currentMode = s.studioMode;
    const signature = buildProcessingSignature();
    
    if (signature === lastSignaturesRef.current[currentMode] && s.result) {
      return;
    }

    const cacheKey = buildProcessingCacheKey();
    if (resultCache.current.has(cacheKey)) {
      const cachedResult = resultCache.current.get(cacheKey)!;
      lastSignaturesRef.current[currentMode] = signature;
      update({
        result: cachedResult,
        isProcessing: false,
        progress: 100,
        statusMsg: `Готово (из кэша) — ${cachedResult.validLabels.size} ${wordColors(cachedResult.validLabels.size)}`,
        activeColors: new Set(cachedResult.validLabels),
        abortController: null,
      });
      return;
    }

    const prev = useAppStore.getState().abortController;
    if (prev) prev.abort();

    const ac = new AbortController();
    processingRef.current = true;
    update({
      isProcessing: true,
      progress: 0,
      statusMsg: "Анализ изображения...",
      activeColors: new Set(),
      abortController: ac,
    });

    try {
      // Искусственная пауза для рендера UI (до того, как главный поток будет заблокирован)
      await new Promise(resolve => setTimeout(resolve, 15));

      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = srcUrl;

      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });

      const c = document.createElement("canvas");
      c.width = img.width;
      c.height = img.height;
      const ctx = c.getContext("2d")!;
      ctx.drawImage(img, 0, 0);

      let imgData = ctx.getImageData(0, 0, img.width, img.height);
      const params = buildProcessingParams();

      const cor = params.correction;
      if (cor.brightness !== 0 || cor.contrast !== 0 || cor.saturation !== 0 || cor.sharpness !== 0 ||
          (cor.shadows ?? 0) !== 0 || (cor.highlights ?? 0) !== 0 || (cor.structure ?? 0) !== 0) {
        // Карта значимости делает «структуру» пограничной (объект/фон).
        imgData = applyCorrection(imgData, cor, s.importanceMap);
      }
      
      if (params.colorHarmony !== "none" && s.imageProfile) {
        const hue = params.colorHarmonyCustomHue !== null ? params.colorHarmonyCustomHue : s.imageProfile.dominantHue;
        const intensity = params.colorHarmonyIntensity / 100;
        imgData = applyColorHarmony(imgData, params.colorHarmony, hue, intensity);
      }
      
      ctx.putImageData(imgData, 0, 0);

      // «Акцент на объекте»: заостряем карту значимости перед подачей в движок,
      // чтобы он концентрировал детали на главном и упрощал фон.
      const impForEngine = emphasizeImportance(s.importanceMap, params.importanceEmphasis ?? 1);

      const newResult = await processImage(
        imgData,
        params.numColors,
        params.detail,
        (msg, pct) => {
          if (!ac.signal.aborted) {
            update({ statusMsg: msg, progress: pct ?? 0 });
          }
        },
        ac.signal,
        impForEngine,
        s.protectMask,
        s.protectDetail,
        params.backgroundSimplify ?? 1
      );

      if (!ac.signal.aborted) {
        resultCache.current.set(cacheKey, newResult);
        lastSignaturesRef.current[currentMode] = signature;

        const actualColorsCount = newResult.validLabels.size;
        const isFirstGeneration = !s.result;

        const baseUpdate: Partial<any> = {
          result: newResult,
          isProcessing: false,
          progress: 100,
          statusMsg: `Готово — ${actualColorsCount} ${wordColors(actualColorsCount)}, ${newResult.contoursData.length} ${wordZones(newResult.contoursData.length)}`,
          activeColors: new Set(newResult.validLabels),
          abortController: null,
          recipeApproximations: null,
          recipeSplitMode: false,
          // Новый результат — в идеальных цветах. Если включён режим «под краски»,
          // адаптация применится отдельным эффектом (CalculatorPanel) после генерации.
          idealPalette: null,
          adaptedPalette: null,
          gamutDelta: null,
          gamutMarker: false,
        };

        if (isFirstGeneration) {
          baseUpdate.showContours = false;
          baseUpdate.showNumbers = false;
          // Note: fill is implicitly determined by activeColors, which we reset above
        }

        update(baseUpdate);

        if (isFirstGeneration) {
          setTimeout(() => {
            window.dispatchEvent(new CustomEvent('melura:force-reset-view'));
          }, 50);
        }

        try {
          const colorPreviewDataUrl = generateColorPreview(newResult);
          const originalImageStr = c.toDataURL("image/webp", 0.7);

          await useAppStore.getState().addToHistory({
            timestamp: Date.now(),
            studioMode: s.studioMode,
            numColors: params.numColors,
            detail: params.detail,
            result: newResult,
            colorPreviewDataUrl,
            originalImageStr,
          });
        } catch {}
      }
    } catch (e: unknown) {
      if ((e as Error).name !== "AbortError" && !ac.signal.aborted) {
        update({
          isProcessing: false,
          statusMsg: `Ошибка: ${(e as Error).message}`,
          abortController: null,
        });
      }
    } finally {
      processingRef.current = false;
    }
  }, [update, buildProcessingCacheKey, buildProcessingSignature, buildProcessingParams]);

  const cancelProcessing = useCallback(() => {
    const ac = useAppStore.getState().abortController;
    if (ac) {
      ac.abort();
      update({
        isProcessing: false,
        isExporting: false,
        abortController: null,
        statusMsg: "Отменено",
        progress: 0,
      });
      processingRef.current = false;
    }
  }, [update]);

  const loadImage = useCallback((file: File) => {
    const isHeic = file.name.toLowerCase().endsWith('.heic') || file.name.toLowerCase().endsWith('.heif');
    if (!ACCEPTED_TYPES.has(file.type) && !isHeic) {
      update({ statusMsg: "Неподдерживаемый формат." });
      return;
    }
    if (file.size > MAX_FILE_SIZE) {
      update({ statusMsg: "Файл слишком большой." });
      return;
    }
    update({ statusMsg: "Подготовка изображения…" });

    const prepareImage = async () => {
      try {
        let processableFile: File | Blob = file;
        
        if (file.name.toLowerCase().endsWith('.heic') || file.type === 'image/heic' || file.type === 'image/heif') {
          update({ statusMsg: "Конвертация HEIC..." });
          try {
            const converted = await heic2any({
              blob: file,
              toType: "image/jpeg",
              quality: 0.9
            });
            processableFile = Array.isArray(converted) ? converted[0] : converted;
          } catch (conversionError) {
            console.warn("HEIC conversion failed, attempting to load as normal image:", conversionError);
            processableFile = file;
          }
        }

        const bmp = await createImageBitmap(processableFile);
        const scale = Math.min(1, MAX_SIDE / Math.max(bmp.width, bmp.height));
        const w = Math.round(bmp.width * scale);
        const h = Math.round(bmp.height * scale);

        const c = document.createElement("canvas");
        c.width = w;
        c.height = h;
        const ctx = c.getContext("2d")!;
        ctx.fillStyle = "#ffffff";
        ctx.fillRect(0, 0, w, h);
        ctx.drawImage(bmp, 0, 0, w, h);
        bmp.close();

        const rawData = ctx.getImageData(0, 0, w, h);
        // «Авто-улучшение» теперь работает через обычную светокоррекцию: анализируем
        // фото и подбираем значения Яркость/Контраст/Насыщенность/Резкость. Их
        // применяет единый конвейер коррекции при генерации (без «запекания» и без
        // конфликтов вроде двойной резкости). Значения кладём в store ниже.
        const st = useAppStore.getState();
        const useAuto = st.autoEnhance !== false;
        // autoCorr считаем ниже — ПОСЛЕ построения карты значимости, чтобы анализ
        // был «зрячим» (учитывал объект/фон).
        const imageData = rawData;
        const profile = profileImageQuick(imageData.data, w, h);

        update({ statusMsg: "Анализ ИИ..." });
        let aiResult = null;
        try {
          aiResult = await aiEngine.processImage(imageData);
        } catch(e) {
          console.warn("AI processing failed:", e);
        }

        // Универсальное выделение главного объекта (животные/предметы/цветы/…).
        // Отказоустойчиво: при недоступности модели fg = null и всё как раньше.
        update({ statusMsg: "Поиск главного объекта..." });
        let fgResult = null;
        try {
          fgResult = await salientObjectEngine.process(imageData);
        } catch (e) {
          console.warn("Salient-object processing failed:", e);
        }

        // Активное «оживление» лиц (тёплая кожа + моделировка) ДО квантизации,
        // ДО сохранения blob — чтобы пиксели, которые реально квантизуются, были живыми.
        enhanceFaces({
          imageData,
          segmentationMask: aiResult?.segmentationMask || null,
          segmentationWidth: aiResult?.segmentationWidth || 0,
          segmentationHeight: aiResult?.segmentationHeight || 0,
        });
        ctx.putImageData(imageData, 0, 0);

        c.toBlob((blob) => {
          if (!blob) throw new Error("Не удалось конвертировать изображение");
          const url = URL.createObjectURL(blob);

          const s = useAppStore.getState();
          if (s.originalImageUrl && s.originalImageUrl.startsWith("blob:")) {
            URL.revokeObjectURL(s.originalImageUrl);
          }
          if (s.correctedImageUrl && s.correctedImageUrl.startsWith("blob:")) {
            URL.revokeObjectURL(s.correctedImageUrl);
          }

          resultCache.current.clear();
          lastSignaturesRef.current = { painting: "", pbn: "" };

          // Build importance map from AI data + image
          update({ statusMsg: "Построение карты значимости..." });
          const importanceMap = buildImportanceMap({
            imageData,
            segmentationMask: aiResult?.segmentationMask || null,
            segmentationWidth: aiResult?.segmentationWidth || 0,
            segmentationHeight: aiResult?.segmentationHeight || 0,
            faceLandmarks: aiResult?.faceLandmarks || null,
            foregroundMask: fgResult?.mask || null,
            foregroundWidth: fgResult?.maskW || 0,
            foregroundHeight: fgResult?.maskH || 0,
          });

          // Pre-compute importance stats WITH REAL PIXELS (done once, cached in store)
          const importanceAnalysis = analyzeImportanceDistribution(importanceMap, imageData);

          update({
            imageFile: file,
            originalImageUrl: url,
            imageDimensions: { w, h },
            imageProfile: profile,
            importanceMap,
            importanceBaseMap: importanceMap.slice(), // базовая карта ИИ для сброса ручных правок
            importanceAnalysis,
            // Новое фото — сбрасываем защитную маску, но запоминаем её разрешение
            // (совпадает с картой значимости) для UI-инструментов выделения.
            protectMask: null,
            protectMaskW: w,
            protectMaskH: h,
            aiMask: aiResult?.segmentationMask || null,
            aiMaskWidth: aiResult?.segmentationWidth || 0,
            aiMaskHeight: aiResult?.segmentationHeight || 0,
            faceLandmarks: aiResult?.faceLandmarks || null,
            correctedImageUrl: null,
            result: null,
            activeColors: new Set(),
            statusMsg: `Загружено: ${w}×${h}`,
            mobilePaletteExpanded: false,
            zoneGuideActive: false,
            showTemperatureMap: false,
            paintingSplitMode: false,
            selectedZoneId: null,
            zoneInfoVisible: false,
            flipHorizontal: false,
            viewTransform: { x: 0, y: 0, z: 1, splitPos: 0.5 },
          });

          // При включённом «авто-улучшении» задаём подобранную светокоррекцию.
          // Анализ «зрячий»: передаём карту значимости — учитываем объект и фон.
          // При выключенном — НЕ трогаем текущие значения: так, выключив авто,
          // пользователь видит на слайдерах уже подобранные параметры и может
          // доправить их вручную (а не получает обнулённые ползунки).
          if (useAuto) {
            const autoCorr = analyzeAutoCorrection(rawData, importanceMap);
            useAppStore.getState().update({ correction: autoCorr });
          }

          if (s.studioMode === "pbn" && profile) {
            // «Хороший результат сразу»: если на фото есть ЛИЦО (портрет) — стартуем
            // с реалистичных настроек (сложность 6 → детали ≥6, ~20–24 краски), чтобы
            // продаваемый результат получался без ползунков и автопоиска. Движок при
            // этом сам применит кожезависимую палитру и упрощение фона. Для остальных
            // фото — привычная «Стандартная» (5).
            const faces = aiResult?.faceLandmarks;
            const isPortrait = Array.isArray(faces) ? faces.length > 0 : !!faces;
            const complexity = isPortrait ? 6 : 5;
            const smart = calculateSmartParams(importanceAnalysis, profile, complexity);
            let detail = smart.detail, numColors = smart.numColors;
            if (isPortrait) {
              // Фиксируем РАЗУМНУЮ детализацию лица (6) — не задираем в 8–10 из-за
              // пёстрого фона, и не опускаем ниже порога реализма. Цвета 18–22.
              detail = 6;
              numColors = Math.max(18, Math.min(22, numColors));
            }
            update({ numColors, detail, complexity });
          } else {
            update({ complexity: 5 });
          }
        }, "image/webp", 0.9);
      } catch (err) {
        update({ statusMsg: `Ошибка: ${(err as Error).message}` });
      }
    };
    prepareImage();
  }, [update]);

  // «Авто-улучшение фото» применяется СРАЗУ: при переключении/правке ползунков
  // переанализируем текущее фото (а не только при следующей загрузке).
  useEffect(() => {
    if (!autoEnhanceMounted.current) { autoEnhanceMounted.current = true; return; }
    // Реагируем ТОЛЬКО на ВКЛючение авто-улучшения: тогда нужно пересчитать
    // светокоррекцию по текущему фото. При ВЫКЛючении настройки не меняются
    // (ползунки остаются на подобранных значениях), поэтому переобрабатывать
    // фото и пересобирать раскраску не нужно — лишней перегенерации не будет.
    if (!autoEnhanceEnabled) return;
    const f = useAppStore.getState().imageFile;
    if (f) loadImage(f);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoEnhanceEnabled]);

  useEffect(() => {
    if (!isOpen || !hasOriginal || isInteracting) return;

    const currentMode = useAppStore.getState().studioMode;
    const nextSignature = buildProcessingSignature();
    if (nextSignature === lastSignaturesRef.current[currentMode]) return;

    if (autoGenTimerRef.current) clearTimeout(autoGenTimerRef.current);

    const hasExistingResultForThisMode = !!useAppStore.getState().result;
    const delay = hasExistingResultForThisMode ? 700 : 120;

    autoGenTimerRef.current = setTimeout(() => {
      const latestSignature = buildProcessingSignature();
      if (latestSignature !== lastSignaturesRef.current[currentMode]) {
        startProcessing();
      }
    }, delay);

    return () => {
      if (autoGenTimerRef.current) clearTimeout(autoGenTimerRef.current);
    };
  }, [
    isOpen, hasOriginal, originalImageUrl, studioMode, correction, isInteracting,
    numColors, detail, paintingModeState.numColors, paintingModeState.detail,
    pbnModeState.numColors, pbnModeState.detail, colorHarmony,
    colorHarmonyIntensity, colorHarmonyCustomHue, protectVersion, importanceEmphasis, backgroundSimplify,
    buildProcessingSignature, startProcessing
  ]);

  useGeneratorHotkeys(isOpen, cancelProcessing, loadImage);

  return { loadImage, cancelProcessing };
}
