import { useEffect, useRef } from 'react';

let isProgrammaticBack = false;

export function programmaticBack() {
  isProgrammaticBack = true;
  window.history.back();
  // Флаг снимаем ТОЛЬКО здесь по таймеру, а не внутри обработчика popstate.
  // Иначе при нескольких открытых окнах (лист настроек → палитра → калибровка)
  // первый же слушатель сбрасывал флаг, и остальные слушатели того же события
  // ошибочно закрывали свои окна. Так один программный «назад» игнорируют все.
  setTimeout(() => { isProgrammaticBack = false; }, 80);
}

export function useBackButton(isOpen: boolean, close: () => void) {
  const closeRef = useRef(close);
  closeRef.current = close;

  useEffect(() => {
    if (!isOpen) return;

    let statePushed = false;

    // Защита от накопления истории браузера (что может вызвать утечку памяти в тестах)
    const timer = setTimeout(() => {
      window.history.pushState({ modalOpen: true }, '');
      statePushed = true;
    }, 100);

    const handlePopState = () => {
      // НЕ сбрасываем флаг здесь: один программный back должен быть проигнорирован
      // всеми смонтированными окнами. Сброс делает таймер в programmaticBack().
      if (isProgrammaticBack) return;
      closeRef.current();
    };

    window.addEventListener('popstate', handlePopState);

    return () => {
      clearTimeout(timer);
      window.removeEventListener('popstate', handlePopState);
      if (statePushed && window.history.state?.modalOpen) {
        programmaticBack();
      }
    };
  }, [isOpen]);
}
