// src/generator/hooks/useAutoPreset.ts
//
// Оркестрация «Автоподбора пресетов»: берёт текущее фото, уменьшает его,
// прогоняет умный поиск (search.ts) и кладёт лучшие варианты в стор. Применение
// выбранного варианта просто пишет numColors/detail/correction в стор — обычный
// конвейер сам перегенерирует картину в полном разрешении.
//
// Результаты СОХРАНЯЮТСЯ: после применения одного варианта список не стирается —
// панель можно открыть снова и выбрать другой БЕЗ повторного поиска (пока фото не
// изменилось). Кнопка «Искать заново» принудительно перезапускает поиск.

import { useCallback, useRef } from "react";
import { useAppStore } from "../store";
import { processImage } from "../utils/imageProcessing";
import { runAutoPresetSearch, type RunOne, type PresetCandidate } from "../utils/autoPreset/search";
import type { PresetCandidateUI, PresetSearchState } from "../store/types";

// Разрешение «мысленных» прогонов. 400px: лицо ~60–70px — метрика уже различает
// чёткое лицо от «мыла» (на 280px лицо ~40px, качество не читалось). Медленнее, но
// пользователь просил упор на качество, не на скорость.
const SEARCH_MAX_SIDE = 400;

function downscaleImportance(imp: Float32Array, w: number, h: number, sw: number, sh: number): Float32Array {
  const out = new Float32Array(sw * sh);
  for (let y = 0; y < sh; y++) {
    const sy = Math.min(h - 1, Math.floor((y * h) / sh));
    for (let x = 0; x < sw; x++) {
      const sx = Math.min(w - 1, Math.floor((x * w) / sw));
      out[y * sw + x] = imp[sy * w + sx];
    }
  }
  return out;
}

function previewToUrl(preview: ImageData): string {
  const c = document.createElement("canvas");
  c.width = preview.width; c.height = preview.height;
  c.getContext("2d")!.putImageData(preview, 0, 0);
  return c.toDataURL("image/webp", 0.85);
}

export function useAutoPreset() {
  const update = useAppStore((s) => s.update);
  const presetSearch = useAppStore((s) => s.presetSearch);
  const acRef = useRef<AbortController | null>(null);

  const setPS = useCallback((patch: Partial<PresetSearchState>) => {
    const cur = useAppStore.getState().presetSearch;
    update({ presetSearch: { ...cur, ...patch } });
  }, [update]);

  const start = useCallback(async () => {
    const s = useAppStore.getState();
    if (s.presetSearch.running) return;
    const srcUrl = s.originalImageUrl;
    const dims = s.imageDimensions;
    if (!srcUrl || !dims) {
      setPS({ running: false, open: true, candidates: null, error: "Сначала загрузите фото" });
      return;
    }

    // Останавливаем текущую генерацию, чтобы не конфликтовать за общий воркер.
    const prev = s.abortController;
    if (prev) { try { prev.abort(); } catch { /* ignore */ } }

    const ac = new AbortController();
    acRef.current = ac;
    setPS({ running: true, open: true, progress: 0, candidates: null, error: null, appliedId: null, sourceUrl: srcUrl });

    try {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = srcUrl;
      await new Promise((res, rej) => { img.onload = res; img.onerror = rej; });

      const scale = Math.min(1, SEARCH_MAX_SIDE / Math.max(img.width, img.height));
      const sw = Math.max(8, Math.round(img.width * scale));
      const sh = Math.max(8, Math.round(img.height * scale));
      const c = document.createElement("canvas");
      c.width = sw; c.height = sh;
      const ctx = c.getContext("2d", { willReadFrequently: true })!;
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.drawImage(img, 0, 0, sw, sh);
      const baseImage = ctx.getImageData(0, 0, sw, sh);

      const imp = s.importanceMap
        ? downscaleImportance(s.importanceMap, dims.w, dims.h, sw, sh)
        : null;

      const runOne: RunOne = (image, nc, dt, importance, bg) =>
        processImage(image, nc, dt, () => {}, ac.signal, importance, null, 30, bg);

      const candidates: PresetCandidate[] = await runAutoPresetSearch({
        baseImage,
        importance: imp,
        baseCorrection: s.correction,
        runOne,
        levers: s.presetLevers,
        baseColors: s.numColors,
        baseDetail: s.detail,
        signal: ac.signal,
        onProgress: (doneN, total) => {
          const pct = total > 0 ? Math.round((doneN / total) * 100) : 0;
          setPS({ running: true, open: true, progress: pct });
        },
      });

      if (ac.signal.aborted) return;

      const ui: PresetCandidateUI[] = candidates.map((cand, i) => ({
        id: i,
        numColors: cand.numColors,
        detail: cand.detail,
        correction: cand.correction,
        fidelity: cand.breakdown.fidelity,
        paintability: cand.breakdown.paintability,
        similarity: cand.breakdown.similarity,
        meanDeltaE: cand.breakdown.meanDeltaE,
        usedColors: cand.breakdown.usedColors,
        zones: cand.breakdown.zones,
        microzones: cand.breakdown.microzones,
        emphasis: cand.emphasis,
        backgroundSimplify: cand.backgroundSimplify,
        score: cand.score,
        previewUrl: previewToUrl(cand.preview),
      }));

      setPS({ running: false, open: true, progress: 100, candidates: ui, error: ui.length ? null : "Не удалось подобрать варианты", sourceUrl: srcUrl });
    } catch (e) {
      if ((e as Error).name === "AbortError") {
        setPS({ running: false });
      } else {
        setPS({ running: false, open: true, candidates: null, error: `Ошибка: ${(e as Error).message}` });
      }
    } finally {
      acRef.current = null;
    }
  }, [setPS]);

  // Кнопка в панели: показать кэш (если найден для этого же фото) или искать заново.
  const openPanel = useCallback(() => {
    const s = useAppStore.getState();
    const ps = s.presetSearch;
    if (ps.running) { setPS({ open: true }); return; }
    if (ps.candidates && ps.candidates.length > 0 && ps.sourceUrl === s.originalImageUrl) {
      setPS({ open: true }); // показываем сохранённые результаты — без повторного поиска
    } else {
      start();
    }
  }, [setPS, start]);

  const cancel = useCallback(() => {
    if (acRef.current) { try { acRef.current.abort(); } catch { /* ignore */ } }
    setPS({ running: false, open: false });
  }, [setPS]);

  // Закрыть панель, НО сохранить найденные варианты (чтобы вернуться без поиска).
  const close = useCallback(() => setPS({ open: false }), [setPS]);

  const apply = useCallback((cand: PresetCandidateUI) => {
    const c = cand.correction;
    const correction = {
      brightness: c.brightness,
      contrast: c.contrast,
      saturation: c.saturation,
      sharpness: c.sharpness,
      shadows: c.shadows ?? 0,
      highlights: c.highlights ?? 0,
      structure: c.structure ?? 0,
    };
    const cur = useAppStore.getState().presetSearch;
    // Пишем ползунки — обычный авто-конвейер перегенерирует в полном разрешении.
    // importanceEmphasis делает применённый результат идентичным превью (движок
    // получит ту же заострённую карту значимости). Список СОХРАНЯЕМ, помечаем применённый.
    update({
      numColors: cand.numColors,
      detail: cand.detail,
      correction,
      importanceEmphasis: cand.emphasis,
      backgroundSimplify: cand.backgroundSimplify,
      presetSearch: { ...cur, open: false, appliedId: cand.id },
    });
  }, [update]);

  return { presetSearch, start, openPanel, cancel, close, apply };
}
