// src/generator/components/ToolBar.tsx
import { useRef, useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { useAppStore } from "../store";
import { cn } from "../../utils/cn";

interface Props {
  onLoadImage: (file: File) => void;
  onCancel: () => void;
  onExport: () => void;
  hasResult: boolean;
}

export function Toolbar({ onLoadImage, onCancel, onExport, hasResult }: Props) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [editMenuOpen, setEditMenuOpen] = useState(false);
  const [editMenuPos, setEditMenuPos] = useState<{ left: number; top: number } | null>(null);
  const editMenuRef = useRef<HTMLDivElement>(null);   // обёртка кнопки-триггера
  const editMenuPopRef = useRef<HTMLDivElement>(null); // сам поповер (в портале)
  const isDark = useAppStore((s) => s.isDark);
  const isProcessing = useAppStore((s) => s.isProcessing);
  const hasOrig = useAppStore((s) => !!s.originalImageUrl);
  const hasProtect = useAppStore((s) => !!s.protectMask);
  const historyCount = useAppStore((s) => s.generationHistory.length);
  const studioMode = useAppStore((s) => s.studioMode);
  const update = useAppStore((s) => s.update);

  // Открыть/закрыть меню «Правка»; при открытии считаем позицию для портала.
  const toggleEditMenu = () => {
    if (!editMenuOpen && editMenuRef.current) {
      const r = editMenuRef.current.getBoundingClientRect();
      // Не даём поповеру уехать за правый край экрана (на мобиле w-72 не влезает,
      // и текст обрезался). Прижимаем к правому краю с отступом 8px.
      const width = 288; // = w-72
      const maxLeft = window.innerWidth - width - 8;
      const left = Math.max(8, Math.min(r.left, maxLeft));
      setEditMenuPos({ left, top: r.bottom + 8 });
    }
    setEditMenuOpen((v) => !v);
  };

  // Закрытие меню по клику вне кнопки И вне поповера; и по прокрутке/ресайзу.
  useEffect(() => {
    if (!editMenuOpen) return;
    const onDoc = (e: MouseEvent) => {
      const t = e.target as Node;
      if (editMenuRef.current?.contains(t) || editMenuPopRef.current?.contains(t)) return;
      setEditMenuOpen(false);
    };
    const onScroll = () => setEditMenuOpen(false);
    document.addEventListener("mousedown", onDoc);
    window.addEventListener("resize", onScroll);
    return () => { document.removeEventListener("mousedown", onDoc); window.removeEventListener("resize", onScroll); };
  }, [editMenuOpen]);

  const drop = (e: React.DragEvent) => {
    e.preventDefault();
    const f = e.dataTransfer.files[0];
    if (f && (f.type.startsWith("image/") || f.name.toLowerCase().endsWith(".heic") || f.name.toLowerCase().endsWith(".heif"))) onLoadImage(f);
  };

  const btnBase =
    "inline-flex items-center justify-center flex-shrink-0 gap-2 rounded-xl text-[13px] font-bold transition-all duration-200 active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed whitespace-nowrap h-11 px-4";

  const btnNeutral = cn(
    btnBase,
    "border-2 transition-all duration-300 shadow-sm",
    isDark
      ? "bg-slate-800/40 border-slate-700/50 text-slate-300 hover:bg-slate-700 hover:border-slate-600 hover:text-white"
      : "bg-slate-50/50 border-slate-100 text-slate-600 hover:bg-slate-100 hover:border-slate-200 hover:text-indigo-600"
  );

  const iconBtn = cn(
    "inline-flex items-center justify-center flex-shrink-0 w-11 h-11 rounded-xl transition-all duration-300 border-2 active:scale-90 shadow-sm",
    isDark
      ? "bg-slate-800/40 border-slate-700/50 text-slate-400 hover:bg-slate-700 hover:border-slate-600 hover:text-white"
      : "bg-slate-50/50 border-slate-100 text-slate-500 hover:bg-slate-100 hover:border-slate-200 hover:text-indigo-600"
  );

  return (
    <header
      className={cn(
        "flex-shrink-0 flex items-center justify-between gap-1 sm:gap-3 px-3 sm:px-5 h-14 sm:h-16 relative z-30 overflow-x-auto scrollbar-none shadow-premium border-b",
        isDark ? "bg-slate-900/80 backdrop-blur-xl border-slate-800" : "bg-white/70 backdrop-blur-xl border-slate-100"
      )}
      onDrop={drop}
      onDragOver={(e) => e.preventDefault()}
      role="toolbar"
      aria-label="Панель инструментов"
    >
      <input
        ref={fileRef}
        type="file"
        accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.heic,.heif"
        className="hidden"
        aria-hidden="true"
        onChange={(e) => {
          const f = e.target.files?.[0];
          if (f) onLoadImage(f);
          e.target.value = "";
        }}
      />

      {/* ЛЕВАЯ ГРУППА */}
      <div className="flex items-center gap-1.5 sm:gap-3">
        <button
          className={cn(btnNeutral, "px-3 sm:px-5 group")}
          onClick={() => fileRef.current?.click()}
          aria-label="Загрузить изображение"
          title="Загрузить с устройства"
        >
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" aria-hidden="true" className="flex-shrink-0 text-indigo-500 transition-transform">
            <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M17 8l-5-5-5 5M12 3v12" />
          </svg>
          <span className="hidden sm:inline">Файл</span>
        </button>

        <button
          className={cn(btnNeutral, "px-3 sm:px-4")}
          onClick={() => update({ urlModalOpen: true })}
          aria-label="Загрузить по URL"
          title="Загрузить по ссылке"
        >
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" aria-hidden="true" className="flex-shrink-0 text-slate-400 dark:text-slate-500">
            <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" />
            <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" />
          </svg>
          <span className="hidden md:inline">URL</span>
        </button>

        {hasOrig && (
          <button
            className={cn(btnNeutral, "px-3 sm:px-4")}
            onClick={() => update({ cropModalOpen: true })}
            aria-label="Обрезать изображение"
            title="Кадрировать"
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className="flex-shrink-0 text-slate-400 dark:text-slate-500">
              <path d="M6.13 1L6 16a2 2 0 0 0 2 2h15" />
              <path d="M1 6.13L16 6a2 2 0 0 1 2 2v15" />
            </svg>
            <span className="hidden md:inline">Обрезка</span>
          </button>
        )}

        {hasOrig && (
          <div className="relative" ref={editMenuRef}>
            <button
              className={cn(btnNeutral, "px-3 sm:px-4 relative", (hasProtect) && "text-indigo-600 dark:text-indigo-400 border-indigo-300 dark:border-indigo-500/50")}
              onClick={toggleEditMenu}
              aria-haspopup="menu"
              aria-expanded={editMenuOpen}
              aria-label="Правка зон"
              title="Ручные инструменты: защита зон и редактор раскраски"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className={cn("flex-shrink-0", hasProtect ? "text-indigo-500" : "text-slate-400 dark:text-slate-500")}>
                <path d="M12 20h9" />
                <path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4z" />
              </svg>
              <span className="hidden md:inline">Правка</span>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={cn("flex-shrink-0 transition-transform", editMenuOpen && "rotate-180")}><path d="M6 9l6 6 6-6" /></svg>
              {hasProtect && <span className="absolute top-1.5 right-1.5 w-2 h-2 rounded-full bg-indigo-500 shadow-[0_0_6px_rgba(99,102,241,0.8)]" />}
            </button>

            {editMenuOpen && editMenuPos && createPortal(
              <div ref={editMenuPopRef} role="menu" style={{ position: "fixed", left: editMenuPos.left, top: editMenuPos.top, maxWidth: "calc(100vw - 16px)" }} className={cn(
                "z-[100] w-72 p-2 rounded-2xl shadow-2xl border-2 backdrop-blur-xl animate-fade-in-up",
                isDark ? "bg-slate-900/95 border-slate-700" : "bg-white/95 border-slate-200"
              )}>
                <button
                  onClick={() => { update({ protectToolActive: true, editModeActive: false }); setEditMenuOpen(false); }}
                  className={cn("w-full flex items-start gap-3 p-2.5 rounded-xl text-left transition-colors", isDark ? "hover:bg-white/10" : "hover:bg-slate-100")}
                >
                  <span className="mt-0.5 text-indigo-500 shrink-0"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" /></svg></span>
                  <span className="min-w-0">
                    <span className={cn("block text-sm font-bold flex items-center gap-2", isDark ? "text-white" : "text-slate-800")}>Карта значимости</span>
                    <span className={cn("block text-[11px] leading-snug mt-0.5", isDark ? "text-slate-400" : "text-slate-500")}>Показать приоритеты ИИ (зелёный — важно, красный — фон) и вручную повысить/понизить значимость нужных зон. Применяется при следующей генерации.</span>
                  </span>
                </button>
                {(() => { const canEdit = hasResult && studioMode === "pbn"; return (
                <button
                  disabled={!canEdit}
                  onClick={() => { update({ editModeActive: true, protectToolActive: false }); setEditMenuOpen(false); }}
                  className={cn("w-full flex items-start gap-3 p-2.5 rounded-xl text-left transition-colors", !canEdit ? "opacity-40 cursor-default" : isDark ? "hover:bg-white/10" : "hover:bg-slate-100")}
                >
                  <span className="mt-0.5 text-indigo-500 shrink-0"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 20h9" /><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4z" /></svg></span>
                  <span className="min-w-0">
                    <span className={cn("block text-sm font-bold", isDark ? "text-white" : "text-slate-800")}>Редактор раскраски</span>
                    <span className={cn("block text-[11px] leading-snug mt-0.5", isDark ? "text-slate-400" : "text-slate-500")}>{canEdit ? "Точная ручная правка готовой раскраски: выделять зоны, перекрашивать, сливать, двигать, лепить контуры." : "Доступно в режиме «по номерам» после генерации."}</span>
                  </span>
                </button>
                ); })()}
              </div>,
              document.body
            )}
          </div>
        )}
      </div>

      {/* ЦЕНТР (скрыт) */}
      <div className="flex-1 min-w-[5px]" />

      {/* ПРАВАЯ ГРУППА */}
      <div className="flex items-center gap-1.5 sm:gap-2.5 justify-end shrink-0 after:content-[''] after:w-1 after:shrink-0 sm:after:hidden">
        {/* Настройки (мобайл): на десктопе настройки в боковой панели, здесь — лист снизу */}
        <button
          className={cn(iconBtn, "md:hidden")}
          onClick={() => update({ mobileSettingsOpen: true })}
          aria-label="Настройки"
          title="Настройки"
        >
          <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className="flex-shrink-0">
            <circle cx="12" cy="12" r="3" />
            <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z" />
          </svg>
        </button>
        {isProcessing && (
          <button
            className={cn(btnBase, "bg-red-500 text-white hover:bg-red-600 shadow-lg shadow-red-500/25 px-4 sm:px-6 animate-pulse border-none")}
            onClick={onCancel}
            aria-label="Остановить генерацию"
            title="Остановить расчет"
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" aria-hidden="true" className="flex-shrink-0">
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
            <span className="hidden sm:inline">Отмена</span>
          </button>
        )}

        {historyCount > 0 && !isProcessing && (
          <button
            className={iconBtn}
            onClick={() => update({ historyModalOpen: true })}
            aria-label="История генераций"
            title="История генераций"
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className="flex-shrink-0">
              <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
              <path d="M3 3v5h5" />
              <path d="M12 7v5l4 2" />
            </svg>
          </button>
        )}

        {hasResult && !isProcessing && (
          <button
            className={cn(btnBase, "bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg shadow-indigo-600/30 border-none px-4 sm:px-6 group")}
            onClick={onExport}
            aria-label="Экспорт"
            title="Сохранить результат"
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className="flex-shrink-0 group-hover:translate-y-0.5 transition-transform">
              <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3" />
            </svg>
            <span className="hidden sm:inline">Экспорт</span>
          </button>
        )}


      </div>
    </header>
  );
}