// src/PWAProvider.tsx
// Регистрирует Service Worker в режиме автообновления и раз в час проверяет
// сервер на новую версию. Обновление применяется само (см. setupAutoReloadOnUpdate
// в main.tsx) — без окон и ручной чистки кэша. Установку приложения предлагает
// сам браузер (Chrome: ⋮ → «Установить приложение…»).
import { ReactNode } from 'react';
import { useRegisterSW } from 'virtual:pwa-register/react';
import { APP_VERSION } from './version';

export default function PWAProvider({ children }: { children: ReactNode }) {
  useRegisterSW({
    onRegisteredSW(_swUrl: string, r: ServiceWorkerRegistration | undefined) {
      if (r) setInterval(() => r.update().catch(() => {}), 60 * 60 * 1000);
    },
    onRegisterError(e: unknown) {
      console.error('Ошибка регистрации Service Worker:', e);
    },
  });

  return <>{children}</>;
}

export { APP_VERSION };
