// src/generator/utils/zip.ts
//
// Минимальный ZIP-упаковщик без внешних зависимостей.
// Зачем свой, а не jszip/fflate: нам нужно упаковать 5–10 текстовых файлов
// (SVG/HTML/README) — это ~120 строк кода против +40 КБ в бандл PWA.
//
// Сжатие берём у платформы: CompressionStream("deflate-raw") — ровно тот алгоритм,
// который ждёт ZIP-метод 8 (deflate). Поддержка: Chrome 80+, Safari 16.4+, Firefox 113+.
// Там, где его нет, честно кладём файлы без сжатия (метод 0) — архив всё равно
// корректный и открывается любым распаковщиком, просто крупнее.

export interface ZipEntry {
  /** Имя внутри архива. Разделитель — только "/", как требует спецификация ZIP. */
  name: string;
  /** Содержимое: строка (будет UTF-8) или готовые байты. */
  data: string | Uint8Array;
}

// CRC-32 (полином 0xEDB88320) — обязательное поле заголовка ZIP.
// Таблицу строим один раз лениво: 256 чисел, считается за микросекунды.
let crcTable: Uint32Array | null = null;
function getCrcTable(): Uint32Array {
  if (crcTable) return crcTable;
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  crcTable = t;
  return t;
}

function crc32(buf: Uint8Array): number {
  const t = getCrcTable();
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = t[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

async function deflateRaw(data: Uint8Array): Promise<Uint8Array | null> {
  const CS = (globalThis as any).CompressionStream;
  if (typeof CS !== "function") return null;
  try {
    const stream = new Blob([data as BlobPart]).stream().pipeThrough(new CS("deflate-raw"));
    const buf = await new Response(stream).arrayBuffer();
    const out = new Uint8Array(buf);
    // Крайне редкий, но возможный случай: на «шумных» данных deflate раздувает
    // поток. Тогда выгоднее положить как есть.
    return out.length < data.length ? out : null;
  } catch {
    return null;
  }
}

/**
 * Собирает ZIP-архив в памяти.
 * Формат: локальные заголовки → центральный каталог → EOCD (без ZIP64, файлы у нас
 * заведомо меньше 4 ГБ). Даты ставим фиксированные — иначе один и тот же экспорт
 * даёт разные байты, а нам это не нужно.
 */
export async function createZip(entries: ZipEntry[]): Promise<Blob> {
  const enc = new TextEncoder();
  const parts: BlobPart[] = [];
  const central: Uint8Array[] = [];
  let offset = 0;

  // 2026-01-01 00:00:00 в формате MS-DOS (год отсчитывается от 1980).
  const DOS_TIME = 0;
  const DOS_DATE = ((2026 - 1980) << 9) | (1 << 5) | 1;

  const u16 = (v: number) => [v & 0xff, (v >>> 8) & 0xff];
  const u32 = (v: number) => [v & 0xff, (v >>> 8) & 0xff, (v >>> 16) & 0xff, (v >>> 24) & 0xff];

  for (const entry of entries) {
    const raw = typeof entry.data === "string" ? enc.encode(entry.data) : entry.data;
    const nameBytes = enc.encode(entry.name);
    const crc = crc32(raw);

    const packed = await deflateRaw(raw);
    const method = packed ? 8 : 0;
    const body = packed || raw;

    // Бит 11 общего флага = имена файлов в UTF-8 (иначе кириллица в именах
    // превращается в кракозябры в проводнике Windows).
    const flags = 0x0800;

    const local = new Uint8Array([
      ...u32(0x04034b50),
      ...u16(20), ...u16(flags), ...u16(method),
      ...u16(DOS_TIME), ...u16(DOS_DATE),
      ...u32(crc), ...u32(body.length), ...u32(raw.length),
      ...u16(nameBytes.length), ...u16(0),
      ...nameBytes,
    ]);

    parts.push(local as BlobPart, body as BlobPart);

    central.push(new Uint8Array([
      ...u32(0x02014b50),
      ...u16(20), ...u16(20), ...u16(flags), ...u16(method),
      ...u16(DOS_TIME), ...u16(DOS_DATE),
      ...u32(crc), ...u32(body.length), ...u32(raw.length),
      ...u16(nameBytes.length), ...u16(0), ...u16(0),
      ...u16(0), ...u16(0), ...u32(0),
      ...u32(offset),
      ...nameBytes,
    ]));

    offset += local.length + body.length;
  }

  const centralSize = central.reduce((sum, c) => sum + c.length, 0);
  const eocd = new Uint8Array([
    ...u32(0x06054b50),
    ...u16(0), ...u16(0),
    ...u16(central.length), ...u16(central.length),
    ...u32(centralSize), ...u32(offset),
    ...u16(0),
  ]);

  return new Blob([...parts, ...(central as BlobPart[]), eocd as BlobPart], { type: "application/zip" });
}
