import { useState, useEffect } from 'react';
import GeneratorModal from './generator/GeneratorModal';
import { InstallButton } from './components/InstallButton';
import { useAppStore } from './store/appStore';
import { useLabStore } from './store/labStore';
import { cn } from './utils/cn';
import { useEscapeKey } from './hooks/useEscapeKey';
import { LabDialog } from './components/dialogs/LabDialog';
import { ServiceMenuDialog } from './components/dialogs/ServiceMenuDialog';
import { HelpDialog } from './components/dialogs/HelpDialog';

export function App() {
  const store = useAppStore();
  const { isDark } = store;

  const [currentScreen, setCurrentScreen] = useState<'generator' | 'calculator' | 'lab'>('generator');
  const [serviceMenuOpen, setServiceMenuOpen] = useState(false);
  const [helpOpen, setHelpOpen] = useState(false);

  useEscapeKey(() => {
    if (currentScreen === 'lab') {
      const labState = useLabStore.getState();
      const activeWell = labState.wells[labState.activeWellIndex];
      const hasWellColor = activeWell && activeWell.totalParts > 0;
      const hasChallengeColor = labState.currentChallenge && labState.challengeWell.totalParts > 0;
      
      if (hasWellColor || hasChallengeColor) {
        if (hasWellColor) labState.clearActiveWell();
        if (hasChallengeColor) labState.clearChallengeWell();
      } else {
        setCurrentScreen('generator');
      }
    }
  }, currentScreen === 'lab');

  useEffect(() => {
    const root = document.documentElement;
    if (isDark) root.classList.add('dark');
    else root.classList.remove('dark');
  }, [isDark]);

  // Навигационный интент от глубоких компонентов (например, «Тренировать цвет
  // в Академии» из режима «Живопись»). После перехода интент сбрасываем.
  const screenRequest = store.screenRequest;
  useEffect(() => {
    if (screenRequest) {
      setCurrentScreen(screenRequest);
      store.setScreenRequest(null);
    }
  }, [screenRequest]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div className="h-[100dvh] flex flex-col bg-slate-50 dark:bg-slate-950 transition-colors duration-300 font-sans">
      <InstallButton />

      <header className="shrink-0 flex items-center justify-between px-4 sm:px-6 py-2 sm:py-3 bg-white/70 dark:bg-slate-900/70 backdrop-blur-xl z-50 shadow-premium border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg overflow-hidden flex items-center justify-center shadow-lg shrink-0">
            <img src="/Melura/favicon.png" alt="Logo" className="w-full h-full object-cover" />
          </div>
          <h1 className="text-lg font-extrabold text-slate-900 dark:text-white tracking-tight">Melura</h1>
        </div>

        <nav className="hidden sm:flex items-center gap-1">
          <TopTab active={currentScreen === 'generator'} onClick={() => setCurrentScreen('generator')} icon={<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 19l7-7 3 3-7 7-3-3z"/><path d="M18 13l-1.5-7.5L2 2l3.5 14.5L13 18l5-5z"/><path d="M2 2l7.586 7.586"/><circle cx="11" cy="11" r="2"/></svg>} label="Студия" />
          <TopTab active={currentScreen === 'lab'} onClick={() => setCurrentScreen('lab')} icon={<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M22 10v6M2 10l10-5 10 5-10 5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/></svg>} label="Академия" />
        </nav>

        <div className="flex items-center gap-2">
          <button onClick={() => setHelpOpen(true)} aria-label="Справка" className="w-11 h-11 rounded-xl flex items-center justify-center transition-colors text-slate-600 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 active:scale-90">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
          </button>
          <button onClick={() => setServiceMenuOpen(true)} aria-label="Сервисное меню" className="w-11 h-11 rounded-xl flex items-center justify-center transition-colors text-slate-600 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 active:scale-90">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/></svg>
          </button>
          <button onClick={store.toggleTheme} aria-label={isDark ? "Включить светлую тему" : "Включить тёмную тему"} className="w-11 h-11 rounded-xl flex items-center justify-center transition-colors text-slate-600 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 active:scale-90">
            {isDark ? <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><circle cx="12" cy="12" r="5" /><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg> : <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" /></svg>}
          </button>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative min-w-0 overflow-hidden bg-transparent">
        <GeneratorModal isOpen={currentScreen === 'generator'} onClose={() => {}} isDark={isDark} />
        {currentScreen === 'lab' && <LabDialog />}
        {serviceMenuOpen && <ServiceMenuDialog onClose={() => setServiceMenuOpen(false)} />}
        {helpOpen && <HelpDialog onClose={() => setHelpOpen(false)} />}
      </main>

      <div className="sm:hidden shrink-0 z-50 bg-white/90 dark:bg-slate-900/90 backdrop-blur-2xl border-t border-slate-100 dark:border-slate-800 pb-safe">
        <div className="flex justify-around items-stretch h-[68px] px-4 gap-2">
          <BottomTab active={currentScreen === 'generator'} onClick={() => setCurrentScreen('generator')} icon={<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 19l7-7 3 3-7 7-3-3z"/><path d="M18 13l-1.5-7.5L2 2l3.5 14.5L13 18l5-5z"/><path d="M2 2l7.586 7.586"/><circle cx="11" cy="11" r="2"/></svg>} label="Студия" />
          <BottomTab active={currentScreen === 'lab'} onClick={() => setCurrentScreen('lab')} icon={<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M22 10v6M2 10l10-5 10 5-10 5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/></svg>} label="Академия" />
        </div>
      </div>
    </div>
  );
}

function TopTab({ active, onClick, icon, label }: { active: boolean; onClick: () => void; icon: React.ReactNode; label: string }) {
  return (
    <button onClick={onClick} className={cn("flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all", active ? "bg-indigo-600 text-white shadow-lg shadow-indigo-500/20" : "text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200")}>
      <span className="shrink-0">{icon}</span>
      <span>{label}</span>
    </button>
  );
}

function BottomTab({ active, onClick, icon, label }: { active: boolean; onClick: () => void; icon: React.ReactNode; label: string }) {
  return (
    <button onClick={onClick} className={cn(
      "flex flex-col items-center justify-center gap-1 flex-1 min-h-[48px] rounded-2xl transition-all duration-200 active:scale-95",
      active
        ? "text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-500/10"
        : "text-slate-400 dark:text-slate-500"
    )}>
      <span className={cn("shrink-0 transition-transform duration-200", active && "scale-110")}>{icon}</span>
      <span className={cn("text-[10px] font-black uppercase tracking-tight transition-colors", active ? "text-indigo-600 dark:text-indigo-400" : "text-slate-400 dark:text-slate-500")}>{label}</span>
    </button>
  );
}
