// Чёткая отрисовка схемы «по номерам» в ОДИН компактный canvas размером с
// контейнер (в реальном разрешении экрана). Рисуем только видимую область под
// текущий пан/зум — поэтому вектор остаётся чётким на любом увеличении, но памяти
// тратится немного (один экранный canvas), в отличие от гигантского SVG-DOM,
// который под нехваткой памяти браузер деградирует в «мыло».
import type { ProcessingResult } from "./imageProcessing/types";

// Замкнутый путь ПО ВЕРШИНАМ полигона зоны (cd.points — уже гладкий вектор, не
// «лесенка»). ОДНА и та же геометрия для заливки, контура и выделения, поэтому:
//  • соседние зоны делят ОДНИ И ТЕ ЖЕ точки границы и стыкуются без щелей;
//  • контур лежит ровно по краю заливки (нет щелей заливка/контур);
//  • выделение точно повторяет форму зоны.
// (Независимое сглаживание каждой зоны раздвигало общие границы — отсюда были щели.)
export function zoneClosedPath(pts: [number, number][]): Path2D {
  const path = new Path2D();
  const n = pts.length;
  if (!n) return path;
  path.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < n; i++) path.lineTo(pts[i][0], pts[i][1]);
  path.closePath();
  return path;
}

export interface SchemeViewportOpts {
  activeColors: Set<number>;
  showNumbers: boolean;
  showContours: boolean;
  numberWeight: number;
}

export function renderSchemeViewport(
  canvas: HTMLCanvasElement,
  cw: number, ch: number,
  res: ProcessingResult,
  opts: SchemeViewportOpts,
  x: number, y: number, z: number, sp: number,
): void {
  const dpr = Math.min(2, (typeof window !== "undefined" ? window.devicePixelRatio : 1) || 1);
  const W = Math.max(1, Math.round(cw * dpr));
  const H = Math.max(1, Math.round(ch * dpr));
  if (canvas.width !== W) canvas.width = W;
  if (canvas.height !== H) canvas.height = H;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, W, H);
  // Пиксель изображения (ix,iy) -> экран (x + ix*z, y + iy*z) -> девайс *dpr.
  const s = z * dpr;
  ctx.setTransform(s, 0, 0, s, x * dpr, y * dpr);

  const { imgW, imgH, colorPalette, contoursData } = res;
  const { activeColors, showNumbers, showContours, numberWeight } = opts;

  // Клип к стороне «после» (ПРАВАЯ часть от sp) — как у splitClip2 со схемой.
  // На стороне «до» (слева) проступает исходное фото из слоя выше — «до/после» цел.
  ctx.save();
  ctx.beginPath();
  ctx.rect(sp * imgW, 0, imgW - sp * imgW, imgH);
  ctx.clip();

  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, imgW, imgH);

  const colored = activeColors.size > 0;
  // От больших к меньшим: вложенные зоны рисуются поверх («пробивают» внешний цвет).
  const sorted = [...contoursData].sort((a, b) => b.area - a.area);

  if (colored) {
    // Заливку слегка обводим ТЕМ ЖЕ цветом (~1px экрана): соседние зоны чуть
    // перекрываются на общей границе — гарантированно без белых швов между ними.
    const seam = 1.0 / z;
    ctx.lineJoin = "round";
    for (const cd of sorted) {
      const pts = cd.points;
      if (!pts || pts.length < 2) continue;
      const path = zoneClosedPath(pts); // ТА ЖЕ геометрия, что у контура ниже
      const col = activeColors.has(cd.labelId) ? colorPalette[cd.labelId] : null;
      const style = col ? `rgb(${col[0]},${col[1]},${col[2]})` : "#ffffff";
      ctx.fillStyle = style;
      ctx.fill(path);
      ctx.strokeStyle = style;
      ctx.lineWidth = seam;
      ctx.stroke(path);
    }
  }

  if (showContours) {
    // Контур рисуем по ТОЙ ЖЕ сглаженной геометрии зоны (cd.points), что и заливка,
    // — поэтому контур лежит ровно по краю заливки, без белых щелей. Общие рёбра
    // рисуются дважды (обеими зонами), но линия одна и та же — визуально нормально.
    ctx.strokeStyle = "rgba(40,40,40,0.45)";
    ctx.lineWidth = 1.2 / z; // ~постоянная толщина ~1.2px на экране
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    for (const cd of sorted) {
      const pts = cd.points;
      if (!pts || pts.length < 2) continue;
      ctx.stroke(zoneClosedPath(pts));
    }
  }

  if (showNumbers) {
    const numAlpha = 0.15 + (numberWeight / 100) * 0.85;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    for (const cd of sorted) {
      const label = String(cd.labelId + 1);
      const col = colored && activeColors.has(cd.labelId) ? colorPalette[cd.labelId] : null;
      let tf = `rgba(51,51,51,${numAlpha})`;
      if (col) {
        const lum = 0.299 * col[0] + 0.587 * col[1] + 0.114 * col[2];
        tf = lum > 140 ? `rgba(0,0,0,${numAlpha})` : `rgba(255,255,255,${numAlpha})`;
      }
      ctx.fillStyle = tf;
      for (const lbl of cd.labelPositions) {
        if (lbl.maxDist < 2.5) continue;
        const digits = label.length;
        const fitFs = (3.27 * lbl.maxDist) / digits;
        const fs = Math.max(5, Math.min(12, lbl.maxDist * 1.2, fitFs));
        ctx.font = `bold ${fs}px sans-serif`;
        ctx.fillText(label, lbl.x, lbl.y);
      }
    }
  }

  ctx.restore();
}
