// src/generator/hooks/useExport.ts
import { useState, useCallback, useMemo, useRef, useEffect } from "react";
import { useAppStore } from "../store";
import { useAppStore as useGlobalStore } from "../../store/appStore";
import { BASE_COLORS, EXTENDED_COLORS, type PaintType, type SurfaceType } from "../../config";
import { generatePdf } from "../utils/pdfExport";
import { generateInteractiveHTML } from "../utils/imageProcessing";
import { scanAndOptimize } from "../utils/recipeOptimizer";
import { buildSvgBundle } from "../utils/svgBundle";
import { createZip } from "../utils/zip";
import { canShareFiles, shareFile, downloadBlob } from "../utils/shareFile";

export interface ExportSettings {
  format: "pdf" | "svg" | "html";
  paperSize: "a4" | "a3" | "a2";
  dpi: number;
  tileMode: boolean;
  includeRecipes: boolean;
}

export const PAPER_SIZES: Record<string, { w: number; h: number; label: string }> = {
  a4: { w: 210, h: 297, label: "A4 (210×297 мм)" },
  a3: { w: 297, h: 420, label: "A3 (297×420 мм)" },
  a2: { w: 420, h: 594, label: "A2 (420×594 мм)" },
};

export function useExport() {
  const s = useAppStore();
  const gs = useGlobalStore();

  const [exportPaintType, setExportPaintType] = useState<PaintType>(gs.engineSettings.paintType);
  const [exportSurfaceType, setExportSurfaceType] = useState<SurfaceType>(gs.engineSettings.surfaceType);
  const [paperSize, setPaperSize] = useState<"a4" | "a3" | "a2">("a4");
  const [dpi, setDpi] = useState(300);
  const [tileMode, setTileMode] = useState(false);
  const [includeRecipes, setIncludeRecipes] = useState(true);
  const [watermark, setWatermark] = useState(false);
  const [showBorder, setShowBorder] = useState(true);
  const [cmykSimulation, setCmykSimulation] = useState(false);
  const [htmlAsZip, setHtmlAsZip] = useState(false);

  // Готовый к отправке HTML-файл. Нужен, когда Safari отклонил первый share()
  // из-за «протухшего» жеста: файл уже собран, второй тап уходит мгновенно.
  const pendingShareRef = useRef<File | null>(null);
  const [shareArmed, setShareArmed] = useState(false);
  const shareSupported = useMemo(() => canShareFiles(), []);

  const close = useCallback(() => s.update({ exportModalOpen: false }), [s.update]);

  // Схема поменялась — заготовленный файл больше не актуален.
  const result = s.result;
  useEffect(() => {
    pendingShareRef.current = null;
    setShareArmed(false);
  }, [result]);

  const allAvailableColors = useMemo(() => {
    const rawColors = [...BASE_COLORS, ...EXTENDED_COLORS, ...gs.customColors];
    const unique = [];
    const seen = new Set();
    for (const c of rawColors) {
      if (gs.deletedBuiltIns.includes(c.name)) continue;
      if (!seen.has(c.name)) {
        seen.add(c.name);
        unique.push(c);
      }
    }
    return unique;
  }, [gs.deletedBuiltIns, gs.customColors]);

  const activeComps = useMemo(() => {
    return allAvailableColors
      .filter((c) => gs.selectedNames.includes(c.name))
      .map((c) => ({ ...c, rgb: gs.overrides[c.name] || c.rgb }));
  }, [allAvailableColors, gs.selectedNames, gs.overrides]);

  const handlePdfExport = async () => {
    if (!s.result) return;

    // Smart Scan Phase
    if (includeRecipes && s.studioMode !== "painting") {
      s.update({ isOptimizing: true, statusMsg: "Сканирование рецептов", progress: 0 });
      try {
        const problems = await scanAndOptimize(
          s.result.colorPalette,
          Array.from(s.result.validLabels),
          activeComps,
          allAvailableColors,
          gs.engineSettings,
          gs.totalPartsLimit === "авто" || gs.totalPartsLimit === "" ? null : Number(gs.totalPartsLimit) || null,
          (pct) => s.update({ progress: pct })
        );

        if (problems.length > 0) {
          s.update({ optimizationData: problems, isOptimizing: false });
          return; // Stop and wait for user to review problems
        }
      } catch (e) {
        console.error("Optimization failed", e);
      }
    }

    proceedToPdf();
  };

  const proceedToPdf = async () => {
    if (!s.result) return;
    s.update({ isExporting: true, statusMsg: "Инициализация экспорта", progress: 0, optimizationData: [], isOptimizing: false });

    try {
      const isPainting = s.studioMode === "painting";
      await generatePdf({
        res: s.result,
        originalImageUrl: s.originalImageUrl,
        paperSize,
        dpi,
        tileMode,
        includeRecipes,
        activeComps,
        exportPaintType,
        exportSurfaceType,
        isArtistic: isPainting,
        contourWeight: isPainting ? s.paintingContourWeight : s.pbnContourWeight,
        numberWeight: s.numberWeight,
        artisticPresetId: s.paintingStyleId,
        notanLevels: s.notanLevels,
        notanThreshold: s.notanThreshold,
        artIntensity: s.artIntensity,
        customArtPalette: s.customArtPalette,
        detailsPhotoOpacity: s.detailsPhotoOpacity,
        totalPartsLimit: gs.totalPartsLimit === "авто" || gs.totalPartsLimit === "" ? null : Number(gs.totalPartsLimit) || null,
        engineSettings: gs.engineSettings,
        updateProgress: (msg, pct) => s.update({ statusMsg: msg, progress: pct }),
        watermark,
        projectTitle: s.projectTitle,
        showBorder,
        recipeOverrides: s.recipeOverrides,
        cmykSimulation
      });
      s.update({ statusMsg: "Экспорт завершён", progress: 100, recipeOverrides: {} });
    } catch (e: any) {
      s.update({ statusMsg: `Ошибка: ${e.message}` });
    } finally {
      setTimeout(() => s.update({ isExporting: false }), 2000);
    }
  };

  /** Общая часть для HTML: собирает готовую строку плеера. */
  const buildHtml = useCallback(async (): Promise<string> => {
    if (!s.result) throw new Error("Нет результата для экспорта");
    const isPainting = s.studioMode === "painting";
    const contourWeight = isPainting ? s.paintingContourWeight : s.pbnContourWeight;

    s.update({ statusMsg: "Обработка изображений", progress: 30 });
    let origBase64 = "";
    if (s.originalImageUrl) {
      // Референс-фото встраивается в HTML-плеер как base64. Полноразмерное
      // фото раздуло бы файл на десятки МБ, поэтому ужимаем: длинную сторону
      // до 1600px и JPEG 0.82 — для экранного просмотра более чем достаточно,
      // а размер HTML остаётся обоснованным.
      origBase64 = await new Promise<string>((resolve) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
          const MAX = 1600;
          const k = Math.min(1, MAX / Math.max(img.width, img.height));
          const cw = Math.max(1, Math.round(img.width * k));
          const ch = Math.max(1, Math.round(img.height * k));
          const cv = document.createElement("canvas");
          cv.width = cw; cv.height = ch;
          const cx = cv.getContext("2d");
          if (!cx) { resolve(""); return; }
          cx.drawImage(img, 0, 0, cw, ch);
          resolve(cv.toDataURL("image/jpeg", 0.82));
        };
        img.onerror = () => resolve("");
        img.src = s.originalImageUrl!;
      });
    }

    s.update({ statusMsg: "Сборка просмотрщика", progress: 70 });
    return generateInteractiveHTML(
      s.result,
      contourWeight,
      isPainting,
      origBase64,
      s.paintingStyleId,
      s.notanLevels,
      s.notanThreshold,
      s.artIntensity,
      s.customArtPalette
    );
  }, [s]);

  const baseName = useCallback(
    () => `melura_${s.studioMode === "painting" ? "art" : "pbn"}_${Date.now()}`,
    [s.studioMode]
  );

  /** Кнопки SVG / HTML — сохранение файла на устройство. */
  const doExport = useCallback((format: "svg" | "html") => {
    s.update({ isExporting: true, statusMsg: "Подготовка данных", progress: 10 });

    setTimeout(async () => {
      try {
        if (!s.result) throw new Error("Нет результата для экспорта");
        const isPainting = s.studioMode === "painting";

        if (format === "svg") {
          // Отдаём не один файл, а весь набор полезных вариантов одним архивом.
          const zip = await buildSvgBundle({
            res: s.result,
            contourWeight: isPainting ? s.paintingContourWeight : s.pbnContourWeight,
            numberWeight: s.numberWeight,
            isArtistic: isPainting,
            artisticPresetId: s.paintingStyleId,
            notanLevels: s.notanLevels,
            notanThreshold: s.notanThreshold,
            artIntensity: s.artIntensity,
            customArtPalette: s.customArtPalette,
            onProgress: (msg, pct) => s.update({ statusMsg: msg, progress: pct }),
          });

          s.update({ statusMsg: "Сохранение архива", progress: 96 });
          downloadBlob(zip, `${baseName()}_svg.zip`);

        } else if (format === "html") {
          const htmlStr = await buildHtml();

          if (htmlAsZip) {
            s.update({ statusMsg: "Упаковка в ZIP", progress: 88 });
            const zip = await createZip([{ name: `${baseName()}.html`, data: htmlStr }]);
            downloadBlob(zip, `${baseName()}_html.zip`);
          } else {
            downloadBlob(new Blob([htmlStr], { type: "text/html" }), `${baseName()}.html`);
          }
        }

        s.update({ statusMsg: "Файл сохранён", progress: 100 });
        setTimeout(() => {
          s.update({ isExporting: false });
        }, 1500);
      } catch (e: any) {
        s.update({ statusMsg: `Ошибка: ${e.message}`, progress: 0 });
        setTimeout(() => s.update({ isExporting: false }), 3000);
      }
    }, 100);
  }, [s, buildHtml, htmlAsZip, baseName]);

  /**
   * «Поделиться» — главный путь для мессенджеров.
   * Файл уходит в системное меню, минуя веб-загрузчик соцсети (который и режет
   * .html). Получатель открывает его одним тапом, без распаковки.
   */
  const shareHtml = useCallback(async () => {
    const SHARE_TITLE = "MELURA. Схема";
    const SHARE_TEXT = "Интерактивная схема MELURA. Файл открывается в браузере.";

    // Второй тап после «протухшего» жеста: файл уже готов, отправляем сразу —
    // никакого await до share(), иначе Safari снова откажет.
    const ready = pendingShareRef.current;
    if (ready) {
      const outcome = await shareFile(ready, SHARE_TITLE, SHARE_TEXT);
      if (outcome === "shared" || outcome === "cancelled") {
        pendingShareRef.current = null;
        setShareArmed(false);
      }
      if (outcome === "unsupported") {
        downloadBlob(ready, ready.name);
        pendingShareRef.current = null;
        setShareArmed(false);
        s.update({ isExporting: true, statusMsg: "Отправка недоступна, файл сохранён", progress: 100 });
        setTimeout(() => s.update({ isExporting: false }), 2500);
      }
      return;
    }

    s.update({ isExporting: true, statusMsg: "Подготовка файла", progress: 10 });
    try {
      const htmlStr = await buildHtml();
      const file = new File([htmlStr], `${baseName()}.html`, { type: "text/html" });
      s.update({ isExporting: false, statusMsg: "", progress: 0 });

      const outcome = await shareFile(file, SHARE_TITLE, SHARE_TEXT);

      if (outcome === "needs-gesture") {
        // Жест истёк, пока собирался файл. Файл держим наготове — кнопка
        // превращается в «Отправить», и следующий тап проходит мгновенно.
        pendingShareRef.current = file;
        setShareArmed(true);
      } else if (outcome === "unsupported") {
        downloadBlob(file, file.name);
      }
    } catch (e: any) {
      s.update({ statusMsg: `Ошибка: ${e.message}`, progress: 0 });
      setTimeout(() => s.update({ isExporting: false }), 3000);
    }
  }, [s, buildHtml, baseName]);

  return {
    exportPaintType, setExportPaintType,
    exportSurfaceType, setExportSurfaceType,
    paperSize, setPaperSize,
    dpi, setDpi,
    tileMode, setTileMode,
    includeRecipes, setIncludeRecipes,
    watermark, setWatermark,
    showBorder, setShowBorder,
    cmykSimulation, setCmykSimulation,
    htmlAsZip, setHtmlAsZip,
    shareSupported, shareArmed, shareHtml,
    close,
    handlePdfExport,
    proceedToPdf,
    doExport,
    isArtistic: s.studioMode === "painting",
    gs, s
  };
}
