import React, { useRef, useState, useEffect, useCallback } from "react";
import { useAppStore } from "../store";
import { cn } from "../../utils/cn";

export function ARCameraModal() {
  const isOpen = useAppStore((s) => s.arCameraOpen);
  const update = useAppStore((s) => s.update);

  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>("");
  const [hasTorch, setHasTorch] = useState(false);
  const [torchOn, setTorchOn] = useState(false);

  const close = useCallback(() => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    update({ arCameraOpen: false });
    setTorchOn(false);
  }, [stream, update]);

  useEffect(() => {
    if (isOpen) {
      setError("");
      setTorchOn(false);
      setHasTorch(false);
      navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'environment',
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        } 
      })
      .then((s) => {
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
        
        // Проверяем наличие фонарика
        const track = s.getVideoTracks()[0];
        if (track) {
          const capabilities = (track.getCapabilities && track.getCapabilities()) as MediaTrackCapabilities & { torch?: boolean };
          if (capabilities && capabilities.torch) {
            setHasTorch(true);
          }
        }
      })
      .catch((err) => {
        setError("Не удалось получить доступ к камере. Убедитесь, что вы разрешили доступ.");
        console.error(err);
      });
    } else {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
        setStream(null);
      }
    }
  }, [isOpen]);

  // Присвоение stream в video при ререндере, если videoRef готов
  useEffect(() => {
    if (videoRef.current && stream && videoRef.current.srcObject !== stream) {
      videoRef.current.srcObject = stream;
    }
  }, [stream, isOpen]);

  const captureColor = useCallback(() => {
    const video = videoRef.current;
    if (!video) return;

    const canvas = document.createElement("canvas");
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    
    // Получаем пиксель по центру (с учетом cropCenter)
    const centerX = Math.floor(canvas.width / 2);
    const centerY = Math.floor(canvas.height / 2);
    
    // Для большей стабильности можно взять среднее значение небольшого квадрата (например 5x5)
    const size = 5;
    const halfSize = Math.floor(size / 2);
    
    // Защита от выхода за границы
    if (centerX - halfSize < 0 || centerY - halfSize < 0 || centerX + halfSize >= canvas.width || centerY + halfSize >= canvas.height) {
      // Фолбэк на 1 пиксель если размеры слишком малы
      const pixel = ctx.getImageData(centerX, centerY, 1, 1).data;
      update({ 
        pickedColor: [pixel[0], pixel[1], pixel[2]],
        colorPickerPanelOpen: true
      });
      close();
      return;
    }

    const imgData = ctx.getImageData(centerX - halfSize, centerY - halfSize, size, size).data;
    
    let r = 0, g = 0, b = 0;
    const count = size * size;
    for (let i = 0; i < imgData.length; i += 4) {
      r += imgData[i];
      g += imgData[i+1];
      b += imgData[i+2];
    }
    
    const finalRgb: [number, number, number] = [
      Math.round(r / count), 
      Math.round(g / count), 
      Math.round(b / count)
    ];

    update({ 
      pickedColor: finalRgb,
      colorPickerPanelOpen: true
    });
    
    setTimeout(() => {
      document.getElementById('physics-of-preview')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 50);
    
    close();
  }, [update, close]);

  const toggleTorch = useCallback(() => {
    if (!stream) return;
    const track = stream.getVideoTracks()[0];
    if (track) {
      const nextState = !torchOn;
      track.applyConstraints({
        advanced: [{ torch: nextState }]
      } as any).then(() => {
        setTorchOn(nextState);
      }).catch(err => {
        console.error("Torch error:", err);
      });
    }
  }, [stream, torchOn]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black" role="dialog" aria-modal="true" aria-label="AR Захват цвета">
      {/* Видео-поток (на весь экран, object-cover) */}
      <video 
        ref={videoRef}
        autoPlay
        playsInline
        muted
        className="absolute inset-0 w-full h-full object-cover"
      />
      
      {/* Оверлей ошибки */}
      {error && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-20 px-6">
          <div className="bg-slate-900 p-6 rounded-3xl text-center shadow-2xl border border-red-500/30 max-w-sm">
            <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-red-500 mx-auto mb-4">
              <circle cx="12" cy="12" r="10" />
              <line x1="12" y1="8" x2="12" y2="12" />
              <line x1="12" y1="16" x2="12.01" y2="16" />
            </svg>
            <h3 className="text-white text-lg font-bold mb-2">Ошибка камеры</h3>
            <p className="text-slate-300 text-sm mb-6">{error}</p>
            <button onClick={close} className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-6 rounded-xl transition-colors uppercase tracking-wider text-xs">Закрыть</button>
          </div>
        </div>
      )}

      {/* Оверлей UI поверх видео */}
      {!error && (
        <div className="absolute inset-0 z-10 pointer-events-none flex flex-col justify-between">
          
          {/* Верхняя панель */}
          <div className="p-4 sm:p-6 pt-[max(1rem,env(safe-area-inset-top))] flex justify-between items-center pointer-events-auto bg-gradient-to-b from-black/50 to-transparent">
            <button onClick={close} className="w-12 h-12 rounded-full flex items-center justify-center bg-black/40 text-white backdrop-blur-md hover:bg-black/60 transition-colors shadow-sm">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M18 6L6 18M6 6l12 12" /></svg>
            </button>
            <h2 className="text-white font-black uppercase tracking-widest text-sm shadow-black drop-shadow-md">Захват цвета</h2>
            <div className="w-12 flex justify-end">
              {hasTorch && (
                <button 
                  onClick={toggleTorch}
                  className={cn(
                    "w-12 h-12 rounded-full flex items-center justify-center backdrop-blur-md transition-all shadow-sm",
                    torchOn ? "bg-amber-500/90 text-white shadow-[0_0_15px_rgba(245,158,11,0.5)]" : "bg-black/40 text-white hover:bg-black/60"
                  )}
                >
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.9 1.3 1.5 1.5 2.5"/><path d="M9 18h6"/><path d="M10 22h4"/>
                  </svg>
                </button>
              )}
            </div>
          </div>

          {/* Прицел по центру */}
          <div className="flex-1 flex items-center justify-center relative">
            <div className="w-16 h-16 border-2 border-white/80 rounded-full flex items-center justify-center shadow-[0_0_15px_rgba(0,0,0,0.5)]">
              <div className="w-2 h-2 rounded-full bg-red-500 animate-ping"></div>
              {/* Крестик */}
              <div className="absolute top-0 bottom-0 left-1/2 w-0.5 -ml-[1px] bg-white/50 h-full"></div>
              <div className="absolute left-0 right-0 top-1/2 h-0.5 -mt-[1px] bg-white/50 w-full"></div>
            </div>
          </div>

          {/* Нижняя панель (Кнопка Захват) */}
          <div className="p-6 pb-[max(2rem,env(safe-area-inset-bottom))] flex justify-center pointer-events-auto bg-gradient-to-t from-black/80 to-transparent">
            <button 
              onClick={captureColor}
              disabled={!stream}
              className="group relative w-24 h-24 rounded-full bg-white/20 backdrop-blur-xl border-4 border-white flex items-center justify-center active:scale-95 transition-all shadow-2xl disabled:opacity-50"
            >
              <div className="w-20 h-20 rounded-full bg-white group-hover:scale-95 transition-transform duration-300 shadow-inner flex items-center justify-center">
                <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-indigo-600">
                  <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M17 8l-5-5-5 5M12 3v12" />
                </svg>
              </div>
            </button>
          </div>
          
        </div>
      )}
    </div>
  );
}
