// src/generator/utils/ai/salientObjectService.ts
// Универсальное выделение ГЛАВНОГО ОБЪЕКТА (class-agnostic salient object
// detection) через ONNX-модель U²-Net(p). В отличие от MediaPipe selfie-
// сегментации (только люди), эта модель понимает «главное/фон» для ЛЮБОГО
// сюжета: животные, игрушки, предметы, цветы, дома и т.п.
//
// Всё сделано отказоустойчиво: если runtime/модель не загрузились, сервис
// возвращает null и весь пайплайн работает как раньше (без регрессий).

// Ленивая загрузка onnxruntime-web (WASM backend) — не раздувает основной бандл.
type OrtNS = typeof import("onnxruntime-web/wasm");

export interface ForegroundResult {
  // Карта «главности» 0..1 в разрешении maskW×maskH (row-major).
  mask: Float32Array;
  maskW: number;
  maskH: number;
  // Доля пикселей, уверенно отнесённых к переднему плану (для эвристик).
  coverage: number;
}

const MODEL_SIZE = 320; // U²-Net вход 320×320
const MEAN = [0.485, 0.456, 0.406];
const STD = [0.229, 0.224, 0.225];

function baseUrl(): string {
  const b = (import.meta as any).env?.BASE_URL || "/";
  return b.endsWith("/") ? b : b + "/";
}

class SalientObjectService {
  private ort: OrtNS | null = null;
  private session: any = null;
  private initPromise: Promise<boolean> | null = null;
  private failed = false;

  /** Пытается инициализировать runtime + модель. Возвращает true при успехе. */
  async initialize(): Promise<boolean> {
    if (this.session) return true;
    if (this.failed) return false;
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
      try {
        const ort = (await import("onnxruntime-web/wasm")) as OrtNS;
        // Однопоточный WASM: не требует COOP/COEP-заголовков (работает под vite preview).
        ort.env.wasm.numThreads = 1;
        ort.env.wasm.simd = true;
        ort.env.wasm.proxy = false;
        ort.env.wasm.wasmPaths = baseUrl() + "ai/onnx/";
        this.ort = ort;

        this.session = await ort.InferenceSession.create(
          baseUrl() + "ai/u2netp.onnx",
          { executionProviders: ["wasm"], graphOptimizationLevel: "all" },
        );
         
        console.log("[AI] Salient-object model (u2netp) initialized");
        return true;
      } catch (e) {
        console.warn("[AI] Salient-object init failed, continuing without it:", e);
        this.failed = true;
        this.session = null;
        return false;
      }
    })();

    return this.initPromise;
  }

  /**
   * Возвращает карту главного объекта для произвольного изображения.
   * null — если модель недоступна или произошла ошибка.
   */
  async process(imageData: ImageData): Promise<ForegroundResult | null> {
    const ok = await this.initialize();
    if (!ok || !this.session || !this.ort) return null;

    try {
      const input = this.preprocess(imageData); // NCHW Float32
      const tensor = new this.ort.Tensor("float32", input, [1, 3, MODEL_SIZE, MODEL_SIZE]);

      const feeds: Record<string, any> = {};
      const inputName = this.session.inputNames?.[0] || "input.1";
      feeds[inputName] = tensor;

      const out = await this.session.run(feeds);
      const outName = this.session.outputNames?.[0] || Object.keys(out)[0];
      const data = out[outName].data as Float32Array; // [1,1,320,320]

      // min-max нормализация (как в rembg) — растягиваем контраст маски
      let mi = Infinity, ma = -Infinity;
      for (let i = 0; i < data.length; i++) {
        const v = data[i];
        if (v < mi) mi = v;
        if (v > ma) ma = v;
      }
      const range = ma - mi > 1e-6 ? ma - mi : 1;

      const mask = new Float32Array(MODEL_SIZE * MODEL_SIZE);
      let fg = 0;
      for (let i = 0; i < mask.length; i++) {
        const v = (data[i] - mi) / range;
        mask[i] = v;
        if (v > 0.5) fg++;
      }

      return { mask, maskW: MODEL_SIZE, maskH: MODEL_SIZE, coverage: fg / mask.length };
    } catch (e) {
      console.warn("[AI] Salient-object inference failed:", e);
      return null;
    }
  }

  /** Ресайз до 320×320 + нормализация ImageNet, layout NCHW. */
  private preprocess(imageData: ImageData): Float32Array {
    const { width, height } = imageData;

    // Рисуем оригинал и масштабируем в 320×320 через canvas.
    const makeCanvas = (w: number, h: number): any => {
      if (typeof OffscreenCanvas !== "undefined") return new OffscreenCanvas(w, h);
      const c = document.createElement("canvas");
      c.width = w; c.height = h; return c;
    };

    const src = makeCanvas(width, height);
    const sctx = src.getContext("2d") as CanvasRenderingContext2D;
    sctx.putImageData(imageData, 0, 0);

    const dst = makeCanvas(MODEL_SIZE, MODEL_SIZE);
    const dctx = dst.getContext("2d") as CanvasRenderingContext2D;
    dctx.drawImage(src as any, 0, 0, width, height, 0, 0, MODEL_SIZE, MODEL_SIZE);
    const resized = dctx.getImageData(0, 0, MODEL_SIZE, MODEL_SIZE).data;

    const n = MODEL_SIZE * MODEL_SIZE;
    const out = new Float32Array(3 * n);

    // Нормализация как в U²-Net: сначала делим на max(image), затем (x-mean)/std.
    // Ищем max по всем каналам (в диапазоне 0..1).
    let maxVal = 0;
    for (let i = 0; i < n; i++) {
      const p = i * 4;
      const r = resized[p] / 255, g = resized[p + 1] / 255, b = resized[p + 2] / 255;
      if (r > maxVal) maxVal = r;
      if (g > maxVal) maxVal = g;
      if (b > maxVal) maxVal = b;
    }
    if (maxVal <= 0) maxVal = 1;

    for (let i = 0; i < n; i++) {
      const p = i * 4;
      const r = resized[p] / 255 / maxVal;
      const g = resized[p + 1] / 255 / maxVal;
      const b = resized[p + 2] / 255 / maxVal;
      out[i] = (r - MEAN[0]) / STD[0];             // channel R
      out[n + i] = (g - MEAN[1]) / STD[1];         // channel G
      out[2 * n + i] = (b - MEAN[2]) / STD[2];     // channel B
    }
    return out;
  }
}

export const salientObjectEngine = new SalientObjectService();
