// src/generator/components/AutoPreset.tsx
//
// «Автоподбор пресетов» — волшебная кнопка + модалка с лучшими вариантами.
// Модалка рендерится через ПОРТАЛ в document.body: иначе position:fixed считается
// относительно трансформированного родителя (боковой панели) и окно оказывается
// зажатым внутри сайдбара. Найденные варианты СОХРАНЯЮТСЯ — панель можно открыть
// снова и выбрать другой без повторного поиска.

import { createPortal } from "react-dom";
import { cn } from "../../utils/cn";
import { useAppStore } from "../store";
import { useAutoPreset } from "../hooks/useAutoPreset";
import type { PresetCandidateUI } from "../store/types";

function Bar({ label, value, tone }: { label: string; value: number; tone: string }) {
  const pct = Math.round(Math.max(0, Math.min(1, value)) * 100);
  return (
    <div className="flex items-center gap-2">
      <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 w-24 shrink-0">{label}</span>
      <span className="flex-1 h-1.5 rounded-full bg-white/10 overflow-hidden">
        <span className={cn("block h-full rounded-full", tone)} style={{ width: `${pct}%` }} />
      </span>
      <span className="text-[10px] font-black text-slate-300 w-8 text-right">{pct}%</span>
    </div>
  );
}

function Card({ cand, rank, applied, onApply }: { cand: PresetCandidateUI; rank: number; applied: boolean; onApply: () => void }) {
  return (
    <button
      onClick={onApply}
      className={cn(
        "group text-left rounded-2xl overflow-hidden border-2 bg-slate-900/60 hover:bg-slate-900 active:scale-[0.98] transition-all flex flex-col",
        applied ? "border-emerald-500" : "border-white/10 hover:border-indigo-500/70",
      )}
    >
      <div className="relative">
        <img src={cand.previewUrl} alt="" className="w-full aspect-[4/3] object-cover bg-slate-800" />
        {rank === 0 && !applied && (
          <span className="absolute top-2 left-2 px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-amber-400 text-slate-900 shadow">Лучший</span>
        )}
        {applied && (
          <span className="absolute top-2 left-2 px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-emerald-400 text-slate-900 shadow">Применён</span>
        )}
        <span className="absolute top-2 right-2 px-2 py-0.5 rounded-full text-[11px] font-black bg-black/60 text-white backdrop-blur">{Math.round(cand.score * 100)}</span>
      </div>
      <div className="p-3 flex flex-col gap-2">
        <div className="flex items-center justify-between">
          <span className="text-sm font-black text-white"><span className="text-fuchsia-300">№{rank + 1}</span> · {cand.usedColors} красок · детали {cand.detail}</span>
          <span className="text-[10px] font-bold text-slate-400">ΔE {cand.meanDeltaE.toFixed(1)}</span>
        </div>
        <div className="flex flex-col gap-1.5">
          <Bar label="Сходство" value={cand.similarity} tone="bg-emerald-400" />
          <Bar label="Раскраска" value={cand.paintability} tone="bg-sky-400" />
        </div>
        <div className="flex items-center justify-between text-[10px] font-bold text-slate-400">
          <span className="flex items-center gap-1.5">
            {cand.zones} зон{cand.microzones > 0 ? ` · ${cand.microzones} микро` : ""}
            {cand.emphasis > 1 && (
              <span className="px-1.5 py-0.5 rounded bg-fuchsia-500/20 text-fuchsia-300 text-[9px] uppercase tracking-wider" title="Детали сосредоточены на главном объекте, фон упрощён">акцент</span>
            )}
          </span>
          <span className="text-indigo-400 group-hover:text-indigo-300 uppercase tracking-wider">{applied ? "Выбрать снова →" : "Применить →"}</span>
        </div>
      </div>
    </button>
  );
}

export function AutoPreset({ isDark }: { isDark?: boolean }) {
  void isDark;
  const curUrl = useAppStore((s) => s.originalImageUrl);
  const hasImage = !!curUrl;
  const { presetSearch, start, openPanel, cancel, close, apply } = useAutoPreset();
  const { running, progress, candidates, error, open, appliedId } = presetSearch;
  const hasCache = !!candidates && candidates.length > 0 && presetSearch.sourceUrl === curUrl;

  const overlay = (running || open) ? (
    <div className="fixed inset-0 z-[100000] flex items-center justify-center p-4 sm:p-6 bg-black/70 backdrop-blur-sm animate-fade-in">
      <div className="w-full max-w-4xl max-h-[88vh] overflow-hidden rounded-3xl border-2 border-white/10 bg-slate-950 shadow-2xl flex flex-col">
        <div className="flex items-center justify-between gap-3 px-5 py-4 border-b border-white/10 shrink-0">
          <div className="flex items-center gap-2">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" className="text-fuchsia-400"><path d="M12 3l1.9 4.6L18.5 9.5 13.9 11.4 12 16l-1.9-4.6L5.5 9.5l4.6-1.9L12 3z" /></svg>
            <h2 className="text-base font-black text-white uppercase tracking-wider">Автоподбор пресетов</h2>
          </div>
          <div className="flex items-center gap-2">
            {!running && hasCache && (
              <button onClick={start} className="px-3 py-1.5 rounded-lg text-xs font-black uppercase tracking-wider text-indigo-300 hover:bg-indigo-500/15 transition-all">Искать заново</button>
            )}
            {running ? (
              <button onClick={cancel} className="px-3 py-1.5 rounded-lg text-xs font-black uppercase tracking-wider text-rose-300 hover:bg-rose-500/15 transition-all">Отмена</button>
            ) : (
              <button onClick={close} className="w-8 h-8 rounded-lg flex items-center justify-center text-slate-300 hover:bg-white/10 transition-all">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round"><path d="M18 6 6 18M6 6l12 12" /></svg>
              </button>
            )}
          </div>
        </div>

        <div className="p-5 overflow-y-auto">
          {running && (
            <div className="flex flex-col items-center justify-center gap-4 py-16">
              <div className="w-full max-w-sm h-2 rounded-full bg-white/10 overflow-hidden">
                <div className="h-full rounded-full bg-gradient-to-r from-indigo-500 to-fuchsia-500 transition-all" style={{ width: `${progress}%` }} />
              </div>
              <p className="text-sm font-bold text-slate-300">Движок перебирает варианты… {progress}%</p>
              <p className="text-xs text-slate-500 text-center max-w-md">Прогоняем сотни «мысленных» генераций на уменьшенной копии и оцениваем каждую по верности фото и удобству раскраски.</p>
            </div>
          )}

          {!running && error && (
            <div className="py-16 text-center"><p className="text-sm font-bold text-rose-300">{error}</p></div>
          )}

          {!running && !error && hasCache && (
            <>
              <p className="text-xs text-slate-400 mb-3 leading-relaxed">
                Все варианты сбалансированы по точности передачи фото — выбери тот, что нравится глазу. Клик применит пресет и перегенерирует картину в полном качестве.
              </p>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {candidates!.map((c, i) => (
                  <Card key={c.id} cand={c} rank={i} applied={appliedId === c.id} onApply={() => apply(c)} />
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  ) : null;

  return (
    <>
      <button
        onClick={openPanel}
        disabled={!hasImage || running}
        title="Умный поиск: движок «мысленно» перебирает варианты генерации и предлагает лучшие сбалансированные пресеты"
        className={cn(
          "w-full flex items-center justify-center gap-2 rounded-xl px-4 py-3 font-black text-sm uppercase tracking-wider transition-all active:scale-[0.98]",
          "bg-gradient-to-r from-indigo-600 to-fuchsia-600 text-white shadow-lg shadow-indigo-600/25 hover:from-indigo-500 hover:to-fuchsia-500",
          (!hasImage || running) && "opacity-50 pointer-events-none",
        )}
      >
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M12 3l1.9 4.6L18.5 9.5 13.9 11.4 12 16l-1.9-4.6L5.5 9.5l4.6-1.9L12 3z" />
          <path d="M19 14l.8 2 2 .8-2 .8-.8 2-.8-2-2-.8 2-.8.8-2z" />
        </svg>
        {hasCache ? "Пресеты найдены — открыть" : "Автоподбор пресетов"}
      </button>

      {overlay && createPortal(overlay, document.body)}
    </>
  );
}
