// src/generator/components/CalculatorBottomSheet.tsx
import { useRef, useCallback } from "react";
import { useAppStore } from "../store";
import { CalculatorContent } from "./CalculatorPanel";
import { cn } from "../../utils/cn";
import { useBackButton } from "../../hooks/useBackButton";

export function CalculatorBottomSheet() {
  const colorPickerActive = useAppStore((s) => s.colorPickerActive);
  const pickedColor = useAppStore((s) => s.pickedColor);
  const panelOpen = useAppStore((s) => s.colorPickerPanelOpen);
  const isDark = useAppStore((s) => s.isDark);
  const update = useAppStore((s) => s.update);

  // Лист «Рецепт цвета» задействован, если мы в режиме пипетки ИЛИ уже получен цвет
  // (в т.ч. с AR-камеры, которая не включает режим пипетки). Открыт — когда есть флаг
  // panelOpen. Так рецепт корректно открывается для ОБОИХ способов получения цвета.
  const engaged = colorPickerActive || !!pickedColor;
  const isOpen = panelOpen && engaged;

  const sheetRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  const close = useCallback(() => {
    update({ colorPickerPanelOpen: false });
  }, [update]);

  useBackButton(isOpen, close);

  if (!engaged) return null;

  return (
    <>
      {/* Кнопка открытия если закрыто — только когда цвет уже выбран (иначе нечего показывать) */}
      {!isOpen && pickedColor && (
        <button 
          onClick={() => update({ colorPickerPanelOpen: true })}
          className="lg:hidden fixed bottom-[calc(80px_+_env(safe-area-inset-bottom))] sm:bottom-6 left-1/2 -translate-x-1/2 z-[45] flex items-center justify-center w-14 h-14 rounded-full bg-indigo-600 text-white shadow-xl animate-fade-in-up active:scale-95 transition-transform"
          aria-label="Показать рецепт"
        >
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="m2 22 1-1h3l9-9" /><path d="M3 21v-3l9-9" /><path d="m15 6 3 3 3-3-3-3z" />
          </svg>
        </button>
      )}

      {/* Затемнение фона */}
      {isOpen && (
        <div 
          className="lg:hidden fixed inset-0 bg-black/40 z-[60] modal-backdrop backdrop-blur-sm"
          onClick={close}
        />
      )}

      {/* Bottom Sheet — anchored to bottom on mobile */}
      <div
        ref={sheetRef}
        role="dialog"
        aria-modal="true"
        aria-label="Рецепт цвета"
        className={cn(
          "lg:hidden fixed inset-0 z-[70] flex items-end justify-center",
          !isOpen && "pointer-events-none"
        )}
      >
        <div 
          className={cn(
            "w-full max-h-[85dvh] rounded-t-3xl shadow-2xl overflow-hidden transition-all duration-300 ease-out flex flex-col",
            isDark ? "bg-slate-900 border-t border-slate-800" : "bg-white border-t border-slate-100",
            isOpen ? "opacity-100 translate-y-0" : "opacity-0 translate-y-full"
          )}
        >
          <div data-handle className="shrink-0 pt-3 pb-2 flex flex-col items-center">
            <div className={cn("w-10 h-1 rounded-full mb-3", isDark ? "bg-slate-700" : "bg-slate-200")} />
            <div className="flex items-center justify-between w-full px-5 mb-1">
              <div>
                 <h2 className={cn("text-lg font-black tracking-tight", isDark ? "text-white" : "text-slate-900")}>Рецепт цвета</h2>
                 <p className="text-xs font-bold text-slate-500 uppercase tracking-widest leading-none mt-0.5">Melura</p>
              </div>
              <button onClick={close} className={cn("w-11 h-11 rounded-2xl flex items-center justify-center transition-colors shadow-sm active:scale-90", isDark ? "bg-slate-800 text-slate-500 hover:bg-slate-700" : "bg-slate-100 text-slate-600 hover:bg-slate-200")} aria-label="Закрыть">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M18 6 6 18M6 6l12 12" />
                </svg>
              </button>
            </div>
          </div>

          <div ref={contentRef} className="flex-1 overflow-y-auto overscroll-contain custom-scrollbar px-2 pb-[max(1.5rem,env(safe-area-inset-bottom))]">
             <CalculatorContent 
               pickedColor={pickedColor} 
               onClose={() => update({ colorPickerActive: false, pickedColor: null, colorPickerPanelOpen: false })} 
               isMobileView 
             />
          </div>
        </div>
      </div>
    </>
  );
}
