// src/generator/components/OptimizationModal.tsx
import { useAppStore } from "../store";
import { PAINT_PROFILES, formatParts, type PaintType } from "../../config";
import { cn } from "../../utils/cn";

export function OptimizationModal({ onContinue, paintType }: { onContinue: () => void; paintType: PaintType }) {
  const s = useAppStore();
  const problems = s.optimizationData;
  const isDark = s.isDark;

  if (problems.length === 0) return null;

  const close = () => {
    s.update({ optimizationData: [] });
  };

  const applyOption = (colorId: number, optionIndex: number) => {
    const problem = problems.find(p => p.id === colorId);
    if (!problem) return;
    const option = problem.options[optionIndex];
    
    const newOverrides = { ...s.recipeOverrides, [colorId]: option.variant };
    s.update({ recipeOverrides: newOverrides });
  };

  const clearOption = (colorId: number) => {
    const newOverrides = { ...s.recipeOverrides };
    delete newOverrides[colorId];
    s.update({ recipeOverrides: newOverrides });
  };

  const skipAll = () => {
    onContinue();
  };

  const applyAndContinue = () => {
    onContinue();
  };

  const paintProfile = PAINT_PROFILES[paintType];

  const getPlural = (n: number, one: string, two: string, five: string) => {
    n = Math.abs(n) % 100;
    const n1 = n % 10;
    if (n > 10 && n < 20) return five;
    if (n1 > 1 && n1 < 5) return two;
    if (n1 === 1) return one;
    return five;
  };

  const recipeText = getPlural(problems.length, "рецепт", "рецепта", "рецептов");
  const foundText = getPlural(problems.length, "Найден", "Найдено", "Найдено");

  return (
    <div className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center p-0 sm:p-4 sm:p-6 pt-[max(1rem,env(safe-area-inset-top))]" role="dialog" aria-modal="true" aria-label="Оптимизация рецептов">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity" onClick={close} />

      <div className={cn("relative z-10 w-full sm:max-w-3xl max-h-[85dvh] flex flex-col rounded-t-3xl sm:rounded-2xl shadow-premium overflow-hidden modal-enter touch-pan-y overscroll-contain", isDark ? "bg-slate-900 border border-white/10" : "bg-white border border-black/5")}>
        <div className={cn("flex-shrink-0 flex flex-col px-6 pt-5 pb-4 border-b", isDark ? "border-slate-800" : "border-slate-100")}>
          <div className="flex items-center justify-between mb-1">
            <div className="flex items-center gap-2.5">
              <div className={cn("p-1.5 rounded-xl", isDark ? "bg-slate-800 text-amber-400" : "bg-amber-50 text-amber-600")}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>
                </svg>
              </div>
              <h2 className={cn("text-base sm:text-lg font-bold", isDark ? "text-slate-100" : "text-slate-900")}>
                Оптимизация рецептов
              </h2>
            </div>
            <button onClick={close} className={cn("w-10 h-10 -mr-2 rounded-full flex items-center justify-center transition-all", isDark ? "bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-white" : "bg-slate-100 text-slate-500 hover:bg-slate-200 hover:text-slate-800")} aria-label="Закрыть">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6L6 18M6 6l12 12" /></svg>
            </button>
          </div>
          <div className="text-xs font-black uppercase tracking-[0.2em] text-slate-500 dark:text-slate-400 ml-10">
            {foundText} {problems.length} {recipeText}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar">
          {problems.map((p) => {
            const override = s.recipeOverrides[p.id];
            const isOptimized = !!override;

            return (
              <div key={p.id} className="space-y-4 animate-fade-in">
                <div className="flex items-center gap-3">
                  <div className={cn("w-8 h-8 rounded-lg shadow-sm border-2 shrink-0", isDark ? "border-slate-800" : "border-white")} style={{ background: `rgb(${p.targetRgb[0]},${p.targetRgb[1]},${p.targetRgb[2]})` }} />
                  <span className={cn("text-xs font-black uppercase tracking-widest", isDark ? "text-slate-300" : "text-slate-700")}>Цвет #{p.id + 1}</span>
                  {isOptimized && (
                    <div className="px-2 py-0.5 rounded-md bg-emerald-500/10 text-emerald-500 text-[9px] font-black uppercase tracking-widest border border-emerald-500/20">Улучшено</div>
                  )}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
                  {/* Текущий вариант */}
                  <button 
                    onClick={() => clearOption(p.id)}
                    className={cn(
                      "w-full p-5 sm:p-6 rounded-3xl border-2 text-left transition-all active:scale-[0.98] group flex flex-col h-full",
                      !isOptimized 
                        ? (isDark ? "border-indigo-500 bg-indigo-500/10 shadow-md shadow-indigo-500/10" : "border-indigo-500 bg-indigo-50 shadow-md shadow-indigo-500/10")
                        : (isDark ? "border-slate-800 hover:border-indigo-500/50 bg-slate-800/30" : "border-slate-100 hover:border-indigo-200 bg-white shadow-sm")
                    )}
                  >
                    <div className="flex justify-between items-start w-full">
                      <div className="min-w-0 pr-3">
                         <span className={cn("text-sm sm:text-base font-black leading-snug block mb-3", isDark ? "text-slate-300" : "text-slate-700")}>Текущий рецепт</span>
                         <div className="flex items-center gap-2 flex-wrap">
                           <span className={cn("text-[10px] font-black uppercase px-2.5 py-1 rounded-md text-white shadow-sm tracking-tight", p.currentVariant.deltaE < 5 ? "bg-emerald-500" : "bg-rose-500")}>
                             {p.currentVariant.rating}
                           </span>
                           {p.currentVariant.deltaE >= 5 && <span className="text-xs font-bold text-rose-400 dark:text-rose-500 uppercase tracking-tight">• Требует улучшения</span>}
                         </div>
                      </div>
                      <div className={cn("w-6 h-6 sm:w-7 sm:h-7 rounded-full flex items-center justify-center transition-all shrink-0 shadow-sm mt-0.5", !isOptimized ? "bg-indigo-500 text-white" : (isDark ? "bg-slate-800 text-transparent group-hover:text-slate-400" : "bg-slate-100 text-transparent group-hover:text-slate-400"))}>
                         <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M20 6L9 17l-5-5"/></svg>
                      </div>
                    </div>
                    
                    <div className="w-full flex flex-col gap-3 mt-auto pt-5 border-t border-slate-200/60 dark:border-slate-700/60">
                       {p.currentVariant.recipe.map((item, idx) => (
                         <div key={idx} className={cn("flex items-center justify-between text-sm font-bold w-full", isDark ? "text-slate-300" : "text-slate-600")}>
                           <div className="flex items-center gap-3 min-w-0 pr-4">
                             <div className="w-5 h-5 rounded-full shadow-inner border border-black/10 shrink-0" style={{ background: `rgb(${item.rgb[0]},${item.rgb[1]},${item.rgb[2]})` }} />
                             <span className="truncate leading-tight">{item.name}</span>
                           </div>
                           <span className="font-mono text-indigo-500 dark:text-indigo-400 shrink-0">{formatParts(item.parts, paintProfile)}</span>
                         </div>
                       ))}
                    </div>
                  </button>

                  {/* Предложения */}
                  <div className="space-y-4">
                    {p.options.map((opt, optIdx) => {
                      const isSelected = override?.deltaE === opt.variant.deltaE;
                      const improvement = (p.currentVariant.deltaE - opt.variant.deltaE).toFixed(1);
                      
                      return (
                        <button 
                          key={optIdx}
                          onClick={() => applyOption(p.id, optIdx)}
                          className={cn(
                            "w-full p-5 sm:p-6 rounded-3xl border-2 text-left transition-all active:scale-[0.98] group flex flex-col",
                            isSelected 
                              ? (isDark ? "border-indigo-500 bg-indigo-500/10 shadow-md shadow-indigo-500/10" : "border-indigo-500 bg-indigo-50 shadow-md shadow-indigo-500/10")
                              : (isDark ? "border-slate-800 hover:border-indigo-500/50 bg-slate-800/30" : "border-slate-100 hover:border-indigo-200 bg-white shadow-sm")
                          )}
                        >
                          <div className="flex justify-between items-start w-full">
                            <div className="min-w-0 pr-3">
                              <span className={cn("text-sm sm:text-base font-black leading-snug block mb-3 text-balance", isDark ? "text-white" : "text-slate-800")}>{opt.description}</span>
                              <div className="flex items-center gap-2 flex-wrap">
                                <span className="text-[10px] font-black text-emerald-500 uppercase tracking-tight bg-emerald-500/10 px-2.5 py-1 rounded-md">{opt.variant.rating}</span>
                                <span className="text-xs font-bold text-slate-400 uppercase tracking-tight">• Лучше на {improvement}</span>
                              </div>
                            </div>
                            <div className={cn("w-6 h-6 sm:w-7 sm:h-7 rounded-full flex items-center justify-center transition-all shrink-0 shadow-sm mt-0.5", isSelected ? "bg-indigo-500 text-white" : (isDark ? "bg-slate-800 text-transparent group-hover:text-slate-400" : "bg-slate-100 text-transparent group-hover:text-slate-400"))}>
                               <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M20 6L9 17l-5-5"/></svg>
                            </div>
                          </div>
                          
                          <div className="w-full flex flex-col gap-3 mt-4 pt-5 border-t border-slate-200/60 dark:border-slate-700/60">
                            {opt.variant.recipe.map((item, idx) => (
                              <div key={idx} className={cn("flex items-center justify-between text-sm font-bold w-full", isDark ? "text-slate-300" : "text-slate-600")}>
                                <div className="flex items-center gap-3 min-w-0 pr-4">
                                  <div className="w-5 h-5 rounded-full shrink-0 shadow-inner border border-black/10" style={{ background: `rgb(${item.rgb[0]},${item.rgb[1]},${item.rgb[2]})` }} />
                                  <span className="truncate leading-tight">{item.name}</span>
                                </div>
                                <span className="font-mono text-indigo-500 dark:text-indigo-400 shrink-0">{formatParts(item.parts, paintProfile)}</span>
                              </div>
                            ))}
                          </div>
                        </button>
                      );
                    })}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        <div className={cn("flex-shrink-0 flex flex-col-reverse sm:grid sm:grid-cols-2 gap-3 p-5 border-t", isDark ? "border-slate-800 bg-slate-900/80" : "border-slate-100 bg-slate-50/80")}>
           <button onClick={skipAll} className={cn("py-3.5 rounded-2xl text-xs font-black uppercase tracking-[0.1em] border-2 transition-all active:scale-95", isDark ? "bg-slate-800 border-slate-700 text-slate-300 hover:bg-slate-700" : "bg-white border-slate-100 text-slate-600 hover:bg-slate-100 shadow-sm")}>
             Пропустить
           </button>
           <button onClick={applyAndContinue} className="py-3.5 rounded-2xl text-xs font-black uppercase tracking-[0.2em] bg-indigo-600 text-white shadow-lg shadow-indigo-600/25 hover:bg-indigo-700 transition-all active:scale-[0.98] flex items-center justify-center gap-2.5">
             Продолжить
             <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M5 12h14m-7-7l7 7-7 7"/></svg>
           </button>
        </div>
      </div>
    </div>
  );
}

