// src/calib/surfaceTexture.ts
//
// Фактура реальной поверхности, снятая с фотографии.
//
// ЗАЧЕМ. Калибровочный бланк печатается на бумаге A4, поэтому по нему можно
// измерить поведение краски, но не фактуру холста: данных о холсте на листе
// просто нет. Чтобы показать работу на ТОЙ поверхности, на которой она будет
// написана, нужен отдельный снимок пустого её куска.
//
// ЧТО ИЗВЛЕКАЕТСЯ.
//   • карта высоты — та самая ткань, зерно или волокно, в виде плитки,
//     которой рендер укрывает всю картину;
//   • шаг структуры в миллиметрах — чтобы переплетение на экране имело тот же
//     размер, что и в жизни;
//   • глубина рельефа;
//   • вытянутость: у холста структура одинакова по обеим осям, у дерева
//     вытянута вдоль волокна;
//   • регулярность: у ткани строгая периодичность, у бумаги её нет вовсе.
//
// О МАСШТАБЕ. Определить по снимку, сколько в нём миллиметров, нельзя: камера
// не сообщает расстояние до объекта. Поэтому ширина снятого участка задаётся
// человеком одним числом. Ошибка даже в четверть здесь безобидна: она меняет
// видимый шаг переплетения, а не его характер.
//
// О СВЕТЕ. Снимок неизбежно освещён неравномерно, и градиент освещения на
// порядок сильнее самой фактуры. Поэтому первым делом вычитается сильно
// размытая копия: остаётся только то, что меняется быстро, то есть структура
// поверхности. Заодно это убирает разнотон самой ткани и тень от руки.

export interface SurfaceTexture {
  /** Сторона плитки в пикселях. */
  size: number;
  /**
   * Карта высоты, упакованная в байты: 128 — уровень поверхности,
   * 0 и 255 — крайние впадина и гребень.
   */
  tile: Uint8Array;
  /** Шаг структуры, мм. Ноль — периодичности не обнаружено. */
  periodMm: number;
  /**
   * Физический размер стороны плитки, мм. По нему рендер укладывает фактуру
   * на картину в натуральную величину: переплетение на экране должно иметь
   * тот же шаг, что и под рукой.
   */
  tileMm: number;
  /** Глубина рельефа, 0..1. */
  amplitude: number;
  /** Вытянутость структуры: 1 — одинакова по осям, больше — вдоль волокна. */
  anisotropy: number;
  /** Доля строгой периодичности против случайного зерна, 0..1. */
  regularity: number;
  /** Человеческое описание того, что распознано. */
  summary: string;
}

/** Сторона плитки. 192 — компромисс между узнаваемостью и объёмом хранения. */
const TILE = 192;

/* ── Вспомогательное ────────────────────────────────────────────────────────*/

function luminance(img: ImageData): Float32Array {
  const { data, width, height } = img;
  const out = new Float32Array(width * height);
  for (let i = 0, p = 0; p < out.length; p++, i += 4) {
    // Свет складывается линейно, поэтому и яркость берём линейную: в sRGB
    // одинаковый по глубине рельеф в тенях и в светах дал бы разную амплитуду.
    const r = data[i] / 255, g = data[i + 1] / 255, b = data[i + 2] / 255;
    const lr = r <= 0.04045 ? r / 12.92 : Math.pow((r + 0.055) / 1.055, 2.4);
    const lg = g <= 0.04045 ? g / 12.92 : Math.pow((g + 0.055) / 1.055, 2.4);
    const lb = b <= 0.04045 ? b / 12.92 : Math.pow((b + 0.055) / 1.055, 2.4);
    out[p] = 0.2126 * lr + 0.7152 * lg + 0.0722 * lb;
  }
  return out;
}

/** Прямоугольное размытие по разделяемым осям — два линейных прохода. */
function boxBlur(src: Float32Array, w: number, h: number, r: number): Float32Array {
  const tmp = new Float32Array(w * h);
  const out = new Float32Array(w * h);
  const win = 2 * r + 1;

  for (let y = 0; y < h; y++) {
    const row = y * w;
    let acc = 0;
    for (let x = -r; x <= r; x++) acc += src[row + Math.min(w - 1, Math.max(0, x))];
    for (let x = 0; x < w; x++) {
      tmp[row + x] = acc / win;
      acc += src[row + Math.min(w - 1, x + r + 1)] - src[row + Math.max(0, x - r)];
    }
  }
  for (let x = 0; x < w; x++) {
    let acc = 0;
    for (let y = -r; y <= r; y++) acc += tmp[Math.min(h - 1, Math.max(0, y)) * w + x];
    for (let y = 0; y < h; y++) {
      out[y * w + x] = acc / win;
      acc += tmp[Math.min(h - 1, y + r + 1) * w + x] - tmp[Math.max(0, y - r) * w + x];
    }
  }
  return out;
}

/**
 * Период по профилю средних значений.
 *
 * Нити переплетения идут вдоль осей, поэтому усреднение вдоль одной оси даёт
 * чистый периодический сигнал по другой. Это дешевле преобразования Фурье и
 * для нашей задачи точнее: интересует именно осевая структура ткани, а не
 * весь спектр.
 *
 * @returns шаг в пикселях и высота автокорреляционного пика 0..1
 */
function periodOf(profile: Float32Array): { period: number; strength: number } {
  const n = profile.length;
  if (n < 24) return { period: 0, strength: 0 };

  let mean = 0;
  for (let i = 0; i < n; i++) mean += profile[i];
  mean /= n;

  const c = new Float32Array(n);
  let energy = 0;
  for (let i = 0; i < n; i++) { c[i] = profile[i] - mean; energy += c[i] * c[i]; }
  if (energy < 1e-12) return { period: 0, strength: 0 };

  // Лаг меньше двух пикселей неотличим от шума матрицы, больше трети выборки
  // это уже не периодичность, а общий наклон.
  const maxLag = Math.min(Math.floor(n / 3), 128);
  const corr = new Float32Array(maxLag + 2);
  for (let lag = 1; lag <= maxLag; lag++) {
    let s = 0;
    for (let i = 0; i + lag < n; i++) s += c[i] * c[i + lag];
    corr[lag] = s / energy;
  }

  // Нужен ПЕРВЫЙ локальный максимум, а не наибольший. Автокорреляция строгой
  // структуры имеет пики на всех кратных периода, и у выраженного переплетения
  // второй или третий пик легко оказывается выше первого — взяв наибольший,
  // мы получили бы удвоенный шаг. Начинаем со второго лага: корреляция всегда
  // спадает от единицы, и первый настоящий подъём начинается после провала.
  let bestLag = 0, bestVal = 0;
  for (let lag = 2; lag < maxLag; lag++) {
    if (corr[lag] > corr[lag - 1] && corr[lag] >= corr[lag + 1] && corr[lag] > PERIOD_MIN_STRENGTH) {
      bestLag = lag; bestVal = corr[lag];
      break;
    }
  }
  if (!bestLag) return { period: 0, strength: 0 };

  // Уточнение вершины параболой по трём точкам: период редко приходится
  // ровно на целое число пикселей.
  const a = corr[bestLag - 1], b = corr[bestLag], cc = corr[bestLag + 1];
  const den = a - 2 * b + cc;
  const shift = Math.abs(den) > 1e-9 ? (0.5 * (a - cc)) / den : 0;
  const period = bestLag + Math.max(-0.5, Math.min(0.5, shift));

  return { period, strength: Math.max(0, Math.min(1, bestVal)) };
}

/**
 * Порог, ниже которого пик автокорреляции считается шумом.
 *
 * На чистом зерне без структуры остаточные пики доходят до 0,12, поэтому
 * планка стоит заметно выше: лучше сказать «структуры не найдено», чем
 * выдать случайное число за шаг переплетения.
 */
const PERIOD_MIN_STRENGTH = 0.2;

/** Робастный разброс: устойчив к пылинкам и бликам. */
function robustSpread(v: Float32Array): number {
  const a = Float32Array.from(v).sort();
  const lo = a[Math.floor(a.length * 0.16)];
  const hi = a[Math.floor(a.length * 0.84)];
  return (hi - lo) / 2;
}

/* ── Основная функция ───────────────────────────────────────────────────────*/

/**
 * Разбирает снимок пустого куска поверхности.
 *
 * @param img      снимок; годится любой кусок, лишь бы без краски и без теней
 * @param widthCm  ширина снятого участка в сантиметрах, со слов человека
 */
export function analyzeSurfacePhoto(img: ImageData, widthCm: number): SurfaceTexture {
  const W = img.width, H = img.height;
  const lum = luminance(img);

  // Отделяем фактуру от освещения. Радиус заведомо больше любого переплетения
  // и заведомо меньше градиента от лампы.
  //
  // Проходов три, а не один, и это не украшательство. Одиночное прямоугольное
  // размытие имеет ступенчатый спектр, и деление на него оставляет в остатке
  // собственную периодичность на масштабе окна. Проверка на чистом шуме без
  // всякой структуры показала ложный пик автокорреляции 0,37 — то есть
  // алгоритм «находил» переплетение там, где его не было. Три прохода дают
  // почти гауссово ядро, и на том же шуме остаётся 0,12.
  const r = Math.max(4, Math.round(Math.min(W, H) / 12));
  let base = boxBlur(lum, W, H, r);
  base = boxBlur(base, W, H, r);
  base = boxBlur(base, W, H, r);

  const detail = new Float32Array(W * H);
  for (let i = 0; i < detail.length; i++) {
    // Делим, а не вычитаем: фактура это модуляция отражения, и на тёмном
    // участке та же ткань даёт меньший абсолютный перепад, чем на светлом.
    detail[i] = base[i] > 1e-5 ? lum[i] / base[i] - 1 : 0;
  }

  const spread = robustSpread(detail);
  // Множитель подобран по реальным снимкам так, чтобы выраженная ткань давала
  // около 0,8, а гладкая бумага — около 0,3. Это шкала для рендера, а не
  // физическая высота в микронах: по одному снимку её не измерить.
  //
  // Величина зависит от того, под каким углом падал свет при съёмке: косой
  // свет подчёркивает рельеф, рассеянный сглаживает. Поэтому глубину имеет
  // смысл потом подправить ползунком выраженности, и это честнее, чем делать
  // вид, что снимок даёт абсолютное значение.
  const amplitude = Math.max(0, Math.min(1.2, spread * 8));

  // Профили средних. Усреднение вдоль оси гасит шум в корень из числа строк.
  const colProfile = new Float32Array(W);
  const rowProfile = new Float32Array(H);
  for (let y = 0; y < H; y++) {
    const row = y * W;
    let s = 0;
    for (let x = 0; x < W; x++) { colProfile[x] += detail[row + x]; s += detail[row + x]; }
    rowProfile[y] = s / W;
  }
  for (let x = 0; x < W; x++) colProfile[x] /= H;

  const px = periodOf(colProfile);
  const py = periodOf(rowProfile);

  const mmPerPx = (widthCm * 10) / W;
  const found = [px, py].filter(p => p.period > 0);

  // Шаг берём МЕНЬШИЙ из двух, а вытянутость — их отношение. Усреднять
  // периоды нельзя: у волокна вдоль и поперёк они различаются в разы, и
  // среднее не описывает ни одну из осей. На проверке волокно с шагом
  // 14 и 84 пикселя давало «49» — число, которого на снимке нет вовсе.
  const periodPx = found.length === 2
    ? Math.min(px.period, py.period)
    : found.length === 1 ? found[0].period : 0;
  const periodMm = periodPx * mmPerPx;
  const regularity = Math.max(px.strength, py.strength);

  // Вытянутость честно измеряется только когда структура читается по обеим
  // осям. Если по одной оси периодичности нет вовсе, это тоже вытянутость,
  // но её величину по автокорреляции не получить: берём умеренную оценку
  // и не выдаём её за измерение.
  const anisotropy = found.length === 2
    ? Math.max(px.period, py.period) / Math.max(1e-6, Math.min(px.period, py.period))
    : found.length === 1 ? 4 : 1;

  /* --- Плитка ----------------------------------------------------------- */

  // Берём центральный квадрат: у края кадра сильнее виньетка и расфокус.
  const side = Math.min(W, H);
  const ox = ((W - side) / 2) | 0, oy = ((H - side) / 2) | 0;
  const tile = new Uint8Array(TILE * TILE);
  const norm = spread > 1e-6 ? 1 / (spread * 3) : 0;

  for (let ty = 0; ty < TILE; ty++) {
    const sy2 = oy + Math.min(side - 1, Math.round((ty / TILE) * side));
    for (let tx = 0; tx < TILE; tx++) {
      const sx2 = ox + Math.min(side - 1, Math.round((tx / TILE) * side));
      const v = detail[sy2 * W + sx2] * norm;
      tile[ty * TILE + tx] = Math.max(0, Math.min(255, Math.round(128 + v * 127)));
    }
  }

  /* --- Описание --------------------------------------------------------- */

  let kind: string;
  if (regularity >= 0.35 && anisotropy < 2.2) kind = 'правильное переплетение, характерное для холста';
  else if (regularity >= 0.35) kind = 'вытянутая структура, характерная для дерева или грубого волокна';
  else if (amplitude < 0.12) kind = 'гладкая поверхность почти без рельефа';
  else kind = 'случайное зерно без правильной структуры, характерное для бумаги';

  const summary = periodMm > 0.05
    ? `Распознано: ${kind}. Шаг структуры ${periodMm.toFixed(2)} мм, глубина рельефа ${(amplitude * 100).toFixed(0)}%.`
    : `Распознано: ${kind}. Глубина рельефа ${(amplitude * 100).toFixed(0)}%.`;

  const tileMm = (side / W) * widthCm * 10;

  return { size: TILE, tile, periodMm, tileMm, amplitude, anisotropy, regularity, summary };
}

/* ── Хранение ───────────────────────────────────────────────────────────────
 *
 * Плитка держится в настройках как строка base64: 192×192 байта это 36 КБ,
 * в base64 около 49 КБ — в пределах разумного для локального хранилища,
 * и гораздо честнее, чем пересчитывать фактуру при каждом запуске.
 */

export function packTile(tile: Uint8Array): string {
  let s = '';
  for (let i = 0; i < tile.length; i++) s += String.fromCharCode(tile[i]);
  return typeof btoa === 'function' ? btoa(s) : Buffer.from(tile).toString('base64');
}

export function unpackTile(b64: string): Uint8Array {
  if (typeof atob === 'function') {
    const s = atob(b64);
    const out = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
    return out;
  }
  return new Uint8Array(Buffer.from(b64, 'base64'));
}
