import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import "./index.css";
import { App } from "./App";
import PWAProvider from "./PWAProvider";
import { ErrorBoundary } from "./components/ui/ErrorBoundary";

/**
 * Глубокая очистка кэшей файлов и IndexedDB.
 * LocalStorage уже очищен синхронно в index.html.
 */
function performFinalCleanup() {
  // 0. Снимаем регистрацию старых Service Worker'ов — без этого «залипший»
  //    старый SW продолжает контролировать страницу, и на Android не появляется
  //    вариант «Установить» (только ярлык). После сброса ставится свежий SW.
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.getRegistrations().then(regs => {
      for (const r of regs) r.unregister();
    }).catch(() => {});
  }

  // 1. Очистка Cache Storage (в фоне)
  if ('caches' in window) {
    caches.keys().then(names => {
      for (const name of names) caches.delete(name);
    });
  }

  // 2. Очистка IndexedDB (в фоне)
  if (window.indexedDB && window.indexedDB.databases) {
    window.indexedDB.databases().then(dbs => {
      for (const db of dbs) {
        if (db.name) window.indexedDB.deleteDatabase(db.name);
      }
    });
  }
  
  // 3. Очистка URL БЕЗ перезагрузки
  const url = new URL(window.location.href);
  url.searchParams.delete('clear_cache');
  url.searchParams.delete('v');
  window.history.replaceState({}, document.title, url.pathname);
}

/**
 * Автообновление: новый Service Worker (skipWaiting + clientsClaim) берёт
 * управление сразу после установки. По событию controllerchange один раз
 * перезагружаем страницу, чтобы применились свежие ассеты — без ручной чистки кэша.
 */
function setupAutoReloadOnUpdate() {
  if (!('serviceWorker' in navigator)) return;
  const hadController = !!navigator.serviceWorker.controller; // была ли уже версия
  let reloaded = false;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!hadController || reloaded) return; // самая первая установка — без перезагрузки
    reloaded = true;
    window.location.reload();
  });
}

function bootstrap() {
  setupAutoReloadOnUpdate();

  const params = new URLSearchParams(window.location.search);

  if (params.has('clear_cache')) {
    performFinalCleanup();
  }

  const container = document.getElementById("root");
  if (!container) return;
  const root = createRoot(container);

  // Лаборатория алгоритма: /Melura/?algolab=1 — изолированный инструмент
  // батч-проверки качества раскрасок. Грузится лениво (не влияет на бандл).
  if (params.has("algolab")) {
    import("./algolab/AlgoLab").then(({ default: AlgoLab }) => {
      root.render(
        <StrictMode>
          <ErrorBoundary>
            <AlgoLab />
          </ErrorBoundary>
        </StrictMode>
      );
    });
    return;
  }

  root.render(
    <StrictMode>
      <ErrorBoundary>
        <PWAProvider>
          <App />
        </PWAProvider>
      </ErrorBoundary>
    </StrictMode>
  );
}

bootstrap();
