// src/calib/flatField.ts
//
// Карта освещённости листа по чистой бумаге.
//
// Главный источник ошибки в «домашней» калибровке — вовсе не отсутствие серой
// карты, а неровный свет: лампа сбоку, тень от собственной руки, виньетирование
// объектива. Один и тот же мазок в углу листа и в центре снимается с разницей
// в 10–20 % яркости, и никакая точечная коррекция по одной серой точке это не
// чинит.
//
// Зато у нас есть эталон, который лежит по всему листу и ничего не стоит —
// сама бумага. Замеряем её в трёх десятках точек, вписываем гладкую поверхность
// (полином 2-й степени по каждому каналу) и делим изображение на неё. Так
// снимаются сразу и неравномерность света, и виньетка, и заодно получается
// баланс белого: после деления бумага становится ровно нейтральной.

import { srgbToLinear } from '../utils/colorMath';
import { paperProbePointsMm, PAPER_PROBE_R_MM, mmToPx } from './sheetSpec';

export interface FlatField {
  /** Локальный белый (линейный RGB, бумага = 1.0) в точке выпрямленного листа. */
  whiteAt: (px: number, py: number) => [number, number, number];
  /** Сколько опорных точек уцелело после отбраковки. */
  probesUsed: number;
  probesTotal: number;
  /** Разброс яркости бумаги по листу, % — насколько неровно лёг свет. */
  unevennessPct: number;
  /**
   * Доля точек бумаги, упёршихся в 255. Ноль-или-чуть — норма: под тёплой
   * лампой красный канал бумаги подходит к потолку почти всегда и ничему
   * не мешает. Тревожно становится, когда выбита заметная часть листа —
   * там оценка локального белого уже неверна.
   */
  clippedFraction: number;
}

interface Probe { x: number; y: number; lin: [number, number, number]; srgbMax: number }

function sampleDisc(img: ImageData, cx: number, cy: number, r: number): { lin: [number, number, number]; srgbMax: number } | null {
  const { data, width, height } = img;
  const x0 = Math.max(0, Math.round(cx - r)), x1 = Math.min(width - 1, Math.round(cx + r));
  const y0 = Math.max(0, Math.round(cy - r)), y1 = Math.min(height - 1, Math.round(cy + r));

  const vals: number[][] = [[], [], []];
  let maxSrgb = 0;
  const r2 = r * r;

  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      const dx = x - cx, dy = y - cy;
      if (dx * dx + dy * dy > r2) continue;
      const i = (y * width + x) * 4;
      if (data[i + 3] < 128) continue;
      for (let c = 0; c < 3; c++) { vals[c].push(data[i + c]); if (data[i + c] > maxSrgb) maxSrgb = data[i + c]; }
    }
  }
  if (vals[0].length < 5) return null;

  // Медиана, а не среднее: одна капля краски, попавшая на точку замера,
  // сдвинула бы среднее и «прогнула» бы всю карту освещённости.
  const med = (a: number[]) => { const s = [...a].sort((p, q) => p - q); return s[s.length >> 1]; };
  return {
    lin: [srgbToLinear(med(vals[0])), srgbToLinear(med(vals[1])), srgbToLinear(med(vals[2]))],
    srgbMax: maxSrgb,
  };
}

/** Метод наименьших квадратов для f(x,y)=a0+a1x+a2y+a3x²+a4xy+a5y². */
function fitQuadratic(pts: { x: number; y: number; v: number }[]): number[] | null {
  const n = 6;
  const ATA = Array.from({ length: n }, () => new Array(n).fill(0));
  const ATb = new Array(n).fill(0);

  for (const p of pts) {
    const b = [1, p.x, p.y, p.x * p.x, p.x * p.y, p.y * p.y];
    for (let i = 0; i < n; i++) {
      ATb[i] += b[i] * p.v;
      for (let j = 0; j < n; j++) ATA[i][j] += b[i] * b[j];
    }
  }

  // Крошечная регуляризация: если точки почти вырождены (все на одной линии),
  // система становится плохо обусловленной и решение «взрывается».
  for (let i = 0; i < n; i++) ATA[i][i] += 1e-9;

  const M = ATA.map((row, i) => [...row, ATb[i]]);
  for (let col = 0; col < n; col++) {
    let piv = col;
    for (let r = col + 1; r < n; r++) if (Math.abs(M[r][col]) > Math.abs(M[piv][col])) piv = r;
    if (Math.abs(M[piv][col]) < 1e-14) return null;
    [M[col], M[piv]] = [M[piv], M[col]];
    const d = M[col][col];
    for (let c = col; c <= n; c++) M[col][c] /= d;
    for (let r = 0; r < n; r++) {
      if (r === col) continue;
      const f = M[r][col];
      if (f === 0) continue;
      for (let c = col; c <= n; c++) M[r][c] -= f * M[col][c];
    }
  }
  return M.map(r => r[n]);
}

/**
 * Строит карту освещённости по выпрямленному листу.
 * @param rect выпрямленное изображение листа (RECTIFY_W × RECTIFY_H)
 */
export function buildFlatField(rect: ImageData): FlatField {
  const ptsMm = paperProbePointsMm();
  const r = mmToPx(PAPER_PROBE_R_MM);

  let probes: Probe[] = [];
  let clippedCount = 0;

  for (const p of ptsMm) {
    const s = sampleDisc(rect, mmToPx(p.x), mmToPx(p.y), r);
    if (!s) continue;
    if (s.srgbMax >= 252) clippedCount++;
    probes.push({ x: mmToPx(p.x), y: mmToPx(p.y), lin: s.lin, srgbMax: s.srgbMax });
  }

  const total = probes.length;

  // Отбраковка: точка, залитая краской или попавшая в тень от загнутого угла,
  // будет заметно темнее остальных. Считаем медиану яркости и выкидываем всё,
  // что ушло больше чем на 3 MAD вниз (вверх не трогаем — блик на бумаге
  // означает пересвет, о нём предупредим отдельно).
  if (probes.length >= 8) {
    const lums = probes.map(p => p.lin[0] * 0.2126 + p.lin[1] * 0.7152 + p.lin[2] * 0.0722);
    const sorted = [...lums].sort((a, b) => a - b);
    const med = sorted[sorted.length >> 1];
    const madArr = lums.map(v => Math.abs(v - med)).sort((a, b) => a - b);
    const mad = Math.max(1e-4, madArr[madArr.length >> 1]);
    probes = probes.filter((_, i) => lums[i] > med - 3 * mad);
  }

  const used = probes.length;

  let coeffs: (number[] | null)[] = [null, null, null];
  if (used >= 8) {
    for (let c = 0; c < 3; c++) {
      coeffs[c] = fitQuadratic(probes.map(p => ({ x: p.x, y: p.y, v: p.lin[c] })));
    }
  }

  // Запасной вариант: точек мало или полином не решился — используем
  // постоянный белый по медиане. Хуже, но лучше, чем ничего.
  const fallback: [number, number, number] = used > 0
    ? [0, 1, 2].map(c => {
        const s = probes.map(p => p.lin[c]).sort((a, b) => a - b);
        return Math.max(1e-3, s[s.length >> 1]);
      }) as [number, number, number]
    : [1, 1, 1];

  const evalAt = (co: number[], x: number, y: number) =>
    co[0] + co[1] * x + co[2] * y + co[3] * x * x + co[4] * x * y + co[5] * y * y;

  const whiteAt = (px: number, py: number): [number, number, number] => {
    const out: [number, number, number] = [0, 0, 0];
    for (let c = 0; c < 3; c++) {
      const co = coeffs[c];
      const v = co ? evalAt(co, px, py) : fallback[c];
      // Полином может уйти в минус за пределами облака точек — подстраховываемся.
      out[c] = Math.max(1e-3, Number.isFinite(v) ? v : fallback[c]);
    }
    return out;
  };

  let minL = Infinity, maxL = -Infinity;
  for (const p of probes) {
    const l = p.lin[0] * 0.2126 + p.lin[1] * 0.7152 + p.lin[2] * 0.0722;
    if (l < minL) minL = l;
    if (l > maxL) maxL = l;
  }
  const unevennessPct = used > 1 && maxL > 0 ? Math.round((1 - minL / maxL) * 100) : 0;

  return {
    whiteAt, probesUsed: used, probesTotal: total, unevennessPct,
    clippedFraction: total ? clippedCount / total : 0,
  };
}
