// src/generator/components/PreviewControls.tsx
import React, { useState } from "react";
import { useAppStore } from "../store";
import { cn } from "../../utils/cn";
import { ZoomBtn, VisualGridBtn } from "./ui/ToolButtons";

interface Props {
  doZoom: (f: number) => void;
  resetView: (force?: boolean) => void;
  flushViewSnapshotToStore: () => void;
  zoomTextRef: React.RefObject<HTMLDivElement | null>;
}

export function PreviewControls({ doZoom, resetView, flushViewSnapshotToStore, zoomTextRef }: Props) {
  const s = useAppStore();
  const hasImage = !!(s.originalImageUrl || s.correctedImageUrl);
  const hasRes = !!s.result;
  const hasOrig = !!s.originalImageUrl;
  const showCorrectionBtn = hasOrig && !hasRes;
  const hasCorrectionChanges =
    s.correction.brightness !== 0 ||
    s.correction.contrast !== 0 ||
    s.correction.saturation !== 0 ||
    s.correction.sharpness !== 0;
  const isPaintingMode = s.studioMode === "painting";
  const colorPickerActive = s.colorPickerActive;

  const [drawerOpen, setDrawerOpen] = useState(false);

  if (!hasImage) return null;

  return (
    <div data-overlay-controls className="pointer-events-none absolute inset-0 z-20 flex flex-col justify-between overflow-hidden p-2 sm:p-5">
      {/* ВЕРХНИЙ РЯД: Коррекция + Пипетка */}
      <div className="flex justify-between items-start w-full">
        {/* Инструменты определения цвета (пипетка/камера) перенесены в поле ввода
            калькулятора — на холсте их больше нет. Здесь только правый блок (коррекция). */}
        <div className="pointer-events-none" />

        <div className="pointer-events-auto flex flex-col gap-2 items-end">
          {showCorrectionBtn && (
            <button
              onClick={() => s.update({ mobileCorrectionOpen: !s.mobileCorrectionOpen })}
              className={cn(
                "lg:hidden flex items-center gap-2 px-4 h-11 rounded-3xl font-black text-xs uppercase tracking-wider shadow-xl transition-all border backdrop-blur-xl",
                s.mobileCorrectionOpen || hasCorrectionChanges
                  ? "bg-amber-500 text-white border-amber-400"
                  : "bg-white/95 dark:bg-gray-900/95 text-slate-700 dark:text-slate-300 border-slate-200/50 dark:border-slate-800/50 hover:bg-slate-50 dark:hover:bg-slate-800"
              )}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <circle cx="12" cy="12" r="10" />
                <path d="M12 2a10 10 0 0 1 0 20" fill="currentColor" opacity="0.3" />
                <line x1="12" y1="6" x2="12" y2="18" />
              </svg>
              Коррекция
            </button>
          )}
        </div>
      </div>

      {/* Баннер режима «пипетка»: понятная подсказка вместо одиноких кнопок */}
      {colorPickerActive && (
        <div className="pointer-events-auto absolute top-3 left-1/2 -translate-x-1/2 z-30 flex items-center gap-2 pl-3.5 pr-1.5 py-1.5 rounded-full bg-indigo-600 text-white shadow-xl shadow-indigo-600/30 max-w-[calc(100%-1.5rem)] animate-fade-in">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" className="shrink-0"><path d="M21.17 2.06a2.12 2.12 0 0 0-3.01 0l-1.41 1.41-1.06-1.06a1.5 1.5 0 0 0-2.12 0L12.16 3.82a1.5 1.5 0 0 0 0 2.12l1.06 1.06L4.64 15.59a2 2 0 0 0-.54 1l-.74 3.37a.5.5 0 0 0 .6.6l3.37-.74a2 2 0 0 0 1-.54L16.92 10.7l1.06 1.06a1.5 1.5 0 0 0 2.12 0l1.41-1.41a1.5 1.5 0 0 0 0-2.12L20.45 7.17l1.41-1.41a2.13 2.13 0 0 0-.69-3.7Z"/><path d="m6 16 2 2"/></svg>
          <span className="text-xs font-bold whitespace-nowrap">Коснитесь холста для выбора цвета</span>
          <button
            onClick={() => { s.update({ colorPickerActive: false, pickedColor: null, colorPickerPanelOpen: false }); flushViewSnapshotToStore(); }}
            aria-label="Отменить выбор цвета"
            className="ml-0.5 w-7 h-7 rounded-full bg-white/20 hover:bg-white/30 flex items-center justify-center shrink-0 active:scale-90 transition-colors"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>
          </button>
        </div>
      )}

      {/* СРЕДНИЙ РЯД: Сетки и Зум */}
      <div className="flex justify-between items-end md:items-center w-full mt-auto mb-4 md:mb-0 md:mt-0 pointer-events-none">
        
        {/* ── Mobile: Collapsible drawer ── */}
        <div className="sm:hidden pointer-events-auto flex items-end gap-1.5">
          {/* Toggle pill button */}
          <button
            onClick={() => setDrawerOpen(!drawerOpen)}
            className={cn(
              "w-10 h-10 rounded-xl flex items-center justify-center shadow-lg border backdrop-blur-xl transition-all duration-300 active:scale-90 shrink-0 z-10",
              drawerOpen
                ? "bg-indigo-600 border-indigo-500 text-white shadow-indigo-500/25"
                : "bg-white/80 dark:bg-gray-900/80 border-gray-200/50 dark:border-gray-700/50 text-slate-500 dark:text-slate-400"
            )}
            aria-label={drawerOpen ? "Скрыть панель" : "Показать панель"}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <polygon points="12 2 2 7 12 12 22 7 12 2"/><polyline points="2 17 12 22 22 17"/><polyline points="2 12 12 17 22 12"/>
            </svg>
          </button>

          {/* Expandable controls panel */}
          <div
            className={cn(
              "flex flex-row gap-1 p-1 rounded-2xl shadow-lg border backdrop-blur-xl bg-white/70 dark:bg-gray-900/70 dark:border-gray-700/50 border-gray-200/50 overflow-hidden transition-all duration-300 ease-out origin-left",
              drawerOpen 
                ? "max-w-[500px] opacity-100 scale-100" 
                : "max-w-0 opacity-0 scale-95 p-0 border-transparent shadow-none"
            )}
          >
            <VisualGridBtn 
              active={s.showContours} 
              onClick={() => { s.update({ showContours: !s.showContours }); flushViewSnapshotToStore(); }} 
              title="Контуры зон"
              icon={<circle cx="12" cy="12" r="8.5" strokeDasharray="4 4" />}
            />
            <VisualGridBtn 
              active={s.showNumbers} 
              onClick={() => { s.update({ showNumbers: !s.showNumbers }); flushViewSnapshotToStore(); }} 
              title="Номера красок"
              icon={<><circle cx="12" cy="12" r="8.5" /><text x="12" y="12" dominantBaseline="central" fontSize="11" fontWeight="900" fontFamily="sans-serif" textAnchor="middle" fill="currentColor" stroke="none">1</text></>}
            />
            <VisualGridBtn 
              active={s.activeColors.size > 0} 
              onClick={() => { s.toggleAllColors(); flushViewSnapshotToStore(); }} 
              title="Заливка цветом"
              icon={<><path d="M12 22a7 7 0 0 0 7-7c0-2-1-3.9-3-5.5s-3.5-4-4-6.5c-.5 2.5-2 4.9-4 6.5C6 11.1 5 13 5 15a7 7 0 0 0 7 7z" fill="currentColor" stroke="none" /></>}
            />
            <div className="w-px h-6 my-auto bg-slate-200 dark:bg-slate-700 shrink-0" />
            <VisualGridBtn 
              active={s.gridType === "thirds"} 
              onClick={() => { s.setGridType(s.gridType === "thirds" ? "none" : "thirds"); flushViewSnapshotToStore(); }} 
              title="Правило третей"
              icon={<><line x1="8" y1="4" x2="8" y2="20"/><line x1="16" y1="4" x2="16" y2="20"/><line x1="4" y1="8" x2="20" y2="8"/><line x1="4" y1="16" x2="20" y2="16"/></>}
            />
            <VisualGridBtn 
              active={s.gridType === "golden"} 
              onClick={() => { s.setGridType(s.gridType === "golden" ? "none" : "golden"); flushViewSnapshotToStore(); }} 
              title="Золотое сечение"
              icon={<><line x1="9" y1="4" x2="9" y2="20" opacity="0.9"/><line x1="15" y1="4" x2="15" y2="20" opacity="0.9"/><line x1="4" y1="9" x2="20" y2="9" opacity="0.9"/><line x1="4" y1="15" x2="20" y2="15" opacity="0.9"/></>}
            />
            <VisualGridBtn 
              active={s.gridType === "grid"} 
              onClick={() => { s.setGridType(s.gridType === "grid" ? "none" : "grid"); flushViewSnapshotToStore(); }} 
              title="Сетка"
              icon={<><path d="M4 4h16v16H4z" opacity="0.1"/><path d="M8 4v16M12 4v16M16 4v16M4 8h16M4 12h16M4 16h16" strokeWidth="1.2"/></>}
            />
            <div className="w-px h-6 my-auto bg-slate-200 dark:bg-slate-700 shrink-0" />
            <ZoomBtn icon={<><path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3" /></>} onClick={() => doZoom(-1)} title="На весь экран" />
            <ZoomBtn icon={<path d="M7 10L3 14l4 4M17 10l4 4-4 4M12 3v18" />} onClick={() => { s.toggleFlip(); flushViewSnapshotToStore(); }} title="Отразить" />
          </div>
        </div>

        {/* ── Desktop: Always visible columns ── */}
        <div className="pointer-events-auto hidden sm:flex flex-col gap-1.5 p-1.5 rounded-3xl shadow-xl border backdrop-blur-xl bg-white/95 dark:bg-gray-900/95 dark:border-gray-700/50 border-gray-200/50">
           <VisualGridBtn 
             active={s.showContours} 
             onClick={() => { s.update({ showContours: !s.showContours }); flushViewSnapshotToStore(); }} 
             title="Контуры зон"
             icon={<circle cx="12" cy="12" r="8.5" strokeDasharray="4 4" />}
           />
           <VisualGridBtn 
             active={s.showNumbers} 
             onClick={() => { s.update({ showNumbers: !s.showNumbers }); flushViewSnapshotToStore(); }} 
             title="Номера красок"
             icon={<><circle cx="12" cy="12" r="8.5" /><text x="12" y="12" dominantBaseline="central" fontSize="11" fontWeight="900" fontFamily="sans-serif" textAnchor="middle" fill="currentColor" stroke="none">1</text></>}
           />
           <VisualGridBtn 
             active={s.activeColors.size > 0} 
             onClick={() => { s.toggleAllColors(); flushViewSnapshotToStore(); }} 
             title="Заливка цветом"
             icon={<><path d="M12 22a7 7 0 0 0 7-7c0-2-1-3.9-3-5.5s-3.5-4-4-6.5c-.5 2.5-2 4.9-4 6.5C6 11.1 5 13 5 15a7 7 0 0 0 7 7z" fill="currentColor" stroke="none" /></>}
           />
           <div className="w-6 h-px mx-auto bg-slate-100 dark:bg-slate-800 my-0.5" />
           <VisualGridBtn 
             active={s.gridType === "thirds"} 
             onClick={() => { s.setGridType(s.gridType === "thirds" ? "none" : "thirds"); flushViewSnapshotToStore(); }} 
             title="Правило третей (3х3)"
             icon={<><line x1="8" y1="4" x2="8" y2="20"/><line x1="16" y1="4" x2="16" y2="20"/><line x1="4" y1="8" x2="20" y2="8"/><line x1="4" y1="16" x2="20" y2="16"/></>}
           />
           <VisualGridBtn 
             active={s.gridType === "golden"} 
             onClick={() => { s.setGridType(s.gridType === "golden" ? "none" : "golden"); flushViewSnapshotToStore(); }} 
             title="Золотое сечение (Фи)"
             icon={<><line x1="9" y1="4" x2="9" y2="20" opacity="0.9"/><line x1="15" y1="4" x2="15" y2="20" opacity="0.9"/><line x1="4" y1="9" x2="20" y2="9" opacity="0.9"/><line x1="4" y1="15" x2="20" y2="15" opacity="0.9"/></>}
           />
           <VisualGridBtn 
             active={s.gridType === "grid"} 
             onClick={() => { s.setGridType(s.gridType === "grid" ? "none" : "grid"); flushViewSnapshotToStore(); }} 
             title="Квадраты (Сетка)"
             icon={<><path d="M4 4h16v16H4z" opacity="0.1"/><path d="M8 4v16M12 4v16M16 4v16M4 8h16M4 12h16M4 16h16" strokeWidth="1.2"/></>}
           />
        </div>

        <div className="pointer-events-auto hidden sm:flex flex-col gap-1 p-1.5 rounded-3xl shadow-xl border backdrop-blur-xl bg-white/95 dark:bg-gray-900/95 dark:border-gray-700/50 border-gray-200/50 items-center">
          <ZoomBtn icon={<path d="M12 5v14M5 12h14" />} onClick={() => doZoom(1.3)} title="Увеличить" />
          <ZoomBtn icon={<path d="M5 12h14" />} onClick={() => doZoom(0.77)} title="Уменьшить" />
          <div className="h-px w-6 mx-auto bg-slate-200 dark:bg-slate-800 my-1" />
          <ZoomBtn icon={<><circle cx="12" cy="12" r="10" /><path d="M12 8v8" /><path d="M8 12h8" /></>} onClick={() => { resetView(true); flushViewSnapshotToStore(); }} title="Сбросить (1:1)" />
          <ZoomBtn icon={<><path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3" /></>} onClick={() => doZoom(-1)} title="На весь экран" />
          <div className="h-px w-6 mx-auto bg-slate-200 dark:bg-slate-800 my-1" />
          <ZoomBtn 
            icon={<path d="M7 10L3 14l4 4M17 10l4 4-4 4M12 3v18" />} 
            onClick={() => { s.toggleFlip(); flushViewSnapshotToStore(); }} 
            title="Отразить холст (F)" 
          />
          <div ref={zoomTextRef} className="text-xs font-black font-mono text-center pt-1 text-slate-500 dark:text-slate-300 tabular-nums">100%</div>
        </div>
      </div>

      {/* НИЖНИЙ РЯД: Только этапы для Академии */}
      <div className="flex flex-col items-center gap-2 pointer-events-auto mb-2 md:mb-0">
        {hasRes && isPaintingMode && (
          <div className="flex p-1 sm:p-1.5 rounded-2xl sm:rounded-3xl shadow-xl border backdrop-blur-xl overflow-x-auto scrollbar-none bg-white/70 sm:bg-white/95 dark:bg-slate-900/70 sm:dark:bg-slate-900/90 border-slate-200/50 dark:border-slate-800/50 max-w-full">
            {[
              { step: 0, label: "Контуры" },
              { step: 1, label: "Подмалёвок" },
              { step: 10, label: "Температура", isTemp: true },
              { step: 3, label: "Цвета" },
              { step: 4, label: "Детали" },
            ].map((btn) => {
              const isActive = btn.isTemp ? s.showTemperatureMap : (s.paintingLayer === btn.step && !s.showTemperatureMap);
              
              return (
                <button
                  key={btn.step}
                  onClick={() => {
                    if (btn.isTemp) {
                      const next = !s.showTemperatureMap;
                      s.update({ showTemperatureMap: next, paintingLayer: next ? -1 : s.paintingLayer === -1 ? 1 : s.paintingLayer });
                      flushViewSnapshotToStore();
                    } else {
                      if (s.showTemperatureMap) s.update({ showTemperatureMap: false });
                      flushViewSnapshotToStore();
                      s.setPaintingLayerAnimated(btn.step);
                    }
                  }}
                  className={cn(
                    "px-3 sm:px-4 py-2 sm:py-2.5 rounded-xl text-[11px] sm:text-xs font-black transition-all whitespace-nowrap uppercase tracking-wider",
                    isActive
                      ? "bg-indigo-600 text-white shadow-lg shadow-indigo-500/30 scale-105"
                      : "text-slate-600 dark:text-slate-200 hover:text-indigo-600 dark:hover:text-indigo-400 hover:bg-slate-100 dark:hover:bg-slate-800"
                  )}
                >
                  {btn.label}
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
