// src/generator/utils/svgBundle.ts
//
// Сборка архива SVG: одна схема даёт набор векторных файлов под разные задачи.
// Прежний экспорт отдавал один файл (текущее состояние холста), и под каждый
// сценарий (печать раскраски, резка трафарета, эталон для заказчика) настройки
// приходилось переключать вручную и экспортировать заново.

import { generateSVGContent, type ProcessingResult } from "./imageProcessing";
import { createZip, type ZipEntry } from "./zip";
import type { ArtisticPresetId, RGB } from "../../config";

export interface SvgBundleParams {
  res: ProcessingResult;
  contourWeight: number;
  numberWeight: number;
  isArtistic: boolean;
  artisticPresetId?: ArtisticPresetId;
  notanLevels: number;
  notanThreshold: number;
  artIntensity: number;
  customArtPalette?: RGB[];
  onProgress?: (msg: string, pct: number) => void;
}

interface VariantSpec {
  file: string;
  /** Описание назначения файла для сопроводительной записки. */
  about: string;
  colored: boolean;
  showNums: boolean;
  showContours: boolean;
  transparentBg?: boolean;
  artisticStep?: number;
}

// Режим «по номерам». Порядок = порядок в архиве, имена с цифрой впереди,
// чтобы файловый менеджер показывал их в осмысленной последовательности.
const PBN_VARIANTS: VariantSpec[] = [
  {
    file: "1_раскраска_контуры+номера.svg",
    about: "Основной файл для печати: белый фон, контуры зон и номера.",
    colored: true, showNums: true, showContours: true,
  },
  {
    file: "2_контуры_без_номеров.svg",
    about: "Только контуры. Применяется для переноса рисунка на холст и для работы без нумерации.",
    colored: false, showNums: false, showContours: true,
  },
  {
    file: "3_контуры_прозрачный_фон.svg",
    about: "Контуры на прозрачном фоне. Предназначен для наложения слоем в графическом редакторе.",
    colored: false, showNums: false, showContours: true, transparentBg: true,
  },
  {
    file: "4_эталон_цвет+контуры+номера.svg",
    about: "Цветной эталон с контурами и нумерацией. Используется как образец в процессе работы.",
    colored: true, showNums: true, showContours: true,
  },
  {
    file: "5_эталон_цвет+контуры.svg",
    about: "Цветной эталон с контурами без нумерации. Пригоден для демонстрации заказчику.",
    colored: true, showNums: false, showContours: true,
  },
  {
    file: "6_заливка_без_контуров.svg",
    about: "Только цветовые заливки, без контуров. Исходник для режущего плоттера, трафарета и шелкографии.",
    colored: true, showNums: false, showContours: false,
  },
];

// Режим художника: варианты — это шаги практикума, а не комбинации слоёв.
const ART_VARIANTS: VariantSpec[] = [
  {
    file: "1_эскиз_линии.svg",
    about: "Этап 1. Композиция: линии построения.",
    colored: false, showNums: false, showContours: true, artisticStep: 0,
  },
  {
    file: "2_нотан_светотень.svg",
    about: "Этап 2. Светотеневой разбор для проверки тональной композиции.",
    colored: true, showNums: false, showContours: false, artisticStep: 1,
  },
  {
    file: "3_цветовая_база.svg",
    about: "Этап 3. Стилизованная цветовая база.",
    colored: true, showNums: false, showContours: false, artisticStep: 2,
  },
  {
    file: "4_детали_прозрачный_фон.svg",
    about: "Этап 4. Детализация: контуры на прозрачном фоне для наложения слоем.",
    colored: false, showNums: false, showContours: true, artisticStep: 3, transparentBg: true,
  },
];

function buildReadme(variants: VariantSpec[], isArtistic: boolean, w: number, h: number): string {
  const lines = [
    "MELURA. Векторный экспорт",
    "=========================",
    "",
    `Режим: ${isArtistic ? "арт-практикум" : "раскраска по номерам"}`,
    `Размер изображения: ${w} × ${h}`,
    "",
    "Состав архива:",
    "",
  ];
  for (const v of variants) lines.push(`  ${v.file}`, `      ${v.about}`, "");
  lines.push(
    "Открытие файлов:",
    "  Просмотр: любой веб-браузер.",
    "  Редактирование: Inkscape, Adobe Illustrator, CorelDRAW, Figma.",
    "",
    "Формат SVG является векторным: изображение масштабируется без потери",
    "качества и пригодно для печати в любом формате.",
    "",
  );
  return lines.join("\r\n"); // CRLF — чтобы «Блокнот» в Windows не слепил всё в одну строку
}

/**
 * Генерирует все варианты SVG и упаковывает их в ZIP.
 * Воркер обрабатывает по одной задаче за раз, поэтому варианты идут строго
 * последовательно — прогресс считаем по числу готовых файлов.
 */
export async function buildSvgBundle(params: SvgBundleParams): Promise<Blob> {
  const {
    res, contourWeight, numberWeight, isArtistic, artisticPresetId,
    notanLevels, notanThreshold, artIntensity, customArtPalette, onProgress,
  } = params;

  const variants = isArtistic ? ART_VARIANTS : PBN_VARIANTS;

  // Для цветных вариантов подсвечиваем ВСЕ зоны, а не текущий выбор на холсте:
  // архив должен быть самодостаточным и не зависеть от того, что было включено
  // в редакторе в момент нажатия кнопки.
  const allLabels = new Set<number>(res.validLabels);

  const entries: ZipEntry[] = [];

  for (let i = 0; i < variants.length; i++) {
    const v = variants[i];
    onProgress?.(`Подготовка варианта ${i + 1} из ${variants.length}`, 10 + Math.round((i / variants.length) * 80));

    const svg = await generateSVGContent(
      res,
      contourWeight,
      numberWeight,
      v.colored,
      v.colored ? allLabels : new Set<number>(),
      v.showNums,
      isArtistic,
      v.artisticStep ?? 0,
      artisticPresetId,
      notanLevels,
      notanThreshold,
      artIntensity,
      customArtPalette,
      { showContours: v.showContours, transparentBg: v.transparentBg },
    );

    entries.push({ name: v.file, data: svg });
  }

  entries.push({
    name: "Описание_файлов.txt",
    data: buildReadme(variants, isArtistic, res.imgW, res.imgH),
  });

  onProgress?.("Формирование архива", 92);
  return createZip(entries);
}
