// src/generator/GeneratorModal.tsx
import { useAppStore } from "./store";
import { Toolbar } from "./components/ToolBar";
import { PreviewPanel } from "./components/PreviewPanel";
import { PalettePanel } from "./components/PalettePanel";
import { SettingsPanel } from "./components/SettingsPanel";
import { CalculatorBottomSheet } from "./components/CalculatorBottomSheet";
import { SettingsBottomSheet } from "./components/SettingsBottomSheet";
import { CropModal } from "./components/CropModal";
import { UrlModal } from "./components/UrlModal";
import { ARCameraModal } from "./components/ARCameraModal";
import { ExportModal } from "./components/ExportModal";
import { HistoryModal } from "./components/HistoryModal";
import { OptimizationModal } from "./components/OptimizationModal";
import { useAppStore as useMainAppStore } from "../store/appStore";
import { HuePickerDialog } from "./components/HuePickerDialog";
import { ErrorBoundary } from "../components/ui/ErrorBoundary";
import { cn } from "../utils/cn";
import { useGeneratorLogic } from "./hooks/useGeneratorLogic";

import { EXTENDED_COLORS } from "../config";

export default function GeneratorModal({
  isOpen,
  isDark,
}: {
  isOpen: boolean;
  onClose: () => void;
  isDark: boolean;
}) {
  const isProcessing = useAppStore((s) => s.isProcessing);
  const isExporting = useAppStore((s) => s.isExporting);
  const progress = useAppStore((s) => s.progress);
  const hasResult = useAppStore((s) => !!s.result);
  const studioMode = useAppStore((s) => s.studioMode);
  const update = useAppStore((s) => s.update);
  const exportModalOpen = useAppStore((s) => s.exportModalOpen);

  const engineSettings = useMainAppStore((s) => s.engineSettings);
  const customColors = useMainAppStore((s) => s.customColors);
  const selectedNames = useMainAppStore((s) => s.selectedNames);
  const overrides = useMainAppStore((s) => s.overrides);
  const totalPartsLimit = useMainAppStore((s) => s.totalPartsLimit);
  const deletedBuiltIns = useMainAppStore((s) => s.deletedBuiltIns);

  const calculateRecipeApproximations = useAppStore(s => s.calculateRecipeApproximations);

  const { loadImage, cancelProcessing } = useGeneratorLogic(isOpen, isDark);



  const handleContinueOptimization = () => {
    update({ optimizationData: [] });

    const ext = EXTENDED_COLORS.filter((c) => !deletedBuiltIns.includes(c.name));
    const allAvailableColors = [...ext, ...customColors].map((c) => ({
      ...c,
      rgb: overrides[c.name] || c.rgb,
    }));
    const activeComps = allAvailableColors.filter(c => selectedNames.includes(c.name));

    calculateRecipeApproximations(engineSettings, activeComps, String(totalPartsLimit), true);
  };

  return (
    <div
      className={cn(
        "flex-1 flex flex-col min-h-0 bg-white dark:bg-slate-900 relative animate-fade-in-up w-full h-full",
        isOpen ? "flex" : "hidden"
      )}
    >
      <ErrorBoundary>
        {(isProcessing || isExporting) && (
          <div
            className="absolute top-0 left-0 right-0 h-1 z-[50] bg-slate-200 dark:bg-slate-800"
            role="progressbar"
            aria-label="Прогресс"
            aria-valuenow={progress}
            aria-valuemin={0}
            aria-valuemax={100}
          >
            <div className="h-full bg-indigo-500 transition-all duration-300 rounded-r-full" style={{ width: `${progress}%` }} />
          </div>
        )}

        <Toolbar
          onLoadImage={loadImage}
          onCancel={cancelProcessing}
          onExport={() => update({ exportModalOpen: true })}
          hasResult={hasResult}
        />

        <div className={cn(
          "flex-1 flex min-h-0 relative w-full overflow-hidden flex-col md:flex-row"
        )}>
          <div className={cn(
            "flex flex-col min-w-0 min-h-0 w-full relative flex-1 overflow-hidden"
          )}>
            <PreviewPanel onLoadImage={loadImage} />
            {hasResult && studioMode !== "painting" && <PalettePanel />}
          </div>

          {/* Desktop: sidebar (на мобиле настройки — в выезжающем листе ниже) */}
          <SettingsPanel />
        </div>
        <SettingsBottomSheet />
        <CalculatorBottomSheet />
        <CropModal />
        <UrlModal onLoadImage={loadImage} />
        <ARCameraModal />
        <ExportModal />
        <HistoryModal />
        <HuePickerDialog />
        {!exportModalOpen && <OptimizationModal onContinue={handleContinueOptimization} paintType={engineSettings.paintType} />}
      </ErrorBoundary>
    </div>
  );
}
