import { ImageSegmenter, FaceLandmarker, FilesetResolver } from "@mediapipe/tasks-vision";

export interface SemanticMasks {
  segmentationMask: Uint8Array | null; // 2D array mapped to 1D, where each pixel is a class ID (0-5)
  segmentationWidth: number;
  segmentationHeight: number;
  // Массив ЛИЦ; каждое лицо — массив из 468 3D-точек. Поддерживаем несколько лиц.
  faceLandmarks: Array<Array<{ x: number, y: number, z: number }>> | null;
}

class MediaPipeService {
  private segmenter: ImageSegmenter | null = null;
  private faceLandmarker: FaceLandmarker | null = null;
  private isInitializing = false;
  private initPromise: Promise<void> | null = null;

  async initialize() {
    if (this.initPromise) {
      return this.initPromise;
    }
    
    this.isInitializing = true;
    this.initPromise = (async () => {
      try {
        const baseUrl = import.meta.env.BASE_URL || "/";
        const basePath = baseUrl.endsWith("/") ? baseUrl.slice(0, -1) : baseUrl;
        
        const vision = await FilesetResolver.forVisionTasks(`${basePath}/ai/wasm`);

        // 1. Initialize Selfie Multiclass Segmenter
        // Classes: 0: background, 1: hair, 2: body-skin, 3: face-skin, 4: clothes, 5: accessories
        this.segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: `${basePath}/ai/selfie_multiclass.tflite`,
            delegate: "GPU",
          },
          runningMode: "IMAGE",
          outputCategoryMask: true,
          outputConfidenceMasks: false,
        });

        // 2. Initialize Face Landmarker (468 points)
        this.faceLandmarker = await FaceLandmarker.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: `${basePath}/ai/face_landmarker.task`,
            delegate: "GPU",
          },
          runningMode: "IMAGE",
          numFaces: 5, // Несколько лиц: в кадре может быть больше одного «главного».
          outputFaceBlendshapes: false,
        });

        console.log("[AI] MediaPipe Models Initialized Successfully");
      } catch (error) {
        console.error("[AI] Failed to initialize MediaPipe models:", error);
        throw error;
      } finally {
        this.isInitializing = false;
      }
    })();

    return this.initPromise;
  }

  async processImage(imageSource: HTMLImageElement | HTMLCanvasElement | ImageData): Promise<SemanticMasks> {
    if (!this.segmenter || !this.faceLandmarker) {
      await this.initialize();
    }

    let segmentationMask: Uint8Array | null = null;
    let segmentationWidth = 0;
    let segmentationHeight = 0;
    let faceLandmarks: Array<Array<{ x: number, y: number, z: number }>> | null = null;

    try {
      // Run Segmentation
      if (this.segmenter) {
        const segmentResult = this.segmenter.segment(imageSource);
        if (segmentResult.categoryMask) {
          const mask = segmentResult.categoryMask;
          // Копируем данные в обычный массив
          const maskData = mask.getAsUint8Array();
          segmentationMask = new Uint8Array(maskData); // Явная копия
          segmentationWidth = mask.width;
          segmentationHeight = mask.height;
          // ВАЖНО: Освобождаем память WebAssembly, иначе будет утечка!
          if (typeof mask.close === 'function') {
            mask.close();
          }
        }
      }

      // Run Face Landmarks
      if (this.faceLandmarker) {
        const faceResult = this.faceLandmarker.detect(imageSource);
        if (faceResult.faceLandmarks && faceResult.faceLandmarks.length > 0) {
          faceLandmarks = faceResult.faceLandmarks; // ВСЕ найденные лица (массив лиц).
        }
      }
    } catch (e) {
      console.warn("[AI] Error processing image with MediaPipe:", e);
    }

    return {
      segmentationMask,
      segmentationWidth,
      segmentationHeight,
      faceLandmarks
    };
  }
}

export const aiEngine = new MediaPipeService();
