// src/generator/utils/imageProcessing/faceEnhance.ts
// Активное «оживление» лиц ДО квантизации. Дальние/тусклые лица при честной
// квантизации выходят серыми, плоскими и с «дырами» вместо глаз. Здесь мы, по
// маске сегментации MediaPipe, возвращаем коже тёплый живой тон и локальный
// контраст (моделировку), а глаза/брови (тёмные детали на лице) слегка
// проявляем — чтобы результат был живым при ЛЮБОМ пресете.
//
// Классы selfie_multiclass: 0 фон, 1 волосы, 2 кожа-тела, 3 кожа-лица,
// 4 одежда, 5 аксессуары.

function boxBlurRGB(data: Uint8ClampedArray, w: number, h: number, radius: number): Float32Array {
  const n = w * h;
  const tmp = new Float32Array(n * 3);
  const out = new Float32Array(n * 3);
  // horizontal
  for (let y = 0; y < h; y++) {
    for (let c = 0; c < 3; c++) {
      let sum = 0;
      const row = y * w;
      for (let x = -radius; x <= radius; x++) sum += data[(row + Math.max(0, Math.min(w - 1, x))) * 4 + c];
      const width = 2 * radius + 1;
      tmp[(row) * 3 + c] = sum / width;
      for (let x = 1; x < w; x++) {
        sum += data[(row + Math.min(w - 1, x + radius)) * 4 + c] - data[(row + Math.max(0, x - radius - 1)) * 4 + c];
        tmp[(row + x) * 3 + c] = sum / width;
      }
    }
  }
  // vertical
  const width = 2 * radius + 1;
  for (let x = 0; x < w; x++) {
    for (let c = 0; c < 3; c++) {
      let sum = 0;
      for (let y = -radius; y <= radius; y++) sum += tmp[(Math.max(0, Math.min(h - 1, y)) * w + x) * 3 + c];
      out[(x) * 3 + c] = sum / width;
      for (let y = 1; y < h; y++) {
        sum += tmp[(Math.min(h - 1, y + radius) * w + x) * 3 + c] - tmp[(Math.max(0, y - radius - 1) * w + x) * 3 + c];
        out[(y * w + x) * 3 + c] = sum / width;
      }
    }
  }
  return out;
}

export interface FaceEnhanceInput {
  imageData: ImageData;
  segmentationMask: Uint8Array | null;
  segmentationWidth: number;
  segmentationHeight: number;
}

/** Модифицирует imageData НА МЕСТЕ: оживляет кожу лица/тела. */
export function enhanceFaces(input: FaceEnhanceInput): void {
  const { imageData, segmentationMask, segmentationWidth: sw, segmentationHeight: sh } = input;
  if (!segmentationMask || sw === 0 || sh === 0) return;
  const { data, width: w, height: h } = imageData;

  // Есть ли вообще кожа лица? Если нет — не трогаем (не портрет).
  let skinCount = 0;
  for (let i = 0; i < segmentationMask.length; i++) {
    const c = segmentationMask[i];
    if (c === 2 || c === 3) skinCount++;
  }
  if (skinCount < segmentationMask.length * 0.01) return;

  // Радиус локального контраста ~ 0.9% от стороны (моделировка объёма лица).
  const radius = Math.max(3, Math.round(Math.min(w, h) * 0.012));
  const blur = boxBlurRGB(data, w, h, radius);

  const scaleX = sw / w, scaleY = sh / h;
  const UNSHARP = 0.40;   // моделировка (мягче, чтобы не было жёстких пятен на низких пресетах)
  const SAT = 1.20;       // насыщенность кожи
  const WARM = 1.05;      // тёплый сдвиг (R вверх, B вниз)

  for (let y = 0; y < h; y++) {
    const sy = Math.min(sh - 1, (y * scaleY) | 0);
    for (let x = 0; x < w; x++) {
      const sx = Math.min(sw - 1, (x * scaleX) | 0);
      const cls = segmentationMask[sy * sw + sx];
      const isSkin = cls === 2 || cls === 3;
      if (!isSkin) continue;

      const p = (y * w + x) * 4;
      const b3 = (y * w + x) * 3;
      let r = data[p], g = data[p + 1], bch = data[p + 2];

      // 1) Локальный контраст (unsharp) — возвращает моделировку, съеденную сглаживанием.
      r = r + (r - blur[b3]) * UNSHARP;
      g = g + (g - blur[b3 + 1]) * UNSHARP;
      bch = bch + (bch - blur[b3 + 2]) * UNSHARP;

      // 2) Насыщенность вокруг средней серой (живость кожи).
      const mean = (r + g + bch) / 3;
      r = mean + (r - mean) * SAT;
      g = mean + (g - mean) * SAT;
      bch = mean + (bch - mean) * SAT;

      // 3) Тёплый сдвиг.
      r *= WARM;
      bch /= WARM;

      data[p] = r < 0 ? 0 : r > 255 ? 255 : r;
      data[p + 1] = g < 0 ? 0 : g > 255 ? 255 : g;
      data[p + 2] = bch < 0 ? 0 : bch > 255 ? 255 : bch;
    }
  }
}

