import type { RGB, ColorComponent, PaintProfile } from '../config';
import { mixColors, mixLinearRgb, mixKubelkaMunk } from '../utils/mixing';
import { calculateDryColor } from '../lab/core';
import { rgbToLab, deltaE00 } from '../utils/colorMath';
import type { RecipeItem, RecipeVariant, SolverCandidate } from './types';

export function getErrorRating(delta: number): string {
  if (delta < 1) return "Идеально";
  if (delta < 2) return "Высокая";
  if (delta < 3.5) return "Хорошая";
  if (delta < 6) return "Средняя";
  return "Низкая";
}

export function buildRecipe(drops: number[], components: ColorComponent[]): RecipeItem[] {
  const total = drops.reduce((s, d) => s + d, 0);
  const items: RecipeItem[] = [];

  for (let i = 0; i < drops.length; i++) {
    if (drops[i] > 0) {
      items.push({
        name: components[i].name,
        rgb: components[i].rgb,
        parts: drops[i],
        percent: total > 0 ? Math.round((drops[i] / total) * 100) : 0,
      });
    }
  }

  if (items.length > 0) {
    const sum = items.reduce((s, it) => s + it.percent, 0);
    if (sum !== 100 && sum > 0) {
      const maxIdx = items.reduce((mi, it, i) => (it.percent > items[mi].percent ? i : mi), 0);
      items[maxIdx].percent += 100 - sum;
    }
  }

  return items;
}

export function makeVariant(
  c: SolverCandidate,
  components: ColorComponent[],
  label: string,
  profile: PaintProfile,
  substrateColor: RGB,
  targetLab: [number, number, number],
): RecipeVariant {
  const compsRgb = components.map((co) => co.rgb);
  const wetMix = mixColors(c.drops, compsRgb, profile, substrateColor);
  const dryMix = profile.drying ? calculateDryColor(wetMix, profile.drying) : wetMix;
  const opticalRgb = mixLinearRgb(c.drops, compsRgb);
  const physicalRgb = mixKubelkaMunk(c.drops, compsRgb);
  
  // ΔE считаем по ТОМУ ЖЕ высохшему цвету, что и показываем (approxRgb=dryMix),
  // чтобы отображаемая ошибка и образец были согласованы. Раньше в deltaE клали
  // c.delta от солвера, а образец — dryMix; при расхождениях числа не сходились.
  const tsDeltaE = deltaE00(targetLab, rgbToLab(dryMix));

  return {
    drops: c.drops,
    components,
    deltaE: tsDeltaE,
    tsDeltaE,
    totalDrops: c.total,
    approxRgb: dryMix,
    wetRgb: wetMix,
    dryRgb: dryMix,
    opticalRgb,
    physicalRgb,
    rating: getErrorRating(tsDeltaE),
    usedColors: c.used,
    label,
    recipe: buildRecipe(c.drops, components),
  };
}

// --- Нейтраль-щадящий штраф ранжирования ---
// Для малонасыщенных (нейтральных) целей ΔE00 занижает ошибку оттенка/насыщенности:
// формально «серый с розовинкой» может получить меньший ΔE, чем чистый серый чуть
// иной светлоты. Из-за этого солвер уводил нейтрали в цвет (Луна «розовела»).
// Штраф добавляет обратно вес за уход в цвет — тем сильнее, чем нейтральнее цель.
// Он правит ТОЛЬКО ранжирование; отображаемая точность (tsDeltaE) считается по dryMix.
const NEUTRAL_C = 20;   // порог хромы цели, ниже которого включается защита нейтрали
const W_EXCESS = 0.6;   // штраф за набранную сверх цели насыщенность
const W_CAST = 0.5;     // штраф за уход в плоскости a*/b* (оттенок+хрома)
const W_MUD = 0.9;      // штраф за лишние пигменты в нейтрали (>2 = замуливание)
function neutralPenalty(
  targetLab: [number, number, number],
  mixLab: [number, number, number],
  used: number,
): number {
  const Ct = Math.hypot(targetLab[1], targetLab[2]);
  if (Ct >= NEUTRAL_C) return 0;
  const neutrality = (NEUTRAL_C - Ct) / NEUTRAL_C; // 0..1, ближе к 1 — чище нейтраль
  const Cm = Math.hypot(mixLab[1], mixLab[2]);
  const excess = Math.max(0, Cm - Ct);
  const cast = Math.hypot(mixLab[1] - targetLab[1], mixLab[2] - targetLab[2]);
  // Чем больше хроматических пигментов в нейтральном замесе, тем сильнее грязь
  // (особенно у акрила/масла с полным субтрактивным смешением). Гоним к 2 краскам.
  const mud = Math.max(0, used - 2);
  return neutrality * (W_EXCESS * excess + W_CAST * cast + W_MUD * mud);
}

export function selectVariants(
  candidates: SolverCandidate[],
  components: ColorComponent[],
  profile: PaintProfile,
  substrateColor: RGB,
  targetLab: [number, number, number],
): RecipeVariant[] {
  if (candidates.length === 0) return [];

  const seen = new Set<string>();
  const unique = candidates.filter((c) => {
    const k = c.drops.join(',');
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });

  const compsRgb = components.map((co) => co.rgb);
  const scored = unique.map((c) => {
    // Достижимый ВЫСОХШИЙ цвет замеса — тот же, что показываем как approxRgb.
    const wetMix = mixColors(c.drops, compsRgb, profile, substrateColor);
    const dryMix = profile.drying ? calculateDryColor(wetMix, profile.drying) : wetMix;
    const mixLab = rgbToLab(dryMix);
    const edelta = c.delta + neutralPenalty(targetLab, mixLab, c.used);
    return {
      ...c,
      edelta,
      cs: Math.pow(edelta, 2) + 0.01 * c.total + 0.05 * c.used,
    };
  });

  scored.sort((a, b) => a.cs - b.cs);

  const variants: RecipeVariant[] = [];
  const best = scored[0];
  variants.push(makeVariant(best, components, ' Лучший', profile, substrateColor, targetLab));

  const acc = [...scored].sort((a, b) => a.edelta - b.edelta)[0];
  if (acc.drops.join(',') !== best.drops.join(',') && acc.edelta < best.edelta - 0.3) {
    variants.push(makeVariant(acc, components, ' Точный', profile, substrateColor, targetLab));
  }

  const eco = [...scored]
    .filter((c) => c.edelta < 8)
    .sort((a, b) => a.total - b.total || a.used - b.used)[0];

  if (eco && eco.drops.join(',') !== best.drops.join(',')) {
    variants.push(makeVariant(eco, components, ' Экономный', profile, substrateColor, targetLab));
  }

  const sim = [...scored]
    .filter((c) => c.edelta < 8)
    .sort((a, b) => a.used - b.used || a.total - b.total)[0];
  
  if (
    sim &&
    sim.drops.join(',') !== best.drops.join(',') &&
    (!eco || sim.drops.join(',') !== eco.drops.join(','))
  ) {
    variants.push(makeVariant(sim, components, ' Простой', profile, substrateColor, targetLab));
  }

  return variants.slice(0, 4);
}