import { rgbToHsl, hslToRgb } from '../../../utils/colorMath';
import type { ColorHarmonyType } from '../../store/types';

export interface FullCorrectionParams {
  brightness: number;
  contrast: number;
  saturation: number;
  sharpness: number;
  shadows?: number;
  highlights?: number;
  structure?: number;
}

/** Разделимое box-размытие RGB-каналов (для локального контраста «структуры»). */
function boxBlurRGB(src: Uint8ClampedArray, w: number, h: number, r: number): Float32Array {
  const tmp = new Float32Array(w * h * 4);
  const out = new Float32Array(w * h * 4);
  const norm = 1 / (2 * r + 1);
  // Горизонтальный проход (скользящая сумма с зажимом краёв).
  for (let y = 0; y < h; y++) {
    const row = y * w;
    for (let c = 0; c < 3; c++) {
      let sum = 0;
      for (let k = -r; k <= r; k++) {
        const x = k < 0 ? 0 : k >= w ? w - 1 : k;
        sum += src[(row + x) * 4 + c];
      }
      for (let x = 0; x < w; x++) {
        tmp[(row + x) * 4 + c] = sum * norm;
        const xOut = x - r < 0 ? 0 : x - r;
        const xIn = x + r + 1 >= w ? w - 1 : x + r + 1;
        sum += src[(row + xIn) * 4 + c] - src[(row + xOut) * 4 + c];
      }
    }
  }
  // Вертикальный проход.
  for (let x = 0; x < w; x++) {
    for (let c = 0; c < 3; c++) {
      let sum = 0;
      for (let k = -r; k <= r; k++) {
        const y = k < 0 ? 0 : k >= h ? h - 1 : k;
        sum += tmp[(y * w + x) * 4 + c];
      }
      for (let y = 0; y < h; y++) {
        out[(y * w + x) * 4 + c] = sum * norm;
        const yOut = y - r < 0 ? 0 : y - r;
        const yIn = y + r + 1 >= h ? h - 1 : y + r + 1;
        sum += tmp[(yIn * w + x) * 4 + c] - tmp[(yOut * w + x) * 4 + c];
      }
    }
  }
  return out;
}

/**
 * Светокоррекция изображения перед квантизацией.
 * Помимо базовых яркости/контраста/насыщенности/резкости поддерживает:
 *   • тени/света — раздельная тональная коррекция по маске яркости пикселя;
 *   • структуру — локальный контраст (unsharp большого радиуса). Если передана
 *     карта значимости `importance`, локальный контраст усиливается на ГРАНИЦЕ
 *     объект/фон (высокий градиент значимости) — так объект перестаёт «сливаться»
 *     с фоном (случай «лапа на песке»), а плоский фон не перешарпливается.
 */
export function applyCorrection(
  src: ImageData,
  params: FullCorrectionParams,
  importance?: Float32Array | null,
): ImageData {
  const { brightness, contrast, saturation, sharpness } = params;
  const shadows = params.shadows ?? 0;
  const highlights = params.highlights ?? 0;
  const structure = params.structure ?? 0;
  const w = src.width;
  const h = src.height;
  const srcData = src.data;
  const out = new ImageData(w, h);
  const dst = out.data;

  const bFactor = brightness / 100;
  const cFactor = (contrast + 100) / 100;
  const cMul = cFactor * cFactor;

  const lut = new Uint8Array(256);
  for (let i = 0; i < 256; i++) {
    let v = i / 255;
    v += bFactor * 0.5;
    v = (v - 0.5) * cMul + 0.5;
    lut[i] = Math.max(0, Math.min(255, Math.round(v * 255)));
  }

  const satMul = 1 + saturation / 100;
  const sAmt = shadows / 100;
  const hAmt = highlights / 100;
  const toneOn = shadows !== 0 || highlights !== 0;

  for (let i = 0; i < srcData.length; i += 4) {
    let r = lut[srcData[i]];
    let g = lut[srcData[i + 1]];
    let b = lut[srcData[i + 2]];

    if (toneOn) {
      const L = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
      const sMask = (1 - L) * (1 - L); // сильнее в тенях
      const hMask = L * L;             // сильнее в светах
      const delta = sAmt * sMask * 90 + hAmt * hMask * 90;
      r = Math.max(0, Math.min(255, r + delta));
      g = Math.max(0, Math.min(255, g + delta));
      b = Math.max(0, Math.min(255, b + delta));
    }

    if (saturation !== 0) {
      const gray = 0.299 * r + 0.587 * g + 0.114 * b;
      r = Math.max(0, Math.min(255, Math.round(gray + (r - gray) * satMul)));
      g = Math.max(0, Math.min(255, Math.round(gray + (g - gray) * satMul)));
      b = Math.max(0, Math.min(255, Math.round(gray + (b - gray) * satMul)));
    }

    dst[i] = r;
    dst[i + 1] = g;
    dst[i + 2] = b;
    dst[i + 3] = srcData[i + 3];
  }

  if (sharpness > 0) {
    const amount = (sharpness / 100) * 1.5;
    const tmp = new Uint8ClampedArray(dst);

    for (let y = 1; y < h - 1; y++) {
      for (let x = 1; x < w - 1; x++) {
        const idx = (y * w + x) * 4;
        for (let c = 0; c < 3; c++) {
          const sum =
            tmp[((y - 1) * w + (x - 1)) * 4 + c] +
            tmp[((y - 1) * w + x) * 4 + c] +
            tmp[((y - 1) * w + (x + 1)) * 4 + c] +
            tmp[(y * w + (x - 1)) * 4 + c] +
            tmp[(y * w + (x + 1)) * 4 + c] +
            tmp[((y + 1) * w + (x - 1)) * 4 + c] +
            tmp[((y + 1) * w + x) * 4 + c] +
            tmp[((y + 1) * w + (x + 1)) * 4 + c];

          const blur = sum / 8;
          const sharp = tmp[idx + c] + (tmp[idx + c] - blur) * amount;
          dst[idx + c] = Math.max(0, Math.min(255, Math.round(sharp)));
        }
      }
    }
  }

  // Локальный контраст («структура»), опционально усиленный на границе объект/фон.
  if (structure > 0) {
    const amount = (structure / 100) * 0.8;
    const radius = Math.max(2, Math.round(Math.min(w, h) / 200));
    const blur = boxBlurRGB(dst, w, h, radius);
    const n = w * h;
    for (let i = 0; i < n; i++) {
      let lw = 1;
      if (importance) {
        const x = i % w, y = (i / w) | 0;
        const xl = x > 0 ? i - 1 : i, xr = x + 1 < w ? i + 1 : i;
        const yu = y > 0 ? i - w : i, yd = y + 1 < h ? i + w : i;
        const grad = Math.abs(importance[xr] - importance[xl]) + Math.abs(importance[yd] - importance[yu]);
        lw = 1 + Math.min(2, grad * 6); // на границе значимости до 3× локального контраста
      }
      const p = i * 4;
      for (let c = 0; c < 3; c++) {
        const detail = dst[p + c] - blur[p + c];
        dst[p + c] = Math.max(0, Math.min(255, Math.round(dst[p + c] + detail * amount * lw)));
      }
    }
  }

  return out;
}

export function applyColorHarmony(
  src: ImageData,
  harmonyType: ColorHarmonyType,
  dominantHue: number,
  intensity: number = 0.7
): ImageData {
  if (harmonyType === "none") return src;

  const w = src.width;
  const h = src.height;
  const srcData = src.data;
  const out = new ImageData(w, h);
  const dst = out.data;

  let targetHues: number[] = [];
  const adjustHue = (hue: number, amount: number) => (hue + amount + 360) % 360;

  switch (harmonyType) {
    case "complementary":
      targetHues = [dominantHue, adjustHue(dominantHue, 180)];
      break;
    case "analogous":
      targetHues = [adjustHue(dominantHue, -30), dominantHue, adjustHue(dominantHue, 30)];
      break;
    case "triadic":
      targetHues = [dominantHue, adjustHue(dominantHue, 120), adjustHue(dominantHue, 240)];
      break;
    case "split-complementary":
      targetHues = [dominantHue, adjustHue(dominantHue, 150), adjustHue(dominantHue, 210)];
      break;
  }

  if (targetHues.length === 0) return src;

  for (let i = 0; i < srcData.length; i += 4) {
    const r = srcData[i];
    const g = srcData[i + 1];
    const b = srcData[i + 2];
    const a = srcData[i + 3];

    if (r === g && g === b) {
      dst[i] = r;
      dst[i + 1] = g;
      dst[i + 2] = b;
      dst[i + 3] = a;
      continue;
    }

    const [hue, sat, lum] = rgbToHsl([r, g, b]);

    let minDiff = Infinity;
    let closestHue = hue;
    for (const th of targetHues) {
      let diff = Math.abs(hue - th);
      if (diff > 180) diff = 360 - diff;
      if (diff < minDiff) {
        minDiff = diff;
        closestHue = th;
      }
    }

    let diff = closestHue - hue;
    if (diff > 180) diff -= 360;
    if (diff < -180) diff += 360;

    const newHue = adjustHue(hue, diff * intensity);

    const newRgb = hslToRgb(newHue, sat, lum);
    dst[i] = newRgb[0];
    dst[i + 1] = newRgb[1];
    dst[i + 2] = newRgb[2];
    dst[i + 3] = a;
  }

  return out;
}

// Умный «зрячий» анализ фото -> рекомендуемые значения ползунков коррекции.
// Помимо глобальной гистограммы использует карту значимости (importance): считает
// светлоту ОТДЕЛЬНО по главному объекту и по фону. Это позволяет: (1) проявлять
// тени именно на объекте (глаза/фактуры), (2) добавлять локальный контраст, когда
// объект «сливается» с фоном по светлоте (лапа на песке), (3) вытягивать реально
// выбитые света. Всё выражается обычными ползунками — применяет их единый конвейер
// applyCorrection (без «запекания», без конфликтов). Адаптивно: ненулевые значения
// только там, где кадр реально в них нуждается. Отдельно ловит низкоkey-сцену с
// ярким объектом (Луна): лёгкое затемнение + контраст против «ореола».
export function analyzeAutoCorrection(
  src: ImageData,
  importance?: Float32Array | null,
): { brightness: number; contrast: number; saturation: number; sharpness: number; shadows: number; highlights: number; structure: number } {
  const w = src.width, h = src.height, d = src.data;
  const N = w * h;
  // Плотный сэмплинг: при разрежённом каждый-N-й пиксель мелкие яркие детали
  // (напр. диск Луны) прореживаются и доля ярких пикселей «проваливается» ниже
  // порога — авто-улучшение ошибочно ничего не делало. ~200k отсчётов стабильны.
  const step = Math.max(1, Math.floor(N / 200000));
  const hasImp = !!importance && importance.length >= N;

  const hist = new Float64Array(256);
  let cnt = 0, darkCnt = 0, brightCnt = 0, satSum = 0;
  // Взвешенная статистика по объекту (imp) и фону (1-imp).
  let wSum = 0, wLum = 0, wDark = 0, bgSum = 0, bgLum = 0, subjCnt = 0;
  for (let i = 0; i < N; i += step) {
    const p = i * 4;
    const r = d[p], g = d[p + 1], b = d[p + 2];
    const lum = (0.299 * r + 0.587 * g + 0.114 * b) | 0;
    hist[lum]++;
    if (lum < 30) darkCnt++;
    if (lum > 225) brightCnt++;
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
    satSum += mx === 0 ? 0 : (mx - mn) / mx;
    if (hasImp) {
      const imp = importance![i];
      wSum += imp; wLum += imp * lum; if (lum < 50) wDark += imp;
      bgSum += 1 - imp; bgLum += (1 - imp) * lum;
      if (imp > 0.5) subjCnt++;
    }
    cnt++;
  }
  let lumSum = 0;
  for (let i = 0; i < 256; i++) lumSum += hist[i] * i;
  const meanLum = lumSum / Math.max(1, cnt);
  const darkFrac = darkCnt / Math.max(1, cnt);
  const brightFrac = brightCnt / Math.max(1, cnt);
  const satMean = satSum / Math.max(1, cnt);

  // Светлота объекта/фона и «есть ли вообще выраженный объект».
  const subjMean = wSum > 1e-3 ? wLum / wSum : meanLum;
  const bgMean = bgSum > 1e-3 ? bgLum / bgSum : meanLum;
  const subjDarkFrac = wSum > 1e-3 ? wDark / wSum : 0;
  const subjFrac = subjCnt / Math.max(1, cnt);
  const haveSubject = hasImp && subjFrac > 0.03 && subjFrac < 0.85;

  // Точки 0.5% гистограммы (чёрная/белая точки). Белая точка hi — устойчивый
  // (перцентильный) признак наличия яркого объекта/блика, в отличие от хрупкой
  // доли ярких пикселей.
  const tgt = cnt * 0.005;
  let acc = 0, lo = 0, hi = 255;
  for (let i = 0; i < 256; i++) { acc += hist[i]; if (acc >= tgt) { lo = i; break; } }
  acc = 0;
  for (let i = 255; i >= 0; i--) { acc += hist[i]; if (acc >= tgt) { hi = i; break; } }
  const range = Math.max(1, hi - lo);

  // Размытость (дисперсия Лапласа) -> резкость.
  let lapSum = 0, lapSq = 0, lc = 0;
  const stride = Math.max(1, Math.floor(Math.min(w, h) / 300));
  const lumAt = (idx: number) => 0.299 * d[idx] + 0.587 * d[idx + 1] + 0.114 * d[idx + 2];
  for (let y = 1; y < h - 1; y += stride) {
    for (let x = 1; x < w - 1; x += stride) {
      const idx = (y * w + x) * 4;
      const lap = 4 * lumAt(idx) - lumAt(idx - 4) - lumAt(idx + 4) - lumAt(idx - w * 4) - lumAt(idx + w * 4);
      lapSum += lap; lapSq += lap * lap; lc++;
    }
  }
  const lapVar = lc > 0 ? lapSq / lc - (lapSum / lc) * (lapSum / lc) : 1000;

  const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));
  const lowKey = meanLum < 72 || darkFrac > 0.34;   // тёмная/низкоключевая сцена
  const hotHighlight = hi >= 200;                   // есть яркий объект/блик

  let brightness = 0, contrast = 0, saturation = 0, sharpness = 0;

  if (lowKey && hotHighlight) {
    // Луна/фонарь/блик на тёмном фоне: гасим пересвет и «ореол», добавляем контраст.
    // Для сверхтёмных сцен затемняем мягче (фон и так почти чёрный).
    const darken = (9 + (hi - 200) * 0.14 + brightFrac * 180) * clamp(meanLum / 60, 0.5, 1.0);
    brightness = -clamp(darken, 8, 20);
    contrast = clamp(9 + (hi - 200) * 0.18, 9, 20);
  } else if (lowKey) {
    // Тёмная сцена без явного блика — деликатно приподнимаем (настроение сохраняем).
    brightness = clamp((72 - meanLum) * 0.32, 0, 15);
  } else if (meanLum < 108) {
    brightness = clamp((116 - meanLum) * 0.5, 0, 26);   // недосвет
  } else if (meanLum > 176) {
    brightness = -clamp((meanLum - 160) * 0.5, 0, 24);  // пересвет
  }

  if (contrast === 0 && range < 198) {
    contrast = clamp((203 - range) * 0.2, 0, 26); // растянуть вымытый контраст
  }

  if (satMean < 0.18) saturation = clamp((0.18 - satMean) * 170, 0, 26);
  else if (satMean > 0.56) saturation = -clamp((satMean - 0.56) * 110, 0, 22);

  // «Проявить» мыльные/слабые детали. Работает и в низкоключевых сценах, если они
  // не выбиты в чёрное (meanLum > 40): это как раз помогает вытянуть Луну и т.п.
  if (meanLum > 40 && lapVar < 130) {
    sharpness = clamp(((130 - lapVar) / 130) * 55, 0, 50);
  }

  // ── «Зрячие» решения ──────────────────────────────────────────────────────
  let shadows = 0, highlights = 0, structure = 0;

  // Тени: проявить детали в тенях. Не трогаем намеренно выбитый в чёрное фон
  // (низкоkey без блика — это настроение).
  if (darkFrac > 0.08 && darkFrac < 0.6 && !(lowKey && !hotHighlight)) {
    shadows = clamp((darkFrac - 0.06) * 70, 0, 24);
  }
  // Если тёмный именно объект — усилить проявление теней на нём (глаза/фактуры).
  if (haveSubject && subjDarkFrac > 0.15) {
    shadows = Math.max(shadows, clamp(subjDarkFrac * 55, 0, 30));
  }

  // Света: вытянуть реально выбитые области (широкие пересветы, не крошечный
  // блик/Луну — их отсекает порог доли ярких пикселей).
  if (hi >= 250 && brightFrac > 0.02) {
    highlights = -clamp(brightFrac * 120 + (hi - 248) * 2, 0, 26);
  }

  // Мягко приподнять яркость, если недосвечен именно объект, а кадр не яркий
  // (безопасно — фон не выбьется). Backlit-портреты/предметы.
  if (haveSubject && subjMean < 85 && meanLum < 135 && brightness < 10) {
    brightness = Math.max(brightness, clamp((90 - subjMean) * 0.2, 0, 10));
  }

  // Структура: объект «сливается» с фоном по светлоте — усилить локальный
  // контраст, чтобы граница объект/фон стала различимой (лапа на песке и т.п.).
  if (haveSubject) {
    const sep = Math.abs(subjMean - bgMean);
    if (sep < 36) structure = clamp((38 - sep) * 1.0, 0, 40);
  }

  return {
    brightness: Math.round(brightness),
    contrast: Math.round(contrast),
    saturation: Math.round(saturation),
    sharpness: Math.round(sharpness),
    shadows: Math.round(shadows),
    highlights: Math.round(highlights),
    structure: Math.round(structure),
  };
}
