import React, { useState, useEffect, useMemo, useRef } from "react";
import { useAppStore } from "../store";
import { useAppStore as useMainAppStore } from "../../store/appStore";
import { useLabStore } from "../../store/labStore";
import { PaintingStageCoach } from "./PaintingCoach";
import { PaintingFirstSteps } from "./PaintingFirstSteps";
import { SmoothSlider } from "./SmoothSlider";
import { ArtisticPresetSelector } from "./ArtisticPresetSelector";
import { cn } from "../../utils/cn";
import { SectionTitle } from "../../components/ui/SectionTitle";
import { calculateSmartParams } from "../utils/smartParams";
import { AutoPreset } from "./AutoPreset";
import { AutoPresetSettings } from "./AutoPresetSettings";
import { rgbToHsl, hslToRgb, rgbToHex } from "../../utils/colorMath";
import { BASE_COLORS, EXTENDED_COLORS } from "../../config";
import { CalculatorContent } from "./CalculatorPanel";
import { scanAndOptimize } from "../utils/recipeOptimizer";

export function SettingsPanel() {
  return (
    <aside
      className={cn(
        "w-[340px] lg:w-[380px] xl:w-[420px] flex-shrink-0 border-l overflow-y-auto p-4 md:block hidden custom-scrollbar pb-24 glass-panel dark:glass-panel border-white/20 dark:border-white/10 z-10 shadow-[-10px_0_30px_rgba(0,0,0,0.05)] dark:shadow-[-10px_0_30px_rgba(0,0,0,0.3)]",
      )}
      aria-label="Панель настроек"
    >
      <SettingsContent />
    </aside>
  );
}

function Section({ title, children, isDark, action }: { title: string; children: React.ReactNode; isDark: boolean; action?: React.ReactNode }) {
  return (
    <section className="space-y-4">
      {action ? (
        <div className="flex items-center justify-between">
          <SectionTitle>{title}</SectionTitle>
          {action}
        </div>
      ) : (
        <SectionTitle>{title}</SectionTitle>
      )}
      <div className="space-y-4">
        {children}
      </div>
    </section>
  );
}

function HighlightSection({ title, children, isDark }: { title: string; children: React.ReactNode; isDark: boolean }) {
  return (
    <div className={cn("flex flex-col gap-4 p-6 rounded-3xl border backdrop-blur-sm", isDark ? "bg-indigo-500/5 border-indigo-500/20" : "bg-indigo-50/80 border-indigo-200/80")}>
      <h3 className="text-xs font-bold uppercase tracking-widest text-indigo-700 dark:text-indigo-200">
        {title}
      </h3>
      <div className="space-y-5">
        {children}
      </div>
    </div>
  );
}

export function SettingsContent({ hideCorrection = false }: { hideCorrection?: boolean }) {
  const isDark = useAppStore((s) => s.isDark);
  const pickedColor = useAppStore((s) => s.pickedColor);

  // Используем актуальные названия из нового стора
  const studioMode = useAppStore((s) => s.studioMode);
  const autoEnhance = useAppStore((s) => s.autoEnhance);
  const numColors = useAppStore((s) => s.numColors);
  const detail = useAppStore((s) => s.detail);
  const pbnContourWeight = useAppStore((s) => s.pbnContourWeight);
  const numberWeight = useAppStore((s) => s.numberWeight);
  const hasResult = useAppStore((s) => !!s.result);
  const hasImage = useAppStore((s) => !!s.originalImageUrl);
  const correction = useAppStore((s) => s.correction);
  const imageProfile = useAppStore((s) => s.imageProfile);
  const colorHarmony = useAppStore((s) => s.colorHarmony);
  const colorHarmonyIntensity = useAppStore((s) => s.colorHarmonyIntensity);
  const colorHarmonyCustomHue = useAppStore((s) => s.colorHarmonyCustomHue);

  const update = useAppStore((s) => s.update);
  const switchStudioMode = useAppStore((s) => s.switchStudioMode);
  const updateCorrection = useAppStore((s) => s.updateCorrection);
  const resetCorrection = useAppStore((s) => s.resetCorrection);
  const pushHistory = useAppStore((s) => s.pushCorrectionHistory);

  const notanLevels = useAppStore((s) => s.notanLevels);
  const notanThreshold = useAppStore((s) => s.notanThreshold);
  const setNotanLevels = useAppStore((s) => s.setNotanLevels);
  const setNotanThreshold = useAppStore((s) => s.setNotanThreshold);

  const artIntensity = useAppStore((s) => s.artIntensity);
  const setArtIntensity = useAppStore((s) => s.setArtIntensity);

  const detailsPhotoOpacity = useAppStore((s) => s.detailsPhotoOpacity);
  const setDetailsPhotoOpacity = useAppStore((s) => s.setDetailsPhotoOpacity);

  const paintingLayer = useAppStore((s) => s.paintingLayer);
  const showTemperatureMap = useAppStore((s) => s.showTemperatureMap);
  const paintingNumColors = useAppStore((s) => s.paintingNumColors);
  const paintingDetail = useAppStore((s) => s.paintingDetail);
  const setPaintingNumColors = useAppStore((s) => s.setPaintingNumColors);
  const setPaintingDetail = useAppStore((s) => s.setPaintingDetail);

  const engineSettings = useMainAppStore((s) => s.engineSettings);

  const paintingStyleId = useAppStore((s) => s.paintingStyleId);

  const isPainting = studioMode === "painting";

  const paintingComplexity = useAppStore((s) => s.paintingModeState.complexity ?? 3);
  const pbnComplexity = useAppStore((s) => s.complexity ?? 5); // топ-левел: пишется onChange и сбрасывается при загрузке фото

  const recipeSplitMode = useAppStore((s) => s.recipeSplitMode);
  const calculateRecipeApproximations = useAppStore((s) => s.calculateRecipeApproximations);
  const customColors = useMainAppStore((s) => s.customColors);
  const selectedNames = useMainAppStore((s) => s.selectedNames);
  const totalPartsLimit = useMainAppStore((s) => s.totalPartsLimit);
  const deletedBuiltIns = useMainAppStore((s) => s.deletedBuiltIns);

  const overrides = useMainAppStore((s) => s.overrides);

  const activeComps = useMemo(() => {
    const all = [...BASE_COLORS, ...customColors].map(c => ({
      ...c, rgb: overrides[c.name] || c.rgb
    }));
    return all.filter(c => selectedNames.includes(c.name));
  }, [customColors, selectedNames, overrides]);

  const lastPhysicsSig = useRef("");

  const result = useAppStore((s) => s.result);

  useEffect(() => {
    if (!isPainting) {
      const sig = JSON.stringify({
        pt: engineSettings.paintType,
        st: engineSettings.surfaceType,
        mc: engineSettings.maxColorsInMix,
        comps: activeComps.map(c => `${c.name}:${c.rgb.join('-')}`).sort().join(','),
        limit: totalPartsLimit
      });
      if (lastPhysicsSig.current !== "" && sig !== lastPhysicsSig.current) {
        lastPhysicsSig.current = sig;
        if (recipeSplitMode && result) {
          (async () => {
             update({ isProcessing: true, isOptimizing: true, statusMsg: "Умное сканирование рецептов...", progress: 0 });
             try {
                const ext = EXTENDED_COLORS.filter((c) => !deletedBuiltIns.includes(c.name));
                const allAvailableColors = [...ext, ...customColors].map((c) => ({
                  ...c,
                  rgb: overrides[c.name] || c.rgb,
                }));

                const problems = await scanAndOptimize(
                  result.colorPalette,
                  Array.from(result.validLabels),
                  activeComps,
                  allAvailableColors,
                  engineSettings,
                  totalPartsLimit === "авто" || totalPartsLimit === "" ? null : Number(totalPartsLimit) || null,
                  (pct) => update({ progress: pct })
                );

                if (problems.length > 0) {
                  update({ optimizationData: problems, isOptimizing: false, isProcessing: false });
                  return;
                }
             } catch (e) {
               console.error("Optimization failed", e);
             } finally {
               update({ isOptimizing: false });
             }
             calculateRecipeApproximations(engineSettings, activeComps, String(totalPartsLimit));
          })();
        }
      } else if (lastPhysicsSig.current === "") {
        lastPhysicsSig.current = sig;
      }
    }
  }, [engineSettings.paintType, engineSettings.surfaceType, engineSettings.maxColorsInMix, isPainting, activeComps, totalPartsLimit, calculateRecipeApproximations, recipeSplitMode, result, customColors, deletedBuiltIns, overrides, update]);

  return (
    <div className="flex flex-col gap-6 pb-4">
      {/* 1. ГЛАВНЫЙ ПЕРЕКЛЮЧАТЕЛЬ РЕЖИМА СТУДИИ */}
      <Section title="Тип проекта" isDark={isDark}>
        <div className={cn("flex p-1.5 rounded-2xl", isDark ? "bg-slate-800/50" : "bg-slate-100")}>
          <ModeButton
            active={!isPainting}
            onClick={() => switchStudioMode("pbn")}
            label="По номерам"
            isDark={isDark}
            icon={
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M4 7h4M4 17h4M4 12h3" />
                <path d="M14 7h2v4M14 17h4M14 13h2v4" />
              </svg>
            }
          />
          <ModeButton
            active={isPainting}
            onClick={() => switchStudioMode("painting")}
            label="Живопись"
            isDark={isDark}
            icon={
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M12 19l7-7 3 3-7 7-3-3z" />
                <path d="m18 13-1.5-7.5L2 2l3.5 14.5L13 18l5-5z" />
              </svg>
            }
          />
        </div>
      </Section>

      {/* 2. ГЛОБАЛЬНАЯ КОРРЕКЦИЯ ФОТО */}
      {!hideCorrection && (
        <div className={cn("animate-fade-in-up", !hasImage && "pointer-events-none opacity-35 grayscale brightness-50 transition-all duration-300")}>
          <Section
            title="Фото"
            isDark={isDark}
            action={
              autoEnhance === false ? (
                <button
                  onClick={resetCorrection}
                  className="text-xs font-black uppercase tracking-widest text-indigo-500 hover:text-indigo-400 transition-colors px-2 py-1"
                >
                  Сбросить
                </button>
              ) : undefined
            }
          >
            <label className={cn("flex items-center justify-between gap-3 cursor-pointer select-none rounded-xl border-2 px-3 py-2.5 mb-3 font-bold text-sm transition-colors", isDark ? "bg-slate-800/70 border-slate-700 text-white" : "bg-white border-slate-200 text-slate-800")}>
              <span>Авто-улучшение</span>
              <span className="relative flex items-center shrink-0">
                <input type="checkbox" checked={autoEnhance !== false} onChange={(e) => update({ autoEnhance: e.target.checked })} className="peer sr-only" />
                <span className="w-10 h-6 bg-slate-200 dark:bg-slate-700 rounded-full peer-checked:bg-indigo-600 transition-colors shadow-inner" />
                <span className="absolute left-1 top-1 w-4 h-4 bg-white rounded-full transition-transform peer-checked:translate-x-4 shadow-sm" />
              </span>
            </label>
            <SmoothSlider
              label="Яркость"
              storeValue={correction.brightness}
              defaultValue={0}
              min={-100}
              max={100}
              onCommit={(v) => updateCorrection({ brightness: v })}
              onDragEnd={pushHistory}
              showSign
              disabled={autoEnhance !== false}
            />
            <SmoothSlider
              label="Контраст"
              storeValue={correction.contrast}
              defaultValue={0}
              min={-100}
              max={100}
              onCommit={(v) => updateCorrection({ contrast: v })}
              onDragEnd={pushHistory}
              showSign
              disabled={autoEnhance !== false}
            />
            <SmoothSlider
              label="Насыщенность"
              storeValue={correction.saturation}
              defaultValue={0}
              min={-100}
              max={100}
              onCommit={(v) => updateCorrection({ saturation: v })}
              onDragEnd={pushHistory}
              showSign
              disabled={autoEnhance !== false}
            />
            <SmoothSlider
              label="Резкость"
              storeValue={correction.sharpness}
              defaultValue={0}
              min={0}
              max={100}
              onCommit={(v) => updateCorrection({ sharpness: v })}
              onDragEnd={pushHistory}
              suffix="%"
              disabled={autoEnhance !== false}
            />
            <SmoothSlider
              label="Тени"
              storeValue={correction.shadows ?? 0}
              defaultValue={0}
              min={-100}
              max={100}
              onCommit={(v) => updateCorrection({ shadows: v })}
              onDragEnd={pushHistory}
              showSign
              disabled={autoEnhance !== false}
            />
            <SmoothSlider
              label="Света"
              storeValue={correction.highlights ?? 0}
              defaultValue={0}
              min={-100}
              max={100}
              onCommit={(v) => updateCorrection({ highlights: v })}
              onDragEnd={pushHistory}
              showSign
              disabled={autoEnhance !== false}
            />
            <SmoothSlider
              label="Структура"
              storeValue={correction.structure ?? 0}
              defaultValue={0}
              min={0}
              max={100}
              onCommit={(v) => updateCorrection({ structure: v })}
              onDragEnd={pushHistory}
              suffix="%"
              disabled={autoEnhance !== false}
            />
          </Section>
        </div>
      )}

      {/* Автоподбор пресетов + доведение ИИ-зрением */}
      {!hideCorrection && (
        <div className={cn("flex flex-col gap-3 animate-fade-in-up", !hasImage && "pointer-events-none opacity-35 grayscale brightness-50 transition-all duration-300")}>
          <AutoPreset isDark={isDark} />
          <AutoPresetSettings isDark={isDark} />
        </div>
      )}

      {/* 3. НАСТРОЙКИ: ЖИВОПИСЬ */}
      {isPainting && (
        <div className={cn("flex flex-col gap-6 animate-fade-in-up", !hasImage && "pointer-events-none opacity-35 grayscale brightness-50 transition-all duration-300")}>
          {hasResult && (
            <PaintingFirstSteps isDark={isDark} />
          )}

          {hasResult && (
            <PaintingStageGuide showTemp={showTemperatureMap} layer={paintingLayer} isDark={isDark} />
          )}

          {hasResult && (
            <PaintingStageCoach showTemp={showTemperatureMap} layer={paintingLayer} isDark={isDark} />
          )}

          {hasResult && paintingLayer === 3 && !showTemperatureMap && (
            <PaintingStagePalette isDark={isDark} />
          )}

          <Section title="Стилизация" isDark={isDark}>
             <ArtisticPresetSelector isDark={isDark} />
          </Section>

          <Section title="Сложность" isDark={isDark}>
            <ComplexitySlider
              isDark={isDark}
              complexity={paintingComplexity}
              onComplexityChange={(c) => {
                const s = useAppStore.getState();
                if (s.importanceAnalysis && s.imageProfile) {
                  const smart = calculateSmartParams(s.importanceAnalysis, s.imageProfile, c);
                  setPaintingNumColors(smart.numColors);
                  setPaintingDetail(smart.detail);
                }
              }}
              numColors={paintingNumColors}
              detail={paintingDetail}
            />
          </Section>

          {hasResult && paintingLayer === 1 && (
            <HighlightSection title="Подмалёвок (Светотень)" isDark={isDark}>
              <SmoothSlider
                label="Уровни тона"
                storeValue={notanLevels}
                defaultValue={2}
                min={2}
                max={5}
                onCommit={setNotanLevels}
                isDark={isDark}
              />
              <SmoothSlider
                label="Граница тени"
                storeValue={notanThreshold}
                defaultValue={128}
                min={40}
                max={220}
                onCommit={setNotanThreshold}
                isDark={isDark}
                disabled={notanLevels !== 2}
              />
            </HighlightSection>
          )}

          {hasResult && paintingLayer === 3 && paintingStyleId !== "original" && (
            <HighlightSection title="Работа с цветом" isDark={isDark}>
              <SmoothSlider
                label="Интенсивность"
                storeValue={artIntensity}
                defaultValue={100}
                min={0}
                max={100}
                onCommit={setArtIntensity}
                isDark={isDark}
                suffix="%"
              />
            </HighlightSection>
          )}

          {hasResult && (paintingLayer === 0 || paintingLayer === 4) && (
            <Section title="Вспомогательные слои" isDark={isDark}>
              <SmoothSlider
                label={paintingLayer === 4 ? "Прозрачность фото" : "Прозрачность эскиза"}
                storeValue={detailsPhotoOpacity}
                defaultValue={60}
                min={0}
                max={100}
                onCommit={setDetailsPhotoOpacity}
                isDark={isDark}
                suffix="%"
              />
            </Section>
          )}
        </div>
      )}

      {/* 4. НАСТРОЙКИ: ПО НОМЕРАМ */}
      {!isPainting && (
        <div className={cn("flex flex-col gap-6 animate-fade-in-up", !hasImage && "pointer-events-none opacity-35 grayscale brightness-50 transition-all duration-300")}>
          <Section title="Векторизация" isDark={isDark}>
            <ComplexitySlider
              isDark={isDark}
              complexity={pbnComplexity}
              onComplexityChange={(c) => {
                const s = useAppStore.getState();
                if (s.importanceAnalysis && s.imageProfile) {
                  const smart = calculateSmartParams(s.importanceAnalysis, s.imageProfile, c);
                  update({ numColors: smart.numColors, detail: smart.detail, complexity: c } as any);
                } else {
                  update({ complexity: c } as any);
                }
              }}
              numColors={numColors}
              detail={detail}
            />
          </Section>

          <div className={cn("animate-fade-in-up", !hasImage && "pointer-events-none opacity-35 grayscale brightness-50 transition-all duration-300")}>
            <HighlightSection title="Идеальная палитра (ИИ)" isDark={isDark}>
              <div className="flex flex-col gap-3">
                <p className="text-xs text-indigo-700/80 dark:text-indigo-300/80 leading-relaxed font-medium">
                  Сдвигает оттенки фото к классическим цветовым гармониям для создания глубокой, кинематографичной картины.
                </p>
                  <select 
                    value={colorHarmony} 
                    onChange={(e) => update({ colorHarmony: e.target.value as any })}
                    className={cn(
                      "w-full px-4 py-3 rounded-2xl border-2 font-bold text-sm outline-none transition-colors appearance-none cursor-pointer",
                      isDark 
                        ? "bg-slate-800/80 border-slate-700 text-white focus:border-indigo-500" 
                        : "bg-white border-slate-200 text-slate-800 focus:border-indigo-500"
                    )}
                  >
                    <option value="none">Оригинальные цвета</option>
                    <option value="complementary">Комплементарная (Контраст)</option>
                    <option value="analogous">Аналоговая (Мягкая)</option>
                    <option value="triadic">Триада (Классика)</option>
                    <option value="split-complementary">Сплит-комплементарная</option>
                  </select>
                  
                  {colorHarmony !== "none" && (
                    <div className="flex flex-col gap-4 mt-2">
                      <div className="bg-indigo-50/50 dark:bg-indigo-900/10 p-3.5 rounded-2xl border border-indigo-100 dark:border-indigo-900/30 shadow-sm animate-fade-in">
                        <p className="text-xs text-indigo-800/80 dark:text-indigo-300/70 font-bold leading-relaxed uppercase tracking-tighter">
                          {colorHarmony === "complementary" && "Сильный контраст двух противоположных цветов. Подходит для ярких акцентов."}
                          {colorHarmony === "analogous" && "Соседние оттенки. Спокойная, плавная палитра без резких переходов."}
                          {colorHarmony === "triadic" && "Три равноудалённых цвета. Живой и сбалансированный результат, как в классической живописи."}
                          {colorHarmony === "split-complementary" && "Мягкий контраст: базовый цвет и два соседних к противоположному. Сложнее и богаче."}
                        </p>
                      </div>
                      
                      <div className="space-y-3 animate-fade-in-up border-t border-indigo-100 dark:border-indigo-900/30 pt-4">
                        <SmoothSlider
                          label="Сила гармонии"
                          storeValue={colorHarmonyIntensity}
                          defaultValue={70}
                          min={0}
                          max={100}
                          onCommit={(v) => update({ colorHarmonyIntensity: v })}
                          isDark={isDark}
                          suffix="%"
                        />
                        <div className="space-y-3">
                          <div className="flex justify-between items-end mb-1">
                            <span className="text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300">Базовый оттенок</span>
                            {colorHarmonyCustomHue !== null && (
                              <button 
                                onClick={() => update({ colorHarmonyCustomHue: null })}
                                className="text-[10px] uppercase font-black tracking-widest text-indigo-500 hover:text-indigo-400 transition-colors"
                              >
                                Авто (ИИ)
                              </button>
                            )}
                          </div>
                          
                          <div className="flex items-center gap-3">
                            <div 
                              onClick={() => update({ pickingHarmonyBaseHue: true })}
                              className="w-14 h-14 rounded-xl shadow-sm border-[3px] border-white dark:border-slate-800 overflow-hidden flex-shrink-0 cursor-pointer transition-transform hover:scale-105 active:scale-95"
                              style={{ backgroundColor: rgbToHex(hslToRgb(colorHarmonyCustomHue !== null ? colorHarmonyCustomHue : (imageProfile?.dominantHue || 0), 0.8, 0.5)) }}
                              title="Выбрать оттенок вручную"
                            />
                            
                            <p className="text-[10px] uppercase font-bold text-slate-400 dark:text-slate-500 leading-tight">
                              Кликните по квадрату для ручного выбора,<br/>
                              либо используйте <span className="text-indigo-500 dark:text-indigo-400">основную пипетку</span><br/>
                              и установите цвет через калькулятор.
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </HighlightSection>
            </div>

          <div className={cn("animate-fade-in-up", !hasResult && "pointer-events-none opacity-35 grayscale brightness-50 transition-all duration-300")}>
            <Section title="Вид холста" isDark={isDark}>
              <SmoothSlider
                label="Толщина контуров"
                storeValue={pbnContourWeight}
                defaultValue={25}
                min={0}
                max={100}
                onCommit={(v) => update({ contourWeight: v, pbnContourWeight: v })}
                isDark={isDark}
                suffix="%"
              />
              <SmoothSlider
                label="Яркость номеров"
                storeValue={numberWeight}
                defaultValue={25}
                min={0}
                max={100}
                onCommit={(v) => update({ numberWeight: v })}
                isDark={isDark}
                suffix="%"
              />
            </Section>
          </div>
        </div>
      )}

      {/* 5. ИНСТРУМЕНТЫ / ПИПЕТКА (КАЛЬКУЛЯТОР) */}
      <div id="physics-of-preview" className="scroll-mt-4">
        <CalculatorContent 
          pickedColor={pickedColor} 
          onClose={() => update({ colorPickerActive: false, pickedColor: null, colorPickerPanelOpen: false })} 
          isMobileView={true} 
        />
      </div>
    </div>
  );
}

function ModeButton({
  active,
  onClick,
  label,
  icon,
  isDark,
}: {
  active: boolean;
  onClick: () => void;
  label: string;
  icon: React.ReactNode;
  isDark: boolean;
}) {
  return (
    <button
      onClick={onClick}
      className={cn(
        "flex-1 flex items-center justify-center gap-2 py-3 rounded-2xl text-xs font-black uppercase tracking-[0.15em] transition-all outline-none",
        active
          ? "bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-[0_2px_10px_rgba(0,0,0,0.08)] dark:shadow-[0_2px_10px_rgba(0,0,0,0.3)] scale-100"
          : "text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 active:scale-[0.98]"
      )}
    >
      <span className={cn("transition-transform duration-300", active ? "scale-110 drop-shadow-sm" : "scale-100")}>{icon}</span>
      <span className="truncate">{label}</span>
    </button>
  );
}

