import { useAppStore as useMainAppStore } from '../store/appStore';
import { useAppStore as useGeneratorStore } from '../generator/store';
import { calculateDrops } from '../engine';
import { PAINT_PROFILES, type PaintType, type SurfaceType, BASE_COLORS, SURFACE_PROFILES } from '../config';
import { rgbToHex, rgbToLab } from './colorMath';
import { getMixingDNA } from './mixing';

export async function generateDiagnosticReport(onProgress: (msg: string, pct: number) => void): Promise<string> {
  const mainState = useMainAppStore.getState();
  const genState = useGeneratorStore.getState();

  const safeCustom = Array.isArray(mainState.customColors) ? mainState.customColors : Object.values(mainState.customColors || {});
  const safeSelected = Array.isArray(mainState.selectedNames) ? mainState.selectedNames : Object.values(mainState.selectedNames || {});
  const safeBase = Array.isArray(BASE_COLORS) ? BASE_COLORS : Object.values(BASE_COLORS || {});
  const overrides = mainState.overrides || {};
  
  const allColors = [...safeBase, ...safeCustom].map((c: any) => ({
    ...c,
    rgb: overrides[c.name] || c.rgb
  }));
  const activeComps = allColors.filter(c => safeSelected.includes(c.name));

  let report = `# Глубокий Диагностический Отчет Физического Движка\n`;
  report += `Версия: ${new Date().toISOString()}\n\n`;

  report += `## 1. Глобальный Контекст и Палитра\n`;
  report += `Глобальный лимит частей (totalPartsLimit): \`${mainState.totalPartsLimit}\`\n`;
  report += `Количество активных базовых красок: ${activeComps.length}\n`;
  report += `Список красок, переданных в движок (до жесткой сортировки внутри ядра):\n`;
  activeComps.forEach(c => {
    report += `  - \`${c.name}\`: RGB(${c.rgb.join(', ')}) -> ${rgbToHex(c.rgb)}\n`;
  });
  report += `\n`;

  let colorsToTest: [number, number, number][] = [];

  if (genState.result && genState.result.validLabels) {
    report += `## 2. Целевые Цвета (из Изображения + Краш-тесты)\n`;
    const vl = genState.result.validLabels;
    let labels: number[] = [];
    if (vl instanceof Set) {
      labels = Array.from(vl);
    } else if (Array.isArray(vl)) {
      labels = vl;
    } else if (typeof vl === 'object' && vl !== null) {
      labels = Object.keys(vl).map(Number);
    }
    
    labels = labels.slice(0, 3);
    colorsToTest = labels.map(id => genState.result!.colorPalette[id]).filter(t => Array.isArray(t));
    
    // Обязательно добавляем пользовательские цвета для краш-теста
    colorsToTest.push([93, 51, 45]); // #5D332D
    colorsToTest.push([96, 51, 46]); // #60332E
  } else {
    report += `## 2. Целевые Цвета (Тестовые)\n`;
    colorsToTest = [
      [255, 0, 0],
      [0, 255, 0],
      [0, 0, 255],
      [128, 128, 128],
      [93, 51, 45], // #5D332D
      [96, 51, 46]  // #60332E
    ];
  }

  colorsToTest.forEach((target, i) => {
    report += `  [${i + 1}] Цель: RGB(${target.join(', ')}) -> ${rgbToHex(target)}\n`;
  });
  report += `\n`;

  report += `## 3. Дамп Физических Профилей Красок\n`;
  const paintTypes: PaintType[] = ['acrylic', 'watercolor', 'gouache', 'oil'];
  paintTypes.forEach(pt => {
    const p = PAINT_PROFILES[pt];
    report += `### Профиль: ${p.name} (${pt})\n`;
    report += `- Вес Кубелки-Мунка (kmWeight): ${p.kmWeight} (1.0 = полное поглощение, 0.0 = чисто оптическое)\n`;
    report += `- Базовая прозрачность (transparency): ${p.transparency}\n`;
    report += `- Влияние подложки (usesSubstrate): ${p.usesSubstrate}\n`;
    report += `- Фактор загрязнения (darkeningFactor): ${p.darkeningFactor}\n`;
    if (p.drying) {
      report += `- Высыхание: Яркость (brightnessFactor) = ${p.drying.brightnessFactor}, Насыщенность (saturationShift) = ${p.drying.saturationShift}\n`;
    } else {
      report += `- Высыхание: ОТСУТСТВУЕТ (сырая краска = сухой краске)\n`;
    }
  });
  report += `\n`;

  report += `## 4. Дамп Профилей Поверхностей\n`;
  const surfaces: SurfaceType[] = ['canvas', 'white_paper', 'wood'];
  surfaces.forEach(st => {
    const s = SURFACE_PROFILES[st];
    report += `- **${s.name} (${st})**: Цвет RGB(${s.color.join(', ')}), Впитываемость: ${s.absorption}\n`;
  });
  report += `\n`;

  report += `## 5. Матрица Стресс-Тестирования Ядра\n`;
  
  const maxColorsOptions = [2, 3, 4];
  let totalSteps = paintTypes.length * maxColorsOptions.length * colorsToTest.length + 4; // +4 for artist scenarios
  let currentStep = 0;

  for (const pt of paintTypes) {
    report += `### >>> ТЕСТ: ${PAINT_PROFILES[pt].name.toUpperCase()} <<<\n`;
    const usesSubstrate = PAINT_PROFILES[pt].usesSubstrate;
    const surfaceOptions = usesSubstrate ? surfaces : ['canvas' as SurfaceType];

    for (const surface of surfaceOptions) {
      if (usesSubstrate) {
        report += `#### Поверхность: ${SURFACE_PROFILES[surface].name}\n`;
      }

      for (const mc of maxColorsOptions) {
        report += `##### Настройки Ядра: { Лимит_Цветов: ${mc}, Тип_Краски: '${pt}', Поверхность: '${surface}', targetTotalParts: ${mainState.totalPartsLimit === 'авто' || !mainState.totalPartsLimit ? 'null (Безлимит)' : Number(mainState.totalPartsLimit)} }\n`;

        for (const target of colorsToTest) {
          onProgress(`Расчет: ${pt} / ${mc} цв. / ${rgbToHex(target)}`, Math.round((currentStep / totalSteps) * 100));
          currentStep++;

          const settings = {
            ...mainState.engineSettings,
            paintType: pt,
            surfaceType: surface,
            maxColorsInMix: mc,
            targetTotalParts: mainState.totalPartsLimit === 'авто' || !mainState.totalPartsLimit ? null : Number(mainState.totalPartsLimit)
          };

          const startTime = performance.now();
          const calcResult = await calculateDrops(target, activeComps, settings, () => {});
          const timeMs = (performance.now() - startTime).toFixed(1);

          report += `- **Цель:** \`RGB(${target.join(', ')})\` -> \`${rgbToHex(target)}\` | LAB(${rgbToLab(target).map(x=>x.toFixed(1)).join(', ')})\n`;
          report += `  - *Время расчета:* ${timeMs} мс\n`;
          
          if (calcResult.warnings && calcResult.warnings.length > 0) {
            report += `  - *Предупреждения физики:* ${calcResult.warnings.join('; ')}\n`;
          }

          if (calcResult.variants && calcResult.variants.length > 0) {
            calcResult.variants.forEach((v, vIdx) => {
              report += `  > **Вариант ${vIdx + 1} (${v.label.trim()}):**\n`;
              report += `    - **Delta E (WASM):** ${v.deltaE.toFixed(4)} | **Delta E (TypeScript):** ${v.tsDeltaE.toFixed(4)} (Оценка: ${v.rating})\n`;
              report += `    - **Сырая краска (Wet):** \`RGB(${v.wetRgb.join(', ')})\` -> \`${rgbToHex(v.wetRgb)}\` | LAB(${rgbToLab(v.wetRgb).map(x=>x.toFixed(1)).join(', ')})\n`;
              report += `      *(Оптическое смешивание [Свет]: \`RGB(${v.opticalRgb.join(', ')})\`)*\n`;
              report += `      *(Физическое смешивание [Пигмент]: \`RGB(${v.physicalRgb.join(', ')})\`)*\n`;
              if (PAINT_PROFILES[pt].drying) {
                report += `    - **Высохшая краска (Dry):** \`RGB(${v.dryRgb.join(', ')})\` -> \`${rgbToHex(v.dryRgb)}\` | LAB(${rgbToLab(v.dryRgb).map(x=>x.toFixed(1)).join(', ')})\n`;
              }
              report += `    - **Рецепт (${v.totalDrops} частей, исп. цветов: ${v.usedColors}):**\n`;
              for (const r of v.recipe) {
                report += `      - ${r.name} (${rgbToHex(r.rgb)}): ${r.parts} ч. (${r.percent}%)\n`;
              }

              // Глубокая трассировка физики только для лучшего варианта
              if (vIdx === 0 && v.totalDrops > 0) {
                const subColor = surfaceOptions.includes(surface) ? SURFACE_PROFILES[surface].color : [255, 255, 255];
                const dna = getMixingDNA(v.drops, v.components.map(c => c.rgb), PAINT_PROFILES[pt], subColor as [number, number, number]);
                if (dna) {
                  report += `\n    --- ГЛУБОКАЯ ТРАССИРОВКА ФИЗИКИ (DNA) ---\n`;
                  report += `    1. Оптическое смешивание (Linear RGB): RGB(${dna.linearMix.join(', ')})\n`;
                  report += `    2. Физическое смешивание (Kubelka-Munk + RYB):\n`;
                  report += `       - Геометрическая Яркость (Subtractive Mix Y): ${dna.kmMixY.toFixed(4)}\n`;
                  report += `       - RYB Вектор X: ${dna.kmVecX.toFixed(4)}, Y: ${dna.kmVecY.toFixed(4)}\n`;
                  report += `       - Сумма весов насыщенности (sumW): ${dna.sumW.toFixed(4)}\n`;
                  report += `       - Фактор взаимного поглощения (Cancellation Factor): ${dna.cancellationFactor.toFixed(4)}\n`;
                  report += `       - Сохранение насыщенности (Vibrancy Preservation): ${dna.vibrancyPreservation.toFixed(4)}\n`;
                  report += `       - Образование "грязи" при смешивании (Mud Drop): ${dna.mudDrop.toFixed(4)}\n`;
                  report += `       - Итоговая Яркость пигмента (Final Y): ${dna.finalY.toFixed(4)}\n`;
                  report += `       - Итоговый цвет пигмента (KM Mix): RGB(${dna.kmMix.join(', ')})\n`;
                  report += `    3. Базовая интерполяция (KM Weight = ${PAINT_PROFILES[pt].kmWeight}): RGB(${dna.interpolatedBase.join(', ')})\n`;
                  report += `    4. Эффект грязной кисти (Impurity Drop): ${dna.impurityDrop.toFixed(4)} -> RGB(${dna.dirtiedBase.join(', ')})\n`;
                  report += `    5. Прозрачность и Подложка (Alpha = ${dna.totalAlpha.toFixed(4)}): RGB(${dna.finalColor.join(', ')})\n`;
                  report += `    -----------------------------------------\n`;
                }
              }
            });
          } else {
            report += `  - **Результат:** Ошибка расчета (Ядро вернуло пустой массив вариантов).\n`;
          }
        }
        report += `\n`;
      }
    }
  }

  report += `## 6. Симуляция Реального Художника (Случайные замесы)\n`;
  report += `В этом блоке алгоритм проверяет поведение красок при типичных манипуляциях художника на палитре (isPuddle=true) и на холсте.\n\n`;

  const runScenario = (title: string, drops: number[], comps: any[], profileId: PaintType, substrate: SurfaceType, isPuddle: boolean) => {
    onProgress(`Сценарий: ${title}`, Math.round((currentStep / totalSteps) * 100));
    currentStep++;
    
    report += `### Сценарий: ${title}\n`;
    report += `- Тип краски: ${PAINT_PROFILES[profileId].name}, Подложка: ${SURFACE_PROFILES[substrate].name}, В лужице (на палитре): ${isPuddle ? 'Да' : 'Нет'}\n`;
    report += `- Ингредиенты:\n`;
    comps.forEach((c, i) => {
      if (drops[i] > 0) report += `  - ${c.name} (${rgbToHex(c.rgb)}): ${drops[i]} ч.\n`;
    });

    const profile = PAINT_PROFILES[profileId];
    const subColor = SURFACE_PROFILES[substrate].color;
    const dna = getMixingDNA(drops, comps.map(c => c.rgb), profile, subColor as [number, number, number], isPuddle);
    
    if (dna) {
      report += `\n#### Результат смешивания (DNA)\n`;
      report += `- Векторный конфликт (Cancellation): ${dna.cancellationFactor.toFixed(4)} (Чем ниже, тем больше противоположных оттенков уничтожили друг друга)\n`;
      report += `- Потеря яркости от смешивания (Mud Drop): ${dna.mudDrop.toFixed(4)}\n`;
      report += `- Фактор грязной кисти (Impurity Drop): ${dna.impurityDrop.toFixed(4)}\n`;
      report += `- Коэффициент непрозрачности (Total Alpha): ${dna.totalAlpha.toFixed(4)}\n`;
      report += `- **Итоговый цвет:** RGB(${dna.finalColor.join(', ')}) -> ${rgbToHex(dna.finalColor)} | LAB(${rgbToLab(dna.finalColor).map(x=>x.toFixed(1)).join(', ')})\n\n`;
    }
  };

  // Сценарий 1: Комплементарная грязь (Желтый + Фиолетовый)
  const yIdx = activeComps.findIndex(c => c.name.toLowerCase().includes('жёлт'));
  const pIdx = activeComps.findIndex(c => c.name.toLowerCase().includes('фиолет'));
  if (yIdx >= 0 && pIdx >= 0) {
    const drops = new Array(activeComps.length).fill(0);
    drops[yIdx] = 5;
    drops[pIdx] = 5;
    runScenario("Комплементарное уничтожение (Желтый + Фиолетовый)", drops, activeComps, 'acrylic', 'canvas', false);
  } else {
    currentStep++;
  }

  // Сценарий 2: Высветление белилами (Красный + много Белого)
  const rIdx = activeComps.findIndex(c => c.name.toLowerCase().includes('красн'));
  const wIdx = activeComps.findIndex(c => c.name.toLowerCase().includes('бел'));
  if (rIdx >= 0 && wIdx >= 0) {
    const drops = new Array(activeComps.length).fill(0);
    drops[rIdx] = 1;
    drops[wIdx] = 10;
    runScenario("Пастелизация белилами (1 ч. Красного + 10 ч. Белого)", drops, activeComps, 'acrylic', 'canvas', false);
  } else {
    currentStep++;
  }

  // Сценарий 3: Лессировка акварелью (одна капля на бумаге)
  const bIdx = activeComps.findIndex(c => c.name.toLowerCase().includes('син') || c.name.toLowerCase().includes('голуб'));
  if (bIdx >= 0) {
    const drops = new Array(activeComps.length).fill(0);
    drops[bIdx] = 1;
    runScenario("Тонкая лессировка (1 ч. Синего Акварелью на Белой Бумаге)", drops, activeComps, 'watercolor', 'white_paper', false);
  } else {
    currentStep++;
  }

  // Сценарий 4: Хаос художника (10 случайных красок в равных пропорциях)
  if (activeComps.length >= 8) {
    const drops = new Array(activeComps.length).fill(0);
    for(let i = 0; i < Math.min(10, activeComps.length); i++) drops[i] = 1;
    runScenario("Хаос на палитре (Смесь 10 разных красок в лужице)", drops, activeComps, 'oil', 'canvas', true);
  } else {
    currentStep++;
  }

  onProgress("Отчет готов", 100);
  return report;
}