// src/calib/markers.ts
//
// Поиск угловых меток-мишеней на фотографии бланка.
//
// Почему именно концентрические квадраты, а не «найди углы листа»: край листа
// теряется на белом столе, заламывается, попадает в тень. А мишень
// чёрный→белый→чёрный даёт по центральной линии строго пять чередующихся
// отрезков с известными пропорциями — узор, которого в кадре с красками
// практически не бывает. Это и есть основной критерий отбора.

import { MARKER, SHEET_W_MM, SHEET_H_MM } from './sheetSpec';

export interface DetectedMarker {
  x: number; y: number;   // центр в координатах ИСХОДНОГО фото
  size: number;           // сторона внешнего квадрата, px
  score: number;
}

interface Component {
  minX: number; maxX: number; minY: number; maxY: number;
  area: number; sumX: number; sumY: number;
}

/** Яркость по Rec.601 — для порога важна воспринимаемая светлота, не среднее. */
function toGray(img: ImageData): Uint8ClampedArray {
  const { data, width, height } = img;
  const g = new Uint8ClampedArray(width * height);
  for (let i = 0, p = 0; p < g.length; p++, i += 4) {
    g[p] = (data[i] * 299 + data[i + 1] * 587 + data[i + 2] * 114) / 1000;
  }
  return g;
}

/**
 * Локальный порог по интегральному изображению (метод Брэдли).
 * Глобальный Оцу проваливается ровно в нашем случае: половина листа у окна
 * светлее другой, и один порог либо съедает метки в тени, либо заливает
 * чёрным светлую часть.
 */
function adaptiveThreshold(gray: Uint8ClampedArray, w: number, h: number): Uint8Array {
  const integral = new Float64Array((w + 1) * (h + 1));
  for (let y = 0; y < h; y++) {
    let rowSum = 0;
    for (let x = 0; x < w; x++) {
      rowSum += gray[y * w + x];
      integral[(y + 1) * (w + 1) + (x + 1)] = integral[y * (w + 1) + (x + 1)] + rowSum;
    }
  }

  const half = Math.max(4, Math.round(Math.min(w, h) / 24));
  const bin = new Uint8Array(w * h); // 1 = чёрное
  const T = 0.86; // пиксель темнее 86 % локального среднего считаем чёрным

  for (let y = 0; y < h; y++) {
    const y0 = Math.max(0, y - half), y1 = Math.min(h - 1, y + half);
    for (let x = 0; x < w; x++) {
      const x0 = Math.max(0, x - half), x1 = Math.min(w - 1, x + half);
      const count = (x1 - x0 + 1) * (y1 - y0 + 1);
      const sum =
        integral[(y1 + 1) * (w + 1) + (x1 + 1)] -
        integral[y0 * (w + 1) + (x1 + 1)] -
        integral[(y1 + 1) * (w + 1) + x0] +
        integral[y0 * (w + 1) + x0];
      bin[y * w + x] = gray[y * w + x] * count < sum * T ? 1 : 0;
    }
  }
  return bin;
}

/** Связные компоненты чёрного (4-связность, итеративная заливка). */
function blackComponents(bin: Uint8Array, w: number, h: number, minArea: number): Component[] {
  const seen = new Uint8Array(w * h);
  const out: Component[] = [];
  const stack = new Int32Array(w * h);

  for (let start = 0; start < bin.length; start++) {
    if (!bin[start] || seen[start]) continue;
    let sp = 0;
    stack[sp++] = start;
    seen[start] = 1;

    const c: Component = { minX: w, maxX: -1, minY: h, maxY: -1, area: 0, sumX: 0, sumY: 0 };

    while (sp > 0) {
      const p = stack[--sp];
      const x = p % w, y = (p / w) | 0;
      c.area++; c.sumX += x; c.sumY += y;
      if (x < c.minX) c.minX = x; if (x > c.maxX) c.maxX = x;
      if (y < c.minY) c.minY = y; if (y > c.maxY) c.maxY = y;

      if (x > 0 && bin[p - 1] && !seen[p - 1]) { seen[p - 1] = 1; stack[sp++] = p - 1; }
      if (x < w - 1 && bin[p + 1] && !seen[p + 1]) { seen[p + 1] = 1; stack[sp++] = p + 1; }
      if (y > 0 && bin[p - w] && !seen[p - w]) { seen[p - w] = 1; stack[sp++] = p - w; }
      if (y < h - 1 && bin[p + w] && !seen[p + w]) { seen[p + w] = 1; stack[sp++] = p + w; }
    }

    if (c.area >= minArea) out.push(c);
  }
  return out;
}

/**
 * Длины чередующихся отрезков вдоль линии, начиная с первого чёрного.
 *
 * Наивный вариант «просто посчитать переходы» здесь не работает по двум
 * причинам, обе выяснились на стенде:
 *  • bbox компоненты шире, чем её след на конкретной строке (углы квадрата
 *    съезжают из-за ракурса), поэтому линия начинается и кончается белым;
 *  • порог оставляет одиночные пиксели-«соринки», и вместо пяти отрезков
 *    получается семь.
 * Поэтому краевые белые отрезки срезаем, а слишком короткие — вливаем в соседей.
 */
function cleanRuns(
  bin: Uint8Array, w: number, h: number,
  x0: number, y0: number, dx: number, dy: number, steps: number,
): number[] | null {
  const runs: { v: number; len: number }[] = [];
  for (let i = 0; i < steps; i++) {
    const x = x0 + dx * i, y = y0 + dy * i;
    if (x < 0 || y < 0 || x >= w || y >= h) return null;
    const v = bin[y * w + x];
    const last = runs[runs.length - 1];
    if (last && last.v === v) last.len++;
    else runs.push({ v, len: 1 });
  }

  trimWhiteEnds(runs);
  if (!runs.length || runs[0].v !== 1) return null;

  const minLen = Math.max(2, Math.round(steps * 0.045));
  for (let guard = 0; guard < 32; guard++) {
    const i = runs.findIndex(r => r.len < minLen);
    if (i === -1) break;
    if (runs.length <= 1) break;
    if (i === 0) { runs[1].len += runs[0].len; runs.splice(0, 1); }
    else if (i === runs.length - 1) { runs[i - 1].len += runs[i].len; runs.splice(i, 1); }
    else { runs[i - 1].len += runs[i].len + runs[i + 1].len; runs.splice(i, 2); }
  }

  trimWhiteEnds(runs);
  if (!runs.length || runs[0].v !== 1) return null;

  return runs.map(r => r.len);
}

/** Срезает белые отрезки по краям линии (bbox всегда чуть шире следа метки). */
function trimWhiteEnds(runs: { v: number; len: number }[]): void {
  while (runs.length && runs[0].v === 0) runs.shift();
  while (runs.length && runs[runs.length - 1].v === 0) runs.pop();
}

/**
 * Проверка «матрёшки» по центральной линии компоненты.
 * Ждём ровно 5 отрезков Ч-Б-Ч-Б-Ч с пропорциями из MARKER.
 * Возвращает 0..1 — насколько профиль похож на эталон.
 */
function ringProfileScore(bin: Uint8Array, w: number, h: number, c: Component): number {
  const cx = Math.round(c.sumX / c.area), cy = Math.round(c.sumY / c.area);
  const bw = c.maxX - c.minX + 1, bh = c.maxY - c.minY + 1;

  const expected = [
    (MARKER.outerMm - MARKER.midMm) / 2,
    (MARKER.midMm - MARKER.innerMm) / 2,
    MARKER.innerMm,
    (MARKER.midMm - MARKER.innerMm) / 2,
    (MARKER.outerMm - MARKER.midMm) / 2,
  ];
  const expSum = expected.reduce((a, b) => a + b, 0);

  const check = (horizontal: boolean): number => {
    // Берём с запасом в 2 пикселя за bbox: край квадрата под углом «съезжает»,
    // и без запаса можно начать сканирование уже внутри белого кольца.
    const pad = 2;
    const x0 = horizontal ? c.minX - pad : cx;
    const y0 = horizontal ? cy : c.minY - pad;
    const steps = (horizontal ? bw : bh) + pad * 2;

    const runs = cleanRuns(bin, w, h, x0, y0, horizontal ? 1 : 0, horizontal ? 0 : 1, steps);
    if (!runs || runs.length !== 5) return 0;

    const total = runs.reduce((a, b) => a + b, 0);
    let err = 0;
    for (let i = 0; i < 5; i++) {
      const want = (expected[i] / expSum) * total;
      err += Math.abs(runs[i] - want) / Math.max(2, want);
    }
    return Math.max(0, 1 - err / 5);
  };

  return (check(true) + check(false)) / 2;
}

/**
 * Ищет 4 угловые метки. Возвращает их в порядке TL, TR, BL, BR
 * или null, если уверенно найти не удалось (тогда UI просит указать углы вручную).
 */
export function detectMarkers(img: ImageData): DetectedMarker[] | null {
  const { width: w, height: h } = img;
  const gray = toGray(img);
  const bin = adaptiveThreshold(gray, w, h);

  const minSide = Math.min(w, h);
  // Метка занимает 14 мм из 210 мм ширины листа. С запасом на кадрирование и
  // на то, что лист может не заполнять кадр целиком.
  const minSize = minSide * 0.012;
  const maxSize = minSide * 0.18;

  const comps = blackComponents(bin, w, h, Math.round(minSize * minSize * 0.35));
  const cands: DetectedMarker[] = [];

  for (const c of comps) {
    const bw = c.maxX - c.minX + 1, bh = c.maxY - c.minY + 1;
    if (bw < minSize || bh < minSize || bw > maxSize || bh > maxSize) continue;

    const aspect = bw / bh;
    if (aspect < 0.7 || aspect > 1.43) continue; // ракурс может сплющить, но не сильно

    // Доля чёрного внутри рамки. Для нашей матрёшки это
    // (outer² − mid² + inner²) / outer² ≈ 0.74; сплошной квадрат дал бы 1.0,
    // буква или пятно краски — заметно меньше.
    const fill = c.area / (bw * bh);
    const ideal =
      (MARKER.outerMm ** 2 - MARKER.midMm ** 2 + MARKER.innerMm ** 2) / MARKER.outerMm ** 2;
    if (fill < ideal - 0.16 || fill > ideal + 0.14) continue;

    const profile = ringProfileScore(bin, w, h, c);
    if (profile < 0.45) continue;

    const fillScore = 1 - Math.abs(fill - ideal) / 0.16;
    const aspectScore = 1 - Math.abs(1 - aspect) / 0.43;

    cands.push({
      x: c.sumX / c.area,
      y: c.sumY / c.area,
      size: (bw + bh) / 2,
      score: profile * 0.6 + fillScore * 0.25 + aspectScore * 0.15,
    });
  }

  if (cands.length < 4) return null;

  cands.sort((a, b) => b.score - a.score);

  // Метки на одном листе примерно одного размера — это отсекает случайные
  // «мишени» на фоне (узор обоев, логотип на тюбике).
  const best = cands[0];
  const sameSize = cands.filter(c => c.size > best.size * 0.55 && c.size < best.size * 1.8);
  if (sameSize.length < 4) return null;

  const four = pickBestQuad(sameSize.slice(0, 12));
  if (!four) return null;

  return orderCorners(four);
}

/** Из кандидатов выбирает четвёрку, максимально похожую на углы листа A4. */
function pickBestQuad(cands: DetectedMarker[]): DetectedMarker[] | null {
  if (cands.length === 4) return cands;

  const targetAspect = SHEET_W_MM / SHEET_H_MM;
  let best: DetectedMarker[] | null = null;
  let bestScore = -Infinity;

  for (let a = 0; a < cands.length; a++)
    for (let b = a + 1; b < cands.length; b++)
      for (let c = b + 1; c < cands.length; c++)
        for (let d = c + 1; d < cands.length; d++) {
          const quad = [cands[a], cands[b], cands[c], cands[d]];
          const xs = quad.map(p => p.x), ys = quad.map(p => p.y);
          const bw = Math.max(...xs) - Math.min(...xs);
          const bh = Math.max(...ys) - Math.min(...ys);
          if (bw < 20 || bh < 20) continue;

          const aspect = bw / bh;
          const aspectErr = Math.abs(aspect - targetAspect) / targetAspect;
          if (aspectErr > 0.45) continue; // ракурс искажает, но A4 не станет квадратом

          const area = bw * bh;
          const conf = quad.reduce((s, p) => s + p.score, 0) / 4;
          const score = conf * 2 - aspectErr + Math.log(area) * 0.15;
          if (score > bestScore) { bestScore = score; best = quad; }
        }

  return best;
}

/** TL, TR, BL, BR. Считаем, что лист не повёрнут более чем на ~40°. */
function orderCorners(q: DetectedMarker[]): DetectedMarker[] {
  const bySum = [...q].sort((a, b) => (a.x + a.y) - (b.x + b.y));
  const tl = bySum[0], br = bySum[3];
  const rest = bySum.slice(1, 3);
  const [tr, bl] = rest[0].y <= rest[1].y ? [rest[0], rest[1]] : [rest[1], rest[0]];
  return [tl, tr, bl, br];
}

/** Ожидаемые центры меток в координатах листа (мм), в порядке TL, TR, BL, BR. */
export const MARKER_CENTERS_MM = MARKER.centers.map(c => ({ x: c.x, y: c.y }));

/** Те же центры, повёрнутые на 180° — для проверки перевёрнутого кадра. */
export const MARKER_CENTERS_MM_FLIPPED = MARKER.centers.map(c => ({
  x: SHEET_W_MM - c.x,
  y: SHEET_H_MM - c.y,
}));
