import { useRef, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { useEscapeKey } from '../../hooks/useEscapeKey';
import { useFocusTrap } from '../../hooks/useFocusTrap';
import { useBodyScrollLock } from '../../hooks/useBodyScrollLock';
import { useBackButton } from '../../hooks/useBackButton';
import { cn } from '../../utils/cn';

export function Modal({ children, onClose, zClass = "z-[100]" }: { children: React.ReactNode; onClose: () => void; zClass?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  useEscapeKey(onClose, true); useFocusTrap(ref, true); useBodyScrollLock(true); useBackButton(true, onClose);
  
  if (!mounted) return null;
  return createPortal(
    <div className={cn("fixed inset-0 flex items-end sm:items-center justify-center modal-backdrop sm:p-6", zClass)} onClick={onClose}>
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" />
      <div ref={ref} role="dialog" aria-modal="true" className="relative bg-white/95 dark:bg-slate-900/90 backdrop-blur-2xl rounded-t-3xl sm:rounded-3xl w-full sm:max-w-md max-h-[80dvh] sm:max-h-[80vh] flex flex-col shadow-[0_20px_60px_-15px_rgba(0,0,0,0.3)] dark:shadow-[0_20px_60px_-15px_rgba(0,0,0,0.7)] border border-white/40 dark:border-white/10 modal-enter" onClick={e => e.stopPropagation()}>
        <button className="sm:hidden w-full pt-3 pb-2 flex justify-center shrink-0" onClick={onClose} aria-label="Закрыть">
          <div className="w-10 h-1 rounded-full bg-slate-300 dark:bg-slate-600" />
        </button>
        {children}
      </div>
    </div>,
    document.body
  );
}

