// src/generator/utils/autoPreset/scoring.ts
//
// ЗОРКАЯ метрика качества варианта раскраски «по номерам» для «Автоподбора».
//
// Идея прежняя: движок — идеальный предсказатель своих ползунков, поэтому мы
// прогоняем его «вхолостую» на уменьшенной копии и оцениваем РЕЗУЛЬТАТ числом.
// Но раньше метрика была слепой (fidelity/structure сжимались 1/(1+x) и все
// варианты схлопывались к ~35%). Теперь она нацелена ПРЯМО на те беды, которые
// губят генерацию, и — главное — РАЗЛИЧАЕТ варианты:
//
//   • colorFidelity   — совпадение цветов с фото (ΔE2000, субъект-первый вес);
//   • featureKept     — сохранены ли ЧЕРТЫ в ядре субъекта (глаза/мимика): доля
//                       удержанной энергии краёв в самой важной зоне. Ловит
//                       «лицо-кашу»/«мыло»;
//   • separation      — не слился ли объект с фоном: удержан ли ЦВЕТОВОЙ контраст
//                       на силуэте (границе значимости). Ловит «лапа = песок»;
//   • paintability    — удобство раскраски: чистый фон без рассыпанных микрозон.
//
// featureKept и separation — ОТНОШЕНИЯ (0..1), они естественно разлетаются между
// мыльным и детальным вариантом, поэтому итоговый балл больше не схлопывается.

import { rgbToLab, deltaE00 } from "../../../utils/colorMath";
import type { ProcessingResult } from "../imageProcessing/types";

export interface ScoreBreakdown {
  fidelity: number;     // 0..1 — верность цвета (выше лучше)
  structure: number;    // 0..1 — сохранность важных черт (выше лучше)
  paintability: number; // 0..1 — удобство раскраски (выше лучше)
  similarity: number;   // 0..1 — сходство с фото (цвет+черты+силуэт) для отбора «колена»
  meanDeltaE: number;   // средневзвешенный ΔE2000 (для подписи)
  usedColors: number;   // реально использованных красок
  zones: number;        // всего зон
  microzones: number;   // из них паразитных
  score: number;        // итоговый сбалансированный балл 0..1
}

// Веса ИТОГОВОГО балла. ГЛАВНЫЙ драйвер — «проявленность черт» (feature): именно
// её пользователь вытягивает руками (тени в минус), именно «максимум деталей в
// разумном плане» он и хочет. Цвет чуть ниже, чтобы полезная тонировка, слегка
// сдвигающая цвет, но проявляющая лицо, не штрафовалась сильнее, чем помогает.
const WEIGHTS = { color: 0.26, feature: 0.30, separation: 0.22, paint: 0.22 };
// Веса «сходства» (для отбора «колена кривой»): похожесть на фото, черты — во главе.
const SIM = { color: 0.34, feature: 0.40, separation: 0.26 };

/** Предвычисленная «эталонная» ссылка на оригинал (считается один раз на фото). */
export interface OrigRef {
  W: number;
  H: number;
  lab: Float32Array;    // 3*N: L,a,b оригинала (после базовой коррекции)
  grad: Float32Array;   // N: магнитуда градиента яркости оригинала
  imp: Float32Array;    // N: важность 0..1 (0.5 если карты нет)
  impGrad: Float32Array; // N: магнитуда градиента карты значимости (силуэт субъекта)
  hasSubject: boolean;  // есть ли выраженный субъект (для выбора ядра/границы)
}

function luma(r: number, g: number, b: number): number {
  return 0.299 * r + 0.587 * g + 0.114 * b;
}

/** Строит эталон из уменьшенного ОРИГИНАЛА + карты значимости. */
export function buildOrigRef(base: ImageData, importance: Float32Array | null): OrigRef {
  const W = base.width, H = base.height, N = W * H;
  const d = base.data;
  const lab = new Float32Array(3 * N);
  const Y = new Float32Array(N);
  for (let i = 0, p = 0; i < N; i++, p += 4) {
    const l = rgbToLab([d[p], d[p + 1], d[p + 2]]);
    lab[i * 3] = l[0]; lab[i * 3 + 1] = l[1]; lab[i * 3 + 2] = l[2];
    Y[i] = luma(d[p], d[p + 1], d[p + 2]);
  }
  const grad = gradMag(Y, W, H);

  let imp: Float32Array;
  let hasSubject = false;
  if (importance && importance.length === N) {
    imp = importance;
    let hi = 0; for (let i = 0; i < N; i++) if (imp[i] > 0.6) hi++;
    hasSubject = hi / N > 0.02;
  } else {
    imp = new Float32Array(N).fill(0.5);
  }
  const impGrad = hasSubject ? gradMag(imp, W, H) : new Float32Array(N);
  return { W, H, lab, grad, imp, impGrad, hasSubject };
}

/** Магнитуда градиента (центральные разности). */
function gradMag(F: Float32Array, W: number, H: number): Float32Array {
  const g = new Float32Array(W * H);
  for (let y = 1; y < H - 1; y++) {
    for (let x = 1; x < W - 1; x++) {
      const i = y * W + x;
      const gx = F[i + 1] - F[i - 1];
      const gy = F[i + W] - F[i - W];
      g[i] = Math.sqrt(gx * gx + gy * gy);
    }
  }
  return g;
}

/**
 * Оценивает один результат генерации против эталона.
 */
export function scoreCandidate(ref: OrigRef, res: ProcessingResult): ScoreBreakdown {
  const W = ref.W, H = ref.H, N = W * H;
  const pv = res.previewImageData.data;
  const { lab, grad, imp, impGrad, hasSubject } = ref;

  // Мемоизация Lab для превью: палитра мала, попаданий много.
  const labMemo = new Map<number, [number, number, number]>();
  const labOf = (r: number, g: number, b: number): [number, number, number] => {
    const key = (r << 16) | (g << 8) | b;
    let v = labMemo.get(key);
    if (!v) { v = rgbToLab([r, g, b]); labMemo.set(key, v); }
    return v;
  };
  const pvLabIdx = (i: number): [number, number, number] => {
    const p = i * 4; return labOf(pv[p], pv[p + 1], pv[p + 2]);
  };

  // --- 1) Fidelity (цвет), субъект-первый вес + сбор яркости превью ---
  const Yp = new Float32Array(N);
  let deSum = 0, wSum = 0;
  for (let i = 0, p = 0; i < N; i++, p += 4) {
    const r = pv[p], g = pv[p + 1], b = pv[p + 2];
    Yp[i] = luma(r, g, b);
    const pl = labOf(r, g, b);
    const de = deltaE00([lab[i * 3], lab[i * 3 + 1], lab[i * 3 + 2]], pl);
    const w = imp[i] * imp[i] + 0.04; // лицо/объект доминирует, фон почти не влияет
    deSum += w * de; wSum += w;
  }
  const meanDeltaE = wSum > 0 ? deSum / wSum : 0;
  // Растянутая шкала: ΔE 3→~1, 9→~0.55, 15→~0.33. Спред обеспечивают feature/separation.
  const colorFidelity = clamp01(1 / (1 + Math.max(0, meanDeltaE - 3) / 7));

  // --- 2) FeatureKept: удержаны ли ЧЕРТЫ в ЯДРЕ субъекта (глаза/мимика) ---
  // Доля удержанной энергии краёв там, где важно. Мыло → мало; детальность → много.
  const gradP = gradMag(Yp, W, H);
  const coreThr = hasSubject ? 0.55 : 0;      // ядро субъекта
  let keptSum = 0, coreSum = 0;
  for (let i = 0; i < N; i++) {
    const wimp = hasSubject ? (imp[i] >= coreThr ? imp[i] * imp[i] : 0) : 1;
    if (wimp <= 0) continue;
    const go = grad[i];
    if (go < 1e-3) continue;                   // где краёв нет — нечего терять
    keptSum += wimp * Math.min(gradP[i], go);
    coreSum += wimp * go;
  }
  const featureKept = coreSum > 0 ? clamp01(keptSum / coreSum) : 0.6;

  // --- 3) Separation: не слился ли объект с фоном (ЦВЕТ-контраст на силуэте) ---
  // На границе значимости сравниваем локальный цветовой контраст оригинала и
  // превью. Если фото имело контраст, а раскраска его «сплющила» — штраф.
  let sep = 0.7;
  if (hasSubject) {
    // Порог границы: заметная часть максимума градиента карты значимости.
    let maxIG = 0; for (let i = 0; i < N; i++) if (impGrad[i] > maxIG) maxIG = impGrad[i];
    const igThr = maxIG * 0.12;
    let sSum = 0, sCnt = 0;
    if (maxIG > 1e-4) {
      for (let y = 1; y < H - 1; y++) {
        for (let x = 1; x < W - 1; x++) {
          const i = y * W + x;
          if (impGrad[i] < igThr) continue;    // только силуэт субъекта
          // Цветовой контраст к правому и нижнему соседу.
          const o0: [number, number, number] = [lab[i * 3], lab[i * 3 + 1], lab[i * 3 + 2]];
          const oR: [number, number, number] = [lab[(i + 1) * 3], lab[(i + 1) * 3 + 1], lab[(i + 1) * 3 + 2]];
          const oD: [number, number, number] = [lab[(i + W) * 3], lab[(i + W) * 3 + 1], lab[(i + W) * 3 + 2]];
          const origC = deltaE00(o0, oR) + deltaE00(o0, oD);
          if (origC < 4) continue;             // на фото тут и так почти нет границы
          const p0 = pvLabIdx(i), pR = pvLabIdx(i + 1), pD = pvLabIdx(i + W);
          const prevC = deltaE00(p0, pR) + deltaE00(p0, pD);
          sSum += clamp01(prevC / origC);
          sCnt++;
        }
      }
    }
    sep = sCnt > 0 ? sSum / sCnt : 0.7;
  } else {
    // Нет субъекта — «слияние» неактуально, отдаём нейтрально-высокое.
    sep = 0.85;
  }
  const separation = clamp01(sep);

  // --- 4) Paintability + анти-хаос фона ---
  const pxN = W * H || 1;
  const scaleN = Math.max(0.35, Math.min(2.2, pxN / 520000));
  const areaMinN = 16 * scaleN, thinMaxN = 1.4, sliverAN = 40 * scaleN;
  const zones = res.contoursData.length;
  let micro = 0, microBg = 0, bgSmall = 0;
  for (const cd of res.contoursData as any[]) {
    if (res.validLabels && !res.validLabels.has(cd.labelId)) continue;
    const cx = Math.max(0, Math.min(W - 1, Math.round((cd.center && cd.center[0]) || 0)));
    const cy = Math.max(0, Math.min(H - 1, Math.round((cd.center && cd.center[1]) || 0)));
    const impZ = imp[cy * W + cx] || 0;
    const isMicro = cd.area <= areaMinN || (cd.maxDist < thinMaxN && cd.area <= sliverAN);
    if (isMicro) { micro++; microBg += 1 - Math.min(1, impZ); }
    if (impZ < 0.3 && cd.area <= 3 * areaMinN) bgSmall++;
  }
  const usedColors = res.validLabels ? res.validLabels.size : 0;
  const microBgFrac = zones > 0 ? microBg / zones : 0;
  const bgFragFrac = zones > 0 ? bgSmall / zones : 0;
  // Штраф за расход красок. Мягкий ГЛОБАЛЬНЫЙ уклон (с ~14 красок) — чтобы при
  // равном качестве побеждала более экономная палитра (простой Луне не нужно 40
  // цветов). Плюс усиленная кара за явный перебор (>34). Но всё это слабее, чем
  // выигрыш по чертам/цвету на сложном фото, поэтому портрет остаётся богатым.
  const paintability = clamp01(
    1
    - 1.7 * microBgFrac
    - 0.9 * bgFragFrac
    - 0.0016 * Math.max(0, usedColors - 14)
    - 0.006 * Math.max(0, usedColors - 34),
  );

  // Сходство — только про похожесть на фото (цвет + черты + силуэт).
  const similarity = clamp01(
    (SIM.color * colorFidelity + SIM.feature * featureKept + SIM.separation * separation) /
    (SIM.color + SIM.feature + SIM.separation),
  );

  const score = clamp01(
    WEIGHTS.color * colorFidelity +
    WEIGHTS.feature * featureKept +
    WEIGHTS.separation * separation +
    WEIGHTS.paint * paintability,
  );

  return {
    fidelity: colorFidelity,
    structure: featureKept,
    paintability,
    similarity,
    meanDeltaE,
    usedColors,
    zones,
    microzones: micro,
    score,
  };
}

function clamp01(x: number): number {
  return x < 0 ? 0 : x > 1 ? 1 : x;
}
