// src/generator/utils/canvasMaterialGL.ts
//
// Тот же расчёт физики материала, но на видеокарте.
//
// ЗАЧЕМ. Проход по каждому пикселю на процессоре занимает около 370 мс на
// полном превью. Для статичной картинки это незаметно, но ползунок света так
// не потащишь: приходилось откладывать перерисовку на 140 мс, и отклик выходил
// вязким. Здесь ровно та же модель выражена шейдером, и кадр считается за
// единицы миллисекунд — свет можно двигать и смотреть, как поворачивается
// рельеф.
//
// ЧТО ВАЖНО ПОНИМАТЬ ПРО УСТРОЙСТВО. Схема рисуется в обычный двумерный холст,
// а на одном холсте нельзя одновременно держать контекст 2D и контекст WebGL.
// Поэтому расчёт идёт в отдельный скрытый холст, а результат возвращается
// в исходный обычным drawImage. Это дешевле, чем кажется: копирование
// картинки видеокартой стоит доли миллисекунды.
//
// ФОРМУЛЫ СОВПАДАЮТ С ПРОЦЕССОРНОЙ ВЕРСИЕЙ намеренно, вплоть до констант.
// Две реализации одной модели, расходящиеся в мелочах, — источник вопросов
// вида «почему на этом компьютере картина другая»; здесь при отсутствии
// WebGL просто включается процессорный проход, и глазу разницы нет.

import type { ProcessingResult } from './imageProcessing';
import type { MaterialParams } from './canvasMaterial';
import { kelvinToRgb, PAINT_MATERIAL, SURFACE_MATERIAL, edgeDistance } from './canvasMaterial';
import { SURFACE_GLSL, KIND_INDEX, findSurfacePreset, defaultSurfaceFor } from './surfacePresets';

/* ── Шейдеры ────────────────────────────────────────────────────────────────*/

const VERT = `#version 300 es
in vec2 aPos;
out vec2 vUv;
void main() {
  // Ось Y переворачивается здесь, а не при загрузке текстур. Так и схема,
  // и карта расстояний читаются в одной системе координат — сверху вниз,
  // как в процессорной версии, — и никакие настройки распаковки на это
  // не влияют.
  vUv = vec2(aPos.x * 0.5 + 0.5, 0.5 - aPos.y * 0.5);
  gl_Position = vec4(aPos, 0.0, 1.0);
}`;

const FRAG_SRC = `#version 300 es
precision highp float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D uAlbedo;   // готовая плоская схема
uniform sampler2D uDist;     // расстояние до края зоны, в пикселях маски / 8
uniform sampler2D uNoise;    // шумовая плитка 256x256
uniform sampler2D uSurface;  // снятая фактура поверхности

uniform vec2  uSize;         // размер холста в пикселях
uniform float uScale;        // во сколько раз холст крупнее маски

uniform float uMmPerPx;      // миллиметров на пиксель холста
uniform int   uKind;         // род структуры основы
uniform float uPitch;        // шаг структуры, мм
uniform float uPitch2;       // второй шаг: понтюзо, годичные слои
uniform float uIrr;          // неправильность структуры
uniform float uAniso;        // вытянутость вдоль волокна
uniform float uDepth;        // глубина рельефа основы
uniform float uGrainScale;   // масштаб выборки шума слоя

uniform float uBodyAmp;      // тело краски
uniform float uStreak;       // след мазка
uniform float uLayerGrain;   // зерно самого слоя
uniform float uStrokeCos;
uniform float uStrokeSin;

uniform float uUseSurface;   // 1 — использовать снятую фактуру
uniform float uTexPerPx;     // текселей плитки на пиксель холста
uniform float uSurfAmp;

uniform vec3  uLightDir;
uniform vec3  uHalf;
uniform vec3  uLightRgb;
uniform float uKs;
uniform float uShininess;
uniform float uShowThrough;
uniform float uStrength;
uniform float uNormalGain;
uniform float uLitNorm;
uniform float uAmbient;

uniform float uTexN;

// Половина текселя добавляется не для красоты: центр текселя лежит в (i+0.5),
// и без поправки выборка на видеокарте оказывается сдвинутой относительно
// процессорной ровно на полшага. На зерне это даёт заметное расхождение
// двух путей — картинка «дёргалась» бы при переключении между ними.
float noiseAt(vec2 p) {
  return texture(uNoise, (p + 0.5) / 256.0).r * 2.0 - 1.0;
}

__SURFACE_GLSL__

// Отражённое повторение: при обычном плитка стыкуется видимым швом.
float mirrorCoord(float v) {
  float p2 = 2.0 * uTexN;
  float m = mod(v, p2);
  return m < uTexN ? m : p2 - 1.0 - m;
}

float heightAt(vec2 px) {
  float base;
  if (uUseSurface > 0.5) {
    vec2 t = vec2(mirrorCoord(px.x * uTexPerPx), mirrorCoord(px.y * uTexPerPx));
    base = (texture(uSurface, (t + 0.5) / uTexN).r - 0.5) * 2.0 * uSurfAmp;
  } else {
    base = uDepth * surfaceHeight(px * uMmPerPx, uKind, uPitch, uPitch2, uIrr, uAniso);
  }

  // Тело краски: у кромки мазок тоньше, к середине толще, по самой кромке
  // краска скапливается валиком.
  // В текстуре расстояние упаковано как доля от восьми пикселей маски.
  float dPx = texture(uDist, (px + 0.5) / uSize).r * 8.0 * uScale;
  float fill = clamp(dPx / (3.0 * uScale), 0.0, 1.0);
  float rim = exp(-pow(dPx - 1.1 * uScale, 2.0) / (1.4 * uScale * uScale));
  float body = uBodyAmp * (0.78 * (fill * fill * (3.0 - 2.0 * fill)) + 0.35 * rim);

  float streak = 0.0;
  if (uStreak > 0.0) {
    float u = (px.x * uStrokeCos + px.y * uStrokeSin) * uGrainScale * 0.35;
    float v = (-px.x * uStrokeSin + px.y * uStrokeCos) * uGrainScale * 2.6;
    streak = uStreak * noiseAt(vec2(u, v));
  }

  float lg = uLayerGrain > 0.0
    ? uLayerGrain * noiseAt(px * uGrainScale * 2.3 + vec2(91.7, 43.1))
    : 0.0;

  return base + body + streak + lg;
}

vec3 toLinear(vec3 c) {
  return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c));
}
vec3 toSrgb(vec3 c) {
  c = clamp(c, 0.0, 1.0);
  return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c));
}

void main() {
  vec2 px = vUv * uSize;

  float hC = heightAt(px);
  float hL = heightAt(px - vec2(1.0, 0.0));
  float hR = heightAt(px + vec2(1.0, 0.0));
  float hU = heightAt(px - vec2(0.0, 1.0));
  float hD = heightAt(px + vec2(0.0, 1.0));

  float dhx = (hR - hL) * uNormalGain;
  float dhy = (hD - hU) * uNormalGain;
  vec3 n = normalize(vec3(-dhx, -dhy, 1.0));

  float diff = max(0.0, dot(n, uLightDir));
  float sp = pow(max(0.0, dot(n, uHalf)), uShininess) * uKs * uStrength;

  float through = uShowThrough > 0.0
    ? 1.0 + uShowThrough * uStrength * 0.30 * hC
    : 1.0;

  float lit = (uAmbient + (1.0 - uAmbient) * diff) * uLitNorm;

  vec3 albedo = toLinear(texture(uAlbedo, vUv).rgb) * through;
  vec3 outLin = albedo * lit * uLightRgb + sp * uLightRgb;

  fragColor = vec4(toSrgb(outLin), 1.0);
}`;

const FRAG = FRAG_SRC.replace('__SURFACE_GLSL__', SURFACE_GLSL);

/* ── Состояние контекста ────────────────────────────────────────────────────*/

interface GLState {
  canvas: HTMLCanvasElement;
  gl: WebGL2RenderingContext;
  program: WebGLProgram;
  vao: WebGLVertexArrayObject;
  texAlbedo: WebGLTexture;
  texDist: WebGLTexture;
  texNoise: WebGLTexture;
  texSurface: WebGLTexture;
  loc: Record<string, WebGLUniformLocation | null>;
}

let state: GLState | null = null;
let unavailable = false;

/** Кэш карты расстояний: она зависит только от разбиения, а не от света. */
const distCache = new WeakMap<ProcessingResult, Uint8Array>();
/** Какая фактура сейчас залита в текстуру — чтобы не заливать её каждый кадр. */
let surfaceKey: Uint8Array | null = null;

function compile(gl: WebGL2RenderingContext, type: number, src: string): WebGLShader | null {
  const sh = gl.createShader(type);
  if (!sh) return null;
  gl.shaderSource(sh, src);
  gl.compileShader(sh);
  if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
    console.warn('material shader:', gl.getShaderInfoLog(sh));
    gl.deleteShader(sh);
    return null;
  }
  return sh;
}

function makeTexture(gl: WebGL2RenderingContext, repeat: boolean, nearest = false): WebGLTexture | null {
  const t = gl.createTexture();
  if (!t) return null;
  gl.bindTexture(gl.TEXTURE_2D, t);
  const f = nearest ? gl.NEAREST : gl.LINEAR;
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, f);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, f);
  const wrap = repeat ? gl.REPEAT : gl.CLAMP_TO_EDGE;
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, wrap);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, wrap);
  return t;
}

function init(): GLState | null {
  if (state) return state;
  if (unavailable || typeof document === 'undefined') return null;

  const canvas = document.createElement('canvas');
  const gl = canvas.getContext('webgl2', {
    alpha: false, antialias: false, depth: false, stencil: false,
    preserveDrawingBuffer: true,
  }) as WebGL2RenderingContext | null;
  if (!gl) { unavailable = true; return null; }

  const vs = compile(gl, gl.VERTEX_SHADER, VERT);
  const fs = compile(gl, gl.FRAGMENT_SHADER, FRAG);
  const program = vs && fs ? gl.createProgram() : null;
  if (!vs || !fs || !program) { unavailable = true; return null; }

  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.bindAttribLocation(program, 0, 'aPos');
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.warn('material program:', gl.getProgramInfoLog(program));
    unavailable = true;
    return null;
  }

  const vao = gl.createVertexArray();
  const buf = gl.createBuffer();
  if (!vao || !buf) { unavailable = true; return null; }
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

  const texAlbedo = makeTexture(gl, false);
  // Карта расстояний читается БЕЗ сглаживания. Валик краски по кромке зоны
  // описан узкой экспонентой шириной около пикселя, и сглаживание карты
  // размывало бы именно его — а это самая заметная часть тела краски.
  const texDist = makeTexture(gl, false, true);
  const texNoise = makeTexture(gl, true);
  const texSurface = makeTexture(gl, false);
  if (!texAlbedo || !texDist || !texNoise || !texSurface) { unavailable = true; return null; }

  // Шумовая плитка — ровно та же, что на процессоре: одинаковое зерно на
  // обоих путях, иначе картинка «прыгала» бы при переключении.
  const N = 256;
  const noise = new Uint8Array(N * N);
  {
    let s = 0x9e3779b9;
    const rnd = () => { s ^= s << 13; s ^= s >>> 17; s ^= s << 5; return (s >>> 0) / 4294967296; };
    for (let i = 0; i < noise.length; i++) noise[i] = Math.round(rnd() * 255);
  }
  gl.bindTexture(gl.TEXTURE_2D, texNoise);
  gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.R8, N, N, 0, gl.RED, gl.UNSIGNED_BYTE, noise);

  const names = [
    'uAlbedo', 'uDist', 'uNoise', 'uSurface', 'uSize', 'uScale',
    'uMmPerPx', 'uKind', 'uPitch', 'uPitch2', 'uIrr', 'uAniso', 'uDepth', 'uGrainScale',
    'uBodyAmp', 'uStreak', 'uLayerGrain', 'uStrokeCos', 'uStrokeSin',
    'uUseSurface', 'uTexPerPx', 'uSurfAmp', 'uTexN',
    'uLightDir', 'uHalf', 'uLightRgb', 'uKs', 'uShininess',
    'uShowThrough', 'uStrength', 'uNormalGain', 'uLitNorm', 'uAmbient',
  ];
  const loc: Record<string, WebGLUniformLocation | null> = {};
  for (const n of names) loc[n] = gl.getUniformLocation(program, n);

  state = { canvas, gl, program, vao, texAlbedo, texDist, texNoise, texSurface, loc };
  return state;
}

/**
 * Самое быстрое из наблюдавшихся времён кадра, мс. Ноль — ещё не мерили.
 *
 * Минимум, а не последнее значение: первый кадр включает сборку шейдера и
 * заливку текстур и потому заведомо медленнее установившегося.
 */
let bestFrameMs = 0;

/** Есть ли WebGL 2 вообще. */
export function materialGLAvailable(): boolean {
  return !unavailable && !!init();
}

/**
 * Даёт ли видеокарта РЕАЛЬНОЕ ускорение.
 *
 * Наличия WebGL мало: на части машин он реализован программно, и тогда кадр
 * стоит столько же, сколько на процессоре, а то и дороже. Слепо доверившись
 * самому факту поддержки, мы бы сократили паузу перед перерисовкой там, где
 * этого делать нельзя, и получили бы вязкий интерфейс вместо живого.
 * Поэтому решение принимается по измеренному времени кадра.
 */
export function materialGLFast(): boolean {
  if (!materialGLAvailable()) return false;
  return bestFrameMs === 0 || bestFrameMs < 60;
}

/* ── Проход ─────────────────────────────────────────────────────────────────*/

/**
 * Считает физику материала на видеокарте и возвращает результат в исходный
 * холст. При любой неудаче возвращает false — вызывающий переходит на
 * процессорный проход, и пользователь ничего не замечает.
 */
export function applyMaterialGL(
  canvas: HTMLCanvasElement,
  res: ProcessingResult,
  scale: number,
  params: MaterialParams,
): boolean {
  const st = init();
  if (!st) return false;

  const W = canvas.width, H = canvas.height;
  if (W < 2 || H < 2) return false;

  const k = Math.max(0, Math.min(1, params.strength / 100));
  if (k <= 0) return false;

  const ctx2d = canvas.getContext('2d');
  if (!ctx2d) return false;

  const t0 = typeof performance !== 'undefined' ? performance.now() : 0;

  const { gl, loc } = st;
  st.canvas.width = W;
  st.canvas.height = H;
  gl.viewport(0, 0, W, H);
  gl.useProgram(st.program);
  gl.bindVertexArray(st.vao);

  /* --- Текстуры ---------------------------------------------------------- */

  gl.activeTexture(gl.TEXTURE0);
  gl.bindTexture(gl.TEXTURE_2D, st.texAlbedo);
  // Браузер по умолчанию волен преобразовать цветовое пространство холста при
  // загрузке в текстуру. Для картинки это было бы незаметно, а здесь означало
  // бы, что видеокарта и процессор считают по разным исходным цветам.
  gl.pixelStorei(gl.UNPACK_COLORSPACE_CONVERSION_WEBGL, gl.NONE);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, 0);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, canvas);
  gl.uniform1i(loc.uAlbedo, 0);

  // Карта расстояний до края зоны: считается один раз на разбиение.
  let dist = distCache.get(res);
  if (!dist) {
    const raw = res.labelMask && res.labelMask.length === res.imgW * res.imgH
      ? edgeDistance(res.labelMask, res.imgW, res.imgH)
      : null;
    dist = new Uint8Array(res.imgW * res.imgH);
    if (raw) for (let i = 0; i < dist.length; i++) dist[i] = Math.min(255, Math.round((raw[i] / 8) * 255));
    distCache.set(res, dist);
  }
  gl.activeTexture(gl.TEXTURE1);
  gl.bindTexture(gl.TEXTURE_2D, st.texDist);
  gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.R8, res.imgW, res.imgH, 0, gl.RED, gl.UNSIGNED_BYTE, dist);
  gl.uniform1i(loc.uDist, 1);

  gl.activeTexture(gl.TEXTURE2);
  gl.bindTexture(gl.TEXTURE_2D, st.texNoise);
  gl.uniform1i(loc.uNoise, 2);

  const surf = params.surface && params.surface.tile.length >= params.surface.size ** 2
    ? params.surface : null;
  gl.activeTexture(gl.TEXTURE3);
  gl.bindTexture(gl.TEXTURE_2D, st.texSurface);
  if (surf && surf.tile !== surfaceKey) {
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.R8, surf.size, surf.size, 0, gl.RED, gl.UNSIGNED_BYTE, surf.tile);
    surfaceKey = surf.tile;
  } else if (!surf && surfaceKey) {
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.R8, 1, 1, 0, gl.RED, gl.UNSIGNED_BYTE, new Uint8Array([128]));
    surfaceKey = null;
  }
  gl.uniform1i(loc.uSurface, 3);

  /* --- Параметры --------------------------------------------------------- */

  const table = PAINT_MATERIAL[params.paintType] ?? PAINT_MATERIAL.gouache;
  const sp = SURFACE_MATERIAL[params.surfaceType] ?? SURFACE_MATERIAL.canvas;
  const m = params.measured;
  const ks = m ? 0.015 + m.gloss * 0.55 : table.ks;
  const grainAmp = m ? m.grain * 0.9 : 0;

  let texPerPx = 0;
  if (surf && surf.tileMm > 0.5) {
    const mmPerMaskPx = Math.min(277 / Math.max(res.imgW, res.imgH), 190 / Math.min(res.imgW, res.imgH));
    texPerPx = (mmPerMaskPx / Math.max(1, scale) * surf.size) / surf.tileMm;
  }

  const az = params.lightAzimuth * Math.PI / 180;
  const el = Math.max(5, Math.min(88, params.lightElevation)) * Math.PI / 180;
  const lx = Math.cos(el) * Math.cos(az), ly = Math.cos(el) * Math.sin(az), lz = Math.sin(el);
  const hx = lx, hy = ly, hz = lz + 1;
  const hn = Math.hypot(hx, hy, hz);

  const light = kelvinToRgb(params.lightKelvin);
  const ADAPT = 0.68;
  const AMBIENT = 0.62;
  const flatLit = AMBIENT + (1 - AMBIENT) * lz;

  const strokeAngle = (params.lightAzimuth + 55) * Math.PI / 180;

  gl.uniform2f(loc.uSize, W, H);
  gl.uniform1f(loc.uScale, scale);
  const mmPerMaskPx = Math.min(277 / Math.max(res.imgW, res.imgH), 190 / Math.min(res.imgW, res.imgH));
  const preset = findSurfacePreset(params.surfacePresetId || defaultSurfaceFor(params.surfaceType));
  gl.uniform1f(loc.uMmPerPx, mmPerMaskPx / Math.max(1, scale));
  gl.uniform1i(loc.uKind, preset ? KIND_INDEX[preset.kind] : 1);
  gl.uniform1f(loc.uPitch, preset ? preset.pitchMm : 0.2);
  gl.uniform1f(loc.uPitch2, preset ? preset.pitch2Mm : 0);
  gl.uniform1f(loc.uIrr, preset ? preset.irregular : 1);
  gl.uniform1f(loc.uAniso, preset ? preset.aniso : 1);
  gl.uniform1f(loc.uDepth, preset ? preset.depth : sp.amp);
  gl.uniform1f(loc.uGrainScale, 1 / Math.max(1, scale * 0.9));
  gl.uniform1f(loc.uBodyAmp, table.bodyAmp);
  gl.uniform1f(loc.uStreak, table.streak);
  gl.uniform1f(loc.uLayerGrain, grainAmp);
  gl.uniform1f(loc.uStrokeCos, Math.cos(strokeAngle));
  gl.uniform1f(loc.uStrokeSin, Math.sin(strokeAngle));
  gl.uniform1f(loc.uUseSurface, surf ? 1 : 0);
  gl.uniform1f(loc.uTexPerPx, texPerPx);
  gl.uniform1f(loc.uSurfAmp, surf ? surf.amplitude : 0);
  gl.uniform1f(loc.uTexN, surf ? surf.size : 1);
  gl.uniform3f(loc.uLightDir, lx, ly, lz);
  gl.uniform3f(loc.uHalf, hx / hn, hy / hn, hz / hn);
  gl.uniform3f(loc.uLightRgb,
    1 + (light[0] - 1) * (1 - ADAPT),
    1 + (light[1] - 1) * (1 - ADAPT),
    1 + (light[2] - 1) * (1 - ADAPT));
  gl.uniform1f(loc.uKs, ks);
  gl.uniform1f(loc.uShininess, table.shininess);
  gl.uniform1f(loc.uShowThrough, table.showThrough);
  gl.uniform1f(loc.uStrength, k);
  gl.uniform1f(loc.uNormalGain, 0.85 * k);
  gl.uniform1f(loc.uLitNorm, flatLit > 1e-6 ? 1 / flatLit : 1);
  gl.uniform1f(loc.uAmbient, AMBIENT);

  gl.drawArrays(gl.TRIANGLES, 0, 3);

  if (gl.getError() !== gl.NO_ERROR) return false;

  // Возвращаем результат в исходный холст. Схема была загружена в текстуру
  // до отрисовки, поэтому затирание её здесь безопасно.
  ctx2d.setTransform(1, 0, 0, 1, 0, 0);
  ctx2d.clearRect(0, 0, W, H);
  ctx2d.drawImage(st.canvas, 0, 0);

  if (t0) {
    const dt = performance.now() - t0;
    if (!bestFrameMs || dt < bestFrameMs) bestFrameMs = dt;
  }
  return true;
}
