// src/generator/components/PaintingFirstSteps.tsx
// «Первые шаги» — вождение новичка за руку в режиме «Живопись». Превращает
// абстрактные слои в крошечные безопасные действия простым языком и сам
// переключает нужный слой/сетку на холсте под каждый шаг. Задача — снять страх
// перед листом и дать понятное «с чего начать».
import { useState } from "react";
import { useAppStore } from "../store";
import { cn } from "../../utils/cn";

interface Step {
  title: string;
  lines: string[];
  reassure?: string;
  cta: string;
  apply: () => void;
}

function showLayer(layer: number) {
  const s = useAppStore.getState();
  s.update({ showTemperatureMap: false });
  s.setPaintingLayerAnimated(layer);
}

const STEPS: Step[] = [
  {
    title: "Спокойно. Испортить нельзя",
    lines: [
      "Живопись — это слои: каждый следующий закрывает предыдущий, поэтому ранние мазки почти никто не увидит.",
      "Мы пойдём крошечными шагами. Твоя задача — повторять то, что видишь, а не «уметь рисовать».",
    ],
    reassure: "Права на ошибку у тебя больше, чем кажется: почти всё правится сверху.",
    cta: "Поехали",
    apply: () => { useAppStore.getState().setGridType("none"); showLayer(0); },
  },
  {
    title: "Шаг 1. Разметь лист по клеточкам",
    lines: [
      "Включаю сетку на образце. Начерти такую же лёгкую сетку карандашом на своём листе.",
      "Не рисуй «предмет». Просто смотри, что попадает в каждую клетку, и повторяй линию за линией — как срисовывание по клеточкам.",
    ],
    reassure: "Карандаш стирается — ошибиться физически невозможно.",
    cta: "Включить сетку",
    apply: () => { useAppStore.getState().setGridType("grid"); showLayer(0); },
  },
  {
    title: "Шаг 2. Только большие пятна",
    lines: [
      "Смотри на слой «Контуры». Лёгкими линиями наметь ТОЛЬКО самые крупные формы и границы.",
      "Никаких мелких деталей — они появятся в самом конце. Пять минут, не дави на карандаш.",
    ],
    reassure: "Это лишь разметка под краску — её не будет видно.",
    cta: "Показать контуры",
    apply: () => showLayer(0),
  },
  {
    title: "Шаг 3. Заложи тёмное (подмалёвок)",
    lines: [
      "Прищурься, глядя на фото — мелочи исчезнут, останутся тёмные и светлые пятна.",
      "Возьми один тёмный замес и грубо закрась все тёмные места. Пятном, можно заходить за края.",
    ],
    reassure: "Подмалёвок перекроют следующие слои — будь смелым и небрежным.",
    cta: "Показать подмалёвок",
    apply: () => showLayer(1),
  },
  {
    title: "Шаг 4. Тёплое и холодное",
    lines: [
      "Показываю карту температуры: красноватое — тёплые места, синеватое — холодные.",
      "Запомни расклад: обычно тёплый свет соседствует с холодной тенью. Это пригодится на следующем шаге.",
    ],
    cta: "Показать температуру",
    apply: () => useAppStore.getState().update({ showTemperatureMap: true, paintingLayer: -1 }),
  },
  {
    title: "Шаг 5. Клади цвет в тон",
    lines: [
      "Закрась большие формы их цветом, сохраняя найденные тёмное и светлое.",
      "Точный замес любого цвета возьми в «Палитре этапа» ниже. Держи цвета чуть приглушёнными — яркое оставь на финал.",
    ],
    reassure: "Границы и оттенки можно поправить сверху позже.",
    cta: "Показать цвета",
    apply: () => showLayer(3),
  },
  {
    title: "Шаг 6. Акценты и проверка",
    lines: [
      "Добавь мелкие детали и самые яркие или тёмные акценты ТОЛЬКО в главном месте. Остальное оставь мягким.",
      "Сфотографируй работу и открой «Самопроверку этапа» ниже — подскажу, что поправить. Готово: ты написал картину.",
    ],
    reassure: "Не гонись за фото один-в-один: живая работа лучше точной копии.",
    cta: "Показать детали",
    apply: () => showLayer(4),
  },
];

export function PaintingFirstSteps({ isDark }: { isDark: boolean }) {
  const [open, setOpen] = useState(true);
  const [i, setI] = useState(0);
  const step = STEPS[i];
  const goTo = (n: number) => {
    const idx = Math.max(0, Math.min(STEPS.length - 1, n));
    setI(idx);
    STEPS[idx].apply();
  };

  return (
    <div className="rounded-2xl border-2 border-indigo-200 dark:border-indigo-500/30 bg-gradient-to-br from-indigo-50 to-violet-50/40 dark:from-indigo-500/10 dark:to-violet-500/5 overflow-hidden">
      <button
        onClick={() => setOpen((o) => !o)}
        className="w-full flex items-center gap-2.5 px-4 py-3 text-left"
      >
        <span className="w-7 h-7 rounded-xl bg-indigo-600 text-white flex items-center justify-center shrink-0 shadow-lg shadow-indigo-500/20">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7c.6.4 1 1.1 1 1.8V17h6v-.5c0-.7.4-1.4 1-1.8A7 7 0 0 0 12 2z"/></svg>
        </span>
        <span className="flex-1 min-w-0">
          <span className="block text-sm font-black text-indigo-700 dark:text-indigo-200 leading-tight">Первые шаги · рисуем без страха</span>
          <span className="block text-[11px] font-bold text-indigo-500/70 dark:text-indigo-300/60 uppercase tracking-wider">Пошаговое вождение для новичка</span>
        </span>
        <svg className={cn("transition-transform text-indigo-500", open && "rotate-180")} width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round"><path d="m6 9 6 6 6-6"/></svg>
      </button>

      {open && (
        <div className="px-4 pb-4 space-y-3">
          {/* Прогресс */}
          <div className="flex items-center gap-1.5">
            {STEPS.map((_, k) => (
              <span key={k} className={cn("h-1.5 rounded-full transition-all", k === i ? "w-6 bg-indigo-600" : k < i ? "w-3 bg-indigo-400" : "w-3 bg-indigo-200 dark:bg-indigo-500/20")} />
            ))}
            <span className="ml-auto text-[10px] font-black uppercase tracking-widest text-indigo-500/70 dark:text-indigo-300/60">{i + 1} / {STEPS.length}</span>
          </div>

          <div className={cn("rounded-xl p-3.5 space-y-2", isDark ? "bg-slate-900/60" : "bg-white/80")}>
            <div className="text-sm font-black text-slate-800 dark:text-slate-100 leading-tight">{step.title}</div>
            {step.lines.map((l, k) => (
              <p key={k} className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed">{l}</p>
            ))}
            {step.reassure && (
              <div className="flex gap-2 pt-1">
                <span className="text-emerald-500 shrink-0 mt-0.5">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M9 12l2 2 4-4"/><circle cx="12" cy="12" r="10"/></svg>
                </span>
                <p className="text-[11px] font-bold text-emerald-700/90 dark:text-emerald-400/90 leading-relaxed">{step.reassure}</p>
              </div>
            )}
          </div>

          {/* Кнопка «показать на холсте» + навигация */}
          <button
            onClick={() => step.apply()}
            className="w-full flex items-center justify-center gap-2 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest bg-indigo-600 text-white shadow-lg shadow-indigo-600/20 hover:bg-indigo-700 transition-all active:scale-[0.98]"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
            {step.cta}
          </button>

          <div className="flex items-center gap-2">
            <button
              onClick={() => goTo(i - 1)}
              disabled={i === 0}
              className={cn("flex-1 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest border-2 transition-all active:scale-[0.98] disabled:opacity-40",
                isDark ? "border-slate-700 text-slate-300" : "border-slate-200 text-slate-500")}
            >
              Назад
            </button>
            {i < STEPS.length - 1 ? (
              <button
                onClick={() => goTo(i + 1)}
                className="flex-[1.4] py-2 rounded-xl text-[11px] font-black uppercase tracking-widest bg-slate-900 dark:bg-white text-white dark:text-slate-900 transition-all active:scale-[0.98]"
              >
                Дальше →
              </button>
            ) : (
              <button
                onClick={() => goTo(0)}
                className="flex-[1.4] py-2 rounded-xl text-[11px] font-black uppercase tracking-widest bg-emerald-600 text-white transition-all active:scale-[0.98]"
              >
                Пройти заново
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
