import type { PaintingModeState, PbnModeState, AppState } from "./types";

/** Создать плоское состояние для быстрого доступа из компонентов */
export function buildFlatState(mode: "painting" | "pbn", paintingModeState: PaintingModeState, pbnModeState: PbnModeState) {
  const state = mode === "painting" ? paintingModeState : pbnModeState;
  
  return {
    numColors: state.numColors,
    detail: state.detail,
    activeColors: state.activeColors,
    contourWeight: state.contourWeight,
    showContours: state.showContours,
    numberWeight: state.numberWeight,
    showNumbers: state.showNumbers,
    paintingLayer: mode === "painting" ? paintingModeState.paintingLayer : 0,
    paintingStyleId: mode === "painting" ? paintingModeState.paintingStyleId : "original",
    notanLevels: mode === "painting" ? paintingModeState.notanLevels : 2,
    notanThreshold: mode === "painting" ? paintingModeState.notanThreshold : 128,
    selectedZoneId: state.selectedZoneId,
    zoneInfoVisible: state.zoneInfoVisible,
    customArtPalette: mode === "painting" ? paintingModeState.customArtPalette : [],
    zoneGuideActive: state.zoneGuideActive,
    currentZoneIndex: state.currentZoneIndex,
    gridType: state.gridType,
    gridSize: state.gridSize,
    flipHorizontal: state.flipHorizontal,
    showTemperatureMap: state.showTemperatureMap,
    artIntensity: mode === "painting" ? paintingModeState.artIntensity : 100,
    detailsPhotoOpacity: mode === "painting" ? paintingModeState.detailsPhotoOpacity : 60,
    prevPaintingLayer: mode === "painting" ? paintingModeState.prevPaintingLayer : 1,
    layerTransitioning: mode === "painting" ? paintingModeState.layerTransitioning : false,
    paintingSplitMode: state.paintingSplitMode,
    recipeSplitMode: mode === "pbn" ? pbnModeState.recipeSplitMode : false,
    recipeApproximations: mode === "pbn" ? pbnModeState.recipeApproximations : null,
    paintingNumColors: paintingModeState.numColors,
    paintingDetail: paintingModeState.detail,
    paintingContourWeight: paintingModeState.contourWeight,
    pbnContourWeight: pbnModeState.contourWeight,
    viewTransform: state.viewTransform,
    result: state.result,
    colorHarmony: mode === "pbn" ? pbnModeState.colorHarmony : "none",
    colorHarmonyIntensity: mode === "pbn" ? pbnModeState.colorHarmonyIntensity : 70,
    colorHarmonyCustomHue: mode === "pbn" ? pbnModeState.colorHarmonyCustomHue : null,
  };
}

/** Синхронизировать плоское состояние Студии с вложенными объектами режимов */
export function syncCurrentFlatIntoModes(state: AppState) {
  const { studioMode, paintingModeState, pbnModeState } = state;

  const currentPainting = {
    ...paintingModeState,
    numColors: studioMode === "painting" ? state.numColors : state.paintingNumColors,
    detail: studioMode === "painting" ? state.detail : state.paintingDetail,
    activeColors: studioMode === "painting" ? state.activeColors : paintingModeState.activeColors,
    contourWeight: studioMode === "painting" ? state.contourWeight : state.paintingContourWeight,
    showContours: studioMode === "painting" ? state.showContours : paintingModeState.showContours,
    numberWeight: studioMode === "painting" ? state.numberWeight : paintingModeState.numberWeight,
    showNumbers: studioMode === "painting" ? state.showNumbers : paintingModeState.showNumbers,
    paintingLayer: state.paintingLayer,
    paintingStyleId: state.paintingStyleId,
    notanLevels: state.notanLevels,
    notanThreshold: state.notanThreshold,
    selectedZoneId: state.selectedZoneId,
    zoneInfoVisible: state.zoneInfoVisible,
    customArtPalette: state.customArtPalette,
    zoneGuideActive: state.zoneGuideActive,
    currentZoneIndex: state.currentZoneIndex,
    gridType: state.gridType,
    gridSize: state.gridSize,
    flipHorizontal: state.flipHorizontal,
    showTemperatureMap: state.showTemperatureMap,
    artIntensity: state.artIntensity,
    detailsPhotoOpacity: state.detailsPhotoOpacity,
    prevPaintingLayer: state.prevPaintingLayer,
    layerTransitioning: state.layerTransitioning,
    paintingSplitMode: state.paintingSplitMode,
    viewTransform: studioMode === "painting" ? { ...state.viewTransform } : { ...paintingModeState.viewTransform },
    result: studioMode === "painting" ? state.result : paintingModeState.result,
  };

  const currentPbn = {
    ...pbnModeState,
    numColors: studioMode === "pbn" ? state.numColors : pbnModeState.numColors,
    detail: studioMode === "pbn" ? state.detail : pbnModeState.detail,
    activeColors: studioMode === "pbn" ? state.activeColors : pbnModeState.activeColors,
    contourWeight: studioMode === "pbn" ? state.contourWeight : state.pbnContourWeight,
    showContours: studioMode === "pbn" ? state.showContours : pbnModeState.showContours,
    numberWeight: studioMode === "pbn" ? state.numberWeight : pbnModeState.numberWeight,
    showNumbers: studioMode === "pbn" ? state.showNumbers : pbnModeState.showNumbers,
    selectedZoneId: state.selectedZoneId,
    zoneInfoVisible: state.zoneInfoVisible,
    zoneGuideActive: state.zoneGuideActive,
    currentZoneIndex: state.currentZoneIndex,
    gridType: state.gridType,
    gridSize: state.gridSize,
    flipHorizontal: state.flipHorizontal,
    showTemperatureMap: state.showTemperatureMap,
    paintingSplitMode: state.paintingSplitMode,
    recipeSplitMode: studioMode === "pbn" ? state.recipeSplitMode : pbnModeState.recipeSplitMode,
    recipeApproximations: pbnModeState.recipeApproximations,
    viewTransform: studioMode === "pbn" ? { ...state.viewTransform } : { ...pbnModeState.viewTransform },
    result: studioMode === "pbn" ? state.result : pbnModeState.result,
    paintingLayer: state.paintingLayer,
    colorHarmony: studioMode === "pbn" ? state.colorHarmony : pbnModeState.colorHarmony,
    colorHarmonyIntensity: studioMode === "pbn" ? state.colorHarmonyIntensity : pbnModeState.colorHarmonyIntensity,
    colorHarmonyCustomHue: studioMode === "pbn" ? state.colorHarmonyCustomHue : pbnModeState.colorHarmonyCustomHue,
  };

  return { paintingModeState: currentPainting, pbnModeState: currentPbn };
}
