// Русское склонение существительных по числу.
// pluralRu(1,'цвет','цвета','цветов') → 'цвет'; (3,...) → 'цвета'; (5,...) → 'цветов'.
export function pluralRu(n: number, one: string, few: string, many: string): string {
  const abs = Math.abs(Math.trunc(n));
  const m10 = abs % 10;
  const m100 = abs % 100;
  if (m100 >= 11 && m100 <= 14) return many;
  if (m10 === 1) return one;
  if (m10 >= 2 && m10 <= 4) return few;
  return many;
}

// Число + правильная форма слова: withCount(3,'цвет','цвета','цветов') → '3 цвета'.
export function withCount(n: number, one: string, few: string, many: string): string {
  return `${n} ${pluralRu(n, one, few, many)}`;
}

// Частые словоформы приложения.
export const wordColors = (n: number) => pluralRu(n, 'цвет', 'цвета', 'цветов');
export const wordZones = (n: number) => pluralRu(n, 'зона', 'зоны', 'зон');
export const wordParts = (n: number) => pluralRu(n, 'часть', 'части', 'частей');
export const wordComponents = (n: number) => pluralRu(n, 'компонент', 'компонента', 'компонентов');
export const wordPigments = (n: number) => pluralRu(n, 'пигмент', 'пигмента', 'пигментов');
export const wordRecipes = (n: number) => pluralRu(n, 'рецепт', 'рецепта', 'рецептов');
