// src/generator/components/SettingsBottomSheet.tsx
// Мобильный доступ к настройкам: холст занимает весь экран, а всё дерево настроек
// (тип проекта, коррекция фото, векторизация, палитра, калькулятор) выезжает снизу
// листом по кнопке — как «Рецепт цвета». На десктопе (md+) не используется: там
// настройки живут в боковой панели SettingsPanel.
import { useRef, useCallback } from "react";
import { useAppStore } from "../store";
import { SettingsContent } from "./SettingsPanel";
import { cn } from "../../utils/cn";
import { useBackButton } from "../../hooks/useBackButton";

export function SettingsBottomSheet() {
  const isOpen = useAppStore((s) => s.mobileSettingsOpen);
  const isDark = useAppStore((s) => s.isDark);
  const studioMode = useAppStore((s) => s.studioMode);
  const update = useAppStore((s) => s.update);

  const contentRef = useRef<HTMLDivElement>(null);

  const close = useCallback(() => {
    update({ mobileSettingsOpen: false });
  }, [update]);

  useBackButton(isOpen, close);

  return (
    <>
      {/* Кнопка-триггер живёт в верхнем тулбаре (Toolbar) — иконка-шестерёнка,
          md:hidden. Здесь только сам лист и затемнение. */}

      {/* Затемнение фона */}
      {isOpen && (
        <div
          className="md:hidden fixed inset-0 bg-black/40 z-[60] modal-backdrop backdrop-blur-sm"
          onClick={close}
        />
      )}

      {/* Сам лист — прижат к низу экрана */}
      <div
        role="dialog"
        aria-modal="true"
        aria-label="Настройки"
        className={cn(
          "md:hidden fixed inset-0 z-[70] flex items-end justify-center",
          !isOpen && "pointer-events-none"
        )}
      >
        <div
          className={cn(
            "w-full max-h-[88dvh] rounded-t-3xl shadow-2xl overflow-hidden transition-all duration-300 ease-out flex flex-col",
            isDark ? "bg-slate-900 border-t border-slate-800" : "bg-white border-t border-slate-100",
            isOpen ? "opacity-100 translate-y-0" : "opacity-0 translate-y-full"
          )}
        >
          <div className="shrink-0 pt-3 pb-2 flex flex-col items-center border-b border-slate-100 dark:border-slate-800/70">
            <div className={cn("w-10 h-1 rounded-full mb-3", isDark ? "bg-slate-700" : "bg-slate-200")} />
            <div className="flex items-center justify-between w-full px-5 mb-1">
              <div>
                <h2 className={cn("text-lg font-black tracking-tight", isDark ? "text-white" : "text-slate-900")}>Настройки</h2>
                <p className="text-xs font-bold text-slate-500 uppercase tracking-widest leading-none mt-0.5">
                  {studioMode === "painting" ? "Живопись" : "По номерам"}
                </p>
              </div>
              <button onClick={close} className={cn("w-11 h-11 rounded-2xl flex items-center justify-center transition-colors shadow-sm active:scale-90", isDark ? "bg-slate-800 text-slate-500 hover:bg-slate-700" : "bg-slate-100 text-slate-600 hover:bg-slate-200")} aria-label="Закрыть настройки">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M18 6 6 18M6 6l12 12" />
                </svg>
              </button>
            </div>
          </div>

          <div ref={contentRef} className="flex-1 overflow-y-auto overscroll-contain custom-scrollbar px-4 pt-3 pb-[max(1.5rem,env(safe-area-inset-bottom))]">
            {isOpen && <SettingsContent />}
          </div>
        </div>
      </div>
    </>
  );
}
